def calculate_marginal_tax(income: float, brackets: List[Tuple[float, float]], 
                           standard_deduction: float = 0) -> float:
    """
    Calculate tax using proper marginal brackets.
    
    THIS IS THE CORRECT WAY - NOT FLAT RATES!
    
    Args:
        income: Gross income
        brackets: List of (upper_limit, rate) tuples
        standard_deduction: Amount to deduct before calculating tax
    
    Returns:
        Tax liability
    """
    if income <= 0:
        return 0
    
    # Apply standard deduction
    taxable_income = max(0, income - standard_deduction)
    
    tax = 0
    prev_bracket = 0
    
    for bracket_limit, rate in brackets:
        if taxable_income <= prev_bracket:
            break
        
        amount_in_bracket = min(taxable_income, bracket_limit) - prev_bracket
        tax += amount_in_bracket * rate
        prev_bracket = bracket_limit
        
        if taxable_income <= bracket_limit:
            break
    
    return tax


def calculate_ltcg_tax_stacked(
    ltcg_amount: float,
    ordinary_income_after_deduction: float,
    ltcg_brackets: List[Tuple[float, float]]
) -> Tuple[float, Dict]:
    """
    Calculate LTCG tax with proper bracket stacking.
    
    LTCG is "stacked" on top of ordinary income and taxed through each bracket
    progressively, just like ordinary income tax works.
    
    This is the CORRECT method per IRS rules. The old method of applying a single
    flat rate based on total income is WRONG.
    
    Args:
        ltcg_amount: Total long-term capital gains to be taxed
        ordinary_income_after_deduction: Taxable ordinary income (after std deduction)
                                         This determines where LTCG "starts" in brackets
        ltcg_brackets: List of (upper_limit, rate) tuples for LTCG
                       e.g., [(47025, 0.00), (518900, 0.15), (inf, 0.20)]
    
    Returns:
        Tuple of (total_ltcg_tax, breakdown_dict)
        breakdown_dict contains details for each bracket
    
    Example:
        Single filer, $40,000 ordinary income, $50,000 LTCG
        Brackets: [(47025, 0.00), (518900, 0.15), (inf, 0.20)]
        
        LTCG stacks starting at $40,000:
        - $7,025 fills 0% bracket ($40k → $47,025) = $0
        - $42,975 fills 15% bracket ($47,025 → $90k) = $6,446.25
        Total LTCG tax = $6,446.25
    """
    if ltcg_amount <= 0:
        return 0.0, {'breakdown': [], 'total': 0.0}
    
    # Where LTCG starts stacking (ordinary income fills up to here)
    stack_start = max(0, ordinary_income_after_deduction)
    
    # Track tax and breakdown
    total_tax = 0.0
    breakdown = []
    remaining_ltcg = ltcg_amount
    current_position = stack_start
    
    for i, (bracket_ceiling, rate) in enumerate(ltcg_brackets):
        if remaining_ltcg <= 0:
            break
        
        # Skip brackets that ordinary income has already filled past
        if current_position >= bracket_ceiling:
            continue
        
        # How much room is left in this bracket?
        room_in_bracket = bracket_ceiling - current_position
        
        # How much LTCG goes into this bracket?
        ltcg_in_bracket = min(remaining_ltcg, room_in_bracket)
        
        # Calculate tax for this portion
        tax_in_bracket = ltcg_in_bracket * rate
        
        # Record breakdown
        breakdown.append({
            'bracket_num': i + 1,
            'bracket_ceiling': bracket_ceiling,
            'rate': rate,
            'rate_pct': f"{rate*100:.0f}%",
            'ltcg_in_bracket': ltcg_in_bracket,
            'tax_in_bracket': tax_in_bracket,
            'income_range': (current_position, current_position + ltcg_in_bracket)
        })
        
        # Update totals
        total_tax += tax_in_bracket
        remaining_ltcg -= ltcg_in_bracket
        current_position += ltcg_in_bracket
    
    return total_tax, {
        'breakdown': breakdown,
        'total': total_tax,
        'ordinary_income_base': stack_start,
        'ltcg_amount': ltcg_amount,
        'effective_ltcg_rate': (total_tax / ltcg_amount) if ltcg_amount > 0 else 0
    }


def _merge_brokerage_tax_quirks(quirks: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    """Normalize brokerage-tax quirk settings to a finite, bounded config."""
    out = dict(BROKERAGE_TAX_QUIRK_DEFAULTS)
    if isinstance(quirks, dict):
        out.update({k: v for k, v in quirks.items() if k in out})

    out['round_taxable_to_dollar'] = bool(out.get('round_taxable_to_dollar', True))
    out['lt_to_st_reclass_rate'] = float(np.clip(float(out.get('lt_to_st_reclass_rate', 0.0)), 0.0, 0.50))
    out['ordinary_income_adjustment'] = float(np.clip(float(out.get('ordinary_income_adjustment', 0.0)), -1e9, 1e9))
    out['investment_income_adjustment'] = float(np.clip(float(out.get('investment_income_adjustment', 0.0)), -1e9, 1e9))
    out['state_tax_addback_for_amt'] = bool(out.get('state_tax_addback_for_amt', True))
    out['misc_preference_income'] = float(np.clip(float(out.get('misc_preference_income', 0.0)), -1e9, 1e9))
    return out


def _apply_brokerage_tax_quirks(taxable_st: float,
                                taxable_lt: float,
                                ordinary_income: float,
                                quirks: Dict[str, Any]) -> Dict[str, float]:
    """Apply broker 1099/reporting quirks before tax computation."""
    st = float(max(0.0, taxable_st))
    lt = float(max(0.0, taxable_lt))
    ordinary = float(max(0.0, ordinary_income))
    q = _merge_brokerage_tax_quirks(quirks)

    # Brokerage reclassification noise: LT lots can be reclassified ST (assignment/timing).
    reclass = float(min(lt, lt * q['lt_to_st_reclass_rate']))
    lt -= reclass
    st += reclass

    ordinary += float(q['ordinary_income_adjustment'])
    inv_adj = float(q['investment_income_adjustment'])

    if q['round_taxable_to_dollar']:
        st = float(np.round(st, 0))
        lt = float(np.round(lt, 0))
        ordinary = float(np.round(ordinary, 0))

    return {
        'taxable_st': float(max(0.0, st)),
        'taxable_lt': float(max(0.0, lt)),
        'ordinary_income': float(max(0.0, ordinary)),
        'investment_income_adjustment': float(inv_adj)
    }


def _compute_amt_tentative_tax(adjusted_ordinary: float,
                               taxable_st: float,
                               taxable_lt: float,
                               state_tax: float,
                               filing_status: str,
                               bracket_multiplier: float,
                               brokerage_quirks: Dict[str, Any]) -> Dict[str, float]:
    """
    Compute a conservative AMT estimate with AMTI add-backs and LTCG stacking.
    """
    fs = filing_status if filing_status in AMT_EXEMPTION_2024 else 'single'
    mult = float(max(bracket_multiplier, 0.10))

    exemption_base = float(AMT_EXEMPTION_2024[fs]) * mult
    phaseout_start = float(AMT_EXEMPTION_PHASEOUT_2024[fs]) * mult
    rate_switch = float(AMT_RATE_SWITCH_2024[fs]) * mult
    ltcg_brackets = [(float(th) * mult, float(rt)) for th, rt in LTCG_BRACKETS_2024.get(fs, LTCG_BRACKETS_2024['single'])]

    q = _merge_brokerage_tax_quirks(brokerage_quirks)
    amti = float(max(0.0, adjusted_ordinary + taxable_st + taxable_lt + q['misc_preference_income']))
    if q['state_tax_addback_for_amt']:
        amti += float(max(0.0, state_tax))

    exemption_reduction = float(max(0.0, (amti - phaseout_start) * 0.25))
    exemption = float(max(0.0, exemption_base - exemption_reduction))
    amt_taxable_income = float(max(0.0, amti - exemption))

    ordinary_base = float(max(0.0, adjusted_ordinary + taxable_st))
    ordinary_after_ex = float(max(0.0, ordinary_base - exemption))
    ex_left_for_lt = float(max(0.0, exemption - ordinary_base))
    lt_after_ex = float(max(0.0, taxable_lt - ex_left_for_lt))

    ordinary_amt_tax = float(0.26 * min(ordinary_after_ex, rate_switch) + 0.28 * max(ordinary_after_ex - rate_switch, 0.0))
    ltcg_amt_tax, _ = calculate_ltcg_tax_stacked(
        ltcg_amount=lt_after_ex,
        ordinary_income_after_deduction=ordinary_after_ex,
        ltcg_brackets=ltcg_brackets
    )
    tentative_min_tax = float(max(0.0, ordinary_amt_tax + ltcg_amt_tax))

    return {
        'amti': float(amti),
        'amt_exemption': float(exemption),
        'amt_taxable_income': float(amt_taxable_income),
        'tentative_min_tax': float(tentative_min_tax),
        'ordinary_amt_tax': float(ordinary_amt_tax),
        'ltcg_amt_tax': float(ltcg_amt_tax)
    }


def build_dynamic_tax_indexation_path(time_horizon_years: int,
                                      income_path: Optional[List[float]] = None,
                                      tax_config: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """
    Build year-by-year tax bracket indexation multipliers.
    Replaces fixed 2.5% with configurable dynamic rates.
    """
    cfg = tax_config if isinstance(tax_config, dict) else {}
    years = int(max(0, time_horizon_years))
    if years == 0:
        return {'rates': [], 'multipliers': []}

    override_path = cfg.get('tax_inflation_path', None)
    scenario_infl = DEFAULT_TAX_INDEXATION_BASE
    try:
        scenario_infl = float(get_scenario().get('inflation', DEFAULT_TAX_INDEXATION_BASE))
    except Exception:
        scenario_infl = DEFAULT_TAX_INDEXATION_BASE

    base = float(cfg.get('tax_bracket_indexation_base', scenario_infl))
    floor = float(cfg.get('tax_bracket_indexation_floor', DEFAULT_TAX_INDEXATION_FLOOR))
    cap = float(cfg.get('tax_bracket_indexation_cap', DEFAULT_TAX_INDEXATION_CAP))
    income_beta = float(np.clip(float(cfg.get('tax_bracket_indexation_income_beta', 0.35)), 0.0, 1.0))
    cycle_amp = float(np.clip(float(cfg.get('tax_bracket_indexation_cycle_amp', 0.0035)), 0.0, 0.02))

    rates: List[float] = []
    multipliers: List[float] = []
    multiplier = 1.0

    for y in range(years):
        if isinstance(override_path, (list, tuple)) and y < len(override_path):
            try:
                rate = float(override_path[y])
            except Exception:
                rate = base
        else:
            inc_growth = base
            if isinstance(income_path, (list, tuple)) and y + 1 < len(income_path):
                prev_i = float(income_path[y])
                next_i = float(income_path[y + 1])
                if np.isfinite(prev_i) and np.isfinite(next_i) and prev_i > 1e-6:
                    inc_growth = float(np.clip(next_i / prev_i - 1.0, -0.05, 0.15))
            cyc = cycle_amp * np.sin((y + 1) * 1.73) + (0.5 * cycle_amp) * np.cos((y + 1) * 0.97)
            rate = float(base + income_beta * (inc_growth - base) + cyc)

        rate = float(np.clip(rate, floor, cap))
        multiplier *= (1.0 + rate)
        rates.append(rate)
        multipliers.append(float(multiplier))

    return {
        'rates': rates,
        'multipliers': multipliers,
        'base_rate': float(base),
        'floor': float(floor),
        'cap': float(cap),
        'income_beta': float(income_beta),
        'cycle_amp': float(cycle_amp)
    }


def calculate_comprehensive_tax_v6(
    taxable_st: float,
    taxable_lt: float,
    capital_loss_deduction: float,
    ordinary_income: float = 0,
    include_state: bool = True,
    include_niit: bool = True,
    include_amt: bool = True,
    filing_status: str = 'single',
    bracket_multiplier: float = 1.0,  # Inflate brackets for future years
    state_code: str = 'CA',  # State for tax calculation (was hardcoded to CA)
    amt_credit_cf_in: float = 0.0,
    amt_credit_use_rate: float = 1.0,
    niit_threshold_override: Optional[float] = None,
    brokerage_quirks: Optional[Dict[str, Any]] = None
) -> Dict:
    """
    Calculate ACTUAL tax liability with proper marginal rates.
    
    THIS REPLACES THE BROKEN FLAT-RATE CALCULATION.
    
    Args:
        taxable_st: Short-term capital gains
        taxable_lt: Long-term capital gains
        capital_loss_deduction: Capital loss deduction (reduces ordinary income)
        ordinary_income: W-2, interest, etc.
        include_state: Include state tax
        include_niit: Include Net Investment Income Tax (3.8%)
        bracket_multiplier: Multiplier for bracket thresholds (for inflation adjustment)
    
    Returns:
        Dict with federal, state, NIIT, and total tax
    """
    fs = filing_status if filing_status in FEDERAL_TAX_BRACKETS_2024 else 'single'
    q = _merge_brokerage_tax_quirks(brokerage_quirks)
    mult = float(max(bracket_multiplier, 0.10))

    ordinary_brackets = [(float(th) * mult, float(rt)) for th, rt in FEDERAL_TAX_BRACKETS_2024.get(fs, FEDERAL_TAX_BRACKETS_2024['single'])]
    std_deduction = float(STANDARD_DEDUCTION_2024.get(fs, STANDARD_DEDUCTION_2024['single'])) * mult
    ltcg_brackets = [(float(th) * mult, float(rt)) for th, rt in LTCG_BRACKETS_2024.get(fs, LTCG_BRACKETS_2024['single'])]

    state_data = STATE_TAX_BRACKETS.get(state_code, STATE_TAX_BRACKETS['CA'])
    state_brackets = [(float(th) * mult, float(rt)) for th, rt in state_data.get(fs, state_data['single'])]
    state_std_ded = float(state_data['std_deduction'].get(fs, state_data['std_deduction']['single'])) * mult

    niit_threshold = float(NIIT_THRESHOLD_2024.get(fs, NIIT_THRESHOLD_2024['single'])) * mult
    if niit_threshold_override is not None and np.isfinite(float(niit_threshold_override)):
        niit_threshold = float(max(0.0, niit_threshold_override))

    # Brokerage reporting quirks (1099 rounding / reclassification / misc adjustments).
    quirked = _apply_brokerage_tax_quirks(
        taxable_st=taxable_st,
        taxable_lt=taxable_lt,
        ordinary_income=ordinary_income,
        quirks=q
    )
    taxable_st_adj = float(quirked['taxable_st'])
    taxable_lt_adj = float(quirked['taxable_lt'])
    ordinary_income_adj = float(quirked['ordinary_income'])
    niit_inv_adj = float(quirked['investment_income_adjustment'])

    # Ordinary income (includes W-2, interest, capital loss deduction offset)
    # Capital loss deduction REDUCES ordinary income.
    adjusted_ordinary = float(max(0.0, ordinary_income_adj - float(max(0.0, capital_loss_deduction))))

    # Federal tax on ordinary income (progressive brackets)
    federal_ordinary = calculate_marginal_tax(
        adjusted_ordinary,
        ordinary_brackets,
        std_deduction
    )

    # Short-term capital gains taxed as ordinary income
    total_ordinary_income = float(adjusted_ordinary + taxable_st_adj)
    federal_with_st = calculate_marginal_tax(
        total_ordinary_income,
        ordinary_brackets,
        std_deduction
    )
    federal_st_tax = float(max(0.0, federal_with_st - federal_ordinary))

    # Long-term capital gains (preferential rates)
    total_income = float(total_ordinary_income + taxable_lt_adj)
    
    # ========================================================================
    # LTCG TAX WITH PROPER BRACKET STACKING
    # ========================================================================
    # LTCG is "stacked" on top of ordinary income (including ST gains) and
    # taxed progressively through each LTCG bracket.
    #
    # This is the CORRECT method. The old flat-rate method was WRONG.
    #
    # Example: Single, $40k ordinary income, $50k LTCG
    #   - First $7,025 of LTCG fills 0% bracket ($40k → $47,025) = $0
    #   - Remaining $42,975 at 15% ($47,025 → $90k) = $6,446
    #   - Total: $6,446 (NOT $7,500 from flat 15% rate!)
    
    # The "base" for LTCG stacking is ordinary income AFTER standard deduction
    # (This includes both W-2 income and short-term capital gains)
    ordinary_income_for_ltcg_stacking = max(0.0, total_ordinary_income - std_deduction)
    
    federal_ltcg_tax = 0.0
    ltcg_breakdown = None
    
    if taxable_lt_adj > 0:
        federal_ltcg_tax, ltcg_breakdown = calculate_ltcg_tax_stacked(
            ltcg_amount=taxable_lt_adj,
            ordinary_income_after_deduction=ordinary_income_for_ltcg_stacking,
            ltcg_brackets=ltcg_brackets
        )
    
    federal_total_regular = float(federal_ordinary + federal_st_tax + federal_ltcg_tax)
    
    # State tax
    state_tax = 0.0
    if include_state:
        if state_data.get('cap_gains_only', False):
            # States like WA: tax applies ONLY to capital gains, not ordinary income.
            # The $250K threshold is a separate deduction against capital gains alone.
            cap_gains = taxable_st_adj + taxable_lt_adj
            state_tax = calculate_marginal_tax(cap_gains, state_brackets, state_std_ded)
        else:
            # Most states (CA, NY, NJ, IL, MA): all income taxed through state brackets
            state_income = total_income
            state_tax = calculate_marginal_tax(state_income, state_brackets, state_std_ded)
    
    # NIIT (3.8% on investment income over threshold)
    niit_tax = 0.0
    if include_niit and total_income > niit_threshold:
        investment_income = max(0.0, taxable_st_adj + taxable_lt_adj + niit_inv_adj)
        niit_base = min(investment_income, max(0.0, total_income - niit_threshold))
        niit_tax = float(niit_base * NIIT_RATE)

    # AMT interactions (tentative minimum tax + credit carryforward/usage).
    amt_info = {
        'amti': 0.0,
        'amt_exemption': 0.0,
        'amt_taxable_income': 0.0,
        'tentative_min_tax': 0.0,
        'ordinary_amt_tax': 0.0,
        'ltcg_amt_tax': 0.0
    }
    amt_tax = 0.0
    amt_credit_cf_in = float(max(0.0, amt_credit_cf_in))
    amt_credit_use_rate = float(np.clip(amt_credit_use_rate, 0.0, 1.0))
    amt_credit_used = 0.0
    amt_credit_cf_out = float(amt_credit_cf_in)

    if include_amt:
        amt_info = _compute_amt_tentative_tax(
            adjusted_ordinary=adjusted_ordinary,
            taxable_st=taxable_st_adj,
            taxable_lt=taxable_lt_adj,
            state_tax=state_tax,
            filing_status=fs,
            bracket_multiplier=mult,
            brokerage_quirks=q
        )
        tentative_min_tax = float(amt_info['tentative_min_tax'])
        amt_tax = float(max(0.0, tentative_min_tax - federal_total_regular))
        regular_excess = float(max(0.0, federal_total_regular - tentative_min_tax))
        amt_credit_used = float(min(amt_credit_cf_in * amt_credit_use_rate, regular_excess))
        amt_credit_cf_out = float(max(0.0, amt_credit_cf_in - amt_credit_used + amt_tax))

    federal_total = float(max(0.0, federal_total_regular + amt_tax - amt_credit_used))
    total_tax = float(federal_total + state_tax + niit_tax)
    
    return {
        'federal_ordinary': federal_ordinary,
        'federal_st': federal_st_tax,
        'federal_ltcg': federal_ltcg_tax,
        'federal_total_regular': federal_total_regular,
        'federal_total': federal_total,
        'state_tax': state_tax,
        'niit_tax': niit_tax,
        'niit_threshold': niit_threshold,
        'amt_tax': amt_tax,
        'amt_credit_cf_in': amt_credit_cf_in,
        'amt_credit_used': amt_credit_used,
        'amt_credit_cf_out': amt_credit_cf_out,
        'amt_detail': amt_info,
        'total_tax': total_tax,
        'effective_rate': (total_tax / total_income) if total_income > 0 else 0,
        'taxable_st_used': taxable_st_adj,
        'taxable_lt_used': taxable_lt_adj,
        'ordinary_income_used': ordinary_income_adj,
        'brokerage_quirks': q,
        'marginal_rate_used': True,
        # NEW: LTCG bracket breakdown for analysis
        'ltcg_breakdown': ltcg_breakdown,
        'ltcg_stacking_used': True
    }


def test_ltcg_stacking():
    """
    Test that LTCG stacking is working correctly.
    
    This verifies that LTCG is taxed progressively through brackets,
    not at a flat rate based on total income.
    """
    print(f"\n{'='*80}")
    print("TEST: LTCG BRACKET STACKING")
    print(f"{'='*80}\n")
    
    # Test case: Single filer, $40k ordinary income, $50k LTCG
    # LTCG brackets for single: [(47025, 0.00), (518900, 0.15), (inf, 0.20)]
    
    ordinary_income = 40000
    ltcg = 50000
    std_deduction = 14600  # 2024 single
    
    # Calculate using stacked method
    ordinary_after_deduction = max(0, ordinary_income - std_deduction)  # $25,400
    
    ltcg_brackets = [(47025, 0.00), (518900, 0.15), (float('inf'), 0.20)]
    
    tax, breakdown = calculate_ltcg_tax_stacked(
        ltcg_amount=ltcg,
        ordinary_income_after_deduction=ordinary_after_deduction,
        ltcg_brackets=ltcg_brackets
    )
    
    print(f"  Test Case: Single filer")
    print(f"    Ordinary income: ${ordinary_income:,}")
    print(f"    Standard deduction: ${std_deduction:,}")
    print(f"    Ordinary after deduction: ${ordinary_after_deduction:,}")
    print(f"    LTCG: ${ltcg:,}")
    print()
    
    # Expected calculation:
    # Ordinary fills up to $25,400
    # LTCG stacks from $25,400:
    #   - $21,625 fills 0% bracket ($25,400 → $47,025) = $0
    #   - $28,375 fills 15% bracket ($47,025 → $75,400) = $4,256.25
    # Total = $4,256.25
    
    expected_0pct_portion = 47025 - ordinary_after_deduction  # $21,625
    expected_15pct_portion = ltcg - expected_0pct_portion  # $28,375
    expected_tax = expected_0pct_portion * 0.00 + expected_15pct_portion * 0.15
    
    print(f"  EXPECTED (manual calculation):")
    print(f"    LTCG in 0% bracket: ${expected_0pct_portion:,.0f} × 0% = $0")
    print(f"    LTCG in 15% bracket: ${expected_15pct_portion:,.0f} × 15% = ${expected_15pct_portion * 0.15:,.2f}")
    print(f"    Total expected: ${expected_tax:,.2f}")
    print()
    
    print(f"  ACTUAL (from stacking function):")
    print(f"    Total LTCG tax: ${tax:,.2f}")
    if breakdown and 'breakdown' in breakdown:
        for b in breakdown['breakdown']:
            print(f"    Bracket {b['bracket_num']} ({b['rate_pct']}): "
                  f"${b['ltcg_in_bracket']:,.0f} → ${b['tax_in_bracket']:,.2f}")
    print(f"    Effective LTCG rate: {breakdown['effective_ltcg_rate']*100:.2f}%")
    print()
    
    # OLD (WRONG) method for comparison
    total_income = ordinary_income + ltcg - std_deduction  # $75,400
    if total_income > 47025:
        old_rate = 0.15
    else:
        old_rate = 0.00
    old_tax = ltcg * old_rate
    
    print(f"  OLD METHOD (flat rate - WRONG):")
    print(f"    Total income: ${total_income:,}")
    print(f"    Rate used: {old_rate*100:.0f}% (because total > $47,025)")
    print(f"    Tax: ${ltcg:,} × {old_rate*100:.0f}% = ${old_tax:,.2f}")
    print()
    
    # Compare
    difference = old_tax - tax
    print(f"  COMPARISON:")
    print(f"    Old method (wrong): ${old_tax:,.2f}")
    print(f"    New method (correct): ${tax:,.2f}")
    print(f"    Difference (tax savings): ${difference:,.2f}")
    print()
    
    # Verify
    tolerance = 0.01
    if abs(tax - expected_tax) < tolerance:
        print(f"  ✓ TEST PASSED: Stacking calculation is correct!")
    else:
        print(f"  ✗ TEST FAILED: Expected ${expected_tax:,.2f}, got ${tax:,.2f}")
    
    return abs(tax - expected_tax) < tolerance


