# Calibration-window policy:
# Use a longer calibration sample than the analysis slice when the selected
# period is recency-heavy (e.g., 2010+), to reduce parameter drift from a
# single regime era.
CALIBRATION_WINDOW_POLICY = 'auto_long'   # {'analysis_only', 'auto_long'}
CALIBRATION_LONG_START = '1985-01-01'
CALIBRATION_LONG_END_CAP = '2025-12-31'
CALIBRATION_ALT_START = '1950-01-01'
CALIBRATION_ALT_END_CAP = '2000-12-31'
CALIBRATION_MIN_YEARS = 12.0


def _years_between(start_dt: pd.Timestamp, end_dt: pd.Timestamp) -> float:
    """Calendar years between two timestamps."""
    return float((end_dt - start_dt).days / 365.25)


def resolve_calibration_window(selected_start: str,
                               selected_end: str,
                               policy: str = CALIBRATION_WINDOW_POLICY) -> Dict[str, Any]:
    """
    Choose calibration window for model fitting.

    In `auto_long` mode, prefer longer anchor windows (1985-2025, then 1950-2000)
    whenever available; otherwise fall back to the selected analysis window.
    """
    s = pd.Timestamp(selected_start)
    e = pd.Timestamp(selected_end)
    if e <= s:
        return {
            'label': 'analysis_window',
            'policy': str(policy),
            'start': str(selected_start),
            'end': str(selected_end),
            'years': 0.0,
            'source': 'analysis'
        }

    analysis = {
        'label': 'analysis_window',
        'policy': str(policy),
        'start': str(s.date()),
        'end': str(e.date()),
        'years': _years_between(s, e),
        'source': 'analysis'
    }

    if str(policy).strip().lower() != 'auto_long':
        return analysis

    cands: List[Dict[str, Any]] = []
    c1s = max(pd.Timestamp(CALIBRATION_LONG_START), pd.Timestamp(DATA_START_DATE))
    c1e = min(pd.Timestamp(CALIBRATION_LONG_END_CAP), e)
    if c1e > c1s:
        cands.append({
            'label': 'long_anchor_1985_to_recent',
            'policy': str(policy),
            'start': str(c1s.date()),
            'end': str(c1e.date()),
            'years': _years_between(c1s, c1e),
            'source': 'extended'
        })

    c2s = max(pd.Timestamp(CALIBRATION_ALT_START), pd.Timestamp(DATA_START_DATE))
    c2e = min(pd.Timestamp(CALIBRATION_ALT_END_CAP), e)
    if c2e > c2s:
        cands.append({
            'label': 'postwar_anchor_1950_to_2000',
            'policy': str(policy),
            'start': str(c2s.date()),
            'end': str(c2e.date()),
            'years': _years_between(c2s, c2e),
            'source': 'extended'
        })

    # Respect candidate order: modern long anchor (1985+) first, then postwar.
    for c in cands:
        if float(c.get('years', 0.0)) >= float(CALIBRATION_MIN_YEARS):
            chosen = dict(c)
            chosen['reason'] = 'reduce_recency_bias'
            return chosen

    analysis = dict(analysis)
    analysis['reason'] = 'fallback_selected_window'
    return analysis


def _asset_synthetic_risk_policy(asset: str) -> Dict[str, Any]:
    """
    Synthetic-window guardrails by leverage tier.
    Tighter limits for 3x funds due greater model-risk amplification.
    """
    lev = float(ASSETS.get(asset, {}).get('leverage', 1.0))
    if lev >= 3.0:
        return {
            'target_synth_pct': 45.0,
            'max_synth_pct_for_validation': 60.0,
            'min_real_windows': 60,
            'risk_tier': 'high_3x'
        }
    if lev >= 2.0:
        return {
            'target_synth_pct': 55.0,
            'max_synth_pct_for_validation': 70.0,
            'min_real_windows': 36,
            'risk_tier': 'medium_2x'
        }
    return {
        'target_synth_pct': 65.0,
        'max_synth_pct_for_validation': 80.0,
        'min_real_windows': 24,
        'risk_tier': 'low_1x'
    }


def report_synthetic_model_risk(df: pd.DataFrame) -> Dict[str, Any]:
    """Run-level synthetic/pre-inception model-risk report with leverage tiering."""
    assets = ['TQQQ', 'UPRO', 'SSO', 'QLD', 'SPY', 'QQQ']
    rows = []
    for asset in assets:
        syn_col = f'{asset}_IsSynthetic'
        if syn_col not in df.columns:
            continue
        flags = df[syn_col].fillna(False).astype(bool).to_numpy()
        n_total = int(len(flags))
        n_syn = int(np.sum(flags))
        n_real = int(n_total - n_syn)
        syn_pct = float(n_syn / n_total * 100.0) if n_total > 0 else float('nan')
        real_years = float(n_real / 252.0)
        lev = float(ASSETS.get(asset, {}).get('leverage', 1.0))
        pol = _asset_synthetic_risk_policy(asset)
        max_syn = float(pol['max_synth_pct_for_validation'])
        if lev >= 3.0 and syn_pct > max_syn:
            risk_flag = 'HIGH'
        elif syn_pct > max_syn:
            risk_flag = 'WARN'
        else:
            risk_flag = 'OK'
        rows.append({
            'asset': asset,
            'leverage': lev,
            'synthetic_pct': syn_pct,
            'real_years': real_years,
            'risk_tier': pol['risk_tier'],
            'max_synth_pct_for_validation': max_syn,
            'risk_flag': risk_flag
        })

    print(f"\n{'='*100}")
    print("SYNTHETIC PRE-INCEPTION MODEL-RISK REPORT")
    print(f"{'='*100}")
    if len(rows) == 0:
        print("  No synthetic flags available in dataset.")
        print(f"{'='*100}\n")
        return {'assets': [], 'high_risk_assets': [], 'has_high_risk': False}

    for r in rows:
        print(f"  {r['asset']:4s} | lev={r['leverage']:.1f}x | synthetic={r['synthetic_pct']:6.1f}% | "
              f"real_years={r['real_years']:5.1f} | tier={r['risk_tier']} | "
              f"limit={r['max_synth_pct_for_validation']:4.0f}% | {r['risk_flag']}")
    high_risk = [r['asset'] for r in rows if r['risk_flag'] == 'HIGH']
    if len(high_risk) > 0:
        print("  ⚠ High synthetic model-risk assets (validation caution): " + ", ".join(high_risk))
    print(f"{'='*100}\n")
    return {
        'assets': rows,
        'high_risk_assets': high_risk,
        'has_high_risk': bool(len(high_risk) > 0)
    }


def report_calibration_details(calibration_info: Dict[str, Any], regime_model: Dict) -> Dict[str, Any]:
    """Print and return calibration metadata + regime stress diagnostics."""
    rp = regime_model.get('regime_params', {}) if isinstance(regime_model, dict) else {}
    shock = rp.get(REGIME_HIGH_VOL, {})
    bear = rp.get(REGIME_BEAR, {})
    sm = regime_model.get('structural_econ_model', {}) if isinstance(regime_model, dict) else {}
    stress_freq = _regime_frequency_from_params(rp, tuple(STRESS_REGIME_IDS), use_topology=True)
    out = {
        'window_label': calibration_info.get('label', 'unknown'),
        'window_start': calibration_info.get('start', None),
        'window_end': calibration_info.get('end', None),
        'window_years': float(calibration_info.get('years', np.nan)),
        'window_source': calibration_info.get('source', None),
        'window_reason': calibration_info.get('reason', None),
        'stress_frequency_pct': float(stress_freq * 100.0) if np.isfinite(stress_freq) else None,
        'shock_frequency_pct': (
            float(shock.get('frequency_topology', shock.get('frequency', np.nan)) * 100.0)
            if np.isfinite(float(shock.get('frequency_topology', shock.get('frequency', np.nan))))
            else None
        ),
        'bear_frequency_pct': (
            float(bear.get('frequency_topology', bear.get('frequency', np.nan)) * 100.0)
            if np.isfinite(float(bear.get('frequency_topology', bear.get('frequency', np.nan))))
            else None
        ),
        'shock_median_days': float(shock.get('duration_median_days', np.nan)),
        'bear_median_days': float(bear.get('duration_median_days', np.nan)),
        'bear_p90_days': float(bear.get('duration_p90_days', np.nan)),
        'structural_cape_center': float(sm.get('cape_center', np.nan)) if isinstance(sm, dict) else None,
        'structural_cape_scale': float(sm.get('cape_scale', np.nan)) if isinstance(sm, dict) else None,
        'structural_beta_cape_annual': float(sm.get('beta_cape_annual', np.nan)) if isinstance(sm, dict) else None,
        'structural_beta_rate_annual': float(sm.get('beta_rate_annual', np.nan)) if isinstance(sm, dict) else None,
        'structural_beta_curve_annual': float(sm.get('beta_curve_annual', np.nan)) if isinstance(sm, dict) else None
    }

    print(f"\n{'='*100}")
    print("CALIBRATION DETAILS (RUN LABEL)")
    print(f"{'='*100}")
    print(f"  Window: {out['window_start']} -> {out['window_end']}  "
          f"({out['window_years']:.2f} years)  [{out['window_label']}]")
    if out.get('window_reason'):
        print(f"  Reason: {out['window_reason']}")
    print(f"  Stress frequency: {out['stress_frequency_pct'] if out['stress_frequency_pct'] is not None else float('nan'):.2f}%")
    print(f"  Shock/Bear frequency: "
          f"{out['shock_frequency_pct'] if out['shock_frequency_pct'] is not None else float('nan'):.2f}% / "
          f"{out['bear_frequency_pct'] if out['bear_frequency_pct'] is not None else float('nan'):.2f}%")
    print(f"  Spell lengths (median / p90): "
          f"shock={out['shock_median_days']:.0f}d, "
          f"bear={out['bear_median_days']:.0f}d, "
          f"bear_p90={out['bear_p90_days']:.0f}d")
    if np.isfinite(out.get('structural_beta_cape_annual', np.nan)):
        print(f"  Structural drivers: CAPE_center={out['structural_cape_center']:.2f}, "
              f"CAPE_scale={out['structural_cape_scale']:.2f}, "
              f"beta_cape={out['structural_beta_cape_annual']:+.4f}/yr, "
              f"beta_rate={out['structural_beta_rate_annual']:+.4f}/yr, "
              f"beta_curve={out['structural_beta_curve_annual']:+.4f}/yr")
    print(f"{'='*100}\n")
    return out


def load_calibration_dataframe(selected_df: pd.DataFrame,
                               selected_start: str,
                               selected_end: str,
                               scenario_name: str) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    """
    Load calibration dataframe according to calibration-window policy.
    Falls back to selected_df when extended fetch is unavailable.
    """
    global ANALYSIS_START_DATE, ANALYSIS_END_DATE

    info = resolve_calibration_window(selected_start=selected_start, selected_end=selected_end)
    cal_start = str(info.get('start', selected_start))
    cal_end = str(info.get('end', selected_end))

    # Selected data already covers requested calibration window.
    if (pd.Timestamp(cal_start) >= pd.Timestamp(selected_start) and
            pd.Timestamp(cal_end) <= pd.Timestamp(selected_end)):
        cal_df = selected_df.loc[cal_start:cal_end].copy()
        if len(cal_df) == 0:
            cal_df = selected_df.copy()
            info['reason'] = 'fallback_empty_subset'
        info['load_mode'] = 'selected_subset'
        info['n_days'] = int(len(cal_df))
        info['n_years_trading'] = float(len(cal_df) / 252.0)
        return cal_df, info

    old_start = ANALYSIS_START_DATE
    old_end = ANALYSIS_END_DATE
    ext_df = None
    try:
        ANALYSIS_START_DATE = cal_start
        ANALYSIS_END_DATE = cal_end
        configure_cache_paths(start_date=cal_start, end_date=cal_end, scenario_name=scenario_name)
        print(f"\nLoading extended calibration data window: {cal_start} -> {cal_end}")
        ext_df = fetch_historical_data()
    except Exception as e:
        print(f"  ⚠ Extended calibration-data load failed ({e}); using selected window data")
        ext_df = None
    finally:
        ANALYSIS_START_DATE = old_start
        ANALYSIS_END_DATE = old_end
        configure_cache_paths(start_date=selected_start, end_date=selected_end, scenario_name=scenario_name)

    if ext_df is None or len(ext_df) == 0:
        cal_df = selected_df.copy()
        info['reason'] = 'fallback_selected_window_load_error'
        info['load_mode'] = 'fallback_selected'
    else:
        cal_df = ext_df.loc[cal_start:cal_end].copy()
        if len(cal_df) == 0:
            cal_df = selected_df.copy()
            info['reason'] = 'fallback_selected_window_empty_extended_slice'
            info['load_mode'] = 'fallback_selected'
        else:
            info['load_mode'] = 'extended_fetch'

    info['n_days'] = int(len(cal_df))
    info['n_years_trading'] = float(len(cal_df) / 252.0)
    return cal_df, info
