@dataclass(frozen=True)
class ScenarioResolution:
    input_key: Optional[str]
    canonical_key: str
    engine_key: str
    display_name: str
    source: str


def _normalize_scenario_key(key: Optional[str]) -> str:
    raw = str(key).strip().lower() if key is not None else ''
    if not raw:
        raw = 'neutral'
    return _SCENARIO_ALIAS_TO_CANONICAL.get(raw, 'neutral')


def _scenario_display_name_for_key(key: Optional[str]) -> str:
    canonical = _normalize_scenario_key(key)
    return _SCENARIO_DISPLAY_NAMES.get(canonical, canonical.replace('_', ' ').title())


def _scenario_engine_key_for_key(key: Optional[str]) -> str:
    canonical = _normalize_scenario_key(key)
    return _SCENARIO_CANONICAL_TO_ENGINE.get(canonical, canonical)


def _is_extended_historical_backtest_key(key: Optional[str]) -> bool:
    return _normalize_scenario_key(key) == 'extended_historical_backtest'


def select_primary_scenario_interactive() -> str:
    """
    Interactive institutional scenario menu.
    Shows the 5 primary scenarios only and returns the canonical scenario key.
    """
    current_canonical = _normalize_scenario_key(MARKET_SCENARIO)
    primary_keys = {row[0] for row in _PRIMARY_SCENARIO_MENU.values()}
    if current_canonical not in primary_keys:
        current_canonical = 'neutral'

    print(f"\n{'='*80}")
    print("SELECT MARKET SCENARIO")
    print(f"{'='*80}\n")
    print("  Choose the scenario for this run:\n")
    for opt, (canonical_key, desc) in _PRIMARY_SCENARIO_MENU.items():
        marker = ' ◄ active' if canonical_key == current_canonical else ''
        print(f"    {opt}. {desc}{marker}")
    print(f"\n  Current: '{_SCENARIO_DISPLAY_NAMES.get(current_canonical, current_canonical)}'")
    print("  [Press Enter to keep current]\n")

    try:
        choice = input("  Enter scenario (1-5) [default = keep current]: ").strip()
    except EOFError:
        choice = ''

    if choice in _PRIMARY_SCENARIO_MENU:
        return _PRIMARY_SCENARIO_MENU[choice][0]
    if choice == '':
        return current_canonical
    print("  Invalid choice — keeping current scenario.")
    return current_canonical


def resolve_selected_scenario(config_scenario: Optional[str] = None) -> ScenarioResolution:
    """
    Resolve a scenario key into canonical + engine keys.

    If config_scenario is None, the interactive 5-option institutional menu is shown.
    Otherwise the provided key is treated as a config override and no menu is displayed.
    """
    if config_scenario is None:
        chosen = select_primary_scenario_interactive()
        source = 'interactive selection'
        input_key = None
    else:
        chosen = str(config_scenario).strip()
        source = 'config override'
        input_key = chosen

    canonical = _normalize_scenario_key(chosen)
    engine_key = _scenario_engine_key_for_key(canonical)
    display_name = _scenario_display_name_for_key(canonical)
    assert canonical is not None
    return ScenarioResolution(
        input_key=input_key,
        canonical_key=canonical,
        engine_key=engine_key,
        display_name=display_name,
        source=source,
    )

# ── Crisis parameter naming convention ────────────────────────────────────────
# Two parameters control crisis dynamics.  Both use >1 = "more severe" by design,
# but through OPPOSITE arithmetic on the empirical dwell-time draw:
#
#   crisis_prob_scale  — FREQUENCY knob (how often crises begin)
#     spell_calm_scaled = spell_drawn / crisis_prob_scale   ← DIVIDES calm spell
#     >1 → shorter calm spells → more frequent entries into crisis
#     Mnemonic: "prob" = how probable a crisis is each calm day
#
#   crisis_dwell_scale — DURATION knob (how long crises last)
#     spell_crisis_scaled = spell_drawn × crisis_dwell_scale  ← MULTIPLIES crisis spell
#     >1 → longer crisis spells → grinding bear markets
#     Mnemonic: "dwell" = how long the market dwells in crisis
#
# The asymmetry (÷ vs ×) is intentional: both knobs are "intuitive" (bigger = worse)
# but operate on different states via different arithmetic.  See the docstring of
# simulate_regime_path_semi_markov() for the full explanation.
# ──────────────────────────────────────────────────────────────────────────────

_SCENARIO_PRESETS = {
    'neutral': {
        # drift_tilt: extra annual arithmetic drift overlay (decimal, e.g. 0.02 = +2%/yr).
        # Applied to SPY and QQQ daily returns as drift_tilt/252.  0.0 = calibrated only.
        #
        # CALIBRATION NOTE (B8-3): Neutral mode uses the raw calibrated drift from the
        # GJR-GARCH model (~7.8%/yr annualised from 2010-2026 data), which is ~170 bps
        # below the long-run S&P 500 mean (~9.5%).  Over 20 years this gap compounds
        # to ~40% lower terminal wealth.  For long-run empirical projections, use
        # 'historical' mode, which auto-anchors the drift to HISTORICAL_NOMINAL_CAGR_TARGET
        # (9.5%) via drift_tilt.  Neutral is correct for pure stochastic model evaluation.
        'drift_tilt':         0.0,
        # crisis_prob_scale: crisis FREQUENCY knob — controls how often crises begin.
        # Mechanism: DIVIDES the calm-state empirical dwell-time draw:
        #   spell_calm_scaled = spell_drawn / crisis_prob_scale
        # Larger value → shorter calm spells → more frequent crisis entries.
        # 2.0 → 2× entry frequency; 0.5 → ½ entry frequency.
        # ASYMMETRY: this DIVIDES the calm spell, whereas crisis_dwell_scale (below)
        # MULTIPLIES the crisis spell.  Both >1 = "more severe" by design.
        # TM[0,1] scaling has no effect in 2-state semi-Markov (next state is
        # always the other state after each spell ends).
        'crisis_prob_scale':  1.0,
        # div_yield: annual dividend yield added as a constant daily credit (div_yield/252).
        # Converts price return to approximate total return.  0.0 = price return only.
        'div_yield':          0.0,
        # inflation: for real-return display only — not applied in simulation.
        # Real CAGR ≈ nominal CAGR − inflation.
        'inflation':          0.0,
        # vol_scale_calm / vol_scale_crisis: multiplicative scale on the GARCH-generated
        # return series within each regime.  Applied before jump and drift overlays.
        # 0.77 → calm vol reduced from 15% to ~11.5%.  1.20 → elevated to ~18%.
        'vol_scale_calm':     1.00,
        'vol_scale_crisis':   1.00,
        # borrow_spread_override: if not None, clamps the predicted LETF financing spread
        # to [low, high] percent (converted to decimal internally).
        # None = use calibrated funding model (default).
        'borrow_spread_override': None,
        # tracking_error_multiplier: scales the base TE for every LETF.
        # 1.75 = 75% more tracking error (stressed markets); 0.75 = tighter tracking.
        'tracking_error_multiplier': 1.0,
        # fat_tail_factor: scales the jump component drawn from the stress-state model.
        # 1.6 → heavier-tailed crisis moves; 0.6 → lighter tails (near-Gaussian).
        'fat_tail_factor':    1.0,
        # normal_spy_tlt_corr: calm-regime SPY↔TLT correlation override used by
        # scenario overlays.  Application scope is controlled by
        # correlation_override_scope below:
        #   - 'portfolio_only': strategy optimization matrices only
        #   - 'generator_only': SPY/QQQ/TLT return generator only
        #   - 'both': apply to both layers
        # None = use calibrated matrix.  −0.20 = strong flight-to-quality hedge.
        # +0.05 = stagflation (stocks and bonds fall together).
        'normal_spy_tlt_corr':  None,
        # crisis_corr_spike: additive TLT-correlation increase in stress regimes.
        # e.g. normal=−0.10, spike=+0.12 → crisis portfolio-optimisation corr = +0.02.
        'crisis_corr_spike':    None,
        # Scope for correlation overrides:
        #   'portfolio_only' | 'generator_only' | 'both'
        'correlation_override_scope': 'portfolio_only',
        # crisis_dwell_scale: crisis DURATION knob — controls how long each crisis lasts.
        # Mechanism: MULTIPLIES the crisis-state empirical dwell-time draw:
        #   spell_crisis_scaled = spell_drawn × crisis_dwell_scale
        # > 1 → longer crisis spells / grinding bear markets (2008/1970s-style).
        # < 1 → shorter crisis spells / brief shocks (COVID-style recovery).
        # = 1 → calibrated baseline.
        # ASYMMETRY: this MULTIPLIES the crisis spell, whereas crisis_prob_scale (above)
        # DIVIDES the calm spell.  Both >1 = "more severe" by design.  See the full
        # explanation in simulate_regime_path_semi_markov() docstring.
        'crisis_dwell_scale':   1.0,
        # qqq_jump_amp: multiplier applied to the stress/jump series before adding to
        # QQQ returns. QQQ has historically amplified SPY gap-moves (~1.35× empirical).
        # Configurable here so pessimistic/optimistic scenarios can tune tail sensitivity.
        'qqq_jump_amp':         1.35,
        # Historical direct-return mode (real contiguous return slices, no synthetic overlay).
        'historical_use_real_returns': False,
    },
    'historical_backtest': {
        # ─────────────────────────────────────────────────────────────────────
        # INSTITUTIONAL-GRADE HISTORICAL BACKTEST MODE  (v1.5 — sole historical mode)
        #
        # Uses real daily driver returns for the EXACT selected analysis window.
        # Underlying index returns (SPY/QQQ/TLT/IRX) come directly from the
        # Fama-French + yfinance pipeline, sliced to [ANALYSIS_START_DATE,
        # ANALYSIS_END_DATE].  NO synthetic drift/vol/jump overlays.
        #
        # Fund emulation layer (financing spread, TE residuals) IS applied and
        # calibrated post-inception.  Circuit breakers are DISABLED for driver
        # returns — they apply only at the fund-mechanics layer if configured.
        #
        # SPY baseline matches real historical total-return exactly.
        # Inflation-adjusted returns use FRED CPIAUCSL (loaded at startup).
        # Borrowing cost: (leverage-1) × (rf + spread) / 252 per day.
        #
        # Key design invariants:
        #   A) max(|driver_original - driver_used|) == 0  (enforced by test)
        #   B) div_yield = 0   (dividends already in FF total-return series)
        #   C) fat_tail_factor = 0  (no synthetic jumps on driver series)
        #   D) Regime path used ONLY for financing / TE layers, not for returns
        # ─────────────────────────────────────────────────────────────────────
        'drift_tilt':         0.0,
        'div_yield':          0.0,    # dividends already embedded in total return series
        'inflation':          HISTORICAL_INFLATION,   # updated at runtime from FRED CPI
        'crisis_prob_scale':  1.0,
        'crisis_dwell_scale': 1.0,
        'vol_scale_calm':     1.0,    # NO vol scaling — real returns are immutable
        'vol_scale_crisis':   1.0,
        'borrow_spread_override': None,
        'tracking_error_multiplier': 1.0,
        'fat_tail_factor':    0.0,    # ZERO — no synthetic jumps on driver returns
        'normal_spy_tlt_corr':  None,
        'crisis_corr_spike':    None,
        'correlation_override_scope': 'portfolio_only',
        'qqq_jump_amp':         1.0,
        'historical_use_real_returns': False,  # legacy flag (unused; window data is in hist_data)
        '_hist1926_mode':     'backtest',       # chronological slice, no wrap
        '_hist1926_block_size': 63,
        '_is_reconstruction': True,             # marker for special handling in pipeline
    },
    'historical_bootstrap': {
        # ─────────────────────────────────────────────────────────────────────
        # INSTITUTIONAL-GRADE HISTORICAL BLOCK BOOTSTRAP  (v1.6 — Pipeline E)
        #
        # Uses the user-selected [ANALYSIS_START_DATE, ANALYSIS_END_DATE] daily
        # driver-return dataset as the population pool.
        # For each Monte Carlo path, contiguous 63-day blocks are drawn at
        # random (with replacement) and concatenated until the horizon is filled.
        # This preserves volatility clustering and crash structure WITHIN each
        # block while randomising the sequence of market regimes ACROSS blocks.
        #
        # Purpose: test sequence-of-returns risk across the widest possible
        # historical envelope without constraining to a single window.
        #
        # Key design invariants:
        #   A) Returns within each block are NEVER modified (pure real data).
        #   B) No GARCH / Student-t / regime path used for driver returns.
        #   C) No drift_tilt, div_yield, vol_scale, or jump overlays.
        #   D) fat_tail_factor = 0  (no synthetic jump overlay on drivers).
        #   E) Fund emulation layer (financing, TE) IS applied — calibrated.
        #   F) Multiple paths = multiple random block sequences (stochastic).
        # ─────────────────────────────────────────────────────────────────────
        'drift_tilt':         0.0,
        'div_yield':          0.0,   # dividends embedded in total-return series
        'inflation':          HISTORICAL_INFLATION,
        'crisis_prob_scale':  1.0,
        'crisis_dwell_scale': 1.0,
        'vol_scale_calm':     1.0,   # NO vol scaling — real block returns are immutable
        'vol_scale_crisis':   1.0,
        'borrow_spread_override': None,
        'tracking_error_multiplier': 1.0,
        'fat_tail_factor':    0.0,   # ZERO — no synthetic jumps on driver returns
        'normal_spy_tlt_corr':  None,
        'crisis_corr_spike':    None,
        'correlation_override_scope': 'portfolio_only',
        'qqq_jump_amp':         1.0,
        'historical_use_real_returns': False,  # legacy flag (unused in this pipeline)
        '_hist1926_mode':     'bootstrap',     # random contiguous-block assembly
        '_hist1926_block_size': 63,            # configurable block length (trading days)
        'bootstrap_seed':     None,            # set int for reproducible block stitching
        'bootstrap_method':   'fixed',         # 'fixed' | 'stationary'
        'stationary_p':       None,            # stationary bootstrap restart prob (default=1/block_size)
        '_is_reconstruction': False,           # bootstrap is stochastic — not deterministic
    },
    'pessimistic': {
        'drift_tilt':        -0.02,    # −2%/yr intentional overlay
        'crisis_prob_scale':  2.0,     # 2× crisis entry frequency (shorter calm spells)
        'div_yield':          0.015,
        'inflation':          0.04,
        'vol_scale_calm':     1.20,    # calm vol: 15% → ~18%
        'vol_scale_crisis':   1.25,    # crisis vol: 40% → ~50%
        # Borrow spreads blow out under credit stress (GFC repo, March-2020 analog).
        # Values in percent: 0.85–2.20% above SOFR.
        'borrow_spread_override': {'low': 0.85, 'high': 2.20},
        'tracking_error_multiplier': 1.75,  # sustained TE deterioration in stressed markets
        'fat_tail_factor':    1.60,    # heavier jump tails (1970s oil-shock clustering)
        'normal_spy_tlt_corr':  0.05,  # stagflation: stocks & bonds fall together
        'crisis_corr_spike':    0.28,  # all equities converge; diversification fails
        'correlation_override_scope': 'both',
        'crisis_dwell_scale':   2.0,   # 2× crisis duration → grinding bear markets (2008/1970s-style)
        'qqq_jump_amp':         1.50,  # amplified QQQ jump sensitivity in stressed markets
        'historical_use_real_returns': False,
    },
    'optimistic': {
        'drift_tilt':        +0.02,    # +2%/yr intentional overlay
        'crisis_prob_scale':  0.5,     # 0.5× crisis entry frequency (longer calm spells)
        'div_yield':          0.020,
        'inflation':          0.02,
        'vol_scale_calm':     0.77,    # calm vol: 15% → ~11.5% (2013-2019 analog)
        'vol_scale_crisis':   0.70,    # crisis vol: 40% → ~28% (shallow corrections)
        # Tight spreads: ample prime-broker liquidity, compressed credit.
        'borrow_spread_override': {'low': 0.20, 'high': 0.45},
        'tracking_error_multiplier': 0.75,  # tight tracking in high-liquidity environment
        'fat_tail_factor':    0.60,    # lighter tails; abundant liquidity dampens jumps
        'normal_spy_tlt_corr':  -0.20,  # strong flight-to-quality (inflation anchored)
        'crisis_corr_spike':    0.08,   # shallow, idiosyncratic corrections
        'correlation_override_scope': 'both',
        'crisis_dwell_scale':   0.5,    # 0.5× crisis duration → brief shocks (COVID-style)
        'qqq_jump_amp':         1.20,  # muted QQQ jump sensitivity in high-liquidity regime
        'historical_use_real_returns': False,
    },
    # 'custom' is handled dynamically in get_scenario() via CUSTOM_SCENARIO_PARAMS.
}


def refresh_scenario_calibration(df: Optional[pd.DataFrame],
                                 regime_model: Optional[Dict[str, Any]] = None,
                                 verbose: bool = True) -> Dict[str, Any]:
    """
    Recalibrate scenario overlays from historical statistics (no arbitrary fixed scaling).
    """
    global _SCENARIO_CALIBRATED_PRESETS, _SCENARIO_CALIBRATION_META

    calibrated: Dict[str, Dict[str, Any]] = {}
    meta: Dict[str, Any] = {
        'available': False,
        'window_start': None,
        'window_end': None,
        'window_years': float('nan')
    }

    if df is None or len(df) < 252 * 5 or 'SPY_Ret' not in df.columns:
        _SCENARIO_CALIBRATED_PRESETS = calibrated
        _SCENARIO_CALIBRATION_META = meta
        return meta

    spy = df['SPY_Ret'].to_numpy(dtype=float)
    spy = spy[np.isfinite(spy)]
    if len(spy) < 252 * 5:
        _SCENARIO_CALIBRATED_PRESETS = calibrated
        _SCENARIO_CALIBRATION_META = meta
        return meta

    # Annual return quantiles anchor scenario drift overlays.
    annual_ret = df['SPY_Ret'].groupby(df.index.year).apply(lambda x: float(np.prod(1.0 + x.fillna(0.0).to_numpy(dtype=float)) - 1.0))
    annual_ret = annual_ret.replace([np.inf, -np.inf], np.nan).dropna()
    if len(annual_ret) >= 5:
        ann_p25 = float(np.percentile(annual_ret, 25))
        ann_p50 = float(np.percentile(annual_ret, 50))
        ann_p75 = float(np.percentile(annual_ret, 75))
    else:
        ann_mu = float(np.nanmean(spy) * 252.0)
        ann_std = float(np.nanstd(spy) * np.sqrt(252))
        ann_p50 = ann_mu
        ann_p25 = ann_mu - 0.67 * ann_std
        ann_p75 = ann_mu + 0.67 * ann_std

    # Rolling-vol quantiles anchor scenario volatility scales.
    rv = (df['SPY_Ret'].rolling(252, min_periods=160).std() * np.sqrt(252)).dropna().to_numpy(dtype=float)
    if len(rv) > 0:
        rv = rv[::21]
    if len(rv) < 20:
        rv = np.asarray([float(np.nanstd(spy) * np.sqrt(252))], dtype=float)
    vol_p25 = float(np.percentile(rv, 25))
    vol_p50 = float(np.percentile(rv, 50))
    vol_p75 = float(np.percentile(rv, 75))
    vol_ratio_low = float(np.clip(vol_p25 / max(vol_p50, 1e-8), 0.5, 1.0))
    vol_ratio_high = float(np.clip(vol_p75 / max(vol_p50, 1e-8), 1.0, 2.0))

    # Stress occupancy and spell lengths anchor crisis frequency/duration scales.
    regs_hist = None
    if isinstance(regime_model, dict) and 'regimes_historical' in regime_model:
        arr = np.asarray(regime_model.get('regimes_historical', []), dtype=int)
        if len(arr) == len(df):
            regs_hist = arr
    stress_share = float('nan')
    stress_q25 = float('nan')
    stress_q50 = float('nan')
    stress_q75 = float('nan')
    stress_spell_q25 = float('nan')
    stress_spell_q50 = float('nan')
    stress_spell_q75 = float('nan')
    if regs_hist is not None and len(regs_hist) > 0:
        stress_mask = np.isin(regs_hist, np.asarray(STRESS_REGIME_IDS, dtype=int))
        stress_share = float(np.mean(stress_mask))
        by_year = pd.Series(stress_mask.astype(float), index=df.index).groupby(df.index.year).mean().dropna().to_numpy(dtype=float)
        if len(by_year) >= 5:
            stress_q25 = float(np.percentile(by_year, 25))
            stress_q50 = float(np.percentile(by_year, 50))
            stress_q75 = float(np.percentile(by_year, 75))
        else:
            stress_q25 = stress_q50 = stress_q75 = stress_share
        episodes = _extract_boolean_episodes(stress_mask.astype(bool))
        lens = np.asarray([e - s + 1 for s, e in episodes], dtype=float) if episodes else np.array([])
        if len(lens) >= 5:
            stress_spell_q25 = float(np.percentile(lens, 25))
            stress_spell_q50 = float(np.percentile(lens, 50))
            stress_spell_q75 = float(np.percentile(lens, 75))
        elif len(lens) > 0:
            stress_spell_q25 = stress_spell_q50 = stress_spell_q75 = float(np.median(lens))

    # Scenario overlays derived from empirical quantiles.
    optimistic_drift = float(np.clip(0.65 * max(ann_p75 - ann_p50, 0.0), 0.0, 0.030))
    pessimistic_drift = float(np.clip(0.65 * min(ann_p25 - ann_p50, 0.0), -0.040, 0.0))

    optimistic_vol_calm = float(np.clip(0.92 + 0.25 * (vol_ratio_low - 0.75), 0.82, 1.03))
    pessimistic_vol_calm = float(np.clip(1.02 + 0.70 * (vol_ratio_high - 1.0), 0.95, 1.35))
    optimistic_vol_crisis = float(np.clip(0.86 + 0.35 * (vol_ratio_low - 0.75), 0.78, 1.05))
    pessimistic_vol_crisis = float(np.clip(1.06 + 0.85 * (vol_ratio_high - 1.0), 1.00, 1.55))

    if np.isfinite(stress_q50) and stress_q50 > 1e-8:
        optimistic_crisis_prob = float(np.clip(stress_q25 / stress_q50, 0.55, 1.00))
        pessimistic_crisis_prob = float(np.clip(stress_q75 / stress_q50, 1.00, 2.20))
    else:
        optimistic_crisis_prob = 0.80
        pessimistic_crisis_prob = 1.35

    if np.isfinite(stress_spell_q50) and stress_spell_q50 > 1e-8:
        optimistic_crisis_dwell = float(np.clip(stress_spell_q25 / stress_spell_q50, 0.55, 1.00))
        pessimistic_crisis_dwell = float(np.clip(stress_spell_q75 / stress_spell_q50, 1.00, 2.10))
    else:
        optimistic_crisis_dwell = 0.80
        pessimistic_crisis_dwell = 1.35

    down_all = float(abs(np.percentile(spy, 1)))
    if regs_hist is not None and len(regs_hist) == len(df):
        stress_sub = df['SPY_Ret'].to_numpy(dtype=float)[np.isin(regs_hist, np.asarray(STRESS_REGIME_IDS, dtype=int))]
        stress_sub = stress_sub[np.isfinite(stress_sub)]
        down_stress = float(abs(np.percentile(stress_sub, 1))) if len(stress_sub) >= 100 else down_all * 1.4
    else:
        down_stress = down_all * 1.4
    tail_ratio = float(np.clip(down_stress / max(down_all, 1e-8), 1.0, 3.0))
    optimistic_tail = float(np.clip(1.0 / tail_ratio, 0.60, 0.95))
    pessimistic_tail = float(np.clip(tail_ratio, 1.05, 1.90))

    calibrated['neutral'] = {}
    # historical_backtest needs no calibration overrides — the preset pins all overlays
    # to zero and the driver data is loaded separately from the FF + yfinance pipeline.
    calibrated['historical_backtest'] = {}   # driver returns are real; no overlay calibration
    # historical_bootstrap likewise uses pure real block returns — no overlay calibration.
    calibrated['historical_bootstrap'] = {}  # block bootstrap from selected window pool
    calibrated['optimistic'] = {
        'drift_tilt': optimistic_drift,
        'crisis_prob_scale': optimistic_crisis_prob,
        'crisis_dwell_scale': optimistic_crisis_dwell,
        'vol_scale_calm': optimistic_vol_calm,
        'vol_scale_crisis': optimistic_vol_crisis,
        'fat_tail_factor': optimistic_tail
    }
    calibrated['pessimistic'] = {
        'drift_tilt': pessimistic_drift,
        'crisis_prob_scale': pessimistic_crisis_prob,
        'crisis_dwell_scale': pessimistic_crisis_dwell,
        'vol_scale_calm': pessimistic_vol_calm,
        'vol_scale_crisis': pessimistic_vol_crisis,
        'fat_tail_factor': pessimistic_tail
    }

    meta = {
        'available': True,
        'window_start': str(pd.Timestamp(df.index[0]).date()),
        'window_end': str(pd.Timestamp(df.index[-1]).date()),
        'window_years': float(len(df) / 252.0),
        'annual_return_p25': float(ann_p25),
        'annual_return_p50': float(ann_p50),
        'annual_return_p75': float(ann_p75),
        'rolling_vol_p25': float(vol_p25),
        'rolling_vol_p50': float(vol_p50),
        'rolling_vol_p75': float(vol_p75),
        'stress_share': float(stress_share) if np.isfinite(stress_share) else None,
        'stress_share_q25': float(stress_q25) if np.isfinite(stress_q25) else None,
        'stress_share_q50': float(stress_q50) if np.isfinite(stress_q50) else None,
        'stress_share_q75': float(stress_q75) if np.isfinite(stress_q75) else None,
        'stress_spell_q25': float(stress_spell_q25) if np.isfinite(stress_spell_q25) else None,
        'stress_spell_q50': float(stress_spell_q50) if np.isfinite(stress_spell_q50) else None,
        'stress_spell_q75': float(stress_spell_q75) if np.isfinite(stress_spell_q75) else None
    }

    _SCENARIO_CALIBRATED_PRESETS = calibrated
    _SCENARIO_CALIBRATION_META = meta

    if bool(verbose):
        print("  Scenario overlays recalibrated from historical quantiles "
              f"[{meta['window_start']} -> {meta['window_end']}, {meta['window_years']:.2f}y]")
    return meta


def _load_historical_1926_data(df: pd.DataFrame) -> None:
    """
    Populate _HIST1926_* globals from the best available data source.

    Priority order:
      1. pandas_datareader Fama-French daily ('F-F_Research_Data_Factors_daily')
         → total return = (Mkt-RF + RF) / 100; date range 1926-07-01 to present.
      2. `df` columns SPY_Ret, QQQ_Ret, TLT_Ret, IRX as fallback.

    QQQ proxy — strict per-day priority (v1.5):
      Tier 1b: df['QQQ_Ret']     — actual QQQ ETF from yfinance (post-1999); highest fidelity.
      Tier 1a: df['NASDAQ_Ret']  — ^IXIC composite from yfinance (post-1971).
      Tier 2:  FF 49-industry 'HiTec' value-weighted portfolio (1926+).
      None     — NaN; dropped by dropna().  In historical_backtest mode a
                 RuntimeError is raised if all three sources are unavailable.
                 In stochastic mode SPY×1.25 beta is used as last-resort fill with
                 a loud warning; historical_backtest will be rejected if attempted.
    TLT proxy: df['TLT_Ret'] or inverse-correlation approximation (SPY×-0.25 + RF).
    IRX: annual pct-points (e.g. 5.0 = 5%/yr).

    Idempotent — safe to call multiple times; re-populates on each call.
    """
    global _HIST1926_SPY, _HIST1926_QQQ, _HIST1926_TLT, _HIST1926_IRX, \
           _HIST1926_N, _HIST1926_DATES, _HIST1926_NASDAQ, _HIST1926_NASDAQ_SOURCE
    # Reset source tag each call so stale values from a previous call do not persist.
    _HIST1926_NASDAQ_SOURCE = 'unknown'
    if df is not None and isinstance(df, pd.DataFrame) and len(df) > 0:
        # Ensure strict real-only driver columns are available even when old cache
        # artifacts are passed directly into this loader.
        df = _attach_real_only_driver_columns(df)

    ff_df = None
    _seed_attempted = False
    _ffd: Optional[pd.DataFrame] = None
    try:
        import pandas_datareader.data as _web
        _raw = _web.DataReader('F-F_Research_Data_Factors_daily', 'famafrench',
                               start='1926-01-01', end=None)
        _ffd = _raw[0].copy()
        _save_local_ff_factors_daily(_ffd, source='network_datareader')
    except Exception as _e:
        print(f"  [hist1926] FF fetch failed ({_e}); trying local persisted fallback.")
        if not _seed_attempted:
            _seed_attempted = True
            _seed_local_ff_caches_from_historical_cache(verbose=True)
        _ffd = _load_local_ff_factors_daily()
        if _ffd is not None and len(_ffd) > 0:
            print(f"  [hist1926] Using local FF factors fallback: {len(_ffd):,} days "
                  f"({_ffd.index[0].date()} → {_ffd.index[-1].date()})")

    if _ffd is not None and len(_ffd) > 0:
        ff_df = pd.DataFrame(index=_ffd.index)
        ff_df['SPY_Ret'] = (_ffd['Mkt-RF'] + _ffd['RF']) / 100.0
        ff_df['RF']      = _ffd['RF'] / 100.0                    # daily decimal
        ff_df['IRX']     = _ffd['RF'] * 252.0                    # annualised pct-points
        # QQQ proxy: strict priority (Tier 1b QQQ_Real > Tier 1a NASDAQ_Composite > Tier 2 FF49_HiTec).
        # Days with no real source remain NaN and are eliminated by dropna() at the end.
        # beta_proxy (SPY×1.25) is NOT used as a per-day initialiser — it is only a last-resort
        # fallback in stochastic (non-reconstruction) mode when ALL three real sources fail entirely.
        ff_df['QQQ_Ret'] = np.nan
        # TLT proxy: crude inverse-correlation using daily RF as anchor
        ff_df['TLT_Ret'] = ff_df['SPY_Ret'] * (-0.25) + ff_df['RF']
        ff_df = ff_df.dropna(subset=['SPY_Ret'])
        print(f"  [hist1926] Loaded Fama-French daily: {len(ff_df):,} days "
              f"({ff_df.index[0].date()} → {ff_df.index[-1].date()})")
    else:
        print("  [hist1926] No FF factors available (network+local fallback unavailable); "
              "falling back to df columns.")

    # ── NASDAQ proxy: Tier 2 — FF 49-industry HiTec value-weighted portfolio ──────
    # This is the preferred long-history proxy (1926+) when yfinance is unavailable.
    _ff_hitech_series: Optional[pd.Series] = None
    try:
        import pandas_datareader.data as _web2
        _hitech_raw = _web2.DataReader('49_Industry_Portfolios_Daily', 'famafrench',
                                       start='1926-01-01', end=None)
        # Index 0 = equal-weighted, index 1 = value-weighted; prefer value-weighted.
        _hitech_idx = 1 if len(_hitech_raw) > 1 else 0
        _hitech_vw = _hitech_raw[_hitech_idx].copy()
        _htcol = 'HiTec' if 'HiTec' in _hitech_vw.columns else None
        if _htcol is None:
            # Try alternate spelling
            for _col in _hitech_vw.columns:
                if 'hi' in _col.lower() and 'tec' in _col.lower():
                    _htcol = _col
                    break
        if _htcol is not None:
            _save_local_ff49_hitec_daily(_hitech_vw[_htcol], unit='pct', source='network_datareader')
            # FF industry returns are in % → divide by 100; -99.99 marks missing values
            _hitech_ret = _hitech_vw[_htcol] / 100.0
            _hitech_ret = _hitech_ret[_hitech_ret > -0.99]  # drop missing-value markers
            _ff_hitech_series = _hitech_ret.rename('QQQ_Ret')
            print(f"  [hist1926] FF 49-industry HiTec loaded: {len(_ff_hitech_series):,} days "
                  f"({_ff_hitech_series.index[0].date()} → {_ff_hitech_series.index[-1].date()})")
        else:
            _col_preview = ', '.join([str(c) for c in list(_hitech_vw.columns)[:12]])
            print("  [hist1926] FF 49-industry: 'HiTec' column not found; skipping Tier 2. "
                  f"Available columns(sample): {_col_preview}")
            # Dataset schema drift: if network fetch succeeds but HiTec label is missing,
            # still attempt local persisted HiTec fallback before giving up Tier 2.
            if not _seed_attempted:
                _seed_attempted = True
                _seed_local_ff_caches_from_historical_cache(verbose=True)
            _hitech_local, _hitech_unit = _load_local_ff49_hitec_daily()
            if _hitech_local is not None and len(_hitech_local) > 0:
                if str(_hitech_unit).lower() == 'pct':
                    _hitech_ret = (_hitech_local / 100.0)
                    _hitech_ret = _hitech_ret[_hitech_ret > -0.99]
                else:
                    _hitech_ret = _hitech_local.copy()
                _ff_hitech_series = _hitech_ret.rename('QQQ_Ret')
                print(f"  [hist1926] Using local FF49 HiTec fallback: {len(_ff_hitech_series):,} days "
                      f"({_ff_hitech_series.index[0].date()} → {_ff_hitech_series.index[-1].date()})")
            else:
                print("  [hist1926] Local FF49 HiTec fallback unavailable; Tier 2 unavailable.")
    except Exception as _he:
        print(f"  [hist1926] FF HiTech fetch failed ({_he}); trying local persisted fallback.")
        if not _seed_attempted:
            _seed_attempted = True
            _seed_local_ff_caches_from_historical_cache(verbose=True)
        _hitech_local, _hitech_unit = _load_local_ff49_hitec_daily()
        if _hitech_local is not None and len(_hitech_local) > 0:
            if str(_hitech_unit).lower() == 'pct':
                _hitech_ret = (_hitech_local / 100.0)
                _hitech_ret = _hitech_ret[_hitech_ret > -0.99]
            else:
                _hitech_ret = _hitech_local.copy()
            _ff_hitech_series = _hitech_ret.rename('QQQ_Ret')
            print(f"  [hist1926] Using local FF49 HiTec fallback: {len(_ff_hitech_series):,} days "
                  f"({_ff_hitech_series.index[0].date()} → {_ff_hitech_series.index[-1].date()})")
        else:
            print("  [hist1926] Local FF49 HiTec fallback unavailable; Tier 2 unavailable.")

    if ff_df is not None and len(ff_df) > 252:
        # Preserve selected-window dates that extend beyond FF coverage (e.g., 2026).
        # Without this union, the left-join against ff_df can silently truncate recent
        # dates from the historical-backtest pool.
        if df is not None and len(df) > 0:
            _ff_idx = pd.DatetimeIndex(ff_df.index)
            _df_idx = pd.DatetimeIndex(df.index)
            _union_idx = _ff_idx.union(_df_idx).sort_values()
            if len(_union_idx) > len(_ff_idx):
                ff_df = ff_df.reindex(_union_idx)
                _n_added = int(len(_union_idx) - len(_ff_idx))
                if 'SPY_Ret' in df.columns:
                    _spy_fill = pd.to_numeric(df['SPY_Ret'], errors='coerce').reindex(_union_idx)
                    _m_spy = ff_df['SPY_Ret'].isna() & _spy_fill.notna()
                    if _m_spy.any():
                        ff_df.loc[_m_spy, 'SPY_Ret'] = _spy_fill.loc[_m_spy]
                if 'IRX' in df.columns:
                    _irx_fill = pd.to_numeric(df['IRX'], errors='coerce').reindex(_union_idx)
                    _m_irx = ff_df['IRX'].isna() & _irx_fill.notna()
                    if _m_irx.any():
                        ff_df.loc[_m_irx, 'IRX'] = _irx_fill.loc[_m_irx]
                    if 'RF' in ff_df.columns:
                        _rf_fill = (_irx_fill / 100.0 / 252.0)
                        _m_rf = ff_df['RF'].isna() & _rf_fill.notna()
                        if _m_rf.any():
                            ff_df.loc[_m_rf, 'RF'] = _rf_fill.loc[_m_rf]
                _m_tlt = ff_df['TLT_Ret'].isna()
                if _m_tlt.any():
                    _rf_for_tlt = ff_df['RF'] if 'RF' in ff_df.columns else 0.0
                    ff_df.loc[_m_tlt, 'TLT_Ret'] = ff_df.loc[_m_tlt, 'SPY_Ret'] * (-0.25) + _rf_for_tlt
                print(f"  [hist1926] Extended FF index with df dates: +{_n_added:,} rows "
                      f"(through {pd.Timestamp(_union_idx[-1]).date()})")

        # ── Apply QQQ/TLT/IRX from df and NASDAQ sources ──────────────────────
        if df is not None and len(df) > 0:
            _df_cols = [
                c for c in [
                    'QQQ_Ret_RealOnly',
                    'NASDAQ_Ret_RealOnly',
                    'QQQ_Ret',
                    'TLT_Ret',
                    'IRX',
                    'NASDAQ_Ret',
                ] if c in df.columns
            ]
            _aligned = ff_df.join(
                df[_df_cols].rename(columns={
                    'QQQ_Ret_RealOnly': '_df_qqq_real',
                    'NASDAQ_Ret_RealOnly': '_df_ndq_real',
                    'QQQ_Ret':    '_df_qqq',
                    'TLT_Ret':    '_df_tlt',
                    'IRX':        '_df_irx',
                    'NASDAQ_Ret': '_df_ndq',
                }),
                how='left'
            )
            _mask_tlt = _aligned['_df_tlt'].notna() if '_df_tlt' in _aligned.columns else pd.Series(False, index=_aligned.index)
            if _mask_tlt.any():
                ff_df.loc[_mask_tlt, 'TLT_Ret'] = _aligned.loc[_mask_tlt, '_df_tlt']
            _mask_irx = _aligned['_df_irx'].notna() if '_df_irx' in _aligned.columns else pd.Series(False, index=_aligned.index)
            if _mask_irx.any():
                ff_df.loc[_mask_irx, 'IRX'] = _aligned.loc[_mask_irx, '_df_irx']

            # ── Tier 2: Merge FF 49-industry HiTec where Tier-1 not available ──────
            if _ff_hitech_series is not None:
                _ht_aligned = ff_df.join(_ff_hitech_series.rename('_ht'), how='left')
                _mask_ht = _ht_aligned['_ht'].notna()
                if _mask_ht.any():
                    ff_df.loc[_mask_ht, 'QQQ_Ret'] = _ht_aligned.loc[_mask_ht, '_ht']
                    _HIST1926_NASDAQ_SOURCE = 'FF49_HiTec'     # v1.4: renamed from 'ff_hitech'
                    print(f"  [hist1926] QQQ proxy Tier 2 (FF49 HiTec VW): "
                          f"{_mask_ht.sum():,} days replaced SPY×1.25 baseline.")

            # ── Tier 1a: Merge df['NASDAQ_Ret'] (^IXIC composite, post-1971) ─────────
            _ndq_col = None
            if '_df_ndq_real' in _aligned.columns and _aligned['_df_ndq_real'].notna().any():
                _ndq_col = '_df_ndq_real'
            elif '_df_ndq' in _aligned.columns:
                _ndq_col = '_df_ndq'
            _mask_ndq = (
                _aligned[_ndq_col].notna()
                if _ndq_col is not None else pd.Series(False, index=_aligned.index)
            )
            if _mask_ndq.any():
                ff_df.loc[_mask_ndq, 'QQQ_Ret'] = _aligned.loc[_mask_ndq, _ndq_col]
                _HIST1926_NASDAQ_SOURCE = 'NASDAQ_COMPOSITE'
                print(f"  [hist1926] QQQ proxy Tier 1a (NASDAQ Composite ^IXIC): "
                      f"{_mask_ndq.sum():,} days applied.")

            # ── Tier 1b: Merge df['QQQ_Ret'] (actual QQQ ETF, post-1999) ────────────
            # Applied last — highest fidelity; overwrites Tier 1a/2 where both exist.
            _qqq_col = None
            if '_df_qqq_real' in _aligned.columns and _aligned['_df_qqq_real'].notna().any():
                _qqq_col = '_df_qqq_real'
            elif '_df_qqq' in _aligned.columns:
                _qqq_col = '_df_qqq'
            _mask_qqq = (
                _aligned[_qqq_col].notna()
                if _qqq_col is not None else pd.Series(False, index=_aligned.index)
            )
            if _mask_qqq.any():
                ff_df.loc[_mask_qqq, 'QQQ_Ret'] = _aligned.loc[_mask_qqq, _qqq_col]
                _HIST1926_NASDAQ_SOURCE = 'QQQ_REAL'
                print(f"  [hist1926] QQQ proxy Tier 1b (QQQ ETF actual): "
                      f"{_mask_qqq.sum():,} days patched with real QQQ returns.")

            # ── Final guard: handle complete source failure ───────────────────────────
            # historical_backtest and historical_bootstrap require at least one real
            # source.  Stochastic modes fall back to SPY×1.25 with a loud warning.
            if _HIST1926_NASDAQ_SOURCE == 'unknown':
                if MARKET_SCENARIO in ('historical_backtest', 'historical_bootstrap'):
                    raise RuntimeError(
                        f"{MARKET_SCENARIO} mode requires at least one real QQQ proxy "
                        "(QQQ_Ret, NASDAQ_Ret, or FF49_HiTec). All three unavailable. "
                        "Ensure pandas_datareader is installed and network is reachable."
                    )
                else:
                    _HIST1926_NASDAQ_SOURCE = 'beta_proxy'
                    ff_df['QQQ_Ret'] = ff_df['QQQ_Ret'].fillna(ff_df['SPY_Ret'] * 1.25)
                    print("  [hist1926] WARNING: all real QQQ proxies unavailable; "
                          "falling back to SPY×1.25 beta for stochastic modes only. "
                          "historical_backtest/historical_bootstrap will be rejected if attempted.")
        else:
            # No df available — apply Tier 2 (FF49_HiTec) only
            if _ff_hitech_series is not None:
                _ht_aligned = ff_df.join(_ff_hitech_series.rename('_ht'), how='left')
                _mask_ht = _ht_aligned['_ht'].notna()
                if _mask_ht.any():
                    ff_df.loc[_mask_ht, 'QQQ_Ret'] = _ht_aligned.loc[_mask_ht, '_ht']
                    _HIST1926_NASDAQ_SOURCE = 'FF49_HiTec'
            # Handle complete failure (HiTec also unavailable)
            if _HIST1926_NASDAQ_SOURCE == 'unknown':
                if MARKET_SCENARIO in ('historical_backtest', 'historical_bootstrap'):
                    raise RuntimeError(
                        f"{MARKET_SCENARIO} mode: FF49_HiTec unavailable and no df "
                        "was passed. Cannot produce a valid QQQ proxy. "
                        "Pass the calibration dataframe or ensure pandas_datareader is installed."
                    )
                else:
                    _HIST1926_NASDAQ_SOURCE = 'beta_proxy'
                    ff_df['QQQ_Ret'] = ff_df['QQQ_Ret'].fillna(ff_df['SPY_Ret'] * 1.25)
                    print("  [hist1926] WARNING: FF HiTec unavailable and no df provided; "
                          "using SPY×1.25 beta for stochastic modes only.")
        src = ff_df
    elif df is not None and len(df) > 252:
        # Path B: FF daily factors unavailable; use yfinance df directly.
        # df['QQQ_Ret'] should already be populated by fetch_historical_data (dynamic factor
        # fill for pre-1999), so 'QQQ_Ret' not in columns is a degenerate case.
        src = df.copy()
        if 'TLT_Ret' not in src.columns:
            src['TLT_Ret'] = src['SPY_Ret'] * (-0.25)
        if 'IRX' not in src.columns:
            src['IRX'] = 4.0  # rough long-run avg fallback
        # Determine source quality from strict real-only columns when available.
        qqq_real = (
            pd.to_numeric(src['QQQ_Ret_RealOnly'], errors='coerce')
            if 'QQQ_Ret_RealOnly' in src.columns
            else pd.Series(np.nan, index=src.index, dtype=float)
        )
        ndq_real = (
            pd.to_numeric(src['NASDAQ_Ret_RealOnly'], errors='coerce')
            if 'NASDAQ_Ret_RealOnly' in src.columns
            else pd.Series(np.nan, index=src.index, dtype=float)
        )
        if not ndq_real.notna().any() and 'NASDAQ_Price_RealOnly' in src.columns:
            ndq_real = pd.to_numeric(src['NASDAQ_Price_RealOnly'], errors='coerce').pct_change()
        if not ndq_real.notna().any() and 'NASDAQ_Price' in src.columns:
            ndq_real = pd.to_numeric(src['NASDAQ_Price'], errors='coerce').pct_change()
        if not qqq_real.notna().any() and 'QQQ_Price_RealOnly' in src.columns:
            qqq_real = pd.to_numeric(src['QQQ_Price_RealOnly'], errors='coerce').pct_change()
        if not qqq_real.notna().any() and 'QQQ_Price' in src.columns:
            qqq_real = pd.to_numeric(src['QQQ_Price'], errors='coerce').pct_change()

        qqq_proxy = ndq_real.copy()
        qqq_proxy.loc[qqq_real.notna()] = qqq_real.loc[qqq_real.notna()]

        if qqq_proxy.notna().any():
            src['QQQ_Ret'] = qqq_proxy
            _HIST1926_NASDAQ_SOURCE = 'QQQ_REAL' if qqq_real.notna().any() else 'NASDAQ_COMPOSITE'
        else:
            # No real QQQ proxy: enforce in historical_backtest/bootstrap modes, warn otherwise.
            if MARKET_SCENARIO in ('historical_backtest', 'historical_bootstrap'):
                raise RuntimeError(
                    f"{MARKET_SCENARIO} mode: df has no real-only QQQ/NASDAQ history "
                    "(QQQ_Ret_RealOnly or NASDAQ_Ret_RealOnly). Cannot produce a valid QQQ proxy."
                )
            _HIST1926_NASDAQ_SOURCE = 'beta_proxy'
            src['QQQ_Ret'] = src.get('QQQ_Ret', src['SPY_Ret'] * 1.25).fillna(src['SPY_Ret'] * 1.25)
            print("  [hist1926] WARNING: df has no real-only QQQ/NASDAQ history; using SPY×1.25 beta "
                  "(stochastic modes only — historical_backtest/historical_bootstrap rejected).")
        print(f"  [hist1926] Using df columns: {len(src):,} days.")
    else:
        print("  [hist1926] WARNING: no 1926 data available; historical scenarios disabled.")
        _HIST1926_N = 0
        return

    src = src.dropna(subset=['SPY_Ret', 'QQQ_Ret', 'TLT_Ret'])
    _HIST1926_SPY = src['SPY_Ret'].to_numpy(dtype=np.float64)
    _HIST1926_QQQ = src['QQQ_Ret'].to_numpy(dtype=np.float64)
    _HIST1926_TLT = src['TLT_Ret'].to_numpy(dtype=np.float64)
    _HIST1926_IRX   = src['IRX'].to_numpy(dtype=np.float64) if 'IRX' in src.columns else np.full(len(src), 4.0)
    _HIST1926_N     = len(_HIST1926_SPY)
    _HIST1926_DATES = pd.to_datetime(src.index)  # DatetimeIndex; .date() safe on elements
    _HIST1926_NASDAQ = _HIST1926_QQQ.copy()   # best available proxy, for external reference
    print(f"  [hist1926] Arrays ready: N={_HIST1926_N:,} days  "
          f"SPY_Ret mean={_HIST1926_SPY.mean()*252*100:.2f}%/yr  "
          f"QQQ_source={_HIST1926_NASDAQ_SOURCE}")


def _compute_recon_regime_from_vol(
    spy_returns: np.ndarray,
    vol_window: int = 63,
    high_vol_pct: float = 80.0,
    bear_pct: float = 95.0,
) -> np.ndarray:
    """
    Derive a deterministic regime-label array from rolling realised volatility.

    Used in historical_backtest mode to replace the Markov-simulated regime
    path with one grounded in the actual historical SPY returns.

    Labels:
      REGIME_LOW (0)       — vol < P80 of full-window distribution
      REGIME_HIGH_VOL (1)  — vol ≥ P80
      REGIME_BEAR (2)      — vol ≥ P95

    Args:
        spy_returns  : daily SPY total-return array
        vol_window   : rolling window for annualised vol (default 63 ≈ 1 quarter)
        high_vol_pct : lower percentile threshold for REGIME_HIGH_VOL
        bear_pct     : upper percentile threshold for REGIME_BEAR

    Returns int32 array of length len(spy_returns) with regime labels.
    """
    arr = np.asarray(spy_returns, dtype=float)
    n = len(arr)
    if n == 0:
        return np.zeros(0, dtype=np.int32)

    roll_vol = (
        pd.Series(arr)
        .rolling(vol_window, min_periods=max(1, vol_window // 4))
        .std()
        .bfill()
        .fillna(0.01)
        .mul(np.sqrt(252))
        .to_numpy(dtype=np.float64)
    )

    thr_high = float(np.nanpercentile(roll_vol, high_vol_pct))
    thr_bear = float(np.nanpercentile(roll_vol, bear_pct))

    regimes = np.zeros(n, dtype=np.int32)
    regimes[roll_vol >= thr_high] = REGIME_HIGH_VOL
    regimes[roll_vol >= thr_bear] = REGIME_BEAR

    return regimes


def _replay_emulator_residuals(
    fund: str,
    n_days: int,
    model: Optional[Dict] = None,
    seed: int = 0,
    block_size: int = 63,
) -> np.ndarray:
    """
    Replay stored tracking-error residuals deterministically.

    Lookup order: model dict (works in worker processes) → _emulator_residuals global.

    Behaviour:
      - n_days ≤ stored length  → exact last-n_days slice (no randomness).
      - n_days >  stored length → exact stored window first, then seeded
        block-bootstrap for the remaining days (reproducible for fixed seed).

    Falls back to an array of zeros if no residuals are stored for the fund.

    Args:
        fund       : fund symbol (e.g. 'TQQQ')
        n_days     : number of days required
        model      : tracking_residual_model dict (for worker IPC access)
        seed       : RNG seed for the block-bootstrap extension
        block_size : block length for bootstrap extension (default 63 ≈ 1 quarter)

    Returns float64 array of length n_days.
    """
    stored_arr: Optional[np.ndarray] = None

    # Priority 1: model dict (present in worker processes via IPC)
    if model is not None and fund in model:
        _r = model[fund].get('residuals_empirical', model[fund].get('residuals', None))
        if _r is not None and len(_r) > 0:
            stored_arr = np.asarray(_r, dtype=np.float64)

    # Priority 2: module-level global (main process only)
    if stored_arr is None:
        _global_entry = _emulator_residuals.get(fund, {})
        _gr = _global_entry.get('residuals', None)
        if _gr is not None and len(_gr) > 0:
            stored_arr = np.asarray(_gr, dtype=np.float64)

    if stored_arr is None or len(stored_arr) == 0:
        return np.zeros(n_days, dtype=np.float64)

    n_stored = len(stored_arr)

    if n_days <= n_stored:
        # Exact replay: return the most recent n_days residuals.
        return stored_arr[-n_days:].copy()

    # Block-bootstrap extension: exact stored window + seeded bootstrap
    rng = np.random.default_rng(seed)
    out = np.empty(n_days, dtype=np.float64)
    out[:n_stored] = stored_arr          # exact replay first
    i = n_stored
    max_start = max(1, n_stored - block_size)
    while i < n_days:
        blk_start = int(rng.integers(0, max_start))
        blk = stored_arr[blk_start:blk_start + block_size]
        take = min(len(blk), n_days - i)
        out[i:i + take] = blk[:take]
        i += take
    return out


def _get_historical_path_returns(
    path_idx: int,
    n_paths: int,
    n_days: int,
    mode: str,
    block_size: int,
    rng: np.random.Generator,
    hist_data: Optional[Dict[str, np.ndarray]] = None,
    bootstrap_seed: Optional[int] = None,
    bootstrap_method: str = 'fixed',
    stationary_p: Optional[float] = None,
) -> Dict[str, np.ndarray]:
    """
    Return arrays of {SPY_Ret, QQQ_Ret, TLT_Ret, IRX} for one simulation path.

    hist_data: dict with keys SPY_Ret, QQQ_Ret, TLT_Ret, IRX, N (from
               regime_model['hist1926_data']).  If None, falls back to the
               module-level _HIST1926_* globals (only valid in the main process).
               Pass hist_data when calling from worker processes (ProcessPoolExecutor).

    mode='backtest':
        Chronological slice.  n_paths start positions are spread evenly across
        [0, N - n_days], so every path covers exactly n_days with NO wrap.
        If N < n_days, raises RuntimeError (no implicit wrap/loop/bootstrap fallback).

    mode='bootstrap':
        Block bootstrap. Draw random contiguous blocks of `block_size` days
        until n_days are assembled. Preserves short-run autocorrelation and
        volatility clustering within each block.
        If `bootstrap_seed` is provided, block selection is reproducible for
        fixed (bootstrap_seed, path_idx).
        bootstrap_method='fixed'       -> fixed-length contiguous blocks.
        bootstrap_method='stationary'  -> stationary bootstrap (geometric block lengths).

    Returns dict with float64 arrays of length n_days.
    """
    if hist_data is not None:
        arr_spy = hist_data['SPY_Ret']
        arr_qqq = hist_data['QQQ_Ret']
        arr_tlt = hist_data['TLT_Ret']
        arr_irx = hist_data['IRX']
        arr_vix = hist_data.get('VIX', None)
        N = int(hist_data.get('N', len(arr_spy)))
        src_indices = np.asarray(
            hist_data.get('source_indices', np.arange(N, dtype=np.int64)),
            dtype=np.int64
        )
    else:
        arr_spy = _HIST1926_SPY
        arr_qqq = _HIST1926_QQQ
        arr_tlt = _HIST1926_TLT
        arr_irx = _HIST1926_IRX
        arr_vix = None
        N = _HIST1926_N
        src_indices = np.arange(N, dtype=np.int64)

    if any(x is None for x in (arr_spy, arr_qqq, arr_tlt, arr_irx)):
        _zero = np.zeros(n_days, dtype=np.float64)
        return {'SPY_Ret': _zero, 'QQQ_Ret': _zero, 'TLT_Ret': _zero, 'IRX': np.full(n_days, 4.0)}

    if not (len(arr_spy) == len(arr_qqq) == len(arr_tlt) == len(arr_irx) == N):
        raise RuntimeError(
            "Historical driver arrays are misaligned. Expected identical lengths for "
            "SPY/QQQ/TLT/IRX in historical path generation."
        )
    if arr_vix is not None and len(arr_vix) != N:
        raise RuntimeError(
            "Historical VIX array is misaligned with historical return arrays."
        )
    if len(src_indices) != N:
        src_indices = np.arange(N, dtype=np.int64)

    # Fail fast: historical bootstrap/backtest must never emit NaNs.
    for _name, _arr in (('SPY_Ret', arr_spy), ('QQQ_Ret', arr_qqq), ('TLT_Ret', arr_tlt), ('IRX', arr_irx)):
        if np.isnan(np.asarray(_arr, dtype=np.float64)).any():
            raise RuntimeError(f"Historical {_name} contains NaN values; cannot sample safely.")
    if arr_vix is not None and np.isnan(np.asarray(arr_vix, dtype=np.float64)).any():
        raise RuntimeError("Historical VIX contains NaN values; cannot sample safely.")

    if N == 0:
        # Data not available — return zeros (simulation will see flat returns)
        _zero = np.zeros(n_days, dtype=np.float64)
        return {'SPY_Ret': _zero, 'QQQ_Ret': _zero, 'TLT_Ret': _zero, 'IRX': np.full(n_days, 4.0)}

    if mode == 'backtest':
        # Distribute path starts evenly across [0, max_valid_start] so every path
        # covers exactly n_days of chronological history with NO cyclic wrap.
        # A true historical backtest must stop when data ends — wrapping back to 1926
        # creates fake history that is indistinguishable from bootstrap.
        max_valid_start = N - n_days
        if max_valid_start < 0:
            raise RuntimeError(
                f"historical_backtest requires no-wrap chronological replay, but "
                f"requested n_days={n_days:,} exceeds available history N={N:,}. "
                "Reduce time horizon or expand [ANALYSIS_START_DATE, ANALYSIS_END_DATE]."
            )

        if n_paths > 1:
            start = int(round(path_idx * max_valid_start / (n_paths - 1)))
        else:
            start = 0
        start = int(np.clip(start, 0, max_valid_start))
        idx = src_indices[start:start + n_days].copy()
        out = {
            'SPY_Ret': arr_spy[start:start + n_days].copy(),
            'QQQ_Ret': arr_qqq[start:start + n_days].copy(),
            'TLT_Ret': arr_tlt[start:start + n_days].copy(),
            'IRX':     arr_irx[start:start + n_days].copy(),
            '_sampled_return_indices': idx,
            '_sampled_rf_indices': idx.copy(),
            '_sampled_blocks': [(int(idx[0]), int(idx[-1]), int(n_days))] if len(idx) > 0 else [],
        }
        if arr_vix is not None:
            out['VIX'] = arr_vix[start:start + n_days].copy()
        for _name in ('SPY_Ret', 'QQQ_Ret', 'TLT_Ret', 'IRX'):
            sampled_returns = np.asarray(out[_name], dtype=np.float64)
            assert not np.isnan(sampled_returns).any(), f"NaN detected in sampled {_name} (backtest mode)"
        return out

    if mode != 'bootstrap':
        raise ValueError(f"Unsupported historical path mode: {mode!r}")

    # bootstrap
    # STRICT contiguous block bootstrap:
    # - choose a contiguous start index
    # - take a contiguous block
    # - apply the exact same block indices to all aligned arrays (SPY/QQQ/TLT/IRX[/VIX])
    # - repeat until the requested horizon is filled
    bootstrap_rng = (
        np.random.default_rng(int(bootstrap_seed) + int(path_idx))
        if bootstrap_seed is not None
        else rng
    )
    eff_block = max(1, min(int(block_size), int(N)))
    method = str(bootstrap_method).strip().lower()
    out_spy, out_qqq, out_tlt, out_irx = [], [], [], []
    out_vix: list = []
    sampled_idx: list = []
    sampled_blocks: list = []

    if method == 'fixed':
        # Off-by-one safety: start index is bounded by N - eff_block exactly.
        max_start = int(N - eff_block)
        assert max_start >= 0, "Invalid bootstrap max_start; block larger than pool."
        filled = 0
        while filled < n_days:
            blk_start = int(bootstrap_rng.integers(0, max_start + 1)) if max_start > 0 else 0
            assert 0 <= blk_start <= (N - eff_block), (
                f"Bootstrap block start out of bounds: start={blk_start}, N={N}, block={eff_block}"
            )
            take = min(eff_block, n_days - filled)
            blk_end = blk_start + take
            assert blk_end <= N, (
                f"Bootstrap block crosses window boundary: start={blk_start}, end={blk_end}, N={N}"
            )

            out_spy.append(arr_spy[blk_start:blk_end])
            out_qqq.append(arr_qqq[blk_start:blk_end])
            out_tlt.append(arr_tlt[blk_start:blk_end])
            out_irx.append(arr_irx[blk_start:blk_end])
            if arr_vix is not None:
                out_vix.append(arr_vix[blk_start:blk_end])

            idx_block = src_indices[blk_start:blk_end]
            sampled_idx.append(idx_block)
            sampled_blocks.append((int(src_indices[blk_start]), int(src_indices[blk_end - 1]), int(take)))
            filled += take
    elif method == 'stationary':
        # Stationary bootstrap (Politis-Romano): geometric block lengths with mean 1/p.
        p = float(stationary_p) if stationary_p is not None else (1.0 / float(eff_block))
        p = float(np.clip(p, 1e-6, 1.0))
        curr = int(bootstrap_rng.integers(0, N))
        block_start = curr
        block_len = 0
        for _ in range(int(n_days)):
            assert 0 <= curr < N, f"Stationary bootstrap index out of bounds: idx={curr}, N={N}"
            out_spy.append(arr_spy[curr:curr + 1])
            out_qqq.append(arr_qqq[curr:curr + 1])
            out_tlt.append(arr_tlt[curr:curr + 1])
            out_irx.append(arr_irx[curr:curr + 1])
            if arr_vix is not None:
                out_vix.append(arr_vix[curr:curr + 1])
            sampled_idx.append(src_indices[curr:curr + 1])
            block_len += 1

            continue_block = (bootstrap_rng.random() > p) and (curr < N - 1)
            if continue_block:
                curr += 1
            else:
                sampled_blocks.append((
                    int(src_indices[block_start]),
                    int(src_indices[block_start + block_len - 1]),
                    int(block_len),
                ))
                curr = int(bootstrap_rng.integers(0, N))
                block_start = curr
                block_len = 0
        if block_len > 0:
            sampled_blocks.append((
                int(src_indices[block_start]),
                int(src_indices[block_start + block_len - 1]),
                int(block_len),
            ))
    else:
        raise ValueError(f"Unsupported bootstrap_method: {bootstrap_method!r}")

    out = {
        'SPY_Ret': np.concatenate(out_spy)[:n_days],
        'QQQ_Ret': np.concatenate(out_qqq)[:n_days],
        'TLT_Ret': np.concatenate(out_tlt)[:n_days],
        'IRX':     np.concatenate(out_irx)[:n_days],
        '_sampled_return_indices': np.concatenate(sampled_idx)[:n_days],
        '_sampled_rf_indices': np.concatenate(sampled_idx)[:n_days],
        '_sampled_blocks': sampled_blocks,
    }
    if arr_vix is not None and len(out_vix) > 0:
        out['VIX'] = np.concatenate(out_vix)[:n_days]
    for _name in ('SPY_Ret', 'QQQ_Ret', 'TLT_Ret', 'IRX'):
        sampled_returns = np.asarray(out[_name], dtype=np.float64)
        assert not np.isnan(sampled_returns).any(), f"NaN detected in sampled {_name} (bootstrap mode)"
    return out


# ============================================================================
# HISTORICAL BACKTEST HELPERS — CPI, WINDOW SLICING, VALIDATION
# ============================================================================

def load_cpi_series(start_date: str = '1913-01-01',
                    end_date: Optional[str] = None) -> Optional['pd.Series']:
    """
    Load FRED CPIAUCSL monthly CPI series and forward-fill to a daily index.

    Returns a pd.Series (index=DatetimeIndex, values=CPI level) or None on failure.
    The caller can compute annualised inflation for any sub-window as:
        inflation_rate = (cpi[-1] / cpi[0]) ** (252 / n_days) - 1
    """
    global _HIST_RECON_CPI
    try:
        import pandas_datareader.data as _web
        _start = start_date
        _end   = end_date or pd.Timestamp.today().strftime('%Y-%m-%d')
        _raw   = _web.DataReader('CPIAUCSL', 'fred', start=_start, end=_end)
        cpi    = _raw['CPIAUCSL'].dropna()
        # Forward-fill to daily frequency
        cpi_daily = cpi.resample('D').ffill()
        _HIST_RECON_CPI = cpi_daily
        print(f"  [CPI] FRED CPIAUCSL loaded: {cpi_daily.index[0].date()} → "
              f"{cpi_daily.index[-1].date()} ({len(cpi_daily):,} days after ffill)")
        return cpi_daily
    except Exception as _e:
        print(f"  [CPI] WARNING: FRED CPIAUCSL fetch failed ({_e}). "
              "Real-return calculations will fall back to constant 3% inflation.")
        return None


def _slice_hist1926_to_window(
        start_date: str,
        end_date: str,
        min_days: int = 2,
) -> Optional[Dict[str, Any]]:
    """
    Slice the _HIST1926_* global arrays to [start_date, end_date] (inclusive).

    Returns a dict compatible with `hist1926_data` (keys: SPY_Ret, QQQ_Ret,
    TLT_Ret, IRX, N, dates_start, dates_end, source_indices) or None if data
    unavailable or window has fewer than `min_days` trading days.

    The returned arrays are COPIES — the originals are never modified.
    """
    if _HIST1926_N == 0 or _HIST1926_DATES is None or _HIST1926_SPY is None:
        print("  [slice_window] _HIST1926 globals not populated — call "
              "_load_historical_1926_data() first.")
        return None

    t_start = pd.Timestamp(start_date)
    t_end = pd.Timestamp(end_date)

    if t_start > t_end:
        print(f"  [slice_window] start_date > end_date ({start_date} > {end_date}); swapping.")
        t_start, t_end = t_end, t_start

    dates = pd.DatetimeIndex(_HIST1926_DATES)
    d0 = pd.Timestamp(dates[0])
    d1 = pd.Timestamp(dates[-1])
    t_start_clip = max(t_start, d0)
    t_end_clip = min(t_end, d1)
    if t_start_clip > t_end_clip:
        print(f"  [slice_window] Requested window [{start_date}, {end_date}] has no overlap with "
              f"available history [{d0.date()}, {d1.date()}]. Returning None.")
        return None

    i0 = int(np.searchsorted(dates.values, np.datetime64(t_start_clip), side='left'))
    i1 = int(np.searchsorted(dates.values, np.datetime64(t_end_clip), side='right'))
    n_obs = int(i1 - i0)
    if n_obs < int(min_days):
        print(f"  [slice_window] Only {n_obs} days in [{t_start_clip.date()}, {t_end_clip.date()}] "
              f"— need ≥ {int(min_days)}. Returning None.")
        return None

    window_data = {
        'SPY_Ret':    _HIST1926_SPY[i0:i1].copy(),
        'QQQ_Ret':    _HIST1926_QQQ[i0:i1].copy(),
        'TLT_Ret':    _HIST1926_TLT[i0:i1].copy(),
        'IRX':        _HIST1926_IRX[i0:i1].copy(),
        'N':          int(i1 - i0),
        'dates':      dates[i0:i1].copy(),
        'dates_start': str(dates[i0].date()),
        'dates_end':   str(dates[i1 - 1].date()),
        'window_start': str(t_start.date()),
        'window_end':   str(t_end.date()),
        'source_i0': int(i0),
        'source_i1': int(i1),
        'source_indices': np.arange(i0, i1, dtype=np.int64),
    }
    print(f"  [slice_window] Window [{window_data['dates_start']} → "
          f"{window_data['dates_end']}]  N={window_data['N']:,} days  "
          f"SPY_Ret mean={window_data['SPY_Ret'].mean()*252*100:.2f}%/yr")
    return window_data


def _driver_immutability_test(original_spy: np.ndarray,
                               used_spy: np.ndarray) -> Dict[str, Any]:
    """
    MANDATORY test: assert driver returns were never altered.

    If the max absolute difference is non-zero this function ABORTS execution
    (raises RuntimeError) because historical reconstruction integrity is violated.
    """
    if original_spy is None or used_spy is None:
        return {'pass': False, 'details': 'arrays unavailable'}
    o = np.asarray(original_spy, dtype=float)
    u = np.asarray(used_spy,     dtype=float)
    if len(o) != len(u):
        raise RuntimeError(
            f"DRIVER IMMUTABILITY VIOLATED: length mismatch "
            f"(original={len(o)}, used={len(u)}).  "
            "Historical underlying returns must never be altered."
        )
    max_diff = float(np.max(np.abs(o - u)))
    passed   = (max_diff == 0.0)
    if not passed:
        raise RuntimeError(
            f"DRIVER IMMUTABILITY VIOLATED: "
            f"max(abs(driver_original - driver_used)) = {max_diff:.2e} != 0.  "
            "Historical underlying returns must never be altered."
        )
    return {'pass': True, 'max_diff': max_diff,
            'details': 'PASS — driver arrays are identical to originals'}


def _validate_borrowing_cost_formula(leverage: float,
                                      rf_annual: float,
                                      spread_annual: float) -> Dict[str, Any]:
    """
    Unit-test: financing cost must equal (leverage-1)*rf/252 + spread/252 per day.
    Returns pass/fail and the correct vs actual values.
    """
    if leverage <= 1.0:
        correct_daily = 0.0
    else:
        correct_daily = ((leverage - 1.0) * rf_annual + spread_annual) / 252.0
    # Common mis-implementations
    wrong_v1 = leverage * rf_annual / 252.0
    wrong_v2 = leverage * (rf_annual + spread_annual) / 252.0
    result = {
        'leverage': leverage,
        'rf_annual': rf_annual,
        'spread_annual': spread_annual,
        'correct_daily_bps': correct_daily * 10_000,
        'wrong_v1_bps': wrong_v1 * 10_000,
        'wrong_v2_bps': wrong_v2 * 10_000,
        'correct': True,
    }
    # Verify our engine's calculate_daily_borrow_cost matches
    engine_daily = calculate_daily_borrow_cost(leverage, rf_annual, spread_annual)
    result['engine_daily_bps'] = engine_daily * 10_000
    result['engine_matches'] = bool(abs(engine_daily - correct_daily) < 1e-12)
    result['correct'] = result['engine_matches']
    return result


# ─────────────────────────────────────────────────────────────────────────────
# PHASE F helpers: readable threshold/value formatting for FAIL REASONS output.
# ─────────────────────────────────────────────────────────────────────────────

def _safe_fmt(v: Any) -> str:
    """Format a scalar for FAIL REASONS output; handles nan/inf gracefully."""
    try:
        f = float(v)
        if not np.isfinite(f):
            return str(f)
        if abs(f) < 0.01:
            return f"{f*1e4:.3f} bps"
        return f"{f*100:.3f}%"
    except (TypeError, ValueError):
        return str(v)


def _format_threshold(key: str, thr: Dict[str, float]) -> str:
    """Return a human-readable threshold string for the given check key."""
    _map = {
        'corr':                  ('corr_min',                 'min'),
        'cagr_diff':             ('cagr_diff_max',            'max'),
        'tracking_error':        ('tracking_error_ann_max',   'max'),
        'vol_ratio':             ('vol_ratio_min',             'range'),
        'max_drawdown_diff':     ('max_drawdown_diff_max',    'max'),
        'terminal_wealth_rel_err': ('terminal_wealth_rel_err_max', 'max'),
        'beta':                  ('beta_min',                 'range'),
        'alpha':                 ('alpha_ann_abs_max',        'abs_max'),
        'spread_sign':           (None,                       'flag'),
    }
    info = _map.get(key, (None, 'unknown'))
    thr_key, style = info
    if thr_key is None:
        return '(no leakage / no negative spread)'
    v = thr.get(thr_key, np.nan)
    if style == 'range':
        lo = thr.get(thr_key, np.nan)
        hi_key = thr_key.replace('_min', '_max')
        hi = thr.get(hi_key, np.nan)
        return f"[{lo:.4f}, {hi:.4f}]"
    prefix = '≤' if style in ('max', 'abs_max') else '≥'
    if abs(v) < 0.02:
        return f"{prefix} {v*1e4:.1f} bps"
    return f"{prefix} {v*100:.2f}%"


def validate_borrowing_cost_correctness() -> Dict[str, Any]:
    """
    Validate borrow cost formula for several (leverage, rate, spread) combos.
    Prints pass/fail for each case.  Returns summary dict.
    """
    print("\n  === BORROW COST FORMULA VALIDATION ===")
    print(f"  Formula: daily_cost = (leverage-1) × rf / 252 + spread / 252  (L>1)")
    cases = [
        (3.0, 0.05, 0.0075, "TQQQ 3x, 5% rf, 75bps spread"),
        (2.0, 0.04, 0.0050, "SSO  2x, 4% rf, 50bps spread"),
        (1.0, 0.05, 0.0075, "SPY  1x, 5% rf (should be 0)"),
        (3.0, 0.01, 0.0025, "UPRO ZIRP era, 1% rf"),
    ]
    all_pass = True
    details  = []
    for lev, rf, sp, label in cases:
        r = _validate_borrowing_cost_formula(lev, rf, sp)
        status = "✓ PASS" if r['engine_matches'] else "⚠ FAIL"
        if not r['engine_matches']:
            all_pass = False
        borrowed = lev - 1.0
        correct  = r['correct_daily_bps']
        engine   = r['engine_daily_bps']
        print(f"  {status}  {label}")
        print(f"         financed_multiple={borrowed:.1f}×,  correct={correct:.3f} bps/d,  "
              f"engine={engine:.3f} bps/d")
        details.append({**r, 'label': label})
    print(f"  {'ALL PASS' if all_pass else 'SOME FAILED'}")
    return {'all_pass': all_pass, 'cases': details}



def validate_letf_emulator_oos(
        df: pd.DataFrame,
        regime_model: Dict,
        fund: str = 'UPRO',
        train_end: str = '2018-12-31',
        val_start: str = '2019-01-01',
        val_end:   Optional[str] = None,
        n_sims:    int = 200,
        mode: ValidationMode = ValidationMode.INSTITUTIONAL_GATE,
) -> Dict[str, Any]:
    """
    Out-of-sample emulator validation for a leveraged fund.

    Protocol:
      1. Calibrate emulator parameters on [df.index[0] … train_end].
      2. Generate synthetic fund returns for [val_start … val_end] using
         only the underlying index driver (real returns from df).
      3. Compare synthetic vs real fund daily returns.

    Metrics:
      - correlation         (target ≥ 0.98)
      - annualized TE       (std of daily return difference × √252)
      - CAGR difference     (synthetic - real)
      - max drawdown diff   (absolute)

    Parameters are calibrated on daily return properties ONLY — no explicit
    CAGR fitting (anti-overfitting constraint).

    Returns a metrics dict.  Prints a pass/fail summary.
    """
    fund_u = str(fund).upper()
    real_ret_col = f'{fund_u}_Real_Ret'
    if real_ret_col not in df.columns:
        return {'fund': fund_u, 'status': 'skipped', 'reason': f'column {real_ret_col} not in df'}

    driver_col = _institutional_validation_driver_for_asset(fund_u, df=df)
    if driver_col not in df.columns:
        return {'fund': fund_u, 'status': 'skipped', 'reason': f'driver column {driver_col} not in df'}

    thr = dict(LETF_RECONSTRUCTION_THRESHOLDS)
    syn_col = f'{fund_u}_IsSynthetic'
    train_end_ts = pd.Timestamp(train_end)
    val_start_ts = pd.Timestamp(val_start)

    # ── Validation header (always printed) ───────────────────────────────────────
    _val_end_display = val_end if val_end is not None else str(pd.Timestamp(df.index.max()).date())
    _syn_col_exists  = syn_col in df.columns
    print(
        f"\n╔{'═'*66}╗\n"
        f"║  LETF EMULATOR OOS VALIDATION\n"
        f"║  Asset: {fund_u:<6s}  Mode: {mode.value:<22s}  CACHE_VER: {CACHE_MODEL_VERSION}\n"
        f"║  Train: {train_end}  (up to)   Valid: {val_start} → {_val_end_display}\n"
        f"║  Flags: use_replay=True  stochastic=False  prefer_real_driver=True\n"
        f"╚{'═'*66}╝"
    )
    if mode == ValidationMode.DIAGNOSTIC_REPLAY:
        print("  [DIAGNOSTIC ONLY — no binding verdict; rolling alpha uses OOS actuals]")
    val_end_ts = pd.Timestamp(val_end) if val_end is not None else pd.Timestamp(df.index.max())

    required = [driver_col, real_ret_col, 'VIX']
    eval_mask = (df.index <= val_end_ts)
    if syn_col in df.columns:
        eval_mask &= (~df[syn_col].fillna(False).to_numpy(dtype=bool))
    df_eval = df.loc[eval_mask].dropna(subset=required).copy()
    if len(df_eval) < 315:
        return {
            'fund': fund_u,
            'status': 'insufficient_data',
            'driver_col': driver_col,
            'usable_days': len(df_eval),
        }

    split_mode = 'requested'
    df_train = df_eval.loc[df_eval.index <= train_end_ts].copy()
    df_val = df_eval.loc[(df_eval.index >= val_start_ts) & (df_eval.index <= val_end_ts)].copy()
    if len(df_train) < 252 or len(df_val) < 63:
        split_idx = int(round(len(df_eval) * 0.70))
        split_idx = int(np.clip(split_idx, 252, len(df_eval) - 63))
        df_train = df_eval.iloc[:split_idx].copy()
        df_val = df_eval.iloc[split_idx:].copy()
        split_mode = 'auto_70_30'

    split_model = calibrate_tracking_residual_model(
        df_train,
        funding_model=(regime_model or {}).get('funding_model', {}),
        bypass_cache=True,
        driver_override_map={fund_u: driver_col},
    )
    rf_daily_eval, rf_source = _load_daily_financing_rate_aligned(df_eval)
    recon = _build_reconstructed_letf_series(
        df=df_eval,
        asset=fund_u,
        tracking_model=split_model,
        rf_daily=rf_daily_eval,
        seed=44511 + sum(ord(c) for c in fund_u),
        use_replay_on_real_dates=True,   # enables hybrid rolling-alpha for OOS dates
        prefer_real_only_driver=True,
        driver_override=driver_col,
        stochastic_shocks=False,
        mode=mode,
        val_start_ts=val_start_ts,
    )
    if recon is None:
        return {'fund': fund_u, 'status': 'skipped', 'reason': 'reconstruction inputs unavailable'}

    idx = pd.DatetimeIndex(recon['index'])
    val_mask = np.asarray(recon['real_mask'], dtype=bool)
    val_mask &= (idx >= df_val.index[0]) & (idx <= df_val.index[-1])
    _act_val  = np.asarray(recon['actual'],        dtype=np.float64)[val_mask]
    _recon_val = np.asarray(recon['reconstructed'], dtype=np.float64)[val_mask]
    m = _compute_reconstruction_metrics(actual=_act_val, reconstructed=_recon_val)

    # Path realism metrics (Item 3)
    _vix_val: Optional[np.ndarray] = None
    if 'VIX' in df_val.columns:
        _vix_full = np.asarray(df_eval['VIX'].ffill().bfill().fillna(20.0).values, dtype=np.float64)
        _vix_val = _vix_full[val_mask]
    try:
        _realism = compute_path_realism_metrics(
            actual=_act_val, reconstructed=_recon_val, vix=_vix_val
        )
    except Exception:
        _realism = {}

    # PHASE A: hard OOS-split assertions — no date overlap, adequate sample sizes.
    train_dates = df_train.index
    valid_dates = df_val.index
    assert len(train_dates) >= 252, (
        f"[{fund_u}] OOS split: training window too short ({len(train_dates)} < 252 days)")
    assert len(valid_dates) >= 63, (
        f"[{fund_u}] OOS split: validation window too short ({len(valid_dates)} < 63 days)")
    assert train_dates.max() < valid_dates.min(), (
        f"[{fund_u}] OOS LEAKAGE: train_end={train_dates.max().date()} "
        f">= val_start={valid_dates.min().date()}")

    spread_mean_daily = float(split_model.get(fund_u, {}).get('spread_mean_daily', np.nan))
    neg_spread_flag = bool(split_model.get(fund_u, {}).get('negative_spread_flag', False))
    driver_alpha = float(split_model.get(fund_u, {}).get('driver_alpha_daily', np.nan))

    # PHASE B: updated checks using terminal_wealth_rel_err (replaces cum_return_error).
    checks = {
        'corr': bool(np.isfinite(m['corr']) and m['corr'] >= thr['corr_min']),
        'cagr_diff': bool(np.isfinite(m['cagr_diff_abs']) and m['cagr_diff_abs'] <= thr['cagr_diff_max']),
        'tracking_error': bool(np.isfinite(m['tracking_error_ann']) and m['tracking_error_ann'] <= thr['tracking_error_ann_max']),
        'vol_ratio': bool(np.isfinite(m['vol_ratio']) and thr['vol_ratio_min'] <= m['vol_ratio'] <= thr['vol_ratio_max']),
        'max_drawdown_diff': bool(np.isfinite(m['max_drawdown_diff_abs']) and m['max_drawdown_diff_abs'] <= thr['max_drawdown_diff_max']),
        # PHASE B: terminal_wealth_rel_err replaces cum_return_error (was |(sum) - (sum)| = broken)
        'terminal_wealth_rel_err': bool(
            np.isfinite(m['terminal_wealth_rel_err'])
            and m['terminal_wealth_rel_err'] <= thr['terminal_wealth_rel_err_max']
        ),
        'beta': bool(np.isfinite(m['beta']) and thr['beta_min'] <= m['beta'] <= thr['beta_max']),
        'alpha': bool(np.isfinite(m['alpha_annual']) and abs(m['alpha_annual']) <= thr['alpha_ann_abs_max']),
        'spread_sign': bool((not neg_spread_flag) or (not np.isfinite(spread_mean_daily)) or spread_mean_daily >= -5e-05),
        # PART 1b — implied_spread_raw_negative: fail if raw implied spread < -50 bps/yr.
        # A strongly negative raw spread signals driver or fund on wrong return basis (price
        # vs total-return). After correcting for driver_alpha (which is now constrained to
        # < 0.2 bps/day), spread_mean_daily ≈ raw mean, so this check is effectively on raw.
        # Threshold: -50 bps/yr = -0.005/yr ≈ -1.98e-5/day.
        'implied_spread_raw_negative': bool(
            mode != ValidationMode.INSTITUTIONAL_GATE
            or not np.isfinite(spread_mean_daily)
            or spread_mean_daily * 252 >= IMPLIED_SPREAD_NEGATIVE_THRESHOLD  # −50 bps/yr [INSTITUTIONAL GATE]
        ),
        # PART 1 — driver_alpha_integrity: in INSTITUTIONAL_GATE |driver_alpha_daily| must be
        # < 2e-5 (= 0.2 bps/day ≈ 0.50%/yr).  A larger value signals total-return vs
        # price-return mismatch — even 1-3 bps/day from dividend absorption is massive and
        # must fail.  Old threshold was 0.001 (= 100 bps/day = 25%/yr) — far too loose.
        # DIAGNOSTIC_REPLAY: check is informational only (overall=None so it can't fail gate).
        'driver_alpha_integrity': bool(
            mode != ValidationMode.INSTITUTIONAL_GATE
            or (not np.isfinite(driver_alpha))
            or (abs(driver_alpha) < DRIVER_ALPHA_INTEGRITY_THRESHOLD)  # 0.2 bps/day; was 0.001 (100 bps/day)
        ),
    }
    fail_reasons = [k for k, v in checks.items() if not v]
    # DIAGNOSTIC_REPLAY: no binding verdict; return overall=None
    if mode == ValidationMode.DIAGNOSTIC_REPLAY:
        overall = None
    else:
        overall = bool(all(checks.values()))
    # Perfect-metrics alert (T10): corr > 0.9999 AND TE < 0.001 → potential leakage
    _te_val = float(m.get('tracking_error_ann', np.nan))
    _corr_val = float(m.get('corr', np.nan))
    if np.isfinite(_corr_val) and np.isfinite(_te_val) and _corr_val > 0.9999 and _te_val < 0.001:
        print(f"  WARN: suspiciously perfect metrics — possible data leakage "
              f"(corr={_corr_val:.6f}, TE={_te_val*100:.4f}%)")

    print(f"\n  === LETF EMULATOR OOS VALIDATION: {fund_u} ===")
    print(f"  Driver: {driver_col}  | split_mode={split_mode} | RF source={rf_source}")
    print(f"  Train : {df_train.index[0].date()} → {df_train.index[-1].date()}  ({len(df_train):,} days)")
    print(f"  Valid : {df_val.index[0].date()} → {df_val.index[-1].date()}  ({len(df_val):,} days)")
    # PHASE A: explicit confirmation that split is truly OOS
    print(f"  OOS check: train_end={train_dates.max().date()} < val_start={valid_dates.min().date()} ✓")
    print(f"  corr={m['corr']:.4f} | TE={m['tracking_error_ann']*100:.2f}% | "
          f"cagr_diff={m['cagr_diff_abs']*100:.2f}%/yr | vol_ratio={m['vol_ratio']:.3f} | "
          f"mdd_diff={m['max_drawdown_diff_abs']*100:.2f}% | "
          f"tw_rel_err={m['terminal_wealth_rel_err']*100:.2f}% | "  # PHASE B
          f"nav_rmse_rel={m['nav_rmse_rel']*100:.2f}% | "
          f"beta={m['beta']:.4f} | alpha={m['alpha_annual']*100:.3f}%/yr")
    if np.isfinite(driver_alpha) and abs(driver_alpha) > 5e-5:
        print(f"  ⚠ driver_alpha_daily={driver_alpha*1e4:.2f} bps/day "
              f"({driver_alpha*252*100:.2f}%/yr) — may indicate return-type mismatch "
              f"(price vs total-return basis)")
    if neg_spread_flag:
        print(f"  ⚠ implied spread sign warning: mean={spread_mean_daily*10000:.3f} bps/day "
              f"(likely return-series basis mismatch; check driver vs fund total-return basis)")
    _emul_type = split_model.get(fund_u, {}).get('emulation_type', None)
    if _emul_type == 'rolling_alpha_hybrid':
        print(f"  ⚠ Emulation term: rolling_alpha_hybrid "
              f"(diagnostic_replay mode only for binding gates)")
    # Canonical lookup: check-key → metrics dict key for actual value.
    _check_to_metric_key = {
        'corr':                   'corr',
        'cagr_diff':              'cagr_diff_abs',
        'tracking_error':         'tracking_error_ann',
        'vol_ratio':              'vol_ratio',
        'max_drawdown_diff':      'max_drawdown_diff_abs',
        'terminal_wealth_rel_err': 'terminal_wealth_rel_err',
        'beta':                   'beta',
        'alpha':                  'alpha_annual',
        'spread_sign':                None,
        'implied_spread_raw_negative': None,  # uses spread_mean_daily directly
        'driver_alpha_integrity':      None,  # uses driver_alpha directly
    }
    if overall is None:
        print(f"  [DIAGNOSTIC ONLY — no binding verdict]")
    elif not overall:
        print(f"  ⚠ FAIL — emulator not credible; reconstruction disabled")
        print(f"  FAIL REASONS:")
        for k, v in checks.items():
            if not v:
                mk = _check_to_metric_key.get(k)
                if k == 'driver_alpha_integrity':
                    actual_val = float(driver_alpha) if np.isfinite(driver_alpha) else float('nan')
                    print(f"    - {k}: driver_alpha_daily={actual_val*1e4:.4f} bps/day "
                          f"({actual_val*252*100:.4f}%/yr) >= 0.2 bps/day limit — "
                          "likely total-return vs price-return mismatch; "
                          "check auto_adjust=True and driver column selection")
                elif k == 'implied_spread_raw_negative':
                    raw_ann = float(spread_mean_daily) * 252 if np.isfinite(spread_mean_daily) else float('nan')
                    print(f"    - {k}: raw implied spread={raw_ann*100:.2f}%/yr "
                          f"< -50 bps/yr limit — driver or fund on wrong return basis "
                          "(price-return vs total-return); check dividend handling")
                elif mk is not None:
                    actual_val = float(m.get(mk, np.nan))
                    print(f"    - {k}: actual={_safe_fmt(actual_val)}  threshold={_format_threshold(k, thr)}")
                else:
                    actual_val = float(spread_mean_daily)
                    print(f"    - {k}: actual={_safe_fmt(actual_val)}  threshold={_format_threshold(k, thr)}")
    else:
        print(f"  ✓ PASS")

    _status_str = 'diagnostic' if overall is None else ('pass' if overall else 'fail')
    return {
        'fund': fund_u,
        'status': _status_str,
        'mode': mode.value,
        'driver_col': driver_col,
        'split_mode': split_mode,
        'train_period': (str(df_train.index[0].date()), str(df_train.index[-1].date())),
        'train_n_days': int(len(df_train)),
        'val_period': (str(df_val.index[0].date()), str(df_val.index[-1].date())),
        'val_n_days': int(len(df_val)),
        'oos_verified': bool(train_dates.max() < valid_dates.min()),
        'metrics': m,
        'correlation': float(m.get('corr', np.nan)),
        'te_ann': float(m.get('tracking_error_ann', np.nan)),
        'cagr_diff': float(m.get('cagr_reconstructed', np.nan) - m.get('cagr_actual', np.nan)),
        'mdd_diff': float(m.get('max_drawdown_diff_abs', np.nan)),
        'terminal_wealth_rel_err': float(m.get('terminal_wealth_rel_err', np.nan)),
        'nav_rmse_rel': float(m.get('nav_rmse_rel', np.nan)),
        'calibrated_spread': float(split_model.get(fund_u, {}).get('calibrated_spread', np.nan)),
        'spread_mean_daily': spread_mean_daily,
        'driver_alpha_daily': driver_alpha,
        'negative_spread_flag': neg_spread_flag,
        'checks': checks,
        'fail_reasons': fail_reasons,
        'overall_pass': overall,
        'realism_metrics': _realism,
    }


def validate_letf_emulator_walkforward(
        df: pd.DataFrame,
        fund: str,
        regime_model: Optional[Dict] = None,
        val_windows: Optional[List[Tuple[str, str]]] = None,
        mode: ValidationMode = ValidationMode.INSTITUTIONAL_GATE,
) -> Dict[str, Any]:
    """
    Walk-forward validation of the LETF reconstruction emulator.

    For each 2-year validation window the TRAIN set covers [inception, val_start).
    Blocks with too-short TRAIN or VALID are skipped or marked LOW_TRAIN.
    Crisis sub-windows (2020Q1, 2022 bear) receive extra TW_rel_err scoring.

    Pass criteria (per asset):
      ≥3 eligible (non-LOW_TRAIN) blocks AND
      pooled |mean_err_ann| < 0.5%/yr AND
      pooled tw_rel_err < 10% AND
      pooled te_ann < 3%/yr
    """
    fund_u = str(fund).upper()
    real_col = f'{fund_u}_Real_Ret'
    syn_col  = f'{fund_u}_IsSynthetic'
    if real_col not in df.columns:
        return {'fund': fund_u, 'status': 'skipped', 'reason': f'{real_col} not in df'}
    driver_col = _institutional_validation_driver_for_asset(fund_u, df=df)
    if driver_col not in df.columns:
        return {'fund': fund_u, 'status': 'skipped', 'reason': f'driver column {driver_col} not in df'}

    windows = val_windows if val_windows is not None else _WALKFORWARD_VAL_WINDOWS

    # Determine asset inception date from first non-synthetic real row
    real_mask_all = np.isfinite(df[real_col].values)
    if syn_col in df.columns:
        real_mask_all &= ~df[syn_col].fillna(False).to_numpy(dtype=bool)
    real_dates = df.index[real_mask_all]
    if len(real_dates) == 0:
        return {'fund': fund_u, 'status': 'skipped', 'reason': 'no real (non-synthetic) rows'}
    inception_ts = real_dates[0]

    # RF for the entire df
    rf_all, rf_src = _load_daily_financing_rate_aligned(df)

    blocks: List[Dict[str, Any]] = []

    for wi, (vs, ve) in enumerate(windows):
        vs_ts = pd.Timestamp(vs)
        ve_ts = pd.Timestamp(ve)
        # Train: from inception to day before val_start
        train_end_ts = vs_ts - pd.tseries.offsets.BDay(1)

        # Count real TRAIN days
        train_mask = (df.index >= inception_ts) & (df.index <= train_end_ts) & pd.Series(real_mask_all, index=df.index).values
        val_mask   = (df.index >= vs_ts)        & (df.index <= ve_ts)        & pd.Series(real_mask_all, index=df.index).values
        n_train = int(np.sum(train_mask))
        n_val   = int(np.sum(val_mask))

        block: Dict[str, Any] = {
            'window_label': f'W{wi + 1}',
            'val_start': vs, 'val_end': ve,
            'train_start': str(inception_ts.date()),
            'train_end': str(train_end_ts.date()),
            'n_train': n_train,
            'n_val': n_val,
            'low_train': n_train < _WF_LOW_TRAIN_DAYS,
            'skipped': False,
            'skip_reason': '',
        }

        if n_train < _WF_MIN_TRAIN_DAYS:
            block['skipped'] = True
            block['skip_reason'] = f'TRAIN too short ({n_train} < {_WF_MIN_TRAIN_DAYS})'
            blocks.append(block)
            continue
        if n_val < _WF_MIN_VAL_DAYS:
            block['skipped'] = True
            block['skip_reason'] = f'VALID too short ({n_val} < {_WF_MIN_VAL_DAYS})'
            blocks.append(block)
            continue

        # Calibrate on TRAIN data only
        df_train = df.loc[(df.index >= inception_ts) & (df.index <= train_end_ts)].copy()
        df_eval  = df.loc[(df.index >= inception_ts) & (df.index <= ve_ts)].copy()
        try:
            split_model = calibrate_tracking_residual_model(
                df_train,
                funding_model=(regime_model or {}).get('funding_model', {}),
                bypass_cache=True,
                driver_override_map={fund_u: driver_col},
            )
        except Exception as cal_err:
            block['skipped'] = True
            block['skip_reason'] = f'calibration error: {cal_err}'
            blocks.append(block)
            continue

        rf_eval = rf_all[np.isin(df.index, df_eval.index)]
        if len(rf_eval) != len(df_eval):
            rf_eval = np.resize(rf_all, len(df_eval))

        try:
            recon = _build_reconstructed_letf_series(
                df=df_eval, asset=fund_u, tracking_model=split_model,
                rf_daily=rf_eval, seed=77701 + wi,
                use_replay_on_real_dates=True,
                prefer_real_only_driver=True,
                driver_override=driver_col,
                stochastic_shocks=False,
                mode=mode,
                val_start_ts=vs_ts,
            )
        except Exception as recon_err:
            block['skipped'] = True
            block['skip_reason'] = f'reconstruction error: {recon_err}'
            blocks.append(block)
            continue

        if recon is None:
            block['skipped'] = True
            block['skip_reason'] = 'reconstruction returned None'
            blocks.append(block)
            continue

        idx_recon = pd.DatetimeIndex(recon['index'])
        oos_mask = np.asarray(recon['real_mask'], dtype=bool)
        oos_mask &= (idx_recon >= vs_ts) & (idx_recon <= ve_ts)
        if oos_mask.sum() < 10:
            block['skipped'] = True
            block['skip_reason'] = 'too few OOS real days after masking'
            blocks.append(block)
            continue

        actual_v  = np.asarray(recon['actual'],        dtype=np.float64)[oos_mask]
        recon_v   = np.asarray(recon['reconstructed'], dtype=np.float64)[oos_mask]
        n_oos     = int(len(actual_v))
        err_v     = recon_v - actual_v
        mean_err_ann = float(np.nanmean(err_v) * 252)
        te_ann       = float(np.nanstd(err_v)  * np.sqrt(252))
        W_actual  = float(np.prod(1.0 + actual_v))
        W_recon   = float(np.prod(1.0 + recon_v))
        tw_rel_err = float(abs(W_recon / W_actual - 1.0)) if W_actual != 0.0 else np.nan
        mdd_actual = float(abs(_max_drawdown_from_returns(actual_v)))
        mdd_recon  = float(abs(_max_drawdown_from_returns(recon_v)))
        mdd_diff   = float(abs(mdd_recon - mdd_actual))

        block['n_oos']       = n_oos
        block['mean_err_ann'] = mean_err_ann
        block['te_ann']       = te_ann
        block['tw_rel_err']   = tw_rel_err
        block['mdd_diff']     = mdd_diff
        block['cagr_actual']  = float(W_actual ** (252.0 / n_oos) - 1.0) if n_oos > 0 else np.nan
        block['cagr_recon']   = float(W_recon  ** (252.0 / n_oos) - 1.0) if n_oos > 0 else np.nan

        # Crisis sub-window scoring
        block['crash_scores'] = {}
        for (_clbl, _cs, _ce) in _CRISIS_WINDOWS:
            _cs_ts = pd.Timestamp(_cs)
            _ce_ts = pd.Timestamp(_ce)
            # Only score if the crisis window overlaps the val window
            if _cs_ts > ve_ts or _ce_ts < vs_ts:
                continue
            _cm = oos_mask & (idx_recon >= _cs_ts) & (idx_recon <= _ce_ts)
            if _cm.sum() < 5:
                continue
            _ca  = np.asarray(recon['actual'],        dtype=np.float64)[_cm]
            _cr  = np.asarray(recon['reconstructed'], dtype=np.float64)[_cm]
            _Wa  = float(np.prod(1.0 + _ca))
            _Wr  = float(np.prod(1.0 + _cr))
            _tw  = float(abs(_Wr / _Wa - 1.0)) if _Wa != 0.0 else np.nan
            block['crash_scores'][_clbl] = {'tw_rel_err': _tw, 'n_days': int(_cm.sum())}

        blocks.append(block)

    # ── Pool metrics and compute asset-level pass ──────────────────────────────
    eligible = [b for b in blocks if not b.get('skipped') and not b.get('low_train')]
    run_blocks = [b for b in blocks if not b.get('skipped')]

    def _pooled_weighted(key: str, blist: List[Dict]) -> float:
        vals  = np.array([b[key]   for b in blist if np.isfinite(b.get(key, np.nan))], dtype=np.float64)
        wts   = np.array([b['n_oos'] for b in blist if np.isfinite(b.get(key, np.nan))], dtype=np.float64)
        if len(vals) == 0 or wts.sum() == 0:
            return np.nan
        return float(np.average(vals, weights=wts))

    pooled_mean_err  = _pooled_weighted('mean_err_ann', eligible)
    pooled_tw        = _pooled_weighted('tw_rel_err', eligible)
    pooled_te        = _pooled_weighted('te_ann', eligible)
    n_eligible       = len(eligible)

    asset_passes = (
        n_eligible >= 3
        and np.isfinite(pooled_mean_err) and abs(pooled_mean_err) < 0.005
        and np.isfinite(pooled_tw)       and pooled_tw             < 0.10
        and np.isfinite(pooled_te)       and pooled_te             < 0.03
    )

    # ── Print walk-forward table ──────────────────────────────────────────────
    _mode_str = mode.value
    print(f"\n  Walk-Forward Validation — {fund_u}  ({_mode_str}, {CACHE_MODEL_VERSION})")
    _hdr = (f"  {'Block':<6} {'Train Window':<25} {'Valid Window':<18} "
            f"{'TrDays':>7} {'Bias':>7} {'TE':>6} {'TW%':>6} {'CrashScore':<20} {'Flag':<10}")
    print(_hdr)
    print("  " + "─" * (len(_hdr) - 2))
    for b in blocks:
        _lbl = b['window_label']
        _tr  = f"{b['train_start'][:7]} → {b['train_end'][:7]}"
        _vl  = f"{b['val_start'][:7]}→{b['val_end'][:7]}"
        _trd = str(b['n_train'])
        if b.get('skipped'):
            print(f"  {_lbl:<6} {_tr:<25} {_vl:<18} {_trd:>7} {'SKIP':>7}  {b.get('skip_reason', '')}")
            continue
        _bias_s = f"{b['mean_err_ann']*100:+.2f}%"
        _te_s   = f"{b['te_ann']*100:.2f}%"
        _tw_s   = f"{b['tw_rel_err']*100:.1f}%"
        _flags  = []
        if b.get('low_train'):
            _flags.append('LOW_TRAIN')
        _crash_s = ''
        for _clbl, _cv in b.get('crash_scores', {}).items():
            _crash_s += f"{_clbl}:{_cv['tw_rel_err']*100:.1f}% "
        if not _crash_s:
            _crash_s = 'n/a'
        print(f"  {_lbl:<6} {_tr:<25} {_vl:<18} {_trd:>7} {_bias_s:>7} {_te_s:>6} {_tw_s:>6} "
              f"{_crash_s:<20} {','.join(_flags):<10}")

    print("  " + "─" * (len(_hdr) - 2))
    _pooled_label = f"{'Pooled':<6} {'(eligible blocks only)':<25} {'':<18} {'':<7}"
    _pe_s  = f"{pooled_mean_err*100:+.2f}%" if np.isfinite(pooled_mean_err) else "n/a"
    _pte_s = f"{pooled_te*100:.2f}%"         if np.isfinite(pooled_te)       else "n/a"
    _ptw_s = f"{pooled_tw*100:.1f}%"          if np.isfinite(pooled_tw)       else "n/a"
    _verdict = 'PASS' if asset_passes else 'FAIL'
    print(f"  {'Pooled':<6} {'(eligible blocks only)':<25} {'':<18} {n_eligible:>7} "
          f"{_pe_s:>7} {_pte_s:>6} {_ptw_s:>6} {'':<20} {_verdict:<10}")

    return {
        'fund': fund_u,
        'mode': mode.value,
        'blocks': blocks,
        'n_blocks_run': len(run_blocks),
        'n_eligible': n_eligible,
        'pooled_mean_err_ann': pooled_mean_err,
        'pooled_tw_rel_err': pooled_tw,
        'pooled_te_ann': pooled_te,
        'all_blocks_pass': asset_passes,
        'overall_pass': asset_passes,
    }


def compute_crisis_fidelity_score(
        df: pd.DataFrame,
        fund: str,
        tracking_model: Optional[Dict] = None,
        rf_daily: Optional[np.ndarray] = None,
        mode: ValidationMode = ValidationMode.INSTITUTIONAL_GATE,
        crisis_windows: Optional[List[Tuple[str, str, str]]] = None,
) -> Dict[str, Any]:
    """
    Compute a crisis-period fidelity score for a leveraged fund.

    For each crisis window in _CRISIS_FIDELITY_WINDOWS (or override via crisis_windows):
      - Build _build_reconstructed_letf_series over the window.
      - Compute per-window mdd_err, tw_rel_err, cum_err_bps.
      - crisis_score_window = 0.5 * min(mdd_err/0.05, 1.0) + 0.5 * min(tw_rel_err/0.10, 1.0)
        (0 = perfect, 1 = worst)

    Aggregate: CRISIS_FIDELITY_SCORE = mean(1 - crisis_score_window)
    Range [0, 1]; higher = better. Threshold for PASS: >= 0.80.

    Returns dict with fund, crisis_fidelity_score, passes, windows, n_windows_scored.
    """
    fund_u = str(fund).upper()
    real_col = f'{fund_u}_Real_Ret'
    if real_col not in df.columns:
        return {
            'fund': fund_u, 'status': 'skipped',
            'reason': f'{real_col} not in df',
            'crisis_fidelity_score': float('nan'), 'passes': False,
            'windows': [], 'n_windows_scored': 0,
        }

    windows_to_check = crisis_windows if crisis_windows is not None else _CRISIS_FIDELITY_WINDOWS

    # Load or compute RF
    if rf_daily is None:
        try:
            rf_daily, _ = _load_daily_financing_rate_aligned(df)
        except Exception:
            rf_daily = np.zeros(len(df), dtype=np.float64)

    # Load tracking model if not provided
    if tracking_model is None:
        tracking_model = load_cache(TRACKING_RESIDUAL_CACHE)
        if not isinstance(tracking_model, dict):
            tracking_model = {}

    print(f"\n  === CRISIS FIDELITY SCORE — {fund_u} ({mode.value}) ===")
    print(f"  {'Window':<20} {'Days':>5} {'MaxDD_err':>10} {'TWE%':>7} {'Bias bps':>9} {'Score':>7}")
    print("  " + "─" * 62)

    scored_windows = []
    window_scores = []

    for (label, w_start, w_end) in windows_to_check:
        try:
            ws_ts = pd.Timestamp(w_start)
            we_ts = pd.Timestamp(w_end)

            # Slice df to window
            w_mask = (df.index >= ws_ts) & (df.index <= we_ts)
            w_df = df.loc[w_mask].copy()

            # Filter to real (non-synthetic) rows
            syn_col = f'{fund_u}_IsSynthetic'
            real_mask = np.isfinite(w_df[real_col].values)
            if syn_col in w_df.columns:
                real_mask &= (~w_df[syn_col].fillna(False).to_numpy(dtype=bool))
            n_real = int(real_mask.sum())

            if n_real < 20:
                print(f"  {label:<20} {n_real:>5} {'<20 real days — skip':>35}")
                continue

            # Align RF
            rf_w = rf_daily[w_mask] if len(rf_daily) == len(df) else np.zeros(int(w_mask.sum()), dtype=np.float64)

            # Build reconstruction
            recon_result = _build_reconstructed_letf_series(
                df=w_df,
                asset=fund_u,
                tracking_model=tracking_model,
                rf_daily=rf_w,
                seed=0,
                use_replay_on_real_dates=True,
                prefer_real_only_driver=True,
                stochastic_shocks=False,
                mode=mode,
                val_start_ts=None,
            )

            if recon_result is None:
                print(f"  {label:<20} {n_real:>5} {'recon failed — skip':>35}")
                continue

            actual_ret = np.asarray(w_df[real_col].values, dtype=np.float64)
            recon_ret = np.asarray(recon_result.get('reconstructed', np.full(len(w_df), np.nan)), dtype=np.float64)

            # Mask to real days only
            pair_mask = np.isfinite(actual_ret) & np.isfinite(recon_ret)
            if syn_col in w_df.columns:
                pair_mask &= (~w_df[syn_col].fillna(False).to_numpy(dtype=bool))
            if pair_mask.sum() < 20:
                continue

            actual_clean = actual_ret[pair_mask]
            recon_clean = recon_ret[pair_mask]

            m = _compute_reconstruction_metrics(actual_clean, recon_clean)

            mdd_actual = float(m.get('max_drawdown_actual', np.nan))
            mdd_recon = float(m.get('max_drawdown_reconstructed', np.nan))
            mdd_err = float(abs(mdd_recon - mdd_actual)) if np.isfinite(mdd_actual) and np.isfinite(mdd_recon) else float('nan')
            tw_rel_err = float(m.get('terminal_wealth_rel_err', np.nan))
            n_days_w = int(pair_mask.sum())
            years_w = max(float(n_days_w) / 252.0, 1e-6)
            # cum_err_bps: annualized CAGR difference in bps
            cagr_diff = float(m.get('cagr_diff_abs', np.nan))
            # signed: recon - actual
            cagr_act = float(m.get('cagr_actual', np.nan))
            cagr_rec = float(m.get('cagr_reconstructed', np.nan))
            cum_err_bps = float((cagr_rec - cagr_act) * 10000.0) if np.isfinite(cagr_act) and np.isfinite(cagr_rec) else float('nan')

            # crisis_score_window (0 = perfect, 1 = worst)
            mdd_component = min(mdd_err / 0.05, 1.0) if np.isfinite(mdd_err) else 1.0
            tw_component = min(tw_rel_err / 0.10, 1.0) if np.isfinite(tw_rel_err) else 1.0
            crisis_score_window = 0.5 * mdd_component + 0.5 * tw_component
            window_fidelity = 1.0 - crisis_score_window

            scored_windows.append({
                'label': label,
                'n_real_days': n_real,
                'n_days_scored': n_days_w,
                'mdd_actual': mdd_actual,
                'mdd_reconstructed': mdd_recon,
                'mdd_err': mdd_err,
                'tw_rel_err': tw_rel_err,
                'cum_err_bps': cum_err_bps,
                'crisis_score_window': crisis_score_window,
                'window_fidelity': window_fidelity,
                'metrics': m,
            })
            window_scores.append(window_fidelity)

            mdd_err_str = f"{mdd_err*100:.1f}%" if np.isfinite(mdd_err) else "n/a"
            tw_str = f"{tw_rel_err*100:.1f}%" if np.isfinite(tw_rel_err) else "n/a"
            bias_str = f"{cum_err_bps:.1f}" if np.isfinite(cum_err_bps) else "n/a"
            score_str = f"{window_fidelity:.3f}"
            print(f"  {label:<20} {n_days_w:>5} {mdd_err_str:>10} {tw_str:>7} {bias_str:>9} {score_str:>7}")

        except Exception as _cfe:
            print(f"  {label:<20} {'error':>5} {str(_cfe)[:40]}")
            continue

    n_scored = len(window_scores)
    if n_scored == 0:
        crisis_fidelity_score = float('nan')
        passes = False
        print("  (no windows scored)")
    else:
        crisis_fidelity_score = float(np.mean(window_scores))
        passes = bool(crisis_fidelity_score >= 0.80)

    print("  " + "─" * 62)
    verdict = "✓ PASS" if passes else ("⚠ SKIP (< 2 windows)" if n_scored < 2 else "⚠ FAIL")
    if n_scored < 2:
        passes = True  # not enough windows to grade
    print(f"  Crisis Fidelity Score ({n_scored} windows): {crisis_fidelity_score:.3f}  {verdict}  (threshold ≥ 0.80)")

    return {
        'fund': fund_u,
        'status': 'scored',
        'crisis_fidelity_score': crisis_fidelity_score,
        'passes': passes,
        'n_windows_scored': n_scored,
        'windows': scored_windows,
    }


def validate_synthetic_driver_realism(
        paths_spy_returns: List[np.ndarray],
        df_historical: pd.DataFrame,
        regime_model: Optional[Dict] = None,
        mean_tol: float = 0.10,
        vol_tol:  float = 0.10,
        mdd_tol:  float = 0.20,
) -> Dict[str, Any]:
    """
    Validate that synthetic driver returns match real driver statistics (PART 5).

    Computes per-path and aggregate statistics vs historical reference.
    Flags WARNING (does NOT block reconstruction gate) if outside tolerance.
    Only blocks scenario generator validation.

    Checks:
        D1: mean return (|sim_mean - hist_mean| / |hist_mean| <= mean_tol)
        D2: annualized volatility (|sim_vol - hist_vol| / hist_vol <= vol_tol)
        D3: skewness (informational)
        D4: kurtosis (informational)
        D5: max drawdown (|sim_mdd - hist_mdd| / hist_mdd <= mdd_tol)
        D6: vol clustering (lag-1 autocorr of squared returns)
    """
    from scipy import stats as _sp_stats_drv

    if not paths_spy_returns:
        return {'overall_warning': False, 'reason': 'no paths provided', 'checks': {}}

    hist_col = (
        'SPY_Ret_RealOnly' if 'SPY_Ret_RealOnly' in df_historical.columns
        else 'SPY_Ret' if 'SPY_Ret' in df_historical.columns
        else None
    )
    if hist_col is None:
        return {'overall_warning': False, 'reason': 'no SPY return column in historical df', 'checks': {}}

    hist_arr = np.asarray(
        pd.to_numeric(df_historical[hist_col], errors='coerce').dropna().values,
        dtype=np.float64,
    )
    if len(hist_arr) < 50:
        return {'overall_warning': False, 'reason': 'insufficient historical data', 'checks': {}}

    hist_mean = float(np.mean(hist_arr))
    hist_vol  = float(np.std(hist_arr, ddof=1) * np.sqrt(252))
    hist_skew = float(_sp_stats_drv.skew(hist_arr))
    hist_kurt = float(_sp_stats_drv.kurtosis(hist_arr))
    hist_mdd  = float(_max_drawdown_from_returns(hist_arr))
    _sq_hist  = hist_arr ** 2
    hist_acf  = float(np.corrcoef(_sq_hist[:-1], _sq_hist[1:])[0, 1]) if len(hist_arr) > 10 else float('nan')

    sim_means, sim_vols, sim_skews, sim_kurts, sim_mdds, sim_acfs = [], [], [], [], [], []
    for p in paths_spy_returns:
        _p = np.asarray(p, dtype=np.float64)
        _p = _p[np.isfinite(_p)]
        if len(_p) < 20:
            continue
        sim_means.append(float(np.mean(_p)))
        sim_vols.append(float(np.std(_p, ddof=1) * np.sqrt(252)))
        sim_skews.append(float(_sp_stats_drv.skew(_p)))
        sim_kurts.append(float(_sp_stats_drv.kurtosis(_p)))
        sim_mdds.append(float(_max_drawdown_from_returns(_p)))
        if len(_p) > 10:
            _sq = _p ** 2
            sim_acfs.append(float(np.corrcoef(_sq[:-1], _sq[1:])[0, 1]))

    if not sim_means:
        return {'overall_warning': False, 'reason': 'no valid sim paths', 'checks': {}}

    agg_mean = float(np.nanmean(sim_means))
    agg_vol  = float(np.nanmean(sim_vols))
    agg_skew = float(np.nanmean(sim_skews))
    agg_kurt = float(np.nanmean(sim_kurts))
    agg_mdd  = float(np.nanmean(sim_mdds))
    agg_acf  = float(np.nanmean(sim_acfs)) if sim_acfs else float('nan')

    warnings_issued: List[str] = []
    checks: Dict[str, Any] = {}

    print(f"\n  Synthetic Driver Realism Validation  (n_paths={len(paths_spy_returns):,})")
    print(f"  {'─'*62}")

    # D1: mean return
    _mean_rel_diff = abs(agg_mean - hist_mean) / (abs(hist_mean) + 1e-12)
    _d1_warn = bool(_mean_rel_diff > mean_tol)
    checks['mean_return'] = {'warning': _d1_warn, 'sim': agg_mean, 'hist': hist_mean,
                              'rel_diff': _mean_rel_diff, 'tol': mean_tol}
    _m1 = '⚠' if _d1_warn else '✓'
    print(f"  {_m1} D1 Mean return  : sim={agg_mean*252*100:.2f}%/yr  "
          f"hist={hist_mean*252*100:.2f}%/yr  "
          f"rel_diff={_mean_rel_diff*100:.1f}%  tol={mean_tol*100:.0f}%")
    if _d1_warn:
        warnings_issued.append(f"D1 mean return diff {_mean_rel_diff*100:.1f}% > {mean_tol*100:.0f}% tol")

    # D2: annualized volatility
    _vol_rel_diff = abs(agg_vol - hist_vol) / max(hist_vol, 1e-6)
    _d2_warn = bool(_vol_rel_diff > vol_tol)
    checks['volatility'] = {'warning': _d2_warn, 'sim': agg_vol, 'hist': hist_vol,
                             'rel_diff': _vol_rel_diff, 'tol': vol_tol}
    _m2 = '⚠' if _d2_warn else '✓'
    print(f"  {_m2} D2 Ann volatility: sim={agg_vol*100:.1f}%/yr  "
          f"hist={hist_vol*100:.1f}%/yr  "
          f"rel_diff={_vol_rel_diff*100:.1f}%  tol={vol_tol*100:.0f}%")
    if _d2_warn:
        warnings_issued.append(f"D2 vol diff {_vol_rel_diff*100:.1f}% > {vol_tol*100:.0f}% tol")

    # D3: skewness (informational)
    checks['skewness'] = {'warning': False, 'sim': agg_skew, 'hist': hist_skew}
    print(f"  — D3 Skewness (info): sim={agg_skew:.3f}  hist={hist_skew:.3f}")

    # D4: kurtosis (informational)
    checks['kurtosis'] = {'warning': False, 'sim': agg_kurt, 'hist': hist_kurt}
    print(f"  — D4 Kurtosis (info): sim={agg_kurt:.3f}  hist={hist_kurt:.3f}")

    # D5: max drawdown
    _mdd_rel_diff = abs(agg_mdd - hist_mdd) / max(abs(hist_mdd), 1e-6)
    _d5_warn = bool(_mdd_rel_diff > mdd_tol)
    checks['max_drawdown'] = {'warning': _d5_warn, 'sim': agg_mdd, 'hist': hist_mdd,
                               'rel_diff': _mdd_rel_diff, 'tol': mdd_tol}
    _m5 = '⚠' if _d5_warn else '✓'
    print(f"  {_m5} D5 Max drawdown : sim={agg_mdd*100:.1f}%  "
          f"hist={hist_mdd*100:.1f}%  "
          f"rel_diff={_mdd_rel_diff*100:.1f}%  tol={mdd_tol*100:.0f}%")
    if _d5_warn:
        warnings_issued.append(f"D5 MDD diff {_mdd_rel_diff*100:.1f}% > {mdd_tol*100:.0f}% tol")

    # D6: vol clustering
    _acf_diff = (abs(agg_acf - hist_acf)
                 if np.isfinite(agg_acf) and np.isfinite(hist_acf)
                 else float('nan'))
    _d6_warn = bool(np.isfinite(_acf_diff) and _acf_diff > 0.07)
    checks['vol_clustering'] = {'warning': _d6_warn, 'sim': agg_acf, 'hist': hist_acf}
    _m6 = '⚠' if _d6_warn else '✓'
    _hist_acf_str = f"{hist_acf:.3f}" if np.isfinite(hist_acf) else "n/a"
    print(f"  {_m6} D6 Vol clustering: sim_acf={agg_acf:.3f}  hist_acf={_hist_acf_str}  tol=0.07")
    if _d6_warn:
        warnings_issued.append(f"D6 vol clustering ACF diff {_acf_diff:.3f} > 0.07 tol")

    overall_warning = len(warnings_issued) > 0
    verdict = "⚠ WARNINGS ISSUED" if overall_warning else "✓ REALISTIC"
    print(f"  {'─'*62}")
    print(f"  {verdict}  (does NOT block reconstruction gate; only blocks scenario gen validation)")
    if warnings_issued:
        for w in warnings_issued:
            print(f"    ⚠ {w}")

    return {
        'overall_warning': overall_warning,
        'warnings': warnings_issued,
        'checks': checks,
        'metrics': {
            'hist': {'mean': hist_mean, 'vol': hist_vol, 'skew': hist_skew,
                     'kurt': hist_kurt, 'mdd': hist_mdd, 'vol_acf': hist_acf},
            'sim':  {'mean': agg_mean,  'vol': agg_vol,  'skew': agg_skew,
                     'kurt': agg_kurt,  'mdd': agg_mdd,  'vol_acf': agg_acf},
    },
}

# Canonical display alias shares the exact same preset object as the legacy
# engine key so any runtime updates (for example inflation display refresh) stay aligned.
_SCENARIO_PRESETS['extended_historical_backtest'] = _SCENARIO_PRESETS['historical_backtest']


def validate_full_history_reconstruction(
        df: pd.DataFrame,
        tracking_model: Optional[Dict] = None,
        rf_daily: Optional[np.ndarray] = None,
        funds: Optional[List[str]] = None,
        mode: ValidationMode = ValidationMode.DIAGNOSTIC_REPLAY,
        warn_only: bool = True,
) -> Dict[str, Any]:
    """
    Full-history LETF reconstruction validation (PART 6) — INFORMATIONAL ONLY.

    Compares hybrid reconstruction vs actual LETF returns over the entire real
    history (both TRAIN and OOS combined) to verify overall fidelity of the
    reconstruction formula.

    *** THIS IS NOT AN INSTITUTIONAL GATE ***
    This is an in-sample fit check.  It can pass even when OOS fails (overfitting /
    leakage) and can fail for legitimate reasons unrelated to forward realism (e.g.
    mixing regimes across long history windows).

    Use validate_letf_emulator_oos for the leakage-free OOS evaluation required by
    INSTITUTIONAL_GATE.  This function is warn-only by default (warn_only=True).
    Set warn_only=False AND STRICT_HIST_RECON=True only when the stated goal is exact
    in-sample replication, not forward simulation.

    Thresholds (informational reference):
        terminal_wealth_error < 10%    (|TW_recon / TW_actual - 1|)
        tracking_error        < 2%/yr  (annualized daily TE)
        correlation           > 0.95
    """
    if funds is None:
        funds = ['UPRO', 'SSO', 'TQQQ', 'QLD']

    if rf_daily is None:
        try:
            rf_daily, _ = _load_daily_financing_rate_aligned(df)
        except Exception:
            rf_daily = np.zeros(len(df), dtype=np.float64)

    if tracking_model is None:
        tracking_model = load_cache(TRACKING_RESIDUAL_CACHE)
        if not isinstance(tracking_model, dict):
            tracking_model = {}

    TW_ERR_MAX = 0.10    # terminal wealth relative error threshold
    TE_ANN_MAX = 0.02    # annualized tracking error threshold
    CORR_MIN   = 0.95    # minimum correlation

    results: Dict[str, Any] = {'warn_only': warn_only}
    # warn_only=True means this function NEVER returns overall_pass=False.
    # It prints health metrics and warns, but does NOT block the institutional gate.
    overall_pass = True  # always True in warn-only mode; health metric only
    n_warn = 0
    n_pass = 0
    n_fail = 0  # counted for reporting only; does not affect overall_pass when warn_only

    print(f"\n{'='*68}")
    print("FULL-HISTORY RECONSTRUCTION  (PART 6 — INFORMATIONAL / WARN-ONLY)")
    print(f"{'='*68}")
    if warn_only:
        print("  *** NOT AN INSTITUTIONAL GATE — in-sample fit check only ***")
        print("  Failures printed as WARN; OOS gate (validate_letf_emulator_oos) is binding.")
    print(f"  Mode: {mode.value}   Thresholds: TW_err<{TW_ERR_MAX*100:.0f}%  "
          f"TE<{TE_ANN_MAX*100:.1f}%/yr  corr>{CORR_MIN:.2f}")
    print(f"  {'Asset':<8} {'Days':>6} {'Corr':>7} {'TE%/yr':>8} {'TW_err%':>9} {'CAGR%/yr':>10} {'Status':>7}")
    print("  " + "─" * 58)

    for fund in funds:
        real_col = f'{fund}_Real_Ret'
        if real_col not in df.columns:
            results[fund] = {'status': 'skipped', 'reason': f'{real_col} not in df'}
            print(f"  {fund:<8} {'—':>6} {'—':>7} {'—':>8} {'—':>9} {'—':>10} {'SKIP':>6}")
            continue

        recon = _build_reconstructed_letf_series(
            df=df,
            asset=fund,
            tracking_model=tracking_model,
            rf_daily=np.asarray(rf_daily, dtype=np.float64),
            seed=0,
            use_replay_on_real_dates=True,
            prefer_real_only_driver=True,
            stochastic_shocks=False,
            mode=mode,
            val_start_ts=None,
        )
        if recon is None:
            results[fund] = {'status': 'skipped', 'reason': 'reconstruction unavailable'}
            print(f"  {fund:<8} {'—':>6} {'—':>7} {'—':>8} {'—':>9} {'—':>10} {'SKIP':>6}")
            continue

        real_mask_arr = np.asarray(recon['real_mask'], dtype=bool)
        actual_all    = np.asarray(recon['actual'],        dtype=np.float64)
        recon_all     = np.asarray(recon['reconstructed'], dtype=np.float64)
        actual_sub    = actual_all[real_mask_arr]
        recon_sub     = recon_all[real_mask_arr]
        n_days = int(real_mask_arr.sum())

        if n_days < 20:
            results[fund] = {'status': 'skipped', 'reason': f'only {n_days} real days'}
            print(f"  {fund:<8} {n_days:>6} {'—':>7} {'—':>8} {'—':>9} {'—':>10} {'SKIP':>6}")
            continue

        m = _compute_reconstruction_metrics(actual=actual_sub, reconstructed=recon_sub)
        corr   = float(m.get('corr',                    np.nan))
        te_ann = float(m.get('tracking_error_ann',      np.nan))
        tw_err = float(m.get('terminal_wealth_rel_err', np.nan))
        cagr_a = float(m.get('cagr_actual',             np.nan))
        cagr_r = float(m.get('cagr_reconstructed',      np.nan))

        passes_corr = bool(np.isfinite(corr)   and corr   >= CORR_MIN)
        passes_te   = bool(np.isfinite(te_ann) and te_ann <= TE_ANN_MAX)
        passes_tw   = bool(np.isfinite(tw_err) and tw_err <= TW_ERR_MAX)
        asset_pass  = passes_corr and passes_te and passes_tw

        if not asset_pass:
            n_fail += 1
            if not warn_only:
                overall_pass = False  # only propagate failure when explicitly NOT warn-only
        else:
            n_pass += 1

        if warn_only:
            verdict_str = '✓ ok' if asset_pass else '⚠ WARN'
        else:
            verdict_str = '✓ PASS' if asset_pass else '✗ FAIL'
        cagr_diff_str = (f"{(cagr_r - cagr_a)*100:+.2f}" if np.isfinite(cagr_a) and np.isfinite(cagr_r)
                         else "n/a")
        print(f"  {fund:<8} {n_days:>6} {corr:>7.4f} {te_ann*100:>8.2f} "
              f"{tw_err*100:>9.2f} {cagr_diff_str:>10} {verdict_str:>7}")

        warn_reasons_fhr = []
        if not passes_corr:
            warn_reasons_fhr.append(f"corr={corr:.4f} < {CORR_MIN:.2f}")
        if not passes_te:
            warn_reasons_fhr.append(f"TE={te_ann*100:.2f}% > {TE_ANN_MAX*100:.1f}%/yr")
        if not passes_tw:
            warn_reasons_fhr.append(f"TW_err={tw_err*100:.1f}% > {TW_ERR_MAX*100:.0f}%")
        if warn_reasons_fhr:
            label = "WARN (in-sample only)" if warn_only else "FAIL"
            print(f"    → {label}: {', '.join(warn_reasons_fhr)}")
        fail_reasons_fhr = warn_reasons_fhr  # alias for result dict

        results[fund] = {
            'status':       'evaluated',
            'n_days':       n_days,
            'corr':         corr,
            'te_ann':       te_ann,
            'tw_rel_err':   tw_err,
            'cagr_actual':  cagr_a,
            'cagr_recon':   cagr_r,
            'passes_corr':  passes_corr,
            'passes_te':    passes_te,
            'passes_tw':    passes_tw,
            'asset_pass':   asset_pass,
            'fail_reasons': fail_reasons_fhr,
            'metrics':      m,
        }

    print("  " + "─" * 58)
    if warn_only:
        verdict_str = (f"✓ all within thresholds" if n_fail == 0
                       else f"⚠ {n_fail} asset(s) outside thresholds (warn-only, not a gate failure)")
        print(f"  Health check: {verdict_str}  ({n_pass} ok, {n_fail} warn)")
        print("  (To use as a hard gate, call with warn_only=False — NOT recommended for forward models)")
    else:
        verdict_str = "✓ ALL PASS" if overall_pass else f"✗ FAIL ({n_fail} asset(s))"
        print(f"  Overall: {verdict_str}  ({n_pass} pass, {n_fail} fail)")
    print(f"{'='*68}\n")

    # overall_pass is always True in warn_only mode — this function is never a hard gate by default
    results['overall_pass'] = overall_pass
    results['n_pass'] = n_pass
    results['n_fail'] = n_fail
    results['n_warn'] = n_fail if warn_only else 0
    return results


def validate_volatility_drag(
        asset: str,
        driver_returns: np.ndarray,
        letf_returns: np.ndarray,
        leverage: float,
        expense: float,
        rf_daily: Optional[np.ndarray] = None,
        tol_relative: float = 0.10,
) -> Dict[str, Any]:
    """
    Verify that the mean LETF return matches the theoretical volatility drag formula
    (PART 8).

    Theoretical mean LETF return per day (Ito's lemma):
        E[r_LETF] ≈ L * E[r_d]
                   - 0.5 * L * (L - 1) * Var(r_d)
                   - expense/252
                   - (L - 1) * E[rf_daily]

    where r_d is the underlying daily return and rf_daily is the daily risk-free rate.

    Flags WARNING if mismatch exceeds tol_relative (default 10%).
    Does NOT fail the validation gate — informational only.
    """
    d_arr = np.asarray(driver_returns, dtype=np.float64)
    l_arr = np.asarray(letf_returns,   dtype=np.float64)
    mask  = np.isfinite(d_arr) & np.isfinite(l_arr)
    if mask.sum() < 30:
        return {'asset': asset, 'status': 'insufficient_data',
                'n_days': int(mask.sum()), 'passes': True}

    d_clean = d_arr[mask]
    l_clean = l_arr[mask]
    if rf_daily is not None and len(rf_daily) >= len(d_arr):
        rf_arr = np.asarray(rf_daily, dtype=np.float64)[mask]
    else:
        rf_arr = np.zeros(int(mask.sum()), dtype=np.float64)

    mean_d  = float(np.mean(d_clean))
    var_d   = float(np.var(d_clean, ddof=1))
    mean_rf = float(np.mean(rf_arr))
    expense_daily = float(expense) / 252.0

    # Theoretical drag via Ito's lemma
    mean_letf_theoretical = (
        leverage * mean_d
        - 0.5 * leverage * (leverage - 1.0) * var_d
        - expense_daily
        - (leverage - 1.0) * mean_rf
    )
    mean_letf_actual = float(np.mean(l_clean))

    abs_diff  = float(abs(mean_letf_actual - mean_letf_theoretical))
    denom     = max(abs(mean_letf_theoretical), 1e-9)
    rel_diff  = abs_diff / denom
    passes    = bool(rel_diff <= tol_relative)
    verdict   = '✓' if passes else '⚠'

    print(f"\n  Volatility Drag Validation — {asset}")
    print(f"  L={leverage:.1f}x | expense={expense*100:.2f}%/yr | n={int(mask.sum()):,}d")
    print(f"  E[r_driver]      = {mean_d   * 252 * 100:.3f}%/yr")
    print(f"  Var(r_driver)    = {var_d    * 252 * 100:.4f}%/yr (annualized)")
    print(f"  Theoretical drag = L*(L-1)/2*Var = "
          f"{0.5 * leverage * (leverage - 1.0) * var_d * 252 * 100:.3f}%/yr")
    print(f"  Mean LETF actual = {mean_letf_actual       * 252 * 100:.3f}%/yr")
    print(f"  Mean LETF theory = {mean_letf_theoretical  * 252 * 100:.3f}%/yr")
    print(f"  Mismatch         = {abs_diff * 252 * 100:.3f}%/yr  "
          f"({rel_diff * 100:.1f}% rel)  tol={tol_relative * 100:.0f}%")
    print(f"  {verdict} {'PASS' if passes else 'WARNING: mismatch exceeds tolerance (informational)'}")

    return {
        'asset':                    asset,
        'n_days':                   int(mask.sum()),
        'mean_driver_ann':          float(mean_d  * 252),
        'var_driver_ann':           float(var_d   * 252),
        'mean_rf_ann':              float(mean_rf * 252),
        'mean_letf_actual_ann':     float(mean_letf_actual      * 252),
        'mean_letf_theoretical_ann': float(mean_letf_theoretical * 252),
        'abs_diff_ann':             float(abs_diff * 252),
        'rel_diff':                 float(rel_diff),
        'passes':                   passes,
        'tol':                      tol_relative,
    }


def compute_parameter_stability_report(
        df: pd.DataFrame,
        fund: str,
        wf_windows: Optional[List[Tuple[str, str]]] = None,
) -> Dict[str, Any]:
    """
    Assess parameter stability of the tracking residual calibration across
    walk-forward blocks.

    For each block with sufficient TRAIN days, calibrate tracking_residual_model
    (bypass_cache=True) and record calibrated_spread, driver_alpha_daily,
    underlying_scale.

    Stability stats across eligible blocks: mean, std, CoV (std/|mean|), max_drift.
    Flag UNSTABLE: CoV > 0.5 OR max_drift > 2 × |mean|.

    Returns a dict with per-parameter stability stats and a compact printed table.
    """
    fund_u = str(fund).upper()
    real_col = f'{fund_u}_Real_Ret'
    syn_col = f'{fund_u}_IsSynthetic'

    if real_col not in df.columns:
        return {'fund': fund_u, 'status': 'skipped', 'reason': f'{real_col} not in df'}

    windows = wf_windows if wf_windows is not None else _WALKFORWARD_VAL_WINDOWS

    print(f"\n  === PARAMETER STABILITY REPORT — {fund_u} ===")
    print(f"  {'Block':<8} {'Train End':<12} {'cal_spread_bps':>15} {'alpha_bps/d':>12} {'scale':>8}")
    print("  " + "─" * 60)

    records = []
    real_mask_all = np.isfinite(df[real_col].values)
    if syn_col in df.columns:
        real_mask_all &= (~df[syn_col].fillna(False).to_numpy(dtype=bool))
    real_dates = df.index[real_mask_all]
    if len(real_dates) == 0:
        return {'fund': fund_u, 'status': 'skipped', 'reason': 'no real rows'}
    inception_ts = real_dates[0]

    for wi, (vs, ve) in enumerate(windows):
        vs_ts = pd.Timestamp(vs)
        train_end_ts = vs_ts - pd.tseries.offsets.BDay(1)
        train_mask = (df.index >= inception_ts) & (df.index <= train_end_ts)
        train_mask_arr = train_mask.values if hasattr(train_mask, 'values') else np.asarray(train_mask)
        real_train = real_mask_all & train_mask_arr
        n_train = int(real_train.sum())

        if n_train < _WF_MIN_TRAIN_DAYS:
            print(f"  W{wi+1:<7} {str(train_end_ts.date()):<12} {'SKIP (too few train days)':>35}")
            continue

        train_df = df.loc[train_mask].copy()

        try:
            trk_model = calibrate_tracking_residual_model(train_df, bypass_cache=True)
        except Exception as _e:
            print(f"  W{wi+1:<7} {str(train_end_ts.date()):<12} {'CALIB ERROR':>35} {str(_e)[:30]}")
            continue

        asset_entry = trk_model.get(fund_u, {}) if isinstance(trk_model, dict) else {}
        if not isinstance(asset_entry, dict):
            continue

        spread_stats = asset_entry.get('spread_model', {})
        cal_spread = float(spread_stats.get('mean_daily', np.nan)) * 252.0 if isinstance(spread_stats, dict) else float('nan')
        driver_alpha = float(asset_entry.get('driver_alpha_daily', np.nan))
        underlying_scale = float(asset_entry.get('underlying_scale', np.nan))

        records.append({
            'block': f'W{wi+1}',
            'train_end': str(train_end_ts.date()),
            'n_train': n_train,
            'cal_spread_ann': cal_spread,
            'driver_alpha_daily': driver_alpha,
            'underlying_scale': underlying_scale,
        })

        cs_str = f"{cal_spread*10000:.1f}" if np.isfinite(cal_spread) else "n/a"
        da_str = f"{driver_alpha*10000:.3f}" if np.isfinite(driver_alpha) else "n/a"
        sc_str = f"{underlying_scale:.4f}" if np.isfinite(underlying_scale) else "n/a"
        print(f"  W{wi+1:<7} {str(train_end_ts.date()):<12} {cs_str:>15} {da_str:>12} {sc_str:>8}")

    print("  " + "─" * 60)

    if len(records) < 2:
        print("  (fewer than 2 blocks — stability cannot be assessed)")
        return {'fund': fund_u, 'status': 'insufficient_blocks', 'records': records}

    def _stability_stats(vals: np.ndarray) -> Dict[str, float]:
        vals = vals[np.isfinite(vals)]
        if len(vals) < 2:
            return {'mean': float('nan'), 'std': float('nan'), 'cov': float('nan'), 'max_drift': float('nan'), 'unstable': False}
        mean_v = float(np.mean(vals))
        std_v = float(np.std(vals, ddof=1))
        cov_v = float(std_v / max(abs(mean_v), 1e-12))
        max_drift = float(np.max(np.abs(vals - mean_v)))
        unstable = bool(cov_v > 0.5 or max_drift > 2.0 * abs(mean_v))
        return {'mean': mean_v, 'std': std_v, 'cov': cov_v, 'max_drift': max_drift, 'unstable': unstable}

    spreads = np.array([r['cal_spread_ann'] for r in records], dtype=np.float64)
    alphas = np.array([r['driver_alpha_daily'] for r in records], dtype=np.float64)
    scales = np.array([r['underlying_scale'] for r in records], dtype=np.float64)

    spread_stats_out = _stability_stats(spreads)
    alpha_stats_out = _stability_stats(alphas)
    scale_stats_out = _stability_stats(scales)

    def _fmt_stat(s: Dict[str, float], scale: float = 1.0, unit: str = '') -> str:
        if not np.isfinite(s['mean']):
            return 'n/a'
        flag = ' ⚠UNSTABLE' if s['unstable'] else ''
        return (f"mean={s['mean']*scale:.2f}{unit}  std={s['std']*scale:.2f}{unit}  "
                f"CoV={s['cov']:.2f}  max_drift={s['max_drift']*scale:.2f}{unit}{flag}")

    print(f"  cal_spread:       {_fmt_stat(spread_stats_out, scale=10000, unit=' bps')}")
    print(f"  driver_alpha:     {_fmt_stat(alpha_stats_out, scale=10000, unit=' bps/d')}")
    print(f"  underlying_scale: {_fmt_stat(scale_stats_out, scale=1.0, unit='')}")

    overall_stable = not any([
        bool(spread_stats_out.get('unstable', False)),
        bool(alpha_stats_out.get('unstable', False)),
        bool(scale_stats_out.get('unstable', False)),
    ])
    print(f"\n  Overall stability: {'✓ STABLE' if overall_stable else '⚠ UNSTABLE (CoV > 0.5 or max_drift > 2×mean)'}")

    return {
        'fund': fund_u,
        'status': 'completed',
        'n_blocks': len(records),
        'records': records,
        'cal_spread': spread_stats_out,
        'driver_alpha': alpha_stats_out,
        'underlying_scale': scale_stats_out,
        'overall_stable': overall_stable,
    }


def validate_taxable_vs_taxfree_spy(
        df: pd.DataFrame,
        regime_model: Dict,
        correlation_matrices: Dict,
        n_paths: int = 100,
        horizon_years: int = 10,
) -> Dict[str, Any]:
    """
    Validation test: SPY taxable CAGR must be strictly lower than tax-free CAGR
    due to dividend taxation. Confirms taxes are applied at portfolio layer only.

    Also checks that NO dividend distributions are injected when the driver is
    a total-return index (double-taxation guard).
    """
    print("\n  === TAX LAYER VALIDATION: TAXABLE vs TAX-FREE SPY ===")

    n_sim = min(int(n_paths), 60)
    elections = TaxpayerElections()
    tax_cfg = {'filing_status': 'single', 'state': 'CA', 'ordinary_income': 150000, 'career_stage': 'mid'}

    def _cagr(terminal_wealth: float, years: float) -> float:
        y = max(float(years), 1e-9)
        return float((max(float(terminal_wealth), 1e-12) / INITIAL_CAPITAL) ** (1.0 / y) - 1.0)

    def _post_tax_terminal(pre_tax_wealth: float,
                           trades: List[Dict[str, Any]],
                           years: int) -> Tuple[float, float]:
        if not trades:
            return float(pre_tax_wealth), 0.0
        tax_result = process_trades_with_wired_engine(
            trades=trades,
            time_horizon_years=int(max(1, years)),
            elections=elections,
            initial_capital=float(INITIAL_CAPITAL),
            debug=False,
            strategy_id='SPY_TAX_VALIDATION',
            tax_config=tax_cfg
        )
        tax_paid = float(max(tax_result.get('total_tax', 0.0), 0.0))
        post_tax = float(max(0.0, float(pre_tax_wealth) - tax_paid))
        return post_tax, tax_paid

    # Prefer a true taxable SPY benchmark if one is explicitly configured.
    taxable_spy_sid = None
    for sid in TAXABLE_IDS:
        _cfg = STRATEGIES.get(sid, {})
        _asset = str(_cfg.get('asset', '')).upper()
        _name = str(_cfg.get('name', '')).upper()
        _stype = str(_cfg.get('type', '')).lower()
        if (_asset == 'SPY' and _stype == 'benchmark') or ('SPY' in _name and 'BUY HOLD' in _name):
            taxable_spy_sid = sid
            break

    wlth_free: List[float] = []
    wlth_taxable: List[float] = []
    years_eff = float(horizon_years)
    mode = 'strategy_pair'

    if taxable_spy_sid is not None:
        # Strategy-pair branch: compare tax-free SPY benchmark to taxable SPY benchmark,
        # and explicitly convert taxable branch to post-tax terminal wealth.
        def _run_sid(sid: str, taxable: bool) -> List[float]:
            results: List[float] = []
            for i in range(n_sim):
                try:
                    res = simulate_single_path_fixed(
                        (i, horizon_years, regime_model, correlation_matrices, [sid])
                    )
                    if not (res and sid in res and res[sid].get('status') == 'success'):
                        continue
                    pre_tax = float(res[sid].get('Final_Wealth', np.nan))
                    if not np.isfinite(pre_tax):
                        continue
                    if taxable:
                        post_tax, _ = _post_tax_terminal(
                            pre_tax_wealth=pre_tax,
                            trades=res[sid].get('Trade_List', []),
                            years=int(max(1, round(float(horizon_years))))
                        )
                        results.append(post_tax)
                    else:
                        results.append(pre_tax)
                except Exception:
                    continue
            return results

        wlth_free = _run_sid('S2', taxable=False)
        wlth_taxable = _run_sid(taxable_spy_sid, taxable=True)
    else:
        # No taxable SPY strategy exists in STRATEGIES/TAXABLE_IDS. Run a direct
        # SPY buy/hold tax sanity check using chronological historical backtest paths.
        print("  Note: no taxable SPY benchmark strategy configured; "
              "using direct SPY buy/hold tax sanity check.")
        window_data = _slice_hist1926_to_window(ANALYSIS_START_DATE, ANALYSIS_END_DATE, min_days=252)
        if window_data is None:
            return {'status': 'skipped', 'reason': 'no valid historical window for SPY tax sanity check'}

        n_days_req = int(max(252, round(float(horizon_years) * 252.0)))
        n_days = int(min(int(window_data.get('N', 0)), n_days_req))
        if n_days < 63:
            return {'status': 'skipped', 'reason': f'insufficient historical days for tax sanity check (N={n_days})'}
        years_eff = float(n_days / 252.0)
        mode = 'direct_spy_buy_hold'
        rng_tax = np.random.default_rng(87231)

        for i in range(n_sim):
            try:
                p = _get_historical_path_returns(
                    path_idx=i,
                    n_paths=max(1, n_sim),
                    n_days=n_days,
                    mode='backtest',
                    block_size=63,
                    rng=rng_tax,
                    hist_data=window_data
                )
                spy = np.asarray(p['SPY_Ret'], dtype=float)
                if len(spy) != n_days or np.isnan(spy).any():
                    continue
                compound = float(np.prod(1.0 + spy))
                pre_tax = float(max(0.0, INITIAL_CAPITAL * compound))
                start_price = 100.0
                shares = float(INITIAL_CAPITAL / start_price)
                end_price = float(max(start_price * compound, 1e-9))
                trades = [
                    {'day_index': 0, 'asset': 'SPY', 'action': 'BUY',
                     'dollar_amount': float(INITIAL_CAPITAL), 'price': float(start_price), 'shares': shares},
                    {'day_index': int(n_days - 1), 'asset': 'SPY', 'action': 'SELL',
                     'dollar_amount': float(shares * end_price), 'price': float(end_price), 'shares': shares},
                ]
                post_tax, _ = _post_tax_terminal(
                    pre_tax_wealth=pre_tax,
                    trades=trades,
                    years=int(max(1, np.ceil(years_eff)))
                )
                wlth_free.append(pre_tax)
                wlth_taxable.append(post_tax)
            except Exception:
                continue

    if not wlth_free or not wlth_taxable:
        return {'status': 'skipped', 'reason': 'simulation returned no valid paths'}

    med_free = float(np.median(np.asarray(wlth_free, dtype=float)))
    med_taxable = float(np.median(np.asarray(wlth_taxable, dtype=float)))
    cagr_free = _cagr(med_free, years_eff)
    cagr_taxable = _cagr(med_taxable, years_eff)
    tax_drag = cagr_free - cagr_taxable

    # Strictly lower when there are gains; otherwise allow equality.
    if med_free > INITIAL_CAPITAL:
        passed = bool(cagr_taxable < cagr_free - 1e-9)
    else:
        passed = bool(cagr_taxable <= cagr_free + 1e-9)

    print(f"  Tax-free SPY  median CAGR: {cagr_free*100:.2f}%")
    print(f"  Taxable  SPY  median CAGR: {cagr_taxable*100:.2f}%")
    print(f"  Tax drag: {tax_drag*100:.2f}% per year")
    if cagr_taxable > cagr_free + 1e-4:
        print(f"  Diagnostic: taxable exceeds tax-free by {(cagr_taxable - cagr_free)*100:.2f}%/yr "
              f"(mode={mode}, med_taxable=${med_taxable:,.0f}, med_taxfree=${med_free:,.0f})")
    print(f"  {'✓ PASS' if passed else '⚠ FAIL — taxable CAGR not lower than tax-free'}")

    # Double-taxation guard: total-return driver must not inject synthetic dividends.
    # In historical_backtest mode, div_yield=0 and no synthetic dividend overlay
    # is applied to SPY_Ret (dividends are already embedded in FF total returns).
    sc = get_scenario()
    div_yield_active = float(sc.get('div_yield', 0.0))
    no_div_double = (div_yield_active == 0.0) if MARKET_SCENARIO == 'historical_backtest' else True
    print(f"  No-double-dividend guard: div_yield={div_yield_active:.4f}  "
          f"{'✓ PASS' if no_div_double else '⚠ FAIL — div_yield != 0 in total-return mode'}")

    return {
        'status': 'pass' if (passed and no_div_double) else 'fail',
        'mode': mode,
        'taxable_spy_sid': taxable_spy_sid,
        'cagr_free': cagr_free,
        'cagr_taxable': cagr_taxable,
        'tax_drag': tax_drag,
        'median_free_wealth': med_free,
        'median_taxable_wealth': med_taxable,
        'years_effective': float(years_eff),
        'tax_drag_positive': passed,
        'no_div_double': no_div_double,
    }

def validate_spy_driver_fidelity(
        window_data: Dict[str, np.ndarray],
        cpi_daily:   Optional['pd.Series'] = None,
        tol_bps:     float = 1.0,
        tol_cumulative_abs: float = 1e-4,
) -> Dict[str, Any]:
    """
    SPY sanity check for historical reconstruction mode.

    A) SPY nominal CAGR from the engine (product of 1+r) must match the driver
       series within `tol_bps` basis points.
    B) SPY real CAGR is computed using the actual FRED CPI series if available,
       otherwise falls back to constant 3% inflation.

    Returns a dict with 'pass', error metrics, and CAGR values.
    """
    spy_ret = np.asarray(window_data['SPY_Ret'], dtype=float)
    n       = len(spy_ret)
    if n < 2:
        return {'pass': False, 'details': 'fewer than 2 observations'}

    # Nominal CAGR from product of returns (ground truth)
    compound  = float(np.prod(1.0 + spy_ret))
    years     = n / 252.0
    cagr_nom  = compound ** (1.0 / years) - 1.0

    # Real CAGR via CPI
    w_start   = window_data.get('dates_start', None)
    w_end     = window_data.get('dates_end',   None)
    if cpi_daily is not None and w_start is not None and w_end is not None:
        try:
            cpi_s = float(cpi_daily.asof(pd.Timestamp(w_start)))
            cpi_e = float(cpi_daily.asof(pd.Timestamp(w_end)))
            infl_ann = (cpi_e / cpi_s) ** (1.0 / years) - 1.0
        except Exception:
            infl_ann = 0.03
    else:
        infl_ann = 0.03
    cagr_real = (1.0 + cagr_nom) / (1.0 + infl_ann) - 1.0

    # Engine check: simulate path 0 through the window (bypass all overlays)
    # using _get_historical_path_returns in backtest mode.
    path = _get_historical_path_returns(
        path_idx=0, n_paths=1, n_days=n,
        mode='backtest', block_size=63,
        rng=np.random.default_rng(42),
        hist_data=window_data
    )
    engine_compound = float(np.prod(1.0 + path['SPY_Ret']))
    cumulative_abs_error = float(abs(engine_compound - compound))
    error_bps = cumulative_abs_error / max(abs(compound), 1e-9) * 10_000.0
    passed_abs = cumulative_abs_error < float(tol_cumulative_abs)
    passed_bps = error_bps < tol_bps
    passed = bool(passed_abs and passed_bps)

    print(f"\n  === SPY DRIVER FIDELITY CHECK ===")
    print(f"  Window : {w_start} → {w_end}  ({n:,} days, {years:.2f} yr)")
    print(f"  Nominal CAGR : {cagr_nom*100:.2f}%")
    print(f"  Inflation     : {infl_ann*100:.2f}%  "
          f"({'FRED CPI' if cpi_daily is not None else 'constant fallback'})")
    print(f"  Real CAGR    : {cagr_real*100:.2f}%")
    print(f"  Cumulative error (abs): {cumulative_abs_error:.8f}  "
          f"({'✓ PASS' if passed_abs else f'⚠ FAIL (> {tol_cumulative_abs:.8f})'})")
    print(f"  Engine error : {error_bps:.3f} bps  "
          f"({'✓ PASS' if passed_bps else f'⚠ FAIL (>{tol_bps} bps)'})")

    return {
        'pass': passed,
        'cagr_nominal': cagr_nom,
        'inflation_ann': infl_ann,
        'cagr_real': cagr_real,
        'compound': compound,
        'engine_compound': engine_compound,
        'cumulative_abs_error': cumulative_abs_error,
        'tol_cumulative_abs': float(tol_cumulative_abs),
        'cumulative_abs_pass': passed_abs,
        'error_bps': error_bps,
        'tol_bps': float(tol_bps),
        'bps_pass': passed_bps,
        'n_days': n,
        'years': years,
    }


def validate_driver_total_return_basis(df: pd.DataFrame,
                                        mode=None) -> Dict[str, Any]:
    """
    Task B — Deterministic return-basis proof for SPY (and NDX) drivers.

    Verifies that driver return columns are on a TOTAL-RETURN basis (dividends
    included, auto_adjust=True) rather than price-return-only.  Runs without
    internet access; uses the canonical dataset if present, else the live df.

    Parameters
    ----------
    mode : ValidationMode, optional
        When set to ValidationMode.INSTITUTIONAL_GATE, raises AssertionError if
        the price-return sentinel (C2) fires — hard-blocking simulation.

    Three checks (all deterministic, unit-testable):

    C1 — Internal consistency (SPY_Real_Ret derived from SPY_Real_Price):
        max |SPY_Real_Price.pct_change() − SPY_Real_Ret| < 1e-8
        A failure here means the return column was not computed from the stored
        price column — a data-integrity bug (e.g. mis-assigned column).

    C2 — Price-return sentinel flag:
        If the fetch stage set _spy_is_price_return_fallback=True (^GSPC used),
        hard-fail immediately with a clear message.  Auto_adjust does not apply
        to ^GSPC (it has no dividends column), so the basis is definitively wrong.

    C3 — Heuristic: no systematic quarterly ex-dividend drops:
        On the last business day of March, June, September, and December (typical
        SPY ex-dividend months), check whether SPY_Real_Ret shows a systematic
        negative bias vs its annual rolling mean.  Price-only series would show
        ~−0.3% to −0.6% drops on each quarterly ex-date.  We flag if the median
        ex-div-month return is more than 20 bps below the annual median on more
        than 60% of sampled calendar years.
        This is a heuristic (no reference download needed), so it is warn-only.

    Returns
    -------
    dict with keys:
        'pass' : bool  — False only when C1 or C2 fails (C3 is warn-only)
        'c1_consistency' : dict  — max_diff, threshold, pass
        'c2_price_return_sentinel' : dict  — flag, pass
        'c3_ex_div_heuristic' : dict  — n_years, frac_negative, warn
        'message' : str  — human-readable summary
    """
    result: Dict[str, Any] = {
        'pass': True,
        'c1_consistency': {},
        'c2_price_return_sentinel': {},
        'c3_ex_div_heuristic': {},
        'message': '',
    }

    print(f"\n  {'─'*60}")
    print("  DRIVER RETURN-BASIS PROOF  (validate_driver_total_return_basis)")
    print(f"  {'─'*60}")

    # ── C1: Internal consistency — SPY_Real_Ret must equal SPY_Real_Price.pct_change() ──
    c1_pass = True
    c1_max_diff = float('nan')
    c1_thr = 1e-8  # floating-point noise only; any real difference → data bug

    spy_price_col = 'SPY_Real_Price'
    spy_ret_col   = 'SPY_Real_Ret'

    if spy_price_col in df.columns and spy_ret_col in df.columns:
        spy_px  = pd.to_numeric(df[spy_price_col], errors='coerce').dropna()
        spy_ret = pd.to_numeric(df[spy_ret_col],   errors='coerce')

        if len(spy_px) >= 2:
            derived = spy_px.pct_change().dropna()
            shared  = derived.index.intersection(spy_ret.dropna().index)
            if len(shared) >= 10:
                diff_arr = (derived.reindex(shared) - spy_ret.reindex(shared)).abs()
                c1_max_diff = float(diff_arr.max())
                c1_pass = bool(c1_max_diff < c1_thr)
                if c1_pass:
                    print(f"  C1 ✓ SPY_Real_Ret consistent with SPY_Real_Price.pct_change()"
                          f"  (max_diff={c1_max_diff:.2e} < {c1_thr:.0e})")
                else:
                    print(f"  C1 ✗ FAIL — SPY_Real_Ret NOT derived from SPY_Real_Price "
                          f"(max_diff={c1_max_diff:.2e} ≥ {c1_thr:.0e})  "
                          "possible column mis-assignment or post-processing overwrite")
                    result['pass'] = False
            else:
                print(f"  C1 ⚠ SKIP — insufficient shared dates ({len(shared)} < 10)")
        else:
            print(f"  C1 ⚠ SKIP — SPY_Real_Price has fewer than 2 non-NaN values")
    else:
        missing = [c for c in [spy_price_col, spy_ret_col] if c not in df.columns]
        print(f"  C1 ⚠ SKIP — columns missing: {missing}")

    result['c1_consistency'] = {
        'max_diff': c1_max_diff,
        'threshold': c1_thr,
        'pass': c1_pass,
    }

    # ── C2: Price-return sentinel ─────────────────────────────────────────────────────
    c2_flag = bool(df.attrs.get('_spy_is_price_return_fallback', False))
    # Also check the column-level sentinel inserted during ingestion
    if '_spy_is_price_return_fallback' in df.columns:
        c2_flag = bool(df['_spy_is_price_return_fallback'].any())

    c2_pass = not c2_flag
    if c2_flag:
        print(f"  C2 ✗ FAIL — _spy_is_price_return_fallback sentinel is set: "
              "^GSPC (price-return) used as SPY driver instead of SPY ETF (total-return).  "
              "Dividend yield (~1.5-2%/yr) is excluded from driver returns.  "
              "This will cause driver_alpha_integrity gate to fire on leveraged assets.")
        result['pass'] = False
        # PART 4 — Hard fail in INSTITUTIONAL_GATE mode: simulation must not proceed
        # when the price-return sentinel is active. Dividend mismatch (~1.5-2%/yr)
        # corrupts driver_alpha and all leveraged reconstruction results.
        if mode is not None and mode == ValidationMode.INSTITUTIONAL_GATE:
            raise AssertionError(
                "INSTITUTIONAL_GATE HARD FAIL: _spy_is_price_return_fallback sentinel detected. "
                "^GSPC (price-return index) was used as the SPY driver instead of SPY ETF "
                "(total-return, auto_adjust=True). Dividend yield (~1.5-2%/yr) is absent. "
                "Simulation cannot proceed — this would corrupt all leveraged reconstructions."
            )
    else:
        print(f"  C2 ✓ SPY driver is total-return (SPY ETF, auto_adjust=True; no ^GSPC fallback)")
    result['c2_price_return_sentinel'] = {'flag': c2_flag, 'pass': c2_pass}

    # ── C3: Heuristic ex-dividend drop detector (warn-only) ──────────────────────────
    c3_warn = False
    c3_frac = float('nan')
    c3_n_years = 0

    if spy_ret_col in df.columns and len(df) >= 252:
        spy_ret_full = pd.to_numeric(df[spy_ret_col], errors='coerce').dropna()
        if len(spy_ret_full) >= 252:
            # Months where SPY typically pays dividends: March, June, September, December.
            # On a price-return series the ex-dividend day shows ~−0.3 to −0.6%.
            # Collect the minimum return in each of those months per year.
            ex_div_months = [3, 6, 9, 12]
            annual_medians: List[float] = []
            ex_div_mins: List[float] = []

            for yr in spy_ret_full.index.year.unique():
                yr_rets = spy_ret_full[spy_ret_full.index.year == yr]
                if len(yr_rets) < 50:
                    continue
                annual_med = float(yr_rets.median())
                annual_medians.append(annual_med)

                for mo in ex_div_months:
                    mo_rets = yr_rets[yr_rets.index.month == mo]
                    if len(mo_rets) > 0:
                        ex_div_mins.append(float(mo_rets.min()))

            if len(annual_medians) >= 3 and len(ex_div_mins) >= 6:
                overall_median = float(np.median(annual_medians))
                # Fraction of ex-div month mins that are more than 20 bps below the
                # annual median — on total-return data this should be rare (<25%)
                # because adjustments eliminate the ex-dividend drop.
                # On price-return data this would be ~60-80% of quarters.
                threshold_bps = -0.0020  # −20 bps per day
                frac_negative = float(
                    np.mean([m < overall_median + threshold_bps for m in ex_div_mins])
                )
                c3_n_years = len(annual_medians)
                c3_frac = frac_negative
                if frac_negative > 0.60:
                    c3_warn = True
                    print(f"  C3 ⚠ WARN — possible price-return basis: "
                          f"{frac_negative*100:.0f}% of quarterly ex-div-month minimum returns "
                          f"are >20 bps below annual median "
                          f"({c3_n_years} years sampled).  "
                          "This pattern is typical of price-only (unadjusted-close) series.  "
                          "Confirm yf.download used auto_adjust=True.")
                else:
                    print(f"  C3 ✓ Quarterly ex-div heuristic OK "
                          f"({frac_negative*100:.0f}% below threshold, {c3_n_years} yr; "
                          "consistent with total-return basis)")
            else:
                print(f"  C3 ⚠ SKIP — insufficient history for heuristic "
                      f"({len(annual_medians)} yr, {len(ex_div_mins)} ex-div samples)")
        else:
            print(f"  C3 ⚠ SKIP — fewer than 252 valid SPY_Real_Ret observations")

    result['c3_ex_div_heuristic'] = {
        'n_years': c3_n_years,
        'frac_negative': c3_frac,
        'warn': c3_warn,
    }

    # PART 2 — Driver-return reproducibility hash.
    # Compute SHA-256 of the raw driver return values used for reconstruction.
    # This hash is printed and stored so future runs can verify byte-for-byte
    # driver series identity, catching any upstream data mutation.
    import hashlib as _dr_hl
    _driver_return_hash: Optional[str] = None
    _hash_col = None
    for _cand in ('SPY_Ret_RealOnly', 'SPY_Ret', 'SPY_Real_Ret'):
        if _cand in df.columns:
            _hash_col = _cand
            break
    _hash_n: Optional[int] = None
    _hash_date_start: Optional[str] = None
    _hash_date_end: Optional[str] = None
    if _hash_col is not None:
        # Force C-contiguous float64 before tobytes() so the hash is stable across
        # runs regardless of the underlying array's memory layout or NaN ordering.
        # Using to_numpy(dtype=np.float64) avoids the implicit copy ambiguity of .values.
        _driver_vals = np.ascontiguousarray(
            pd.to_numeric(df[_hash_col], errors='coerce').fillna(0.0).to_numpy(dtype=np.float64)
        )
        _driver_return_hash = _dr_hl.sha256(_driver_vals.tobytes()).hexdigest()
        _hash_n = len(_driver_vals)
        _hash_date_start = str(pd.Timestamp(df.index[0]).date()) if len(df) > 0 else None
        _hash_date_end   = str(pd.Timestamp(df.index[-1]).date()) if len(df) > 0 else None
        print(f"  [driver_return_hash] col={_hash_col}  n={_hash_n:,}  "
              f"dates={_hash_date_start}→{_hash_date_end}  "
              f"sha256={_driver_return_hash[:32]}...")
    else:
        print(f"  [driver_return_hash] ⚠ no driver return column found — hash not computed")
    result['driver_return_hash'] = _driver_return_hash
    result['driver_return_hash_col'] = _hash_col
    result['driver_return_hash_n'] = _hash_n
    result['driver_return_hash_date_start'] = _hash_date_start
    result['driver_return_hash_date_end'] = _hash_date_end

    status = '✓ PASS' if result['pass'] else '✗ FAIL'
    c3_note = '  C3=WARN (heuristic only)' if c3_warn else ''
    result['message'] = (
        f"Driver total-return basis: {status}{c3_note}. "
        f"C1={'PASS' if c1_pass else 'FAIL'} "
        f"C2={'PASS' if c2_pass else 'FAIL'} "
        f"C3={'WARN' if c3_warn else 'OK'}"
    )
    print(f"  {result['message']}")
    print(f"  {'─'*60}")
    return result


def _assert_real_data_priority(
        df: pd.DataFrame,
        funds: Optional[List[str]] = None,
) -> None:
    """
    Production purity guard: raises AssertionError if any fund has its
    ``{fund}_IsSynthetic`` flag set True on a day where real return data exists
    (``{fund}_Real_Ret`` is finite).

    This is the **shared** enforcement function called by:
      - run_historical_reconstruction_validation() — gate A0b (binding hard-fail)
      - T15 regression test — must call this function, not an inline copy, so
        that the test remains a true regression guard against production regressions.

    Raises
    ------
    AssertionError
        When any overlap is detected.  Message includes the total count.
    """
    if funds is None:
        funds = ['UPRO', 'SSO', 'TQQQ', 'QLD']
    total_overlap = 0
    for _fund in funds:
        _real_col = f'{_fund}_Real_Ret'
        _syn_col  = f'{_fund}_IsSynthetic'
        if _real_col not in df.columns:
            continue
        _is_real = np.isfinite(pd.to_numeric(df[_real_col], errors='coerce').to_numpy())
        _is_syn  = (df[_syn_col].fillna(False).to_numpy(dtype=bool)
                    if _syn_col in df.columns
                    else np.zeros(len(df), dtype=bool))
        total_overlap += int((_is_real & _is_syn).sum())
    if total_overlap > 0:
        raise AssertionError(
            f"HISTORICAL BACKTEST PURITY VIOLATION: {total_overlap} day(s) have "
            "synthetic flag set where real LETF data also exists.  "
            "This violates real-data-priority in historical_backtest mode."
        )


# ═══════════════════════════════════════════════════════════════════════════════
# SCENARIO-AWARE FORWARD REALISM VALIDATION LAYER
# Helpers and core API.  scipy soft-imported; no hard dependency.
# ═══════════════════════════════════════════════════════════════════════════════

# ── Acceptance-band constants (tune here; values propagate everywhere) ─────────
# Volatility-clustering block
_FRL_ACF_MEAN_DIFF_WARN      = 0.05   # mean |ACF_real - ACF_synth| over lags 1..20 → WARN
_FRL_RVOL_P99_REL_ERR_WARN   = 0.15   # realized-vol p99 relative error              → WARN
# Drawdown block
_FRL_DD_P2R_P90_REL_ERR_WARN = 0.30   # peak→recovery p90 relative error             → WARN
# Tail-frequency block (daily exceedance band → FAIL in STRICT mode)
_FRL_DAILY_EXCEED_LO         = 0.008  # daily 1%-tail exceedance frequency lower bound
_FRL_DAILY_EXCEED_HI         = 0.012  # daily 1%-tail exceedance frequency upper bound
_FRL_5D_Q01_MAG_BAND         = 0.10   # 5-day left-1% quantile magnitude ±10%        → WARN
_FRL_TAIL_COND_PROB_BAND     = 0.25   # tail conditional probability ±25% relative    → WARN
# Absurdity thresholds (always enforced, even in WARN_ONLY)
_FRL_ABSURDITY_MIN_VOL       = 0.02   # ann_vol < 2%                    → ValueError
_FRL_ABSURDITY_MAX_VOL       = 1.00   # ann_vol > 100%                  → ValueError
_FRL_ABSURDITY_MAX_DRIFT     = 0.005  # |mean_daily| > 0.5% (≈125%/yr) → ValueError
_FRL_ABSURDITY_JUMP_FRAC     = 0.005  # fraction of |r|>20% days > this → ValueError
_FRL_ABSURDITY_NO_DD_DAYS    = 7560   # 30 yr × 252: no DD>5% this long → ValueError


def _acf_manual(arr: np.ndarray, lag: int) -> float:
    """Lag-h autocorrelation of a 1-D array (no scipy dependency)."""
    n = len(arr)
    if n < lag + 2:
        return float('nan')
    mu  = float(np.nanmean(arr))
    var = float(np.nanmean((arr - mu) ** 2))
    if var < 1e-15:
        return float('nan')
    return float(np.nanmean((arr[:n - lag] - mu) * (arr[lag:] - mu)) / var)


def _acf_vector(arr: np.ndarray, max_lag: int = 20) -> np.ndarray:
    """
    Return array of sample autocorrelations for lags 1..max_lag (length max_lag).
    Uses the biased variance estimator (mean-subtracted; denominator = n).
    """
    n   = len(arr)
    mu  = float(np.nanmean(arr))
    var = float(np.nanmean((arr - mu) ** 2))
    out = np.full(max_lag, float('nan'))
    if var < 1e-15 or n < max_lag + 2:
        for k in range(1, min(max_lag + 1, n - 1)):
            out[k - 1] = float(np.nanmean((arr[:n-k] - mu) * (arr[k:] - mu)) / var)
        return out
    for k in range(1, max_lag + 1):
        out[k - 1] = float(np.nanmean((arr[:n-k] - mu) * (arr[k:] - mu)) / var)
    return out


def _ljung_box_pvalue(arr: np.ndarray, n_lags: int) -> float:
    """
    Ljung-Box Q-statistic for the first n_lags autocorrelations.

    Returns chi-squared(df=n_lags) p-value.  Falls back to a
    normal approximation when scipy is absent.
    """
    n = len(arr)
    if n < n_lags + 5:
        return float('nan')
    acf = _acf_vector(arr, max_lag=n_lags)
    q   = 0.0
    for k in range(1, n_lags + 1):
        rk = acf[k - 1]
        if not np.isfinite(rk):
            return float('nan')
        q += (rk ** 2) / max(n - k, 1)
    q *= n * (n + 2)
    try:
        from scipy.stats import chi2 as _chi2
        return float(1.0 - _chi2.cdf(q, df=n_lags))
    except ImportError:
        import math
        z = (q - n_lags) / max(math.sqrt(2.0 * n_lags), 1e-9)
        return float(0.5 * math.erfc(z / math.sqrt(2.0)))


def _realized_vol_stats(arr: np.ndarray, window: int = 21) -> Dict[str, float]:
    """
    Non-overlapping rolling realized vol statistics (annualised).

    Returns dict: mean, median, p90, p99.
    """
    if len(arr) < window * 2:
        return {k: float('nan') for k in ('mean', 'median', 'p90', 'p99')}
    vols = np.array([
        np.std(arr[i:i + window], ddof=1) * np.sqrt(252)
        for i in range(0, len(arr) - window, window)
    ])
    vols = vols[np.isfinite(vols)]
    if len(vols) == 0:
        return {k: float('nan') for k in ('mean', 'median', 'p90', 'p99')}
    return {
        'mean'  : float(np.mean(vols)),
        'median': float(np.median(vols)),
        'p90'   : float(np.percentile(vols, 90)),
        'p99'   : float(np.percentile(vols, 99)),
    }


def _high_vol_run_lengths(arr: np.ndarray, vol_threshold: float) -> List[int]:
    """
    High-vol state run lengths (consecutive days with trailing-21d vol > vol_threshold).

    vol_threshold should be the REAL data's p90 non-overlapping 21-day annualised vol.
    """
    window = 21
    if len(arr) < window + 1:
        return []
    high = np.zeros(len(arr), dtype=bool)
    for i in range(window - 1, len(arr)):
        rv = float(np.std(arr[i - window + 1:i + 1], ddof=1) * np.sqrt(252))
        high[i] = (rv > vol_threshold)
    runs: List[int] = []
    cur = 0
    for v in high:
        if v:
            cur += 1
        else:
            if cur > 0:
                runs.append(cur)
            cur = 0
    if cur > 0:
        runs.append(cur)
    return runs


def _drawdown_episodes(
        daily_ret: np.ndarray,
        min_dd: float = 0.05,
) -> Dict[str, Any]:
    """
    Identify drawdown episodes and compute comprehensive duration/depth statistics.

    Returns dict:
      p2t_days    : list of peak→trough durations (trading days)
      t2r_days    : list of trough→recovery durations
      p2r_days    : list of peak→recovery (total) durations
      max_depths  : list of per-episode max drawdown depth (fraction)
      time_in_dd  : fraction of total days spent in drawdown ≥ min_dd
      n_episodes  : number of fully completed episodes
      n_open      : number of episodes still open at end of series
    """
    arr = np.asarray(daily_ret, dtype=np.float64)
    arr = arr[np.isfinite(arr)]
    n   = len(arr)
    if n < 10:
        return {
            'p2t_days': [], 't2r_days': [], 'p2r_days': [],
            'max_depths': [], 'time_in_dd': float('nan'),
            'n_episodes': 0, 'n_open': 0,
        }
    wealth      = np.cumprod(1.0 + arr)
    running_max = np.maximum.accumulate(wealth)
    dd          = 1.0 - wealth / running_max
    p2t: List[int]   = []
    t2r: List[int]   = []
    p2r: List[int]   = []
    depths: List[float] = []
    dd_days = int(np.sum(dd >= min_dd))
    in_dd     = False
    peak_i    = 0
    trough_i  = 0
    trough_dd = 0.0
    n_open    = 0
    for i, d in enumerate(dd):
        if not in_dd:
            if d >= min_dd:
                in_dd     = True
                peak_i    = i
                trough_i  = i
                trough_dd = d
        else:
            if d > trough_dd:
                trough_i  = i
                trough_dd = d
            if d < 0.001:   # recovered to new ATH
                p2t.append(trough_i - peak_i)
                t2r.append(i        - trough_i)
                p2r.append(i        - peak_i)
                depths.append(trough_dd)
                in_dd = False
    n_open = 1 if in_dd else 0
    return {
        'p2t_days'  : p2t,
        't2r_days'  : t2r,
        'p2r_days'  : p2r,
        'max_depths': depths,
        'time_in_dd': float(dd_days / n),
        'n_episodes': len(p2t),
        'n_open'    : n_open,
    }


def _compounded_returns(arr: np.ndarray, h: int) -> np.ndarray:
    """Non-overlapping h-day compounded returns from a daily-return array."""
    return np.array([
        (1.0 + arr[i:i + h]).prod() - 1.0
        for i in range(0, len(arr) - h, h)
        if len(arr[i:i + h]) == h
    ])


def _tail_cond_prob(arr: np.ndarray, threshold: float) -> float:
    """
    Conditional probability P(tail_t | tail_{t-1}) where tail = arr < threshold.
    Returns nan when fewer than 2 consecutive tail events exist.
    """
    tail = (arr < threshold)
    n_prev = int(tail[:-1].sum())
    if n_prev == 0:
        return float('nan')
    return float(np.sum(tail[:-1] & tail[1:]) / n_prev)


def _frac_windows_with_k_tails(
        arr: np.ndarray, threshold: float, window: int = 5, k: int = 2,
) -> float:
    """Fraction of rolling `window`-day windows containing ≥ k tail days."""
    tail = (arr < threshold).astype(np.int32)
    n    = len(tail)
    if n < window:
        return float('nan')
    counts = np.array([tail[i:i + window].sum() for i in range(n - window + 1)])
    return float(np.mean(counts >= k))


def validate_forward_scenario_realism(
        real_r  : np.ndarray,
        synth_r : np.ndarray,
        horizons: Tuple[int, ...] = (1, 5, 21),
        lags    : int             = 20,
        real_r2 : Optional[np.ndarray] = None,
        synth_r2: Optional[np.ndarray] = None,
) -> Dict[str, Any]:
    """
    Compare one synthetic daily-return path (driver level: SPY or QQQ) to the
    historical record across three metric blocks.

    Does NOT enforce any blocking — the caller inspects the returned
    ``block_fails`` list and acts according to ScenarioRealismMode.

    Metric blocks
    -------------
    1. vol_clustering
         ACF(|r|) and ACF(r²) at lags 1..lags;
         Ljung-Box p-values on r² at lags 10 and 20;
         21-day realized vol: mean, median, p90, p99;
         High-vol state run lengths (threshold = real p90 realized vol).

    2. drawdown
         Full episode stats on the wealth index: peak→trough, trough→recovery,
         peak→recovery durations; max depth per episode; time-under-water fraction.

    3. tail_frequency
         For H in horizons (1, 5, 21):
           – compounded H-day returns, REAL q1% and q0.5% thresholds,
             synthetic exceedance frequencies.
         Tail clustering (daily):
           – conditional probability P(tail_t | tail_{t-1}),
           – fraction of 5-day windows with ≥2 tail days.

    Parameters
    ----------
    real_r  : 1-D array-like of historical daily returns (SPY or QQQ).
    synth_r : 1-D array-like of simulated daily returns (one path).
    horizons: Tuple of trading-day horizons for tail checks.  Default (1, 5, 21).
    lags    : Maximum ACF lag (computes lags 1..lags).  Default 20.

    Returns
    -------
    dict with keys:
      vol_clustering      : sub-dict of ACF arrays, LB p-values, realized-vol stats,
                            high-vol run lengths, and 'status' ('PASS'|'WARN').
      drawdown            : sub-dict with synth/real episode stats and 'status'.
      tail_frequency      : sub-dict of per-horizon tail exceedance stats and 'status'
                            ('PASS'|'WARN'|'FAIL').
      block_fails         : List[str] — names of blocks with FAIL status.
      block_warns         : List[str] — names of blocks with WARN status.
      threshold_exceeded  : bool — True if any block is WARN or FAIL.
      metric_warnings     : List[str] — human-readable warning messages.
    """
    real_r  = np.asarray(real_r,  dtype=np.float64)
    synth_r = np.asarray(synth_r, dtype=np.float64)
    real_r  = real_r[np.isfinite(real_r)]
    synth_r = synth_r[np.isfinite(synth_r)]

    block_fails:   List[str] = []
    block_warns:   List[str] = []
    warn_msgs:     List[str] = []

    # ══════════════════════════════════════════════════════════════════════════
    # Block 1: VOLATILITY CLUSTERING
    # ══════════════════════════════════════════════════════════════════════════
    vc: Dict[str, Any] = {}
    vc_warn = False

    # ACF of |r| and r² at lags 1..lags
    acf_abs_r = _acf_vector(np.abs(real_r),  max_lag=lags)
    acf_abs_s = _acf_vector(np.abs(synth_r), max_lag=lags)
    acf_sq_r  = _acf_vector(real_r  ** 2,    max_lag=lags)
    acf_sq_s  = _acf_vector(synth_r ** 2,    max_lag=lags)

    vc['acf_abs_real']  = acf_abs_r.tolist()
    vc['acf_abs_synth'] = acf_abs_s.tolist()
    vc['acf_sq_real']   = acf_sq_r.tolist()
    vc['acf_sq_synth']  = acf_sq_s.tolist()

    # Mean |ACF_real - ACF_synth| across all lags
    valid_mask  = np.isfinite(acf_abs_r) & np.isfinite(acf_abs_s)
    mean_abs_diff = float(np.mean(np.abs(acf_abs_r - acf_abs_s)[valid_mask])) \
        if valid_mask.any() else float('nan')
    valid_sq_mask = np.isfinite(acf_sq_r) & np.isfinite(acf_sq_s)
    mean_sq_diff  = float(np.mean(np.abs(acf_sq_r - acf_sq_s)[valid_sq_mask])) \
        if valid_sq_mask.any() else float('nan')
    vc['mean_acf_abs_diff'] = mean_abs_diff
    vc['mean_acf_sq_diff']  = mean_sq_diff
    # STEP 5 — per-lag diffs at economically meaningful lags [1, 5, 10, 20]
    for _lg in (1, 5, 10, 20):
        _idx = _lg - 1   # _acf_vector is 0-indexed: index k-1 = lag k
        if _idx < len(acf_abs_r) and _idx < len(acf_abs_s):
            _d = float(acf_abs_r[_idx]) - float(acf_abs_s[_idx])
            _q = float(acf_sq_r[_idx])  - float(acf_sq_s[_idx])
            vc[f'acf_lag{_lg}_abs_diff'] = abs(_d) if np.isfinite(_d) else float('nan')
            vc[f'acf_sq_lag{_lg}_diff']  = abs(_q) if np.isfinite(_q) else float('nan')
    if np.isfinite(mean_abs_diff) and mean_abs_diff > _FRL_ACF_MEAN_DIFF_WARN:
        vc_warn = True
        warn_msgs.append(
            f"vol_clustering: mean|ACF(|r|) diff|={mean_abs_diff:.3f} "
            f"> {_FRL_ACF_MEAN_DIFF_WARN} (lags 1..{lags})")
    if np.isfinite(mean_sq_diff) and mean_sq_diff > _FRL_ACF_MEAN_DIFF_WARN:
        vc_warn = True
        warn_msgs.append(
            f"vol_clustering: mean|ACF(r²) diff|={mean_sq_diff:.3f} "
            f"> {_FRL_ACF_MEAN_DIFF_WARN} (lags 1..{lags})")

    # Ljung-Box at lags 10 and 20 on r²
    for _lb_k in (10, 20):
        lb_r = _ljung_box_pvalue(real_r  ** 2, _lb_k)
        lb_s = _ljung_box_pvalue(synth_r ** 2, _lb_k)
        vc[f'lb_pvalue_real_lag{_lb_k}']  = lb_r
        vc[f'lb_pvalue_synth_lag{_lb_k}'] = lb_s

    # 21-day realized vol: mean, median, p90, p99
    rvol_r = _realized_vol_stats(real_r)
    rvol_s = _realized_vol_stats(synth_r)
    vc['rvol_real']  = rvol_r
    vc['rvol_synth'] = rvol_s
    if (np.isfinite(rvol_r.get('p99', float('nan'))) and
            np.isfinite(rvol_s.get('p99', float('nan'))) and
            rvol_r['p99'] > 0):
        rel_err_p99 = abs(rvol_s['p99'] - rvol_r['p99']) / rvol_r['p99']
        vc['rvol_p99_rel_err'] = rel_err_p99
        if rel_err_p99 > _FRL_RVOL_P99_REL_ERR_WARN:
            vc_warn = True
            warn_msgs.append(
                f"vol_clustering: rvol p99 rel_err={rel_err_p99:.2f} "
                f"> {_FRL_RVOL_P99_REL_ERR_WARN}  "
                f"(synth={rvol_s['p99']*100:.1f}% real={rvol_r['p99']*100:.1f}%)")

    # STEP 4 — Annual volatility realism
    _ann_vol_r = float(np.std(real_r,  ddof=1) * np.sqrt(252)) if len(real_r)  > 1 else float('nan')
    _ann_vol_s = float(np.std(synth_r, ddof=1) * np.sqrt(252)) if len(synth_r) > 1 else float('nan')
    vc['ann_vol_real']  = _ann_vol_r
    vc['ann_vol_synth'] = _ann_vol_s
    if np.isfinite(_ann_vol_r) and np.isfinite(_ann_vol_s) and _ann_vol_r > 0:
        _ann_vol_rel = abs(_ann_vol_s - _ann_vol_r) / max(_ann_vol_r, _ann_vol_s, 1e-8)
        vc['ann_vol_rel_err'] = _ann_vol_rel
        if _ann_vol_rel > 0.15:
            vc_warn = True
            warn_msgs.append(
                f"vol_clustering: ann_vol rel_err={_ann_vol_rel:.2f} > 0.15  "
                f"(synth={_ann_vol_s*100:.1f}%/yr real={_ann_vol_r*100:.1f}%/yr)")

    # High-vol state run lengths (threshold = real p90 non-overlapping realized vol)
    _real_p90_vol = rvol_r.get('p90', float('nan'))
    if np.isfinite(_real_p90_vol) and _real_p90_vol > 0:
        runs_r = _high_vol_run_lengths(real_r,  _real_p90_vol)
        runs_s = _high_vol_run_lengths(synth_r, _real_p90_vol)
        vc['high_vol_run_real_median'] = float(np.median(runs_r)) if runs_r else float('nan')
        vc['high_vol_run_real_p90']    = float(np.percentile(runs_r, 90)) if runs_r else float('nan')
        vc['high_vol_run_synth_median']= float(np.median(runs_s)) if runs_s else float('nan')
        vc['high_vol_run_synth_p90']   = float(np.percentile(runs_s, 90)) if runs_s else float('nan')
        vc['high_vol_threshold_used']  = _real_p90_vol

        # PART 2 — Volatility regime persistence realism
        _run_med_r = vc['high_vol_run_real_median']
        _run_med_s = vc['high_vol_run_synth_median']
        _run_p90_r = vc['high_vol_run_real_p90']
        _run_p90_s = vc['high_vol_run_synth_p90']
        if np.isfinite(_run_med_r) and np.isfinite(_run_med_s) and _run_med_r > 0:
            _vp_med_rel = abs(_run_med_s - _run_med_r) / _run_med_r
            vc['vol_run_median_rel_err'] = _vp_med_rel
            if _vp_med_rel > 0.25:
                vc_warn = True
                warn_msgs.append(
                    f"vol_clustering: high-vol run median rel_err={_vp_med_rel:.2f} "
                    f"> 0.25  (synth={_run_med_s:.1f}d real={_run_med_r:.1f}d)")
        if np.isfinite(_run_p90_r) and np.isfinite(_run_p90_s) and _run_p90_r > 0:
            _vp_p90_rel = abs(_run_p90_s - _run_p90_r) / _run_p90_r
            vc['vol_run_p90_rel_err'] = _vp_p90_rel
            if _vp_p90_rel > 0.25:
                vc_warn = True
                warn_msgs.append(
                    f"vol_clustering: high-vol run p90 rel_err={_vp_p90_rel:.2f} "
                    f"> 0.25  (synth={_run_p90_s:.1f}d real={_run_p90_r:.1f}d)")

        # PART 3 — Tail clustering conditional on high vol (21d trailing vol > real p90)
        if len(real_r) > 42:
            _tc_tail_thr = float(np.percentile(real_r, 1.0))
            _tc_hv_r = np.zeros(len(real_r), dtype=bool)
            for _i in range(20, len(real_r)):
                _tc_rv = float(np.std(real_r[_i - 20:_i + 1], ddof=1) * np.sqrt(252))
                _tc_hv_r[_i] = (_tc_rv > _real_p90_vol)
            _tc_hv_s = np.zeros(len(synth_r), dtype=bool)
            for _i in range(20, len(synth_r)):
                _tc_rv = float(np.std(synth_r[_i - 20:_i + 1], ddof=1) * np.sqrt(252))
                _tc_hv_s[_i] = (_tc_rv > _real_p90_vol)
            _tc_tail_r = (real_r < _tc_tail_thr)
            _tc_tail_s = (synth_r < _tc_tail_thr)
            _n_hv_r    = int(_tc_hv_r.sum())
            _n_hv_s    = int(_tc_hv_s.sum())
            _p_tail_hv_r = (float(np.sum(_tc_tail_r & _tc_hv_r)) / _n_hv_r
                            if _n_hv_r > 0 else float('nan'))
            _p_tail_hv_s = (float(np.sum(_tc_tail_s & _tc_hv_s)) / _n_hv_s
                            if _n_hv_s > 0 else float('nan'))
            vc['tail_cond_on_high_vol_real']  = _p_tail_hv_r
            vc['tail_cond_on_high_vol_synth'] = _p_tail_hv_s
            if (np.isfinite(_p_tail_hv_r) and np.isfinite(_p_tail_hv_s)
                    and _p_tail_hv_r > 0):
                _hv_cond_rel = abs(_p_tail_hv_s - _p_tail_hv_r) / _p_tail_hv_r
                vc['tail_cond_on_high_vol_rel_err'] = _hv_cond_rel
                if _hv_cond_rel > 0.25:
                    vc_warn = True
                    warn_msgs.append(
                        f"vol_clustering: P(tail|high_vol) rel_err={_hv_cond_rel:.2f} "
                        f"> 0.25  (synth={_p_tail_hv_s:.3f} real={_p_tail_hv_r:.3f})")
            # STEP 2 — High-vol state frequency realism
            _hv_frac_r = float(np.mean(_tc_hv_r))
            _hv_frac_s = float(np.mean(_tc_hv_s))
            vc['high_vol_frac_real']  = _hv_frac_r
            vc['high_vol_frac_synth'] = _hv_frac_s
            _hv_frac_denom = max(_hv_frac_r, _hv_frac_s, 1e-6)
            _hv_frac_rel = abs(_hv_frac_s - _hv_frac_r) / _hv_frac_denom
            vc['high_vol_frac_rel_err'] = _hv_frac_rel
            if _hv_frac_rel > 0.25:
                vc_warn = True
                warn_msgs.append(
                    f"vol_clustering: high-vol fraction rel_err={_hv_frac_rel:.2f} > 0.25  "
                    f"(synth={_hv_frac_s:.3f} real={_hv_frac_r:.3f})")

    vc['status'] = 'WARN' if vc_warn else 'PASS'
    if vc_warn:
        block_warns.append('vol_clustering')

    # ══════════════════════════════════════════════════════════════════════════
    # Block 2: DRAWDOWN DURATION
    # ══════════════════════════════════════════════════════════════════════════
    dd_ep_r = _drawdown_episodes(real_r)
    dd_ep_s = _drawdown_episodes(synth_r)
    dd_warn = False

    def _ep_summary(ep: Dict[str, Any]) -> Dict[str, Any]:
        """Aggregate list-valued episode fields to median/p90."""
        out: Dict[str, Any] = {}
        for key, data in ep.items():
            if isinstance(data, list) and data:
                arr_k = np.asarray(data, dtype=np.float64)
                out[f'{key}_median'] = float(np.median(arr_k))
                out[f'{key}_p90']    = float(np.percentile(arr_k, 90))
            elif not isinstance(data, list):
                out[key] = data
        return out

    dd_r_sum = _ep_summary(dd_ep_r)
    dd_s_sum = _ep_summary(dd_ep_s)
    dd_out: Dict[str, Any] = {'synth': dd_s_sum, 'real': dd_r_sum}

    # peak→recovery p90 relative error
    p2r_p90_real  = dd_r_sum.get('p2r_days_p90', float('nan'))
    p2r_p90_synth = dd_s_sum.get('p2r_days_p90', float('nan'))
    if np.isfinite(p2r_p90_real) and np.isfinite(p2r_p90_synth) and p2r_p90_real > 0:
        rel_err_p2r = abs(p2r_p90_synth - p2r_p90_real) / p2r_p90_real
        dd_out['p2r_p90_rel_err'] = rel_err_p2r
        if rel_err_p2r > _FRL_DD_P2R_P90_REL_ERR_WARN:
            dd_warn = True
            warn_msgs.append(
                f"drawdown: peak→recovery p90 rel_err={rel_err_p2r:.2f} "
                f"> {_FRL_DD_P2R_P90_REL_ERR_WARN}  "
                f"(synth={p2r_p90_synth:.0f}d real={p2r_p90_real:.0f}d)")

    dd_out['status'] = 'WARN' if dd_warn else 'PASS'
    if dd_warn:
        block_warns.append('drawdown')

    # ══════════════════════════════════════════════════════════════════════════
    # Block 3: TAIL EVENT FREQUENCY
    # ══════════════════════════════════════════════════════════════════════════
    tail_out: Dict[str, Any] = {}
    tail_warn = False
    tail_fail = False   # daily exceedance outside band → FAIL in STRICT

    # Per-horizon compounded return tails (H ∈ horizons; always includes 5d + 21d)
    _horizons_set = set(horizons) | {5, 21}   # LETF sequence-risk mandatory
    _tail_magnitude_out: Dict[str, Any] = {}  # STEP 1 — will be top-level in _frl_out
    for h in sorted(_horizons_set):
        if len(real_r) < h * 2 or len(synth_r) < h * 2:
            tail_out[f'h{h}_skipped'] = True
            continue
        real_h  = _compounded_returns(real_r,  h)
        synth_h = _compounded_returns(synth_r, h)
        if len(real_h) < 4 or len(synth_h) < 2:
            tail_out[f'h{h}_skipped'] = True
            continue
        # REAL thresholds
        real_q1   = float(np.percentile(real_h, 1.0))
        real_q05  = float(np.percentile(real_h, 0.5))
        real_q01  = float(np.percentile(real_h, 0.1))   # STEP 4
        tail_out[f'h{h}_real_q1pct']   = real_q1
        tail_out[f'h{h}_real_q05pct']  = real_q05
        tail_out[f'h{h}_real_q01pct']  = real_q01       # STEP 4
        # Synthetic exceedance frequencies
        synth_freq_q1   = float(np.mean(synth_h < real_q1))
        synth_freq_q05  = float(np.mean(synth_h < real_q05))
        synth_freq_q01  = float(np.mean(synth_h < real_q01))   # STEP 4
        tail_out[f'h{h}_synth_exceed_q1']  = synth_freq_q1
        tail_out[f'h{h}_synth_exceed_q05'] = synth_freq_q05
        tail_out[f'h{h}_synth_exceed_q01'] = synth_freq_q01    # STEP 4
        # STEP 4 — actual real exceedance rates (perfect match → synth==real → error=0)
        tail_out[f'h{h}_real_exceed_q1']  = float(np.mean(real_h < real_q1))
        tail_out[f'h{h}_real_exceed_q05'] = float(np.mean(real_h < real_q05))
        tail_out[f'h{h}_real_exceed_q01'] = float(np.mean(real_h < real_q01))
        # H=1 (daily): exceedance at real 1% must be in [lo, hi]
        if h == 1:
            outside_band = not (_FRL_DAILY_EXCEED_LO <= synth_freq_q1 <= _FRL_DAILY_EXCEED_HI)
            tail_out['daily_exceed_band_fail'] = outside_band
            if outside_band:
                tail_fail = True
                warn_msgs.append(
                    f"tail_frequency: daily 1% exceedance={synth_freq_q1*100:.3f}% "
                    f"outside [{_FRL_DAILY_EXCEED_LO*100:.1f}%, "
                    f"{_FRL_DAILY_EXCEED_HI*100:.1f}%] → FAIL in STRICT")
            # PART 1 — Tail magnitude realism: quantiles at 0.1%, 0.5%, 1%, 5%
            # STEP 2 — robust rel_err + sign sanity check
            _tail_mag: Dict[str, Any] = {}
            for _q_pct in (0.1, 0.5, 1.0, 5.0):
                _rq = float(np.percentile(real_h,  _q_pct))
                _sq = float(np.percentile(synth_h, _q_pct))
                _qkey = f'q{_q_pct:.1f}'
                _tail_mag[_qkey] = {'real': _rq, 'synth': _sq}
                if np.isfinite(_rq) and np.isfinite(_sq):
                    # Sign sanity: left-tail quantiles (< median) must be negative
                    if _rq < 0 and _sq >= 0:
                        _tail_mag[_qkey]['sign_violation'] = True
                        tail_warn = True
                        warn_msgs.append(
                            f"tail_magnitude: daily q{_q_pct:.1f}% sign violation "
                            f"(real={_rq*100:.2f}% synth={_sq*100:.2f}%)")
                    # STEP 2 — robust formula: abs diff / max(|real|, eps)
                    _mag_rel = abs(_sq - _rq) / max(abs(_rq), 1e-6)
                    _tail_mag[_qkey]['rel_err'] = _mag_rel
                    if _mag_rel > 0.15:
                        tail_warn = True
                        warn_msgs.append(
                            f"tail_magnitude: daily q{_q_pct:.1f}% "
                            f"rel_err={_mag_rel:.2f} > 0.15  "
                            f"(synth={_sq*100:.2f}% real={_rq*100:.2f}%)")
            # STEP 1 — store separately; added to _frl_out at top level below
            _tail_magnitude_out = _tail_mag
        # H=5: 1% quantile magnitude within ±10%
        if h == 5:
            if real_q1 != 0 and np.isfinite(real_q1) and np.isfinite(synth_freq_q1):
                synth_q1_h5 = float(np.percentile(synth_h, 1.0))
                rel_5d = abs(synth_q1_h5 - real_q1) / abs(real_q1)
                tail_out['h5_q1_rel_err'] = rel_5d
                if rel_5d > _FRL_5D_Q01_MAG_BAND:
                    tail_warn = True
                    warn_msgs.append(
                        f"tail_frequency: 5d q1% magnitude rel_err={rel_5d:.2f} "
                        f"> {_FRL_5D_Q01_MAG_BAND}  "
                        f"(synth={synth_q1_h5*100:.2f}% real={real_q1*100:.2f}%)")

    # STEP 5 — Skew and kurtosis realism (daily returns)
    if len(real_r) >= 4 and len(synth_r) >= 4:
        _mu_r  = float(np.mean(real_r));  _std_r = float(np.std(real_r,  ddof=1))
        _mu_s  = float(np.mean(synth_r)); _std_s = float(np.std(synth_r, ddof=1))
        if _std_r > 1e-10 and _std_s > 1e-10:
            _skew_r = float(np.mean(((real_r  - _mu_r) / _std_r) ** 3))
            _skew_s = float(np.mean(((synth_r - _mu_s) / _std_s) ** 3))
            _kurt_r = float(np.mean(((real_r  - _mu_r) / _std_r) ** 4))
            _kurt_s = float(np.mean(((synth_r - _mu_s) / _std_s) ** 4))
            _skew_diff = abs(_skew_s - _skew_r)
            _kurt_diff = abs(_kurt_s - _kurt_r)
            _tail_magnitude_out['skew_real']       = _skew_r
            _tail_magnitude_out['skew_synth']      = _skew_s
            _tail_magnitude_out['skew_diff']       = _skew_diff
            _tail_magnitude_out['kurtosis_real']   = _kurt_r
            _tail_magnitude_out['kurtosis_synth']  = _kurt_s
            _tail_magnitude_out['kurtosis_diff']   = _kurt_diff
            if _skew_diff > 0.5:
                tail_warn = True
                warn_msgs.append(
                    f"tail_magnitude: skew diff={_skew_diff:.2f} > 0.5  "
                    f"(synth={_skew_s:.2f} real={_skew_r:.2f})")
            if _kurt_diff > 2.0:
                tail_warn = True
                warn_msgs.append(
                    f"tail_magnitude: kurtosis diff={_kurt_diff:.2f} > 2.0  "
                    f"(synth={_kurt_s:.2f} real={_kurt_r:.2f})")

    # STEP 4 — Multi-threshold tail-frequency error across levels × horizons
    # Uses actual observed real exceedance rates as reference so that perfect
    # match (synth == real) always yields error = 0, regardless of sample size.
    _tf_err_parts: List[float] = []
    _tf_eps = 1e-6
    for _tqskey, _tqrkey, _nom_rate in [
        ('h1_synth_exceed_q1',   'h1_real_exceed_q1',   0.01),
        ('h1_synth_exceed_q05',  'h1_real_exceed_q05',  0.005),
        ('h1_synth_exceed_q01',  'h1_real_exceed_q01',  0.001),
        ('h5_synth_exceed_q1',   'h5_real_exceed_q1',   0.01),
        ('h5_synth_exceed_q05',  'h5_real_exceed_q05',  0.005),
        ('h5_synth_exceed_q01',  'h5_real_exceed_q01',  0.001),
        ('h21_synth_exceed_q1',  'h21_real_exceed_q1',  0.01),
        ('h21_synth_exceed_q05', 'h21_real_exceed_q05', 0.005),
        ('h21_synth_exceed_q01', 'h21_real_exceed_q01', 0.001),
    ]:
        _sv_rate = tail_out.get(_tqskey)
        _rv_rate = tail_out.get(_tqrkey, _nom_rate)  # fallback to nominal rate
        if isinstance(_sv_rate, float) and np.isfinite(_sv_rate) and np.isfinite(_rv_rate):
            # STEP 1 — symmetric: max(real, synth, eps) prevents inflation when real≈0
            _denom = max(abs(_rv_rate), abs(_sv_rate), _nom_rate, _tf_eps)
            _err = abs(_sv_rate - _rv_rate) / _denom
            _tf_err_parts.append(min(_err, 2.0))
    tail_out['tail_freq_error'] = (float(np.mean(_tf_err_parts))
                                   if _tf_err_parts else float('nan'))

    # Daily tail clustering
    if len(real_r) > 10 and len(synth_r) > 10:
        real_q1_daily  = float(np.percentile(real_r, 1.0))
        cond_prob_real  = _tail_cond_prob(real_r,  real_q1_daily)
        cond_prob_synth = _tail_cond_prob(synth_r, real_q1_daily)
        tail_out['tail_cond_prob_real']  = cond_prob_real
        tail_out['tail_cond_prob_synth'] = cond_prob_synth
        if (np.isfinite(cond_prob_real) and np.isfinite(cond_prob_synth)
                and cond_prob_real > 0):
            cond_rel = abs(cond_prob_synth - cond_prob_real) / cond_prob_real
            tail_out['tail_cond_prob_rel_err'] = cond_rel
            if cond_rel > _FRL_TAIL_COND_PROB_BAND:
                tail_warn = True
                warn_msgs.append(
                    f"tail_frequency: cond P(tail|tail) rel_err={cond_rel:.2f} "
                    f"> {_FRL_TAIL_COND_PROB_BAND}  "
                    f"(synth={cond_prob_synth:.3f} real={cond_prob_real:.3f})")
        # Fraction of 5-day windows with ≥2 tail days
        frac_5d_real  = _frac_windows_with_k_tails(real_r,  real_q1_daily, 5, 2)
        frac_5d_synth = _frac_windows_with_k_tails(synth_r, real_q1_daily, 5, 2)
        tail_out['frac_5d_ge2_tails_real']  = frac_5d_real
        tail_out['frac_5d_ge2_tails_synth'] = frac_5d_synth

    if tail_fail:
        tail_out['status'] = 'FAIL'
        block_fails.append('tail_frequency')
    elif tail_warn:
        tail_out['status'] = 'WARN'
        block_warns.append('tail_frequency')
    else:
        tail_out['status'] = 'PASS'

    # ══════════════════════════════════════════════════════════════════════════
    # Block 4: STRESS-WINDOW REALISM (PART 6) — reuses drawdown + rvol data above
    # ══════════════════════════════════════════════════════════════════════════
    _cr: Dict[str, Any] = {}
    _cr_warns: List[str] = []
    _cr_mdd_r = float(max(dd_ep_r.get('max_depths') or [0.0]))
    _cr_mdd_s = float(max(dd_ep_s.get('max_depths') or [0.0]))
    _cr['max_drawdown_real']  = _cr_mdd_r
    _cr['max_drawdown_synth'] = _cr_mdd_s
    if _cr_mdd_r > 0 and np.isfinite(_cr_mdd_s):
        _cr_mdd_rel = abs(_cr_mdd_s - _cr_mdd_r) / _cr_mdd_r
        _cr['max_drawdown_rel_err'] = _cr_mdd_rel
        if _cr_mdd_rel > 0.25:
            _cr_warns.append(
                f"stress_window_realism: max_drawdown rel_err={_cr_mdd_rel:.2f} > 0.25  "
                f"(synth={_cr_mdd_s*100:.1f}% real={_cr_mdd_r*100:.1f}%)")
    _t2r_r = dd_ep_r.get('t2r_days') or []
    _t2r_s = dd_ep_s.get('t2r_days') or []
    _cr_rt_r = float(np.median(_t2r_r)) if _t2r_r else float('nan')
    _cr_rt_s = float(np.median(_t2r_s)) if _t2r_s else float('nan')
    _cr['recovery_time_real']  = _cr_rt_r
    _cr['recovery_time_synth'] = _cr_rt_s
    if np.isfinite(_cr_rt_r) and np.isfinite(_cr_rt_s) and _cr_rt_r > 0:
        _cr_rt_rel = abs(_cr_rt_s - _cr_rt_r) / _cr_rt_r
        _cr['recovery_time_rel_err'] = _cr_rt_rel
        if _cr_rt_rel > 0.25:
            _cr_warns.append(
                f"stress_window_realism: recovery_time rel_err={_cr_rt_rel:.2f} > 0.25  "
                f"(synth={_cr_rt_s:.0f}d real={_cr_rt_r:.0f}d)")
    _cr_pv_r = rvol_r.get('p99', float('nan'))
    _cr_pv_s = rvol_s.get('p99', float('nan'))
    _cr['peak_vol_real']  = _cr_pv_r
    _cr['peak_vol_synth'] = _cr_pv_s
    if np.isfinite(_cr_pv_r) and np.isfinite(_cr_pv_s) and _cr_pv_r > 0:
        _cr_pv_rel = abs(_cr_pv_s - _cr_pv_r) / _cr_pv_r
        _cr['peak_vol_rel_err'] = _cr_pv_rel
        if _cr_pv_rel > 0.25:
            _cr_warns.append(
                f"stress_window_realism: peak_vol rel_err={_cr_pv_rel:.2f} > 0.25  "
                f"(synth={_cr_pv_s*100:.1f}%/yr real={_cr_pv_r*100:.1f}%/yr)")
    _cr['warnings'] = _cr_warns
    _cr['any_warn'] = bool(_cr_warns)
    if _cr_warns:
        warn_msgs.extend(_cr_warns)
        block_warns.append('stress_window_realism')

    # ══════════════════════════════════════════════════════════════════════════
    # Block 5: CROSS-ASSET CORRELATION REALISM (PART 7 — optional)
    # Activated when real_r2 and synth_r2 are supplied (e.g., SPY + QQQ).
    # ══════════════════════════════════════════════════════════════════════════
    _ca_out: Optional[Dict[str, Any]] = None
    if real_r2 is not None and synth_r2 is not None:
        _rr2 = np.asarray(real_r2,  dtype=np.float64)
        _sr2 = np.asarray(synth_r2, dtype=np.float64)
        _rr2 = _rr2[np.isfinite(_rr2)]
        _sr2 = _sr2[np.isfinite(_sr2)]
        _cw  = 63
        _ca_out = {}
        _ca_warn_flag = False
        _n_rca = min(len(real_r),  len(_rr2))
        _n_sca = min(len(synth_r), len(_sr2))
        if _n_rca >= _cw * 2 and _n_sca >= _cw * 2:
            _r1ca = real_r[:_n_rca];   _r2ca = _rr2[:_n_rca]
            _s1ca = synth_r[:_n_sca];  _s2ca = _sr2[:_n_sca]
            _rc_r = np.array([
                np.corrcoef(_r1ca[_i - _cw + 1:_i + 1],
                            _r2ca[_i - _cw + 1:_i + 1])[0, 1]
                for _i in range(_cw - 1, _n_rca)
            ])
            _rc_s = np.array([
                np.corrcoef(_s1ca[_i - _cw + 1:_i + 1],
                            _s2ca[_i - _cw + 1:_i + 1])[0, 1]
                for _i in range(_cw - 1, _n_sca)
            ])
            _rc_r = _rc_r[np.isfinite(_rc_r)]
            _rc_s = _rc_s[np.isfinite(_rc_s)]
            if len(_rc_r) > 0 and len(_rc_s) > 0:
                _ca_out.update({
                    'real_mean':  float(np.mean(_rc_r)),
                    'real_p10':   float(np.percentile(_rc_r, 10)),
                    'real_p90':   float(np.percentile(_rc_r, 90)),
                    'synth_mean': float(np.mean(_rc_s)),
                    'synth_p10':  float(np.percentile(_rc_s, 10)),
                    'synth_p90':  float(np.percentile(_rc_s, 90)),
                })
                # STEP 3 — absolute errors; mean tol=0.05, p10/p90 tol=0.10
                for _stat, _rv, _sv, _tol in (
                    ('mean', _ca_out['real_mean'],  _ca_out['synth_mean'],  0.05),
                    ('p10',  _ca_out['real_p10'],   _ca_out['synth_p10'],   0.10),
                    ('p90',  _ca_out['real_p90'],   _ca_out['synth_p90'],   0.10),
                ):
                    if np.isfinite(_rv) and np.isfinite(_sv):
                        _ca_abs = abs(_sv - _rv)
                        _ca_out[f'corr_{_stat}_abs_err'] = _ca_abs
                        if _ca_abs > _tol:
                            _ca_warn_flag = True
                            warn_msgs.append(
                                f"cross_asset_corr: rolling 63d corr {_stat} "
                                f"abs_err={_ca_abs:.3f} > {_tol}  "
                                f"(synth={_sv:.3f} real={_rv:.3f})")
        _ca_out['status'] = 'WARN' if _ca_warn_flag else 'PASS'
        if _ca_warn_flag:
            block_warns.append('cross_asset_corr')

    threshold_exceeded = bool(block_fails or block_warns)
    _frl_out: Dict[str, Any] = {
        'vol_clustering'        : vc,
        'drawdown'              : dd_out,
        'tail_frequency'        : tail_out,
        'tail_magnitude'        : _tail_magnitude_out,    # STEP 1 — top-level
        'stress_window_realism' : _cr,                    # STEP 6 — renamed
        'block_fails'           : block_fails,
        'block_warns'           : block_warns,
        'threshold_exceeded'    : threshold_exceeded,
        'metric_warnings'       : warn_msgs,
    }
    if _ca_out is not None:
        _frl_out['cross_asset_corr'] = _ca_out
    return _frl_out


def compute_realism_score(result: Dict[str, Any]) -> float:
    """
    Compute a 0–100 weighted realism score from validate_forward_scenario_realism output.

    Components (each 0–100, via linear decay from 0 error → 100 to 2× threshold → 0):
      vol_clustering  (25%) — mean ACF |r| diff and realized-vol p99 relative error
      drawdown        (25%) — peak→recovery p90 + crisis max-DD + crisis recovery-time
      tail_frequency  (20%) — daily 1% exceedance proximity to [0.8%, 1.2%] band
      tail_magnitude  (15%) — quantile magnitude relative errors at 0.1/0.5/1/5%
      vol_persistence (15%) — high-vol run-length median and p90 relative errors

    Returns float in [0, 100].  Returns 50.0 when data is insufficient for a component.
    """
    def _score_rel(rel_err: float, critical: float) -> float:
        """0-error → 100; at critical → 0; linear decay.  NaN/inf → neutral 50."""
        if not np.isfinite(rel_err) or not np.isfinite(critical) or critical <= 0:
            return 50.0
        return float(max(0.0, 100.0 * (1.0 - rel_err / critical)))

    vc = result.get('vol_clustering', {})
    dd = result.get('drawdown', {})
    tf = result.get('tail_frequency', {})
    cr = result.get('stress_window_realism', {})   # STEP 6 — renamed key

    # ── 1. Vol clustering score (25%) ─────────────────────────────────────────
    _vc_parts: List[float] = []
    # STEP 5 — use specific lags [1, 5, 10, 20] instead of mean across all lags
    _acf_lag_diffs    = [float(vc.get(f'acf_lag{lg}_abs_diff', float('nan')))
                         for lg in (1, 5, 10, 20)]
    _acf_sq_lag_diffs = [float(vc.get(f'acf_sq_lag{lg}_diff',  float('nan')))
                         for lg in (1, 5, 10, 20)]
    _finite_abs = [d for d in _acf_lag_diffs    if np.isfinite(d)]
    _finite_sq  = [d for d in _acf_sq_lag_diffs if np.isfinite(d)]
    if _finite_abs:
        _vc_parts.append(_score_rel(float(np.mean(_finite_abs)),
                                    _FRL_ACF_MEAN_DIFF_WARN * 2))
    else:   # fallback to global mean when per-lag keys absent (old results)
        _acf_diff = float(vc.get('mean_acf_abs_diff', float('nan')))
        if np.isfinite(_acf_diff):
            _vc_parts.append(_score_rel(_acf_diff, _FRL_ACF_MEAN_DIFF_WARN * 2))
    if _finite_sq:
        _vc_parts.append(_score_rel(float(np.mean(_finite_sq)),
                                    _FRL_ACF_MEAN_DIFF_WARN * 2))
    else:
        _rvol_err = float(vc.get('rvol_p99_rel_err', float('nan')))
        if np.isfinite(_rvol_err):
            _vc_parts.append(_score_rel(_rvol_err, _FRL_RVOL_P99_REL_ERR_WARN * 2))
    # Always include rvol_p99 as an independent sub-component
    _rvol_err = float(vc.get('rvol_p99_rel_err', float('nan')))
    if np.isfinite(_rvol_err):
        _vc_parts.append(_score_rel(_rvol_err, _FRL_RVOL_P99_REL_ERR_WARN * 2))
    # STEP 4 — Annual vol rel_err (critical = 2×0.15 = 0.30)
    _ann_vol_err = float(vc.get('ann_vol_rel_err', float('nan')))
    if np.isfinite(_ann_vol_err):
        _vc_parts.append(_score_rel(_ann_vol_err, 0.30))
    vc_score = float(np.mean(_vc_parts)) if _vc_parts else 50.0

    # ── 2. Drawdown score (25%) — includes crisis realism contributions ────────
    _dd_parts: List[float] = []
    _p2r_err = float(dd.get('p2r_p90_rel_err', float('nan')))
    if np.isfinite(_p2r_err):
        _dd_parts.append(_score_rel(_p2r_err, _FRL_DD_P2R_P90_REL_ERR_WARN * 2))
    # time-in-drawdown: always available, good proxy when episodes don't close
    _tid_r = float(dd.get('real',  {}).get('time_in_dd', float('nan')))
    _tid_s = float(dd.get('synth', {}).get('time_in_dd', float('nan')))
    if np.isfinite(_tid_r) and np.isfinite(_tid_s):
        if _tid_r > 1e-4:
            _dd_parts.append(_score_rel(abs(_tid_s - _tid_r) / _tid_r, 1.0))
        elif abs(_tid_s - _tid_r) < 0.01:
            _dd_parts.append(100.0)   # both near zero → PASS
    # Crisis realism contributions (max DD + recovery time)
    _mdd_rel = float(cr.get('max_drawdown_rel_err', float('nan')))
    if np.isfinite(_mdd_rel):
        _dd_parts.append(_score_rel(_mdd_rel, 0.50))
    _rt_rel = float(cr.get('recovery_time_rel_err', float('nan')))
    if np.isfinite(_rt_rel):
        _dd_parts.append(_score_rel(_rt_rel, 0.50))
    # No data at all (no episodes, no time-in-dd) → assume PASS (no evidence of mismatch)
    dd_score = float(np.mean(_dd_parts)) if _dd_parts else 100.0

    # ── 3. Tail frequency score (20%) — STEP 4: multi-threshold distance ──────
    # tail_freq_error: mean relative error across [1%, 0.5%, 0.1%] × [1d, 5d, 21d]
    _tfe = float(tf.get('tail_freq_error', float('nan')))
    if np.isfinite(_tfe):
        # 0 error → 100, error ≥ 2.0 → 0, linear interpolation
        tf_score = max(0.0, 100.0 * (1.0 - _tfe / 2.0))
    else:
        # Fallback to old daily-1%-band logic when tail_freq_error not stored
        _h1_exceed = float(tf.get('h1_synth_exceed_q1', float('nan')))
        if np.isfinite(_h1_exceed):
            _lo, _hi = _FRL_DAILY_EXCEED_LO, _FRL_DAILY_EXCEED_HI
            if _lo <= _h1_exceed <= _hi:
                tf_score = 100.0
            else:
                _target = 0.5 * (_lo + _hi)
                _excess = max(0.0, _h1_exceed - _hi) + max(0.0, _lo - _h1_exceed)
                tf_score = _score_rel(_excess / _target, 2.0)
        else:
            tf_score = 50.0

    # ── 4. Tail magnitude score (15%) — STEP 1: read from top-level ───────────
    _tm = result.get('tail_magnitude', {})
    _tm_parts: List[float] = []
    for _qkey in ('q0.1', 'q0.5', 'q1.0', 'q5.0'):
        _err = float(_tm.get(_qkey, {}).get('rel_err', float('nan')))
        if np.isfinite(_err):
            _tm_parts.append(_score_rel(_err, 0.30))   # critical = 2 × 0.15
    # STEP 5 — Skew (critical=1.0 = 2×0.5) and kurtosis (critical=4.0 = 2×2.0)
    _skew_diff = float(_tm.get('skew_diff', float('nan')))
    if np.isfinite(_skew_diff):
        _tm_parts.append(_score_rel(_skew_diff, 1.0))
    _kurt_diff = float(_tm.get('kurtosis_diff', float('nan')))
    if np.isfinite(_kurt_diff):
        _tm_parts.append(_score_rel(_kurt_diff, 4.0))
    tail_mag_score = float(np.mean(_tm_parts)) if _tm_parts else 50.0

    # ── 5. Vol persistence score (15%) ────────────────────────────────────────
    _vp_parts: List[float] = []
    _med_err = float(vc.get('vol_run_median_rel_err', float('nan')))
    if np.isfinite(_med_err):
        _vp_parts.append(_score_rel(_med_err, 0.50))   # critical = 2 × 0.25
    _p90_err = float(vc.get('vol_run_p90_rel_err', float('nan')))
    if np.isfinite(_p90_err):
        _vp_parts.append(_score_rel(_p90_err, 0.50))
    # STEP 2 — High-vol state frequency rel_err (critical = 2×0.25 = 0.50)
    _hv_frac_err = float(vc.get('high_vol_frac_rel_err', float('nan')))
    if np.isfinite(_hv_frac_err):
        _vp_parts.append(_score_rel(_hv_frac_err, 0.50))
    pers_score = float(np.mean(_vp_parts)) if _vp_parts else 50.0

    # ── Weighted average ──────────────────────────────────────────────────────
    score = (0.25 * vc_score
             + 0.25 * dd_score
             + 0.20 * tf_score
             + 0.15 * tail_mag_score
             + 0.15 * pers_score)
    return float(np.clip(score, 0.0, 100.0))


def validate_crisis_realism(
        real_r  : np.ndarray,
        synth_r : np.ndarray,
) -> Dict[str, Any]:
    """
    Standalone crisis realism validator.

    Compares max drawdown, median recovery time, and peak volatility (p99 of 21-day
    rolling annualised vol) between a real and synthetic daily-return series.
    Warns when any metric's relative error exceeds 25%.

    Parameters
    ----------
    real_r  : 1-D array of historical daily returns.
    synth_r : 1-D array of simulated daily returns.

    Returns
    -------
    dict with keys:
      max_drawdown_{real,synth}      : worst peak-to-trough depth (fraction)
      max_drawdown_rel_err           : |synth/real − 1|
      recovery_time_{real,synth}     : median trough→recovery (trading days)
      recovery_time_rel_err          : |synth/real − 1|
      peak_vol_{real,synth}          : 99th-pct 21d realised vol (annualised)
      peak_vol_rel_err               : |synth/real − 1|
      warnings                       : list of human-readable warning strings
      any_warn                       : bool — True if any metric exceeds threshold
    """
    real_r  = np.asarray(real_r,  dtype=np.float64)
    synth_r = np.asarray(synth_r, dtype=np.float64)
    real_r  = real_r[np.isfinite(real_r)]
    synth_r = synth_r[np.isfinite(synth_r)]

    out: Dict[str, Any] = {}
    warn_list: List[str] = []

    def _max_dd(r: np.ndarray) -> float:
        if len(r) < 2:
            return float('nan')
        w  = np.cumprod(1.0 + r)
        rm = np.maximum.accumulate(w)
        return float(np.max(1.0 - w / rm))

    # Max drawdown
    mdd_r = _max_dd(real_r)
    mdd_s = _max_dd(synth_r)
    out['max_drawdown_real']  = mdd_r
    out['max_drawdown_synth'] = mdd_s
    if mdd_r > 0 and np.isfinite(mdd_s):
        _rel = abs(mdd_s - mdd_r) / mdd_r
        out['max_drawdown_rel_err'] = _rel
        if _rel > 0.25:
            warn_list.append(
                f"stress_window_realism: max_drawdown rel_err={_rel:.2f} > 0.25  "
                f"(synth={mdd_s*100:.1f}% real={mdd_r*100:.1f}%)")

    # Median recovery time (trough→recovery days)
    ep_r = _drawdown_episodes(real_r)
    ep_s = _drawdown_episodes(synth_r)
    t2r_r = ep_r.get('t2r_days') or []
    t2r_s = ep_s.get('t2r_days') or []
    rt_r = float(np.median(t2r_r)) if t2r_r else float('nan')
    rt_s = float(np.median(t2r_s)) if t2r_s else float('nan')
    out['recovery_time_real']  = rt_r
    out['recovery_time_synth'] = rt_s
    if np.isfinite(rt_r) and np.isfinite(rt_s) and rt_r > 0:
        _rel = abs(rt_s - rt_r) / rt_r
        out['recovery_time_rel_err'] = _rel
        if _rel > 0.25:
            warn_list.append(
                f"stress_window_realism: recovery_time rel_err={_rel:.2f} > 0.25  "
                f"(synth={rt_s:.0f}d real={rt_r:.0f}d)")

    # Peak volatility (p99 of non-overlapping 21d realized vol)
    pv_r = _realized_vol_stats(real_r).get('p99', float('nan'))
    pv_s = _realized_vol_stats(synth_r).get('p99', float('nan'))
    out['peak_vol_real']  = pv_r
    out['peak_vol_synth'] = pv_s
    if np.isfinite(pv_r) and np.isfinite(pv_s) and pv_r > 0:
        _rel = abs(pv_s - pv_r) / pv_r
        out['peak_vol_rel_err'] = _rel
        if _rel > 0.25:
            warn_list.append(
                f"stress_window_realism: peak_vol rel_err={_rel:.2f} > 0.25  "
                f"(synth={pv_s*100:.1f}%/yr real={pv_r*100:.1f}%/yr)")

    out['warnings'] = warn_list
    out['any_warn'] = bool(warn_list)
    return out


def aggregate_forward_realism_across_paths(
        real_r     : np.ndarray,
        synth_paths: List[np.ndarray],
        horizons   : Tuple[int, ...] = (1, 5, 21),
        lags       : int             = 20,
        mode       : ScenarioRealismMode = ScenarioRealismMode.WARN_ONLY,
) -> Dict[str, Any]:
    """
    Run validate_forward_scenario_realism across multiple synthetic driver-level
    paths and aggregate to median/p10/p90.

    Absurdity guards are always enforced regardless of mode:
      - ann_vol < 2%                    → ValueError
      - ann_vol > 100%                  → ValueError
      - |mean_daily| > 0.5% (≈125%/yr) → ValueError
      - fraction of |r|>20% days > 0.5% → ValueError
      - no 5%+ drawdown for ≥30 yr of data (if series is long enough) → ValueError

    Parameters
    ----------
    real_r       : 1-D array-like of historical daily driver returns.
    synth_paths  : list of per-path 1-D return arrays.
    horizons     : passed to validate_forward_scenario_realism.  Default (1, 5, 21).
    lags         : maximum ACF lag.  Default 20.
    mode         : ScenarioRealismMode.

    Returns
    -------
    dict with keys:
      mode               : str value of ScenarioRealismMode used
      n_paths            : paths evaluated
      n_fail_paths       : paths with at least one block FAIL
      n_warn_paths       : paths with at least one block WARN (but no FAIL)
      fraction_failed    : n_fail_paths / n_paths
      aggregate          : per-metric {p10, median, p90} across paths
      block_statuses     : dict block_name → {'PASS'|'WARN'|'FAIL': count}
      absurdity_errors   : List[str]
      blocked            : True iff STRICT and ≥50% of paths FAIL any block
      skipped            : True iff mode == SKIP
    """
    if mode == ScenarioRealismMode.SKIP:
        return {'mode': mode.value, 'skipped': True, 'blocked': False}

    real_r = np.asarray(real_r, dtype=np.float64)
    real_r = real_r[np.isfinite(real_r)]

    if not synth_paths:
        return {
            'mode': mode.value, 'n_paths': 0, 'blocked': False,
            'skipped': False, 'reason': 'no synth_paths provided',
            'absurdity_errors': [],
        }

    # ── Absurdity guards (always enforced, even in WARN_ONLY) ─────────────────
    abs_errs: List[str] = []
    _check_n = min(len(synth_paths), 10)
    for i, sp in enumerate(synth_paths[:_check_n]):
        _sp = np.asarray(sp, dtype=np.float64)
        _sp = _sp[np.isfinite(_sp)]
        if len(_sp) < 5:
            continue
        ann_vol  = float(np.std(_sp, ddof=1) * np.sqrt(252))
        mean_abs = float(abs(np.mean(_sp)))
        jump_frac = float(np.mean(np.abs(_sp) > 0.20))
        if ann_vol < _FRL_ABSURDITY_MIN_VOL:
            abs_errs.append(
                f"path[{i}] ann_vol={ann_vol*100:.2f}%"
                f"<{_FRL_ABSURDITY_MIN_VOL*100:.0f}% (degenerate/flat)")
        if ann_vol > _FRL_ABSURDITY_MAX_VOL:
            abs_errs.append(
                f"path[{i}] ann_vol={ann_vol*100:.0f}%"
                f">{_FRL_ABSURDITY_MAX_VOL*100:.0f}% (explosive)")
        if mean_abs > _FRL_ABSURDITY_MAX_DRIFT:
            abs_errs.append(
                f"path[{i}] |mean_daily|={mean_abs*100:.3f}%"
                f">{_FRL_ABSURDITY_MAX_DRIFT*100:.1f}% "
                f"(={mean_abs*252*100:.0f}%/yr — implausible drift)")
        if jump_frac > _FRL_ABSURDITY_JUMP_FRAC:
            abs_errs.append(
                f"path[{i}] {jump_frac*100:.2f}% of days have |r|>20% "
                f"(>{_FRL_ABSURDITY_JUMP_FRAC*100:.1f}% limit — explosive jumps)")
        if len(_sp) >= _FRL_ABSURDITY_NO_DD_DAYS:
            wealth = np.cumprod(1.0 + _sp)
            dd_max = float(np.max(1.0 - wealth / np.maximum.accumulate(wealth)))
            if dd_max < 0.05:
                abs_errs.append(
                    f"path[{i}] no 5%+ drawdown across {len(_sp):,} days "
                    f"({len(_sp)/252:.0f}yr) — permanently up / no crash modelled")
    if abs_errs:
        raise ValueError(
            "FORWARD REALISM ABSURDITY GUARD:\n  " + "\n  ".join(abs_errs))

    # ── Per-path validation ────────────────────────────────────────────────────
    per_path: List[Dict[str, Any]] = []
    for sp in synth_paths:
        try:
            per_path.append(
                validate_forward_scenario_realism(
                    real_r, np.asarray(sp, dtype=np.float64),
                    horizons=horizons, lags=lags,
                )
            )
        except Exception as _e:
            per_path.append({
                'block_fails': [], 'block_warns': [],
                'threshold_exceeded': False, 'error': str(_e),
            })

    n_paths     = len(per_path)
    n_fail_paths = sum(1 for r in per_path if r.get('block_fails'))
    n_warn_paths = sum(1 for r in per_path
                       if r.get('block_warns') and not r.get('block_fails'))
    frac_fail    = float(n_fail_paths / n_paths) if n_paths else 0.0

    # ── Per-block status counts ────────────────────────────────────────────────
    _block_names = ('vol_clustering', 'drawdown', 'tail_frequency')
    block_statuses: Dict[str, Dict[str, int]] = {
        b: {'PASS': 0, 'WARN': 0, 'FAIL': 0} for b in _block_names
    }
    for r in per_path:
        for b in _block_names:
            st = r.get(b, {}).get('status', 'PASS')
            if st in block_statuses[b]:
                block_statuses[b][st] += 1

    # ── Aggregate scalar metrics (median / p10 / p90) ─────────────────────────
    def _agg(vals: List[float]) -> Dict[str, float]:
        a = [v for v in vals if np.isfinite(float(v))]
        if not a:
            return {}
        return {
            'p10'   : float(np.percentile(a, 10)),
            'median': float(np.percentile(a, 50)),
            'p90'   : float(np.percentile(a, 90)),
        }

    agg: Dict[str, Any] = {}
    # Vol-clustering scalars
    for key in ('mean_acf_abs_diff', 'mean_acf_sq_diff', 'rvol_p99_rel_err'):
        agg[key] = _agg([r.get('vol_clustering', {}).get(key, float('nan'))
                          for r in per_path])
    for lb_k in (10, 20):
        key = f'lb_pvalue_synth_lag{lb_k}'
        agg[key] = _agg([r.get('vol_clustering', {}).get(key, float('nan'))
                          for r in per_path])
    for _sub in ('mean', 'median', 'p90', 'p99'):
        key = f'rvol_synth_{_sub}'
        agg[key] = _agg([r.get('vol_clustering', {}).get('rvol_synth', {}).get(_sub, float('nan'))
                          for r in per_path])
    for _sub in ('high_vol_run_synth_median', 'high_vol_run_synth_p90'):
        agg[_sub] = _agg([r.get('vol_clustering', {}).get(_sub, float('nan'))
                           for r in per_path])
    # STEP 4 — Annual vol; STEP 2 — high-vol fraction
    for _sub in ('ann_vol_rel_err', 'high_vol_frac_rel_err',
                 'ann_vol_real', 'ann_vol_synth',
                 'high_vol_frac_real', 'high_vol_frac_synth'):
        agg[_sub] = _agg([r.get('vol_clustering', {}).get(_sub, float('nan'))
                           for r in per_path])
    # STEP 5 — Skew and kurtosis from tail_magnitude (top-level)
    for _sub in ('skew_diff', 'kurtosis_diff', 'skew_real', 'skew_synth',
                 'kurtosis_real', 'kurtosis_synth'):
        agg[_sub] = _agg([r.get('tail_magnitude', {}).get(_sub, float('nan'))
                           for r in per_path])
    # Drawdown scalars
    for _sub in ('p2t_days_median', 'p2t_days_p90',
                 't2r_days_median', 't2r_days_p90',
                 'p2r_days_median', 'p2r_days_p90',
                 'max_depths_median', 'max_depths_p90',
                 'time_in_dd'):
        agg[f'dd_synth_{_sub}'] = _agg([
            r.get('drawdown', {}).get('synth', {}).get(_sub, float('nan'))
            for r in per_path
        ])
    agg['dd_p2r_p90_rel_err'] = _agg([
        r.get('drawdown', {}).get('p2r_p90_rel_err', float('nan'))
        for r in per_path
    ])
    # Tail scalars
    for h in sorted(set(horizons) | {5, 21}):
        for _sub in (f'h{h}_synth_exceed_q1', f'h{h}_synth_exceed_q05'):
            agg[_sub] = _agg([r.get('tail_frequency', {}).get(_sub, float('nan'))
                               for r in per_path])
    for _sub in ('tail_cond_prob_synth', 'frac_5d_ge2_tails_synth', 'h5_q1_rel_err'):
        agg[_sub] = _agg([r.get('tail_frequency', {}).get(_sub, float('nan'))
                           for r in per_path])

    # ── Per-path realism scores ────────────────────────────────────────────────
    _path_scores: List[float] = []
    for _r in per_path:
        if 'vol_clustering' in _r and 'tail_frequency' in _r:
            try:
                _path_scores.append(compute_realism_score(_r))
            except Exception:
                pass
    median_realism_score = float(np.median(_path_scores)) if _path_scores else 50.0
    # STEP 3 — P10 score for dispersion-based blocking
    p10_realism_score = float(np.percentile(_path_scores, 10)) if _path_scores else 50.0

    # ── Blocking logic — STEP 3: median OR dispersion (p10) ───────────────────
    # STRICT: block when median < 70 OR p10 < 50 (catches fat-tailed poor-path dist.)
    _median_blocks = median_realism_score < 70.0
    _p10_blocks    = p10_realism_score    < 50.0
    blocked = bool(mode == ScenarioRealismMode.STRICT and (_median_blocks or _p10_blocks))

    return {
        'mode'              : mode.value,
        'n_paths'           : n_paths,
        'n_fail_paths'      : n_fail_paths,
        'n_warn_paths'      : n_warn_paths,
        'fraction_failed'   : frac_fail,
        'aggregate'         : agg,
        'block_statuses'    : block_statuses,
        'absurdity_errors'  : abs_errs,
        'blocked'           : blocked,
        'realism_score'     : median_realism_score,    # median across paths
        'p10_realism_score' : p10_realism_score,       # STEP 3
        'skipped'           : False,
    }


def print_forward_realism_report(
        result  : Dict[str, Any],
        scenario: str = '',
) -> None:
    """
    Print the SCENARIO REALISM REPORT with PASS/WARN/FAIL per block.

    Output is concise and machine-scannable.
    """
    mode_str = result.get('mode', 'unknown')
    skipped  = result.get('skipped', False)
    blocked  = result.get('blocked', False)
    n_paths  = result.get('n_paths', 0)
    n_fail   = result.get('n_fail_paths', 0)
    n_warn   = result.get('n_warn_paths', 0)
    frac_f   = result.get('fraction_failed', 0.0)
    agg      = result.get('aggregate', {})
    bst      = result.get('block_statuses', {})
    scen_tag = f"  scenario: {scenario.upper()}" if scenario else ''

    W = 80
    print(f"\n{'='*W}")
    print(f"SCENARIO REALISM REPORT{scen_tag}")
    print(f"  mode: {mode_str.upper()}"
          f"  {'*** BLOCKED ***' if blocked else '[not blocked]'}"
          f"{'  [SKIPPED]' if skipped else ''}")
    print(f"{'='*W}")

    if skipped:
        print("  Skipped — historical_backtest has its own institutional validator.")
        print(f"{'='*W}\n")
        return

    if result.get('reason'):
        print(f"  {result['reason']}")
        print(f"{'='*W}\n")
        return

    print(f"  Paths  : {n_paths}  |  FAIL paths: {n_fail} ({frac_f*100:.0f}%)  "
          f"|  WARN paths: {n_warn}")

    def _st_tag(block: str) -> str:
        """Majority status across paths for a block."""
        bc = bst.get(block, {})
        if bc.get('FAIL', 0) * 2 >= max(n_paths, 1):
            return 'FAIL'
        if bc.get('WARN', 0) * 2 >= max(n_paths, 1):
            return 'WARN'
        return 'PASS'

    def _fmt(d: Dict) -> str:
        if not d:
            return 'n/a'
        return (f"p10={d.get('p10', float('nan')):.3f}  "
                f"med={d.get('median', float('nan')):.3f}  "
                f"p90={d.get('p90', float('nan')):.3f}")

    # ── Block 1: VOL CLUSTERING ───────────────────────────────────────────────
    _st1 = _st_tag('vol_clustering')
    print(f"\n  [Block 1] VOL CLUSTERING                             [{_st1}]")
    print(f"  {'─'*50}")
    if 'mean_acf_abs_diff' in agg:
        _v = agg['mean_acf_abs_diff']
        print(f"    mean|ACF(|r|) diff| lags1..20  : {_fmt(_v)}"
              f"  tol<{_FRL_ACF_MEAN_DIFF_WARN}")
    if 'mean_acf_sq_diff' in agg:
        _v = agg['mean_acf_sq_diff']
        print(f"    mean|ACF(r²) diff|  lags1..20  : {_fmt(_v)}"
              f"  tol<{_FRL_ACF_MEAN_DIFF_WARN}")
    for lb_k in (10, 20):
        key = f'lb_pvalue_synth_lag{lb_k}'
        if key in agg:
            print(f"    Ljung-Box p-val (synth) lag{lb_k:2d} : {_fmt(agg[key])}")
    if 'rvol_p99_rel_err' in agg:
        _v = agg['rvol_p99_rel_err']
        print(f"    rvol p99 rel_err               : {_fmt(_v)}"
              f"  tol<{_FRL_RVOL_P99_REL_ERR_WARN}")
    for _sub in ('mean', 'median', 'p90', 'p99'):
        key = f'rvol_synth_{_sub}'
        if key in agg and agg[key]:
            print(f"    rvol synth {_sub:6s}             : {_fmt(agg[key])}")
    if agg.get('high_vol_run_synth_median'):
        print(f"    high-vol run median (synth)    : {_fmt(agg['high_vol_run_synth_median'])}")
        print(f"    high-vol run p90    (synth)    : {_fmt(agg['high_vol_run_synth_p90'])}")

    # ── Block 2: DRAWDOWN ─────────────────────────────────────────────────────
    _st2 = _st_tag('drawdown')
    print(f"\n  [Block 2] DRAWDOWN DURATIONS  (trading days)         [{_st2}]")
    print(f"  {'─'*50}")
    dur_labels = [
        ('dd_synth_p2t_days_median', 'peak→trough  median'),
        ('dd_synth_p2t_days_p90',    'peak→trough  p90   '),
        ('dd_synth_t2r_days_median', 'trough→recov median'),
        ('dd_synth_t2r_days_p90',    'trough→recov p90   '),
        ('dd_synth_p2r_days_median', 'peak→recov   median'),
        ('dd_synth_p2r_days_p90',    'peak→recov   p90   '),
        ('dd_synth_max_depths_median','depth        median'),
        ('dd_synth_max_depths_p90',  'depth        p90   '),
        ('dd_synth_time_in_dd',      'time-in-DD         '),
    ]
    for key, lbl in dur_labels:
        if key in agg and agg[key]:
            print(f"    {lbl} : {_fmt(agg[key])}")
    if 'dd_p2r_p90_rel_err' in agg and agg['dd_p2r_p90_rel_err']:
        _v = agg['dd_p2r_p90_rel_err']
        print(f"    p→r p90 rel_err               : {_fmt(_v)}"
              f"  tol<{_FRL_DD_P2R_P90_REL_ERR_WARN}")

    # ── Block 3: TAIL FREQUENCY ───────────────────────────────────────────────
    _st3 = _st_tag('tail_frequency')
    print(f"\n  [Block 3] TAIL EVENT FREQUENCY                       [{_st3}]")
    print(f"  {'─'*50}")
    _horizon_label = {1: '1d', 5: '5d', 21: '21d'}
    _horizons_present = sorted({int(k[1:].split('_')[0])
                                 for k in agg if k.startswith('h') and '_' in k
                                 and k[1:].split('_')[0].isdigit()} | {5, 21})
    for h in _horizons_present:
        lbl = _horizon_label.get(h, f'{h}d')
        for _sub in (f'h{h}_synth_exceed_q1', f'h{h}_synth_exceed_q05'):
            if _sub in agg and agg[_sub]:
                qname = '1.0%' if 'q1' in _sub else '0.5%'
                print(f"    exceed real {qname} (H={lbl:3s})        : {_fmt(agg[_sub])}")
    if agg.get('h5_q1_rel_err'):
        print(f"    5d q1% mag rel_err            : {_fmt(agg['h5_q1_rel_err'])}"
              f"  tol<{_FRL_5D_Q01_MAG_BAND}")
    if agg.get('tail_cond_prob_synth'):
        print(f"    cond P(tail|tail) synth       : {_fmt(agg['tail_cond_prob_synth'])}"
              f"  tol±{_FRL_TAIL_COND_PROB_BAND*100:.0f}%")
    if agg.get('frac_5d_ge2_tails_synth'):
        print(f"    frac 5d-windows ≥2 tails      : {_fmt(agg['frac_5d_ge2_tails_synth'])}")
    _daily_band = agg.get(f'h{1}_synth_exceed_q1', {})
    if _daily_band:
        _med = _daily_band.get('median', float('nan'))
        _lo  = _FRL_DAILY_EXCEED_LO
        _hi  = _FRL_DAILY_EXCEED_HI
        _ok  = np.isfinite(_med) and _lo <= _med <= _hi
        print(f"    daily 1% exceed band [{_lo*100:.1f}%,{_hi*100:.1f}%] : "
              f"med={_med*100:.3f}%  {'✓ in band' if _ok else '✗ OUTSIDE BAND'}")

    # ── Realism score + final verdict (STEP 6 additions) ─────────────────────
    _score    = result.get('realism_score',     float('nan'))
    _p10_score = result.get('p10_realism_score', float('nan'))
    print(f"\n  {'─'*50}")
    if np.isfinite(_score):
        _verdict = ('PASS' if _score >= 80.0
                    else 'WARN' if _score >= 70.0
                    else 'FAIL')
        print(f"  Median realism score : {_score:.1f} / 100  →  {_verdict}")
    if np.isfinite(_p10_score):
        _p10_v = ('PASS' if _p10_score >= 50.0 else 'WARN')
        print(f"  P10 realism score    : {_p10_score:.1f} / 100  →  {_p10_v}")
    # Per-metric diffs (from aggregate medians)
    for _key, _label, _unit in (
        ('ann_vol_rel_err',      'Annual vol diff     ', '%'),
        ('skew_diff',            'Skew diff           ', ''),
        ('kurtosis_diff',        'Kurtosis diff       ', ''),
        ('high_vol_frac_rel_err','High-vol freq diff  ', '%'),
    ):
        _v = agg.get(_key, {}).get('median', float('nan'))
        if np.isfinite(_v):
            _disp = f"{_v*100:.1f}" if _unit == '%' else f"{_v:.3f}"
            print(f"  {_label} : {_disp}{_unit} (median across paths)")
    print(f"  {'─'*50}")
    if blocked:
        _why = []
        if _score < 70.0: _why.append(f"median={_score:.0f}<70")
        if _p10_score < 50.0: _why.append(f"p10={_p10_score:.0f}<50")
        print(f"  ✗ BLOCKED  (STRICT mode — {', '.join(_why)})")
    elif n_fail > 0:
        print(f"  ⚠ {n_fail}/{n_paths} paths FAILED a block  "
              f"({'WARN_ONLY — not blocking' if mode_str == 'warn_only' else 'check mode'})")
    elif n_warn > 0:
        print(f"  ⚠ {n_warn}/{n_paths} paths have WARN blocks  (not blocking)")
    else:
        print(f"  ✓ PASS — all {n_paths} paths within realism thresholds")
    print(f"{'='*W}\n")


def run_historical_reconstruction_validation(
        df: pd.DataFrame,
        regime_model: Dict,
        correlation_matrices: Dict,
        window_start: str,
        window_end: str,
) -> Dict[str, Any]:
    """
    Run all mandatory institutional-grade validation tests for the
    historical_backtest mode.  Called automatically when
    MARKET_SCENARIO == 'historical_backtest'.

    Tests performed:
      A0.  Historical backtest purity gates (scenario params, no-wrap guard)
      A0b. Real-data-priority overlap assert (overlap_count must be 0)
      A.   Driver immutability (assertion — aborts on violation)
      A1b. Driver total-return basis proof (C1/C2 hard-fail; C3 heuristic warn-only)
      B.   SPY nominal/real CAGR fidelity vs driver (≤ 1 bp tolerance)
      C.   Borrowing cost formula unit test
      D.   LETF emulator OOS validation for each fund with real history
      E.   Taxable vs tax-free SPY comparison
      F.   Determinism test

    Prints a comprehensive validation report and returns a summary dict.
    """
    print(f"\n{'='*80}")
    print("HISTORICAL BACKTEST VALIDATION SUITE")
    print(f"  Window: {window_start} → {window_end}")
    print(f"{'='*80}")

    results: Dict[str, Any] = {}

    # ── A. Window data check ──────────────────────────────────────────────
    window_data = _slice_hist1926_to_window(window_start, window_end)
    if window_data is None:
        print("  ⚠ Cannot slice window — validation aborted.")
        return {'status': 'aborted', 'reason': 'window_data unavailable'}

    # ── A0. Historical backtest purity gates ──────────────────────────────
    print("\n  A0. HISTORICAL BACKTEST PURITY GATES")
    _sc = get_scenario()
    _gates = {
        'mode_backtest': str(_sc.get('_hist1926_mode', '')) == 'backtest',
        'is_reconstruction': bool(_sc.get('_is_reconstruction', False)),
        'drift_tilt_zero': abs(float(_sc.get('drift_tilt', 0.0))) < 1e-12,
        'div_yield_zero': abs(float(_sc.get('div_yield', 0.0))) < 1e-12,
        'vol_scale_calm_one': abs(float(_sc.get('vol_scale_calm', 1.0)) - 1.0) < 1e-12,
        'vol_scale_crisis_one': abs(float(_sc.get('vol_scale_crisis', 1.0)) - 1.0) < 1e-12,
        'fat_tail_zero': abs(float(_sc.get('fat_tail_factor', 0.0))) < 1e-12,
    }
    _gate_pass = bool(all(_gates.values()))
    if _gate_pass:
        print("  ✓ PASS — no synthetic driver overlays configured")
    else:
        for _k, _ok in _gates.items():
            if not _ok:
                print(f"  ⚠ FAIL — {_k}")
    # No-loop enforcement check (must raise when requesting beyond window length).
    _no_wrap_ok = False
    try:
        _ = _get_historical_path_returns(
            path_idx=0,
            n_paths=1,
            n_days=int(window_data['N']) + 1,
            mode='backtest',
            block_size=63,
            rng=np.random.default_rng(7),
            hist_data=window_data,
        )
    except RuntimeError:
        _no_wrap_ok = True
    print(f"  {'✓ PASS' if _no_wrap_ok else '⚠ FAIL'} — no-wrap guard when n_days > window length")
    # ── A0b. Real-data-priority overlap assert ────────────────────────────
    # historical_backtest mode must have ZERO days where a synthetic flag is set
    # on a date that also has real LETF data.  This is a hard purity requirement:
    # the backtest is supposed to use only real data wherever it exists.
    print("  A0b. REAL-DATA-PRIORITY OVERLAP ASSERT (historical_backtest)")
    _usage = print_data_usage_summary(df)
    _overlap_detected = bool(_usage.get('overlap_detected', False))
    _overlap_total = sum(
        int(v.get('overlap_days', 0))
        for v in _usage.values()
        if isinstance(v, dict) and 'overlap_days' in v
    )
    if _overlap_detected:
        # Delegate to the shared production purity guard.
        # _assert_real_data_priority() is also called by T15 so any regression
        # in this code path will be caught by the regression test suite.
        _assert_real_data_priority(df)
    else:
        print("  ✓ PASS — overlap_count == 0 (no synthetic overlay on real dates)")

    results['backtest_purity_gates'] = {
        'pass': bool(_gate_pass and _no_wrap_ok and not _overlap_detected),
        'checks': _gates,
        'no_wrap_guard': _no_wrap_ok,
        'real_data_overlap_count': _overlap_total,
        'real_data_overlap_pass': not _overlap_detected,
    }

    # ── A1. Driver immutability ───────────────────────────────────────────
    print("\n  A. DRIVER IMMUTABILITY TEST")
    original = window_data['SPY_Ret'].copy()
    try:
        imm = _driver_immutability_test(original, window_data['SPY_Ret'])
        results['driver_immutability'] = imm
        print(f"  {imm['details']}")
    except RuntimeError as _e:
        print(f"  ⚠ {_e}")
        results['driver_immutability'] = {'pass': False, 'details': str(_e)}

    # ── A1b. Driver total-return basis proof ──────────────────────────────
    print("\n  A1b. DRIVER TOTAL-RETURN BASIS PROOF")
    try:
        tr_basis = validate_driver_total_return_basis(df, mode=ValidationMode.INSTITUTIONAL_GATE)
        results['driver_total_return_basis'] = tr_basis
        if not tr_basis.get('pass', True):
            print(f"  ⚠ HARD FAIL: driver not on total-return basis — "
                  "reconstruction results are unreliable")
    except Exception as _e:
        print(f"  ⚠ driver_total_return_basis check error: {_e!r}")
        results['driver_total_return_basis'] = {'pass': False, 'message': str(_e)}

    # ── B. SPY driver fidelity ────────────────────────────────────────────
    cpi_series = _HIST_RECON_CPI
    if cpi_series is None:
        cpi_series = load_cpi_series()
    spy_fid = validate_spy_driver_fidelity(window_data, cpi_daily=cpi_series)
    results['spy_fidelity'] = spy_fid

    # Validation horizon must fit inside the selected window so custom date
    # ranges (including short windows) remain valid in historical_backtest mode.
    _window_years = float(max(int(window_data.get('N', 0)), 2) / 252.0)
    _validation_horizon_years = float(min(10.0, max(0.25, _window_years - (1.0 / 252.0))))
    print(f"  Validation horizon used for path-level tests: {_validation_horizon_years:.2f} years")

    # ── C. Borrowing cost formula ─────────────────────────────────────────
    borrow_val = validate_borrowing_cost_correctness()
    results['borrow_cost_formula'] = borrow_val

    # ── D. LETF emulator OOS validation ───────────────────────────────────
    print("\n  D. LETF EMULATOR OOS VALIDATION")
    emulator_results = {}
    oos_funds = ['UPRO', 'TQQQ', 'SSO', 'QLD']
    for fund in oos_funds:
        real_col = f'{fund}_Real_Ret'
        if real_col not in df.columns:
            print(f"  {fund}: no real return data in df — skipping.")
            emulator_results[fund] = {'status': 'skipped', 'reason': 'no real data'}
            continue
        oos = validate_letf_emulator_oos(
            df=df,
            regime_model=regime_model,
            fund=fund,
            train_end='2018-12-31',
            val_start='2019-01-01',
            val_end=window_end,
        )
        emulator_results[fund] = oos
        if oos.get('status') == 'fail':
            print(f"  ⚠ WARNING [{fund}]: emulator failed OOS validation. "
                  "Reconstruction results are indicative only.")
    results['emulator_oos'] = emulator_results
    _emul_rows = [v for v in emulator_results.values() if isinstance(v, dict) and v.get('status') != 'skipped']
    _emul_overall_pass = bool(len(_emul_rows) == 0 or all(bool(v.get('overall_pass', False)) for v in _emul_rows))
    results['emulator_oos_overall_pass'] = _emul_overall_pass
    print(f"  Emulator OOS aggregate: {'PASS' if _emul_overall_pass else 'FAIL'} "
          f"({sum(1 for v in _emul_rows if bool(v.get('overall_pass', False)))}/{len(_emul_rows)} assets)")

    # PART 3 — Reconstruction integrity summary (per-asset gate table)
    try:
        _trk_model_d = load_cache(TRACKING_RESIDUAL_CACHE)
        _integ_pass = print_reconstruction_integrity_summary(
            emulator_results=emulator_results,
            tracking_model=_trk_model_d if isinstance(_trk_model_d, dict) else {},
        )
        results['reconstruction_integrity_summary_pass'] = _integ_pass
    except Exception as _ris_err:
        print(f"  ⚠ reconstruction_integrity_summary error: {_ris_err!r}")
        results['reconstruction_integrity_summary_pass'] = None

    # ── E. Taxable vs tax-free ─────────────────────────────────────────────
    print("\n  E. TAXABLE vs TAX-FREE SPY VALIDATION")
    tax_val = validate_taxable_vs_taxfree_spy(
        df=df,
        regime_model=regime_model,
        correlation_matrices=correlation_matrices,
        n_paths=60,
        horizon_years=_validation_horizon_years,
    )
    results['taxable_vs_taxfree'] = tax_val

    # ── F. Determinism test ────────────────────────────────────────────────
    det_val = validate_reconstruction_determinism(
        regime_model=regime_model,
        correlation_matrices=correlation_matrices,
        window_start=window_start,
        window_end=window_end,
        horizon_years=_validation_horizon_years,
    )
    results['determinism'] = det_val

    # ── G. Regression tests (Phase G) ─────────────────────────────────────
    print("\n  G. REGRESSION TESTS (Phase G)")
    try:
        reg_results = run_reconstruction_regression_tests(df=df)
        results['regression_tests'] = reg_results
    except Exception as _reg_err:
        print(f"  ⚠ Regression test error: {_reg_err!r}")
        results['regression_tests'] = {'overall_pass': False, 'error': str(_reg_err)}

    # ── Summary ────────────────────────────────────────────────────────────
    overall_pass = (
        results.get('backtest_purity_gates', {}).get('pass', False)
        and results.get('driver_immutability', {}).get('pass', False)
        and results.get('driver_total_return_basis', {}).get('pass', True)  # A1b
        and results.get('spy_fidelity',     {}).get('pass', False)
        and results.get('borrow_cost_formula', {}).get('all_pass', False)
        and results.get('emulator_oos_overall_pass', False)
        and results.get('taxable_vs_taxfree', {}).get('status') == 'pass'
        and results.get('determinism', {}).get('pass', False)
        and results.get('regression_tests', {}).get('overall_pass', True)  # Phase G
    )
    print(f"\n  {'='*60}")
    print(f"  HISTORICAL BACKTEST VALIDATION: {'✓ ALL PASS' if overall_pass else '⚠ SOME FAILURES'}")
    print(f"  {'='*60}")
    results['overall_pass'] = overall_pass
    return results


def build_data_qa_report(df: pd.DataFrame) -> Dict[str, Any]:
    """
    Item 4 — Audit-grade data provenance report for all key return series in df.

    For each column in a predefined scan list:
      - Determines date range, NaN count, large-jump dates (|ret| > 15%), checksum
      - Checks for NYSE calendar gaps (missing business days)
      - Prints a compact summary table and flags issues

    Returns a dict with per-column metadata and `total_issues` count.
    """
    import hashlib as _hashlib
    import dataclasses

    @dataclasses.dataclass
    class ReturnSeriesMetadata:
        column: str
        source: str           # 'yfinance_adj', 'fama_french', 'synthetic_proxy', 'unknown'
        fetch_method: str     # e.g. 'yfinance(auto_adjust=True, Close=total_return)'
        auto_adjust: bool     # True → yfinance 'Close' column is dividend-adjusted total return
        dividend_included: bool
        first_date: str
        last_date: str
        n_days: int
        n_missing: int
        n_large_jumps: int
        large_jump_dates: List[str]
        checksum_hex: str     # sha256(np.round(arr, 6)) — reproducible given same data
        checksum_note: str    # human-readable description of checksum method
        calendar_gaps: List[str]
        issues: List[str]

    # Fetch-method annotations (for audit trail): yfinance auto_adjust=True means
    # the 'Close' price column IS the total-return (dividend-reinvested) adjusted price.
    # pct_change('Close') == total return daily, NO separate dividend adjustment needed.
    _YFINANCE_FETCH = 'yfinance(auto_adjust=True, Close=total_return_adj)'
    _FF_FETCH       = 'fama_french_datareader(daily_factors)'

    _SCAN_COLUMNS: List[Tuple[str, str, str, bool, bool]] = [
        # (column, source_label, fetch_method, auto_adjust, dividend_included)
        ('SPY_Ret',          'yfinance_adj', _YFINANCE_FETCH, True,  True),
        ('QQQ_Ret',          'yfinance_adj', _YFINANCE_FETCH, True,  True),
        ('SPY_Ret_RealOnly', 'yfinance_adj', _YFINANCE_FETCH, True,  True),
        ('QQQ_Ret_RealOnly', 'yfinance_adj', _YFINANCE_FETCH, True,  True),
        ('NDX_Ret_RealOnly', 'yfinance_adj', _YFINANCE_FETCH, True,  False),  # ^NDX: price-return index, no divs
        ('UPRO_Real_Ret',    'yfinance_adj', _YFINANCE_FETCH, True,  True),
        ('SSO_Real_Ret',     'yfinance_adj', _YFINANCE_FETCH, True,  True),
        ('TQQQ_Real_Ret',    'yfinance_adj', _YFINANCE_FETCH, True,  True),
        ('QLD_Real_Ret',     'yfinance_adj', _YFINANCE_FETCH, True,  True),
    ]

    # NYSE approximate business day set (5-day week approximation; skips known holidays)
    # If pandas_market_calendars is available use it, otherwise fall back to ~5d/wk
    _nyse_bdays: Optional[pd.DatetimeIndex] = None
    try:
        import pandas_market_calendars as mcal  # type: ignore[import]
        _nyse = mcal.get_calendar('NYSE')
        _sched = _nyse.schedule(start_date=str(df.index[0].date()),
                                 end_date=str(df.index[-1].date()))
        _nyse_bdays = pd.DatetimeIndex(_sched.index.normalize())
    except Exception:
        # Fallback: use pandas BDay
        _nyse_bdays = pd.bdate_range(start=df.index[0], end=df.index[-1])

    _df_idx_set = set(pd.DatetimeIndex(df.index).normalize())

    all_meta: Dict[str, Any] = {}
    total_issues = 0

    print(f"\n  {'='*72}")
    print(f"  DATA QA REPORT  —  {len(df):,} rows  "
          f"{df.index[0].date()} → {df.index[-1].date()}")
    print(f"  {'='*72}")
    print(f"  {'Column':<26} {'Src':>4} {'Adj':<5} {'Days':>6} {'Mis':>5} {'Jumps':>6} "
          f"{'Checksum':>14} {'Issues'}")
    print(f"  {'─'*72}")

    for (_col, _src, _fetch, _auto_adj, _div) in _SCAN_COLUMNS:
        if _col not in df.columns:
            continue

        _src_eff = _src
        _fetch_eff = _fetch
        _auto_adj_eff = _auto_adj
        _div_eff = _div
        if _col == 'NDX_Ret_RealOnly':
            _ndx_src_series = df['NDX_Ret_RealOnly_Source'] if 'NDX_Ret_RealOnly_Source' in df.columns else None
            _ndx_src = ''
            if _ndx_src_series is not None:
                _ndx_non_na = _ndx_src_series.dropna()
                if len(_ndx_non_na) > 0:
                    _ndx_src = str(_ndx_non_na.iloc[-1])
            if _ndx_src == 'NDXT_real':
                _src_eff = 'ndxt_real'
                _fetch_eff = 'nasdaq_100_total_return_index'
                _auto_adj_eff = True
                _div_eff = True
            elif _ndx_src == 'QQQ_adj_close_total_return':
                _src_eff = 'qqq_adj'
                _fetch_eff = 'qqq_adjusted_close_pct_change'
                _auto_adj_eff = True
                _div_eff = True
            elif 'proxy' in _ndx_src:
                _src_eff = 'proxy'
                _fetch_eff = f'proxy_fallback({_ndx_src})'
                _auto_adj_eff = False
                _div_eff = False

        _s = pd.to_numeric(df[_col], errors='coerce')
        _finite = _s.dropna()
        if len(_finite) == 0:
            continue

        _first = str(_finite.index[0].date())
        _last  = str(_finite.index[-1].date())
        _n     = int(len(_finite))
        _n_mis = int(_s.isna().sum())

        # Large jumps
        _jump_m = _finite.abs() > 0.15
        _n_jmp  = int(_jump_m.sum())
        _jmp_dates = [str(d.date()) for d in _finite[_jump_m].index[:5]]  # cap at 5

        # Checksum — reproducible: sha256 of float64 array rounded to 6 decimal places
        _arr_raw = np.asarray(_finite.values, dtype=np.float64)
        _chk = _hashlib.sha256(np.round(_arr_raw, 6).tobytes()).hexdigest()[:12]
        _chk_note = 'sha256(round(arr, 6).tobytes())[:12]'

        # Calendar gaps
        _col_dates = set(pd.DatetimeIndex(_finite.index).normalize())
        _nyse_iter = _nyse_bdays if (_nyse_bdays is not None and len(_nyse_bdays) > 0) else []
        _col_range = pd.DatetimeIndex([d for d in _nyse_iter
                                        if pd.Timestamp(d) >= pd.Timestamp(_first)
                                        and pd.Timestamp(d) <= pd.Timestamp(_last)])
        _gaps = [str(d.date()) for d in _col_range
                 if d not in _col_dates and d not in _df_idx_set][:5]

        _issues: List[str] = []
        if _n_mis > int(_n * 0.02):
            _issues.append(f'high_NaN({_n_mis})')
        if _n_jmp > 5:
            _issues.append(f'many_jumps({_n_jmp})')
        if len(_gaps) > 2:
            _issues.append(f'cal_gaps({len(_gaps)}+)')

        meta = ReturnSeriesMetadata(
            column=_col, source=_src_eff, fetch_method=_fetch_eff,
            auto_adjust=_auto_adj_eff, dividend_included=_div_eff,
            first_date=_first, last_date=_last, n_days=_n,
            n_missing=_n_mis, n_large_jumps=_n_jmp,
            large_jump_dates=_jmp_dates, checksum_hex=_chk,
            checksum_note=_chk_note, calendar_gaps=_gaps, issues=_issues,
        )
        all_meta[_col] = dataclasses.asdict(meta)
        total_issues += len(_issues)

        _flag = '⚠' if _issues else '✓'
        _adj_tag = 'adj✓' if _auto_adj_eff else 'raw'
        print(f"  {_flag} {_col:<25} {_src_eff[:4]:>4} {_adj_tag:<5} {_n:>6,} {_n_mis:>5} {_n_jmp:>6} "
              f"{_chk:>14}  {', '.join(_issues) if _issues else 'OK'}")

    print(f"  {'─'*72}")
    print(f"  Total issues: {total_issues}  |  Columns scanned: {len(all_meta)}")

    # Persist alongside historical_data.pkl — includes full provenance for audit
    try:
        import json as _json, datetime as _dt
        _qa_path = CACHE_DIR / 'data_qa_report.json'
        _report_payload = {
            'generated': _dt.datetime.now().isoformat(),
            'engine_version': 'v1.6',
            'cache_model_version': CACHE_MODEL_VERSION,
            'df_start': str(df.index[0].date()),
            'df_end':   str(df.index[-1].date()),
            'df_rows':  int(len(df)),
            'total_issues': total_issues,
            'fetch_provenance': {
                'etf_returns': 'yfinance(auto_adjust=True): Close IS total-return adjusted price',
                'auto_adjust_note': (
                    'With auto_adjust=True, the Close column is dividend-and-split adjusted. '
                    'pct_change(Close) gives total return. No separate div_yield adjustment needed.'
                ),
                'index_returns': (
                    'yfinance(auto_adjust=True): price-return only for ^NDX/^SPX unless a dedicated '
                    'Nasdaq-100 total-return series is present and labeled NDXT_real'
                ),
            },
            'columns': all_meta,
        }
        with open(_qa_path, 'w') as _qf:
            _json.dump(_report_payload, _qf, indent=2)
        print(f"  Report saved → {_qa_path}  (includes fetch_provenance + auto_adjust annotation)")
    except Exception:
        pass

    return {'total_issues': total_issues, 'columns': all_meta}


def export_validation_metadata(
        canonical_hash: Optional[str],
        driver_return_hash: Optional[str],
        validation_pass: Optional[bool],
        output_path: str = 'validation_metadata.json',
        driver_return_hash_n: Optional[int] = None,
        driver_return_hash_date_start: Optional[str] = None,
        driver_return_hash_date_end: Optional[str] = None,
        engine_code_hash: Optional[str] = None,
) -> Dict[str, Any]:
    """
    PART 5 — Audit metadata export.

    Saves a machine-readable JSON audit record containing:
      - canonical_hash              : SHA-256 prefix of the frozen canonical dataset
      - driver_return_hash          : SHA-256 of the driver return series (SPY basis)
      - driver_return_hash_n        : Row count of the hashed series
      - driver_return_hash_date_start : First date in the hashed window
      - driver_return_hash_date_end   : Last date in the hashed window
      - engine_code_hash            : SHA-256[:16] of this source file at import time
      - validation_pass             : True / False / None (None = not yet evaluated)
      - timestamp                   : ISO-8601 UTC timestamp of the export
      - python_version              : sys.version string

    Called twice per run:
      1. Pre-validation (validation_pass=None) from generate_validation_snapshot.
      2. Post-validation (validation_pass=True/False) from the main() try/finally block.
         The second write always executes even if validation crashes, so the file never
         lies with an optimistic None when an actual failure occurred.

    Parameters
    ----------
    canonical_hash : str or None
    driver_return_hash : str or None
    validation_pass : bool or None
    output_path : str
    driver_return_hash_n : int or None
    driver_return_hash_date_start : str or None  (ISO date)
    driver_return_hash_date_end   : str or None  (ISO date)
    engine_code_hash : str or None
    """
    import json as _meta_json, sys as _meta_sys, datetime as _meta_dt, pathlib as _meta_pl

    metadata: Dict[str, Any] = {
        'canonical_hash':               canonical_hash,
        'driver_return_hash':           driver_return_hash,
        'driver_return_hash_n':         driver_return_hash_n,
        'driver_return_hash_date_start': driver_return_hash_date_start,
        'driver_return_hash_date_end':   driver_return_hash_date_end,
        'engine_code_hash':             engine_code_hash,
        'validation_pass':              validation_pass,
        'timestamp':                    _meta_dt.datetime.utcnow().isoformat() + 'Z',
        'python_version':               _meta_sys.version,
    }

    _out = _meta_pl.Path(output_path)
    _out.parent.mkdir(parents=True, exist_ok=True)
    with open(_out, 'w') as _mf:
        _meta_json.dump(metadata, _mf, indent=2, sort_keys=True)

    print(f"  [validation_metadata] Saved → {_out}")
    print(f"    canonical_hash    : {canonical_hash or 'n/a'}")
    print(f"    driver_return_hash: {(driver_return_hash or 'n/a')[:32]}{'...' if driver_return_hash else ''}")
    if driver_return_hash_n is not None:
        print(f"    hash_n/dates      : n={driver_return_hash_n:,}  "
              f"{driver_return_hash_date_start}→{driver_return_hash_date_end}")
    print(f"    engine_code_hash  : {engine_code_hash or 'n/a'}")
    print(f"    validation_pass   : {validation_pass}")
    print(f"    timestamp         : {metadata['timestamp']}")
    return metadata


def generate_validation_snapshot(
        df: pd.DataFrame,
        tracking_model: Optional[Dict] = None,
        rf_daily: Optional[np.ndarray] = None,
        output_path: str = 'validation_snapshots/v2.1_reference.json',
        funds: Optional[List[str]] = None,
) -> Dict[str, Any]:
    """
    Generate a frozen validation snapshot capturing per-asset OOS metrics
    (INSTITUTIONAL_GATE, 2015-2024 window) and per-WF-block metrics.

    Used as the reference for T12 silent-regression detection.

    Content of snapshot JSON:
      - generated, cache_model_version, commit_hash
      - assets: per-asset cagr_diff, te_ann, tw_rel_err, mdd_diff, beta, data_checksum
      - walkforward: per-asset per-block mean_err_ann, te_ann, tw_rel_err, mdd_diff

    Run this once to create the reference, then T12 in regression tests will compare
    future runs against it.
    """
    import json as _json, datetime as _dt, subprocess as _sp, pathlib as _pl

    if funds is None:
        funds = ['UPRO', 'SSO', 'TQQQ', 'QLD']

    # PART 10 — Canonical data protection:
    # If the canonical frozen dataset exists, load and use it instead of the live df
    # parameter.  This ensures snapshot reproducibility: the snapshot reflects the
    # frozen canonical data, not live Yahoo Finance data which changes every run.
    _canon_df = load_canonical_dataset('data/canonical')
    _canonical_hash: Optional[str] = None
    if _canon_df is not None:
        import hashlib as _hl_canon
        _canonical_hash = _hl_canon.sha256(
            pd.util.hash_pandas_object(_canon_df, index=True).values.tobytes()
        ).hexdigest()[:16]
        # Loud canonical-override line so callers can never miss it
        print(f"  [snapshot] USING CANONICAL DATASET (parquet hash={_canonical_hash})"
              f" — ignoring provided df")
        df = _canon_df
    else:
        print("  [snapshot] WARNING: No canonical dataset found at data/canonical — "
              "using live df (results may differ across runs; run letf_finalize.py first)")

    if rf_daily is None:
        try:
            rf_daily, _ = _load_daily_financing_rate_aligned(df)
        except Exception:
            rf_daily = np.zeros(len(df), dtype=np.float64)

    if tracking_model is None:
        tracking_model = load_cache(TRACKING_RESIDUAL_CACHE)
        if not isinstance(tracking_model, dict):
            tracking_model = {}

    # Get commit hash for provenance
    try:
        commit_hash = _sp.check_output(
            ['git', 'rev-parse', '--short', 'HEAD'], stderr=_sp.DEVNULL
        ).decode().strip()
    except Exception:
        commit_hash = 'unknown'

    # Data checksums from QA report
    qa_report = build_data_qa_report(df)
    data_checksums = {}
    for col, meta in qa_report.get('columns', {}).items():
        if isinstance(meta, dict):
            data_checksums[col] = str(meta.get('checksum', ''))

    # PART 2 — Driver-return reproducibility hash for snapshot metadata.
    # Compute SHA-256 of the driver return column so the snapshot pins the exact
    # driver series in use at generation time.  Future runs can verify match.
    import hashlib as _snap_hl
    _driver_return_hash_snap: Optional[str] = None
    _driver_hash_col_snap = None
    for _dc in ('SPY_Ret_RealOnly', 'SPY_Ret', 'SPY_Real_Ret'):
        if _dc in df.columns:
            _driver_hash_col_snap = _dc
            break
    _driver_hash_n_snap: Optional[int] = None
    _driver_hash_date_start_snap: Optional[str] = None
    _driver_hash_date_end_snap: Optional[str] = None
    if _driver_hash_col_snap is not None:
        # Force C-contiguous float64 — same policy as validate_driver_total_return_basis —
        # so snapshot hashes are byte-for-byte comparable across runs.
        _dv = np.ascontiguousarray(
            pd.to_numeric(df[_driver_hash_col_snap], errors='coerce').fillna(0.0).to_numpy(dtype=np.float64)
        )
        _driver_return_hash_snap = _snap_hl.sha256(_dv.tobytes()).hexdigest()
        _driver_hash_n_snap = len(_dv)
        _driver_hash_date_start_snap = str(pd.Timestamp(df.index[0]).date()) if len(df) > 0 else None
        _driver_hash_date_end_snap   = str(pd.Timestamp(df.index[-1]).date()) if len(df) > 0 else None
        print(f"  [snapshot] driver_return_hash col={_driver_hash_col_snap} "
              f"n={_driver_hash_n_snap:,} dates={_driver_hash_date_start_snap}→{_driver_hash_date_end_snap} "
              f"sha256={_driver_return_hash_snap[:32]}...")

    snap: Dict[str, Any] = {
        'generated': _dt.datetime.now().isoformat(),
        'cache_model_version': str(CACHE_MODEL_VERSION),
        'commit_hash': commit_hash,
        'output_path': output_path,
        'canonical_hash': _canonical_hash,  # None when live df used; non-None means frozen data
        'driver_return_hash': _driver_return_hash_snap,  # SHA-256 of driver return series
        'driver_return_hash_col': _driver_hash_col_snap,
        'driver_return_hash_n': _driver_hash_n_snap,           # row count hashed
        'driver_return_hash_date_start': _driver_hash_date_start_snap,  # date window start
        'driver_return_hash_date_end': _driver_hash_date_end_snap,      # date window end
        'assets': {},
        'walkforward': {},
        'data_checksums': data_checksums,
    }

    val_start = '2015-01-01'
    val_end = None  # use full available data

    for fund in funds:
        real_col = f'{fund}_Real_Ret'
        if real_col not in df.columns:
            print(f"  [snapshot] {fund}: skipping — {real_col} not in df")
            continue

        print(f"  [snapshot] Computing OOS metrics for {fund} ...")
        try:
            # OOS reconstruction 2015-present
            train_end_snap = '2014-12-31'
            oos_result = validate_letf_emulator_oos(
                df=df,
                regime_model={},
                fund=fund,
                train_end=train_end_snap,
                val_start=val_start,
                val_end=val_end,
                n_sims=1,
                mode=ValidationMode.INSTITUTIONAL_GATE,
            )
            m = oos_result.get('metrics', {})
            snap['assets'][fund] = {
                'cagr_diff': float(m.get('cagr_diff_abs', np.nan)),
                'te_ann': float(m.get('tracking_error_ann', np.nan)),
                'tw_rel_err': float(m.get('terminal_wealth_rel_err', np.nan)),
                'mdd_diff': float(m.get('max_drawdown_diff_abs', np.nan)),
                'beta': float(m.get('beta', np.nan)),
                'data_checksum': data_checksums.get(real_col, ''),
            }
        except Exception as _e:
            print(f"  [snapshot] {fund} OOS error: {_e}")
            snap['assets'][fund] = {'error': str(_e)}

        try:
            # Walk-forward blocks
            wf_result = validate_letf_emulator_walkforward(
                df=df,
                fund=fund,
                mode=ValidationMode.INSTITUTIONAL_GATE,
            )
            wf_blocks = []
            for b in wf_result.get('blocks', []):
                if b.get('skipped'):
                    continue
                wf_blocks.append({
                    'window_label': b.get('window_label', ''),
                    'val_start': b.get('val_start', ''),
                    'val_end': b.get('val_end', ''),
                    'mean_err_ann': float(b.get('mean_err_ann', np.nan)),
                    'te_ann': float(b.get('te_ann', np.nan)),
                    'tw_rel_err': float(b.get('tw_rel_err', np.nan)),
                    'mdd_diff': float(b.get('mdd_diff', np.nan)),
                })
            snap['walkforward'][fund] = wf_blocks
        except Exception as _e:
            print(f"  [snapshot] {fund} WF error: {_e}")
            snap['walkforward'][fund] = []

    # Compute a deterministic content hash (excludes volatile fields: generated, commit_hash, output_path)
    # This hash is stable across runs on the same data and will be equal byte-for-byte.
    _hashable = {
        'cache_model_version': snap['cache_model_version'],
        'assets': snap['assets'],
        'walkforward': snap['walkforward'],
        'data_checksums': snap['data_checksums'],
    }
    import hashlib as _hl
    _content_json = _json.dumps(_hashable, sort_keys=True, indent=None,
                                default=lambda x: None if (isinstance(x, float) and np.isnan(x)) else x)
    snap['content_hash'] = _hl.sha256(_content_json.encode('utf-8')).hexdigest()

    # Save — use sort_keys=True so key order is deterministic across Python versions/dict insertions
    _out_path = _pl.Path(output_path)
    _out_path.parent.mkdir(parents=True, exist_ok=True)
    with open(_out_path, 'w') as _f:
        _json.dump(snap, _f, indent=2, sort_keys=True,
                   default=lambda x: None if (isinstance(x, float) and np.isnan(x)) else x)
    print(f"\n  [snapshot] Saved to {_out_path}")
    print(f"  [snapshot] Content hash: {snap['content_hash']}")
    snap['output_path'] = str(_out_path)

    # PART 5 — Export audit metadata alongside the snapshot.
    # Writes a pre-validation record (validation_pass=None).
    # The main() try/finally block will overwrite this with the final verdict.
    try:
        export_validation_metadata(
            canonical_hash=snap.get('canonical_hash'),
            driver_return_hash=snap.get('driver_return_hash'),
            validation_pass=None,  # overwritten after full validation completes
            driver_return_hash_n=snap.get('driver_return_hash_n'),
            driver_return_hash_date_start=snap.get('driver_return_hash_date_start'),
            driver_return_hash_date_end=snap.get('driver_return_hash_date_end'),
            engine_code_hash=ENGINE_CODE_HASH,
        )
    except Exception as _meta_err:
        print(f"  [snapshot] ⚠ validation_metadata export error: {_meta_err!r}")

    return snap


def load_validation_snapshot(
        path: str = 'validation_snapshots/v2.1_reference.json',
) -> Optional[Dict[str, Any]]:
    """
    Load a validation snapshot generated by generate_validation_snapshot.
    Returns None (no exception) if file does not exist.
    """
    import json as _json, pathlib as _pl
    _p = _pl.Path(path)
    if not _p.exists():
        return None
    try:
        with open(_p, 'r') as _f:
            return _json.load(_f)
    except Exception:
        return None


def save_canonical_dataset(
        df: pd.DataFrame,
        output_dir: str = 'data/canonical',
        rf_daily: Optional[np.ndarray] = None,
) -> Dict[str, Any]:
    """
    Save a frozen canonical dataset for reproducible validation runs.

    Columns saved:
      SPY_Ret, QQQ_Ret, SPY_Ret_RealOnly, QQQ_Ret_RealOnly,
      NDX_Ret_RealOnly, UPRO_Real_Ret, SSO_Real_Ret, TQQQ_Real_Ret, QLD_Real_Ret,
      RF_daily (Fama-French daily RF for reproducible calibration)

    Saves as parquet (pyarrow) with pickle fallback.
    Saves canonical_metadata.json with checksums from build_data_qa_report.

    Note: These are utilities; validation does NOT auto-switch to canonical.
    User explicitly calls them for frozen-data validation runs.
    """
    import json as _json, datetime as _dt, pathlib as _pl

    _out = _pl.Path(output_dir)
    _out.mkdir(parents=True, exist_ok=True)

    _cols = [
        'SPY_Ret', 'QQQ_Ret', 'SPY_Ret_RealOnly', 'QQQ_Ret_RealOnly',
        'NDX_Ret_RealOnly', 'UPRO_Real_Ret', 'SSO_Real_Ret', 'TQQQ_Real_Ret', 'QLD_Real_Ret',
        'VIX',   # required by emulator OOS/WF validation (regime classification threshold)
        'UPRO_IsSynthetic', 'SSO_IsSynthetic', 'TQQQ_IsSynthetic', 'QLD_IsSynthetic',
    ]
    present_cols = [c for c in _cols if c in df.columns]
    canon_df = df[present_cols].copy()

    # Attach RF as a column
    if rf_daily is None:
        try:
            rf_daily, _ = _load_daily_financing_rate_aligned(df)
        except Exception:
            rf_daily = np.zeros(len(df), dtype=np.float64)
    rf_arr = np.asarray(rf_daily, dtype=np.float64)
    if len(rf_arr) == len(canon_df):
        canon_df['RF_daily'] = rf_arr
    else:
        canon_df['RF_daily'] = np.nan

    # Save dataframe
    saved_format = 'unknown'
    try:
        pq_path = _out / 'canonical_data.parquet'
        canon_df.to_parquet(str(pq_path), engine='pyarrow')
        saved_format = 'parquet'
        print(f"  [canonical] Saved parquet → {pq_path}")
    except Exception:
        pkl_path = _out / 'canonical_data.pkl'
        import pickle as _pkl
        with open(pkl_path, 'wb') as _pf:
            _pkl.dump(canon_df, _pf, protocol=4)
        saved_format = 'pickle'
        print(f"  [canonical] Saved pickle (parquet failed) → {pkl_path}")

    # Save metadata + checksums
    qa_report = build_data_qa_report(df)
    meta = {
        'generated': _dt.datetime.now().isoformat(),
        'cache_model_version': str(CACHE_MODEL_VERSION),
        'df_start': str(df.index[0].date()),
        'df_end': str(df.index[-1].date()),
        'n_rows': int(len(canon_df)),
        'columns': list(canon_df.columns),
        'saved_format': saved_format,
        'checksums': {col: str(m.get('checksum', '')) for col, m in qa_report.get('columns', {}).items() if isinstance(m, dict)},
    }
    meta_path = _out / 'canonical_metadata.json'
    with open(meta_path, 'w') as _mf:
        _json.dump(meta, _mf, indent=2)
    print(f"  [canonical] Metadata → {meta_path}")

    return {'status': 'saved', 'format': saved_format, 'output_dir': str(_out), 'columns': list(canon_df.columns), 'n_rows': int(len(canon_df))}


def load_canonical_dataset(
        input_dir: str = 'data/canonical',
) -> Optional[pd.DataFrame]:
    """
    Load and verify the canonical dataset saved by save_canonical_dataset.
    Verifies checksums against current df checksums from metadata.
    Returns merged DataFrame or None if not found.
    """
    import json as _json, pathlib as _pl

    _inp = _pl.Path(input_dir)
    meta_path = _inp / 'canonical_metadata.json'

    if not meta_path.exists():
        print(f"  [canonical] No metadata at {meta_path} — canonical dataset not found.")
        return None

    with open(meta_path, 'r') as _mf:
        meta = _json.load(_mf)

    canon_df = None
    pq_path = _inp / 'canonical_data.parquet'
    pkl_path = _inp / 'canonical_data.pkl'

    if pq_path.exists():
        try:
            canon_df = pd.read_parquet(str(pq_path), engine='pyarrow')
            print(f"  [canonical] Loaded parquet ({len(canon_df):,} rows)")
        except Exception as _e:
            print(f"  [canonical] Parquet load failed: {_e}")

    if canon_df is None and pkl_path.exists():
        try:
            import pickle as _pkl
            with open(pkl_path, 'rb') as _pf:
                canon_df = _pkl.load(_pf)
            print(f"  [canonical] Loaded pickle ({len(canon_df):,} rows)")
        except Exception as _e:
            print(f"  [canonical] Pickle load failed: {_e}")

    if canon_df is None:
        print(f"  [canonical] No canonical data files found in {_inp}")
        return None

    print(f"  [canonical] Loaded: {len(canon_df):,} rows, {len(canon_df.columns)} columns")
    print(f"  [canonical] Date range: {canon_df.index[0].date()} → {canon_df.index[-1].date()}")
    return canon_df


def validate_reconstruction_determinism(
        regime_model: Dict,
        correlation_matrices: Dict,
        window_start: str,
        window_end: str,
        horizon_years: float = 10.0,
) -> Dict[str, Any]:
    """
    Run the historical reconstruction path (sim_id=0) twice and assert all
    numerical result-dict fields are identical.

    A non-zero max_diff indicates residual randomness in the reconstruction
    pipeline (e.g. stochastic TE still active, tail-events not disabled, or
    circuit breakers producing different outcomes).

    The test is lightweight: a single path takes < 1 s.  The comparison covers
    all float-valued keys in the result dict (CAGR, Max_DD, Final_Wealth, etc.).

    Returns:
        {'pass': bool, 'max_diff': float, 'n_fields': int, 'details': str}
    """
    print("\n  F. RECONSTRUCTION DETERMINISM TEST")

    if MARKET_SCENARIO != 'historical_backtest':
        msg = f'skipped (MARKET_SCENARIO={MARKET_SCENARIO!r}, not historical_backtest)'
        print(f"  {msg}")
        return {'pass': True, 'max_diff': 0.0, 'n_fields': 0, 'details': msg}

    # We need a strategy list; use all defined strategy IDs (first few are stable).
    from copy import deepcopy as _dc
    _rm1 = _dc(regime_model)
    _rm2 = _dc(regime_model)
    _cm1 = _dc(correlation_matrices)
    _cm2 = _dc(correlation_matrices)

    # Use a minimal set of strategies to keep the test fast.
    _test_strategies = ['S1', 'S2', 'S3']  # SPY Roth + QQQ Roth + basic bond

    args1 = (0, float(horizon_years), _rm1, _cm1, _test_strategies)
    args2 = (0, float(horizon_years), _rm2, _cm2, _test_strategies)

    try:
        _r1 = simulate_single_path_fixed(args1)
        _r2 = simulate_single_path_fixed(args2)
    except Exception as _e:
        msg = f'exception during path simulation: {_e}'
        print(f"  ⚠ FAIL — {msg}")
        return {'pass': False, 'max_diff': float('nan'), 'n_fields': 0, 'details': msg}

    # Compare all float fields across all strategies present in both results.
    diffs: Dict[str, float] = {}
    for _sid in _test_strategies:
        _d1 = _r1.get(_sid, {})
        _d2 = _r2.get(_sid, {})
        if not isinstance(_d1, dict) or not isinstance(_d2, dict):
            continue
        for _key in _d1:
            _v1 = _d1.get(_key)
            _v2 = _d2.get(_key)
            if isinstance(_v1, float) and isinstance(_v2, float):
                if np.isnan(_v1) and np.isnan(_v2):
                    continue   # both NaN → identical, no diff
                diff = abs(_v1 - _v2)
                diffs[f'{_sid}.{_key}'] = diff
            elif isinstance(_v1, int) and isinstance(_v2, int):
                diffs[f'{_sid}.{_key}'] = float(abs(_v1 - _v2))

    max_diff = max(diffs.values()) if diffs else 0.0
    passed = (max_diff == 0.0)

    if passed:
        details = f'PASS — {len(diffs)} fields compared, max_diff=0.0 (fully deterministic)'
        print(f"  ✓ {details}")
    else:
        failing = sorted(
            ((k, v) for k, v in diffs.items() if v > 0),
            key=lambda x: -x[1]
        )
        details = f'FAIL — {len(failing)} fields differ'
        print(f"  ⚠ {details}:")
        for _k, _v in failing[:8]:
            print(f"    {_k}: diff={_v:.3e}")
        if len(failing) > 8:
            print(f"    ... and {len(failing) - 8} more")

    return {
        'pass': passed,
        'max_diff': float(max_diff),
        'n_fields': len(diffs),
        'details': details,
    }


def _cagr_from_returns(ret: np.ndarray) -> float:
    arr = np.asarray(ret, dtype=np.float64)
    if len(arr) < 2:
        return float('nan')
    years = float(len(arr) / 252.0)
    if years <= 0:
        return float('nan')
    growth = float(np.prod(1.0 + arr))
    if growth <= 0.0:
        return float('nan')
    return float(growth ** (1.0 / years) - 1.0)


def _count_drawdown_episodes(returns: np.ndarray, threshold: float = 0.20) -> int:
    """
    Count drawdown episodes where DD crosses above `threshold`.
    """
    arr = np.asarray(returns, dtype=np.float64)
    if len(arr) == 0:
        return 0
    wealth = np.cumprod(1.0 + arr)
    peak = np.maximum.accumulate(wealth)
    dd = 1.0 - wealth / np.maximum(peak, 1e-12)
    in_event = dd >= float(threshold)
    starts = int(np.sum((~in_event[:-1]) & in_event[1:])) if len(in_event) > 1 else 0
    if bool(in_event[0]):
        starts += 1
    return int(starts)


def print_historical_bootstrap_diagnostics(
        hist_data: Optional[Dict[str, np.ndarray]] = None,
        block_size: int = 63,
        bootstrap_seed: Optional[int] = None,
        bootstrap_method: str = 'fixed',
        stationary_p: Optional[float] = None,
        n_test_paths: int = 20,
) -> Dict[str, Any]:
    """
    Print bootstrap realism diagnostics versus the original selected window.
    Metrics: mean CAGR, mean annualised vol, mean max drawdown.
    """
    if hist_data is None:
        hist_data = _slice_hist1926_to_window(
            ANALYSIS_START_DATE, ANALYSIS_END_DATE, min_days=2
        )
    if hist_data is None:
        msg = "skipped — selected historical window unavailable."
        print(f"  [bootstrap diagnostics] {msg}")
        return {'status': 'skipped', 'reason': msg}

    n_days = int(hist_data.get('N', 0))
    if n_days < 2:
        msg = f"skipped — insufficient window length (N={n_days})."
        print(f"  [bootstrap diagnostics] {msg}")
        return {'status': 'skipped', 'reason': msg}

    src_spy = np.asarray(hist_data['SPY_Ret'], dtype=np.float64)
    src_cagr = _cagr_from_returns(src_spy)
    src_vol = float(src_spy.std() * np.sqrt(252))
    src_mdd = float(abs(_max_drawdown_from_returns(src_spy)))

    rng_diag = np.random.default_rng(13579)
    cagr_list: list = []
    vol_list: list = []
    mdd_list: list = []
    for i in range(int(n_test_paths)):
        p = _get_historical_path_returns(
            path_idx=i,
            n_paths=max(1, int(n_test_paths)),
            n_days=n_days,
            mode='bootstrap',
            block_size=int(block_size),
            rng=rng_diag,
            hist_data=hist_data,
            bootstrap_seed=bootstrap_seed,
            bootstrap_method=bootstrap_method,
            stationary_p=stationary_p,
        )
        spy = np.asarray(p['SPY_Ret'], dtype=np.float64)
        cagr_list.append(float(_cagr_from_returns(spy)))
        vol_list.append(float(spy.std() * np.sqrt(252)))
        mdd_list.append(float(abs(_max_drawdown_from_returns(spy))))

    mean_cagr = float(np.nanmean(cagr_list))
    mean_vol = float(np.nanmean(vol_list))
    mean_mdd = float(np.nanmean(mdd_list))

    print("\n  BOOTSTRAP DIAGNOSTICS (selected window vs bootstrap paths)")
    print(f"  Window : {hist_data.get('dates_start')} → {hist_data.get('dates_end')}  ({n_days:,} days)")
    print(f"  CAGR   : source={src_cagr*100:.2f}%   bootstrap_mean={mean_cagr*100:.2f}%")
    print(f"  Vol    : source={src_vol*100:.2f}%   bootstrap_mean={mean_vol*100:.2f}%")
    print(f"  Max DD : source={src_mdd*100:.2f}%   bootstrap_mean={mean_mdd*100:.2f}%")

    return {
        'status': 'ok',
        'window_start': hist_data.get('dates_start'),
        'window_end': hist_data.get('dates_end'),
        'n_days': n_days,
        'source': {'cagr': src_cagr, 'vol': src_vol, 'max_drawdown': src_mdd},
        'bootstrap_mean': {'cagr': mean_cagr, 'vol': mean_vol, 'max_drawdown': mean_mdd},
        'bootstrap_seed': bootstrap_seed,
        'bootstrap_method': str(bootstrap_method),
        'stationary_p': (float(stationary_p) if stationary_p is not None else None),
        'n_test_paths': int(n_test_paths),
    }


def validate_bootstrap_integrity(
        hist_data: Optional[Dict[str, np.ndarray]] = None,
        n_test_paths: int = 20,
        horizon_years: float = 10.0,
        block_size: int = 63,
        bootstrap_seed: Optional[int] = None,
        bootstrap_method: str = 'fixed',
        stationary_p: Optional[float] = None,
) -> Dict[str, Any]:
    """
    Required integrity checks for historical bootstrap:
      1) Every sampled bootstrap value exists in historical driver arrays.
      2) Bootstrap annualised vol is within ±5% (relative) of source vol.
      3) Bootstrap max drawdown is non-zero.
      4) Borrowing-rate index alignment is exact for every sampled day.
    """
    if hist_data is None:
        hist_data = _slice_hist1926_to_window(
            ANALYSIS_START_DATE, ANALYSIS_END_DATE, min_days=2
        )
    if hist_data is None:
        return {
            'overall_pass': False,
            'status': 'skipped',
            'reason': 'selected window unavailable for bootstrap integrity check',
        }

    n_days = max(2, int(horizon_years * 252))
    src_spy = np.asarray(hist_data['SPY_Ret'], dtype=np.float64)
    src_qqq = np.asarray(hist_data['QQQ_Ret'], dtype=np.float64)
    src_tlt = np.asarray(hist_data['TLT_Ret'], dtype=np.float64)
    src_irx = np.asarray(hist_data['IRX'], dtype=np.float64)

    source_sets = {
        'SPY_Ret': set(np.round(src_spy, 8).tolist()),
        'QQQ_Ret': set(np.round(src_qqq, 8).tolist()),
        'TLT_Ret': set(np.round(src_tlt, 8).tolist()),
        'IRX': set(np.round(src_irx, 8).tolist()),
    }

    rng_chk = np.random.default_rng(24680)
    missing_count = 0
    checked_total = 0
    vols: list = []
    mdds: list = []
    alignment_pass = True

    for i in range(int(n_test_paths)):
        p = _get_historical_path_returns(
            path_idx=i,
            n_paths=max(1, int(n_test_paths)),
            n_days=n_days,
            mode='bootstrap',
            block_size=int(block_size),
            rng=rng_chk,
            hist_data=hist_data,
            bootstrap_seed=bootstrap_seed,
            bootstrap_method=bootstrap_method,
            stationary_p=stationary_p,
        )

        for k in ('SPY_Ret', 'QQQ_Ret', 'TLT_Ret', 'IRX'):
            vals = np.round(np.asarray(p[k], dtype=np.float64), 8).tolist()
            checked_total += len(vals)
            _set = source_sets[k]
            missing_count += int(sum(1 for v in vals if v not in _set))

        ret_idx = np.asarray(p.get('_sampled_return_indices', []), dtype=np.int64)
        rf_idx = np.asarray(p.get('_sampled_rf_indices', []), dtype=np.int64)
        _aligned = bool(np.array_equal(ret_idx, rf_idx))
        alignment_pass = alignment_pass and _aligned
        assert _aligned, "Borrowing-rate alignment failed: sampled_RF_index != sampled_return_index"

        spy = np.asarray(p['SPY_Ret'], dtype=np.float64)
        vols.append(float(spy.std() * np.sqrt(252)))
        mdds.append(float(abs(_max_drawdown_from_returns(spy))))

    source_vol = float(src_spy.std() * np.sqrt(252))
    bootstrap_vol = float(np.mean(vols)) if vols else float('nan')
    if source_vol > 0:
        vol_rel_diff = float(abs(bootstrap_vol / source_vol - 1.0))
    else:
        vol_rel_diff = float('inf')
    vol_pass = bool(vol_rel_diff <= 0.05)
    drawdown_nonzero = bool(all(mdd > 0.0 for mdd in mdds))
    returns_exist_pass = bool(missing_count == 0)

    out = {
        'returns_in_driver_set': {
            'pass': returns_exist_pass,
            'n_missing': int(missing_count),
            'n_checked': int(checked_total),
        },
        'volatility_fidelity': {
            'pass': vol_pass,
            'source_vol': source_vol,
            'bootstrap_vol': bootstrap_vol,
            'relative_diff': vol_rel_diff,
            'tolerance': 0.05,
        },
        'drawdown_nonzero': {
            'pass': drawdown_nonzero,
            'mean_mdd': float(np.mean(mdds)) if mdds else float('nan'),
            'min_mdd': float(np.min(mdds)) if mdds else float('nan'),
        },
        'rf_alignment': {
            'pass': alignment_pass,
            'assertion': 'sampled_RF_index == sampled_return_index',
        },
    }
    out['overall_pass'] = bool(
        out['returns_in_driver_set']['pass']
        and out['volatility_fidelity']['pass']
        and out['drawdown_nonzero']['pass']
        and out['rf_alignment']['pass']
    )
    out['bootstrap_method'] = str(bootstrap_method)
    out['stationary_p'] = float(stationary_p) if stationary_p is not None else None
    out['status'] = 'pass' if out['overall_pass'] else 'fail'
    return out


def validate_bootstrap_regime_frequency(
        hist_data: Dict[str, np.ndarray],
        n_test_paths: int = 20,
        block_size: int = 63,
        bootstrap_seed: Optional[int] = None,
        bootstrap_method: str = 'fixed',
        stationary_p: Optional[float] = None,
        horizon_years: float = 50.0,
        drawdown_threshold: float = 0.20,
        tolerance_rel: float = 0.35,
) -> Dict[str, Any]:
    """
    Validate crisis-frequency preservation using drawdown-episode counts.
    Metric: number of drawdown episodes >= `drawdown_threshold` per 50 years.
    """
    src = np.asarray(hist_data['SPY_Ret'], dtype=np.float64)
    src_years = max(len(src) / 252.0, 1e-9)
    src_episodes = _count_drawdown_episodes(src, threshold=drawdown_threshold)
    src_per_50y = float(src_episodes / src_years * 50.0)

    n_days = max(2, int(horizon_years * 252))
    rng_rf = np.random.default_rng(97531)
    counts_50y: list = []
    for i in range(int(n_test_paths)):
        p = _get_historical_path_returns(
            path_idx=i,
            n_paths=max(1, int(n_test_paths)),
            n_days=n_days,
            mode='bootstrap',
            block_size=int(block_size),
            rng=rng_rf,
            hist_data=hist_data,
            bootstrap_seed=bootstrap_seed,
            bootstrap_method=bootstrap_method,
            stationary_p=stationary_p,
        )
        spy = np.asarray(p['SPY_Ret'], dtype=np.float64)
        ep = _count_drawdown_episodes(spy, threshold=drawdown_threshold)
        yrs = max(len(spy) / 252.0, 1e-9)
        counts_50y.append(float(ep / yrs * 50.0))

    boot_mean = float(np.mean(counts_50y)) if counts_50y else float('nan')
    if src_per_50y > 0:
        rel_diff = float(abs(boot_mean / src_per_50y - 1.0))
        passed = bool(rel_diff <= tolerance_rel)
    else:
        rel_diff = float(abs(boot_mean - src_per_50y))
        passed = bool(rel_diff <= 1.0)

    return {
        'pass': passed,
        'source_episodes_per_50y': src_per_50y,
        'bootstrap_mean_episodes_per_50y': boot_mean,
        'relative_diff': rel_diff,
        'tolerance_rel': float(tolerance_rel),
        'drawdown_threshold': float(drawdown_threshold),
        'details': (
            f"PASS — source={src_per_50y:.2f}, bootstrap_mean={boot_mean:.2f} episodes per 50y"
            if passed else
            f"FAIL — source={src_per_50y:.2f}, bootstrap_mean={boot_mean:.2f} episodes per 50y"
        ),
    }


def validate_historical_bootstrap(
        n_test_paths: int = 20,
        horizon_years: float = 10.0,
        block_size: int = 63,
        bootstrap_seed: Optional[int] = None,
        bootstrap_method: str = 'fixed',
        stationary_p: Optional[float] = None,
        start_date: Optional[str] = None,
        end_date: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Validation suite for historical bootstrap using the selected analysis window.
    """
    _start = str(start_date or ANALYSIS_START_DATE)
    _end = str(end_date or ANALYSIS_END_DATE)

    print(f"\n{'='*80}")
    print("HISTORICAL BOOTSTRAP VALIDATION SUITE")
    print(f"  Window: {_start} → {_end}")
    print(f"  Test  : {n_test_paths} bootstrap paths × {horizon_years:.0f} yr @ {block_size}-day blocks")
    print(f"  Method: {bootstrap_method}")
    if str(bootstrap_method).strip().lower() == 'stationary':
        _p_disp = float(stationary_p) if stationary_p is not None else (1.0 / max(int(block_size), 1))
        print(f"  Stationary p(restart): {_p_disp:.6f}")
    if bootstrap_seed is not None:
        print(f"  Seed  : {bootstrap_seed}")
    print(f"{'='*80}")

    results: Dict[str, Any] = {}
    window_data = _slice_hist1926_to_window(_start, _end, min_days=2)
    if window_data is None:
        msg = f"skipped — unable to slice selected window [{_start}, {_end}]"
        print(f"  ⚠  {msg}")
        return {'status': 'skipped', 'reason': msg, 'overall_pass': False}

    results['diagnostics'] = print_historical_bootstrap_diagnostics(
        hist_data=window_data,
        block_size=block_size,
        bootstrap_seed=bootstrap_seed,
        bootstrap_method=bootstrap_method,
        stationary_p=stationary_p,
        n_test_paths=n_test_paths,
    )

    integrity = validate_bootstrap_integrity(
        hist_data=window_data,
        n_test_paths=n_test_paths,
        horizon_years=horizon_years,
        block_size=block_size,
        bootstrap_seed=bootstrap_seed,
        bootstrap_method=bootstrap_method,
        stationary_p=stationary_p,
    )
    results['integrity'] = integrity

    # Keep legacy output keys used in existing reports.
    results['purity'] = {
        'pass': bool(integrity.get('returns_in_driver_set', {}).get('pass', False)),
        'details': (
            "PASS — all bootstrap values exist in selected-window source arrays"
            if integrity.get('returns_in_driver_set', {}).get('pass', False)
            else f"FAIL — missing={integrity.get('returns_in_driver_set', {}).get('n_missing', 'n/a')}"
        ),
    }
    results['vol_fidelity'] = {
        'pass': bool(integrity.get('volatility_fidelity', {}).get('pass', False)),
        'details': (
            f"PASS — rel_diff={integrity.get('volatility_fidelity', {}).get('relative_diff', float('nan'))*100:.2f}%"
            if integrity.get('volatility_fidelity', {}).get('pass', False)
            else f"FAIL — rel_diff={integrity.get('volatility_fidelity', {}).get('relative_diff', float('nan'))*100:.2f}% "
                 f"> 5.00%"
        ),
    }
    results['mdd_sanity'] = {
        'pass': bool(integrity.get('drawdown_nonzero', {}).get('pass', False)),
        'details': (
            f"PASS — min_MDD={integrity.get('drawdown_nonzero', {}).get('min_mdd', float('nan'))*100:.2f}%"
            if integrity.get('drawdown_nonzero', {}).get('pass', False)
            else "FAIL — at least one bootstrap path has zero max drawdown"
        ),
    }
    results['rf_alignment'] = integrity.get('rf_alignment', {})
    results['regime_frequency'] = validate_bootstrap_regime_frequency(
        hist_data=window_data,
        n_test_paths=n_test_paths,
        block_size=block_size,
        bootstrap_seed=bootstrap_seed,
        bootstrap_method=bootstrap_method,
        stationary_p=stationary_p,
        horizon_years=50.0,
        drawdown_threshold=0.20,
    )
    print(f"  {'✓' if results['regime_frequency'].get('pass', False) else '⚠'} "
          f"{results['regime_frequency'].get('details', '')}")

    overall_pass = bool(integrity.get('overall_pass', False))
    print(f"\n  {'='*60}")
    print(f"  HISTORICAL BOOTSTRAP VALIDATION: {'✓ ALL PASS' if overall_pass else '⚠ SOME FAILURES'}")
    print(f"  {'='*60}")
    results['overall_pass'] = overall_pass
    results['status'] = 'pass' if overall_pass else 'fail'
    results['window_start'] = window_data.get('dates_start')
    results['window_end'] = window_data.get('dates_end')
    return results


def compute_historical_drift_anchor(bypass_cache: bool = False) -> float:
    """
    Analytically compute the drift_tilt for 'historical' scenario mode so that
    simulated SPY median CAGR ≈ HISTORICAL_NOMINAL_CAGR_TARGET.

    Method — steady-state weighted log-return approximation:
      CAGR ≈ exp(μ_annual − σ²_annual / 2) − 1   (Ito, 1st-order)
      drift_tilt = target_CAGR − natural_CAGR − div_yield_already_in_overlay

    The mu used here mirrors the crisis drift constraint (mu_crisis ≤ mu_calm * 0.5
    for equity assets) so the anchor is consistent with the post-constraint drift.

    Clipped to [−10%, +10%] to prevent runaway overlays from stale caches.
    Returns the drift_tilt value (stored in _HISTORICAL_DRIFT_ANCHOR).
    """
    global _HISTORICAL_DRIFT_ANCHOR
    if _HISTORICAL_DRIFT_ANCHOR is not None and not bypass_cache:
        return _HISTORICAL_DRIFT_ANCHOR

    jm = load_cache(JOINT_RETURN_MODEL_CACHE)
    rm = load_cache(REGIME_MODEL_CACHE)
    if jm is None or rm is None:
        _HISTORICAL_DRIFT_ANCHOR = 0.0
        return 0.0

    tm  = np.array(rm['transition_matrix'], dtype=float)
    ss1 = tm[0, 1] / (tm[0, 1] + tm[1, 0]) if (tm[0, 1] + tm[1, 0]) > 0 else 0.04
    ss0 = 1.0 - ss1

    r0      = jm['regimes'][0]
    r1      = jm['regimes'][1]
    mu0_spy = float(np.asarray(r0['mu'])[0])
    mu1_raw = float(np.asarray(r1['mu'])[0])
    # Mirror crisis drift constraint: equity crisis mu ≤ mu_calm * 0.5
    mu1_spy = min(mu1_raw, mu0_spy * 0.5)

    mu_daily  = ss0 * mu0_spy + ss1 * mu1_spy
    var_daily = ss0 * float(np.asarray(r0['cov'])[0, 0]) + \
                ss1 * float(np.asarray(r1['cov'])[0, 0])

    mu_annual     = mu_daily * 252
    sigma2_annual = var_daily * 252
    # Log-return → CAGR (arithmetic)
    natural_cagr  = float(np.exp(mu_annual - 0.5 * sigma2_annual) - 1.0)

    # div_yield will be applied separately as an additive overlay in simulation;
    # subtract it from the gap so we don't double-count.
    active_target = float(_HISTORICAL_NOMINAL_CAGR_TARGET_ACTIVE)
    drift_tilt = active_target - natural_cagr - HISTORICAL_DIV_YIELD
    _HISTORICAL_DRIFT_ANCHOR = float(np.clip(drift_tilt, -0.10, +0.10))

    print(f"  [historical anchor] natural_CAGR≈{natural_cagr:.2%}  "
          f"target={active_target:.2%}  "
          f"div_yield={HISTORICAL_DIV_YIELD:.2%}  "
          f"drift_tilt→{_HISTORICAL_DRIFT_ANCHOR:+.2%}")
    return _HISTORICAL_DRIFT_ANCHOR


def set_historical_anchor_target_from_data(df: pd.DataFrame) -> None:
    """
    Set the active historical nominal CAGR target from the selected data window.

    Uses SPY price-return geometric mean from the selected period and adds the
    configured dividend overlay to get a nominal total-return target for anchor mode.
    """
    global _HISTORICAL_NOMINAL_CAGR_TARGET_ACTIVE, _HISTORICAL_DRIFT_ANCHOR

    default_target = float(HISTORICAL_NOMINAL_CAGR_TARGET)
    if df is None or 'SPY_Ret' not in df.columns or len(df) < 252 * 5:
        _HISTORICAL_NOMINAL_CAGR_TARGET_ACTIVE = default_target
        _HISTORICAL_DRIFT_ANCHOR = None
        print(f"  [historical anchor target] fallback to default {default_target:.2%} "
              f"(insufficient SPY history in selected window)")
        return

    spy_annual = df['SPY_Ret'].groupby(df.index.year).apply(lambda x: (1 + x).prod() - 1)
    spy_annual = spy_annual.replace([np.inf, -np.inf], np.nan).dropna()
    if len(spy_annual) < 5 or np.any(spy_annual <= -0.999):
        _HISTORICAL_NOMINAL_CAGR_TARGET_ACTIVE = default_target
        _HISTORICAL_DRIFT_ANCHOR = None
        print(f"  [historical anchor target] fallback to default {default_target:.2%} "
              f"(insufficient valid annual SPY returns)")
        return

    spy_price_geo = float(np.exp(np.mean(np.log(1.0 + spy_annual))) - 1.0)
    dynamic_target = float(np.clip(spy_price_geo + HISTORICAL_DIV_YIELD, 0.02, 0.16))
    _HISTORICAL_NOMINAL_CAGR_TARGET_ACTIVE = dynamic_target
    _HISTORICAL_DRIFT_ANCHOR = None  # force recompute with the new active target

    print(f"  [historical anchor target] selected-window SPY price geo={spy_price_geo:.2%}  "
          f"+ div={HISTORICAL_DIV_YIELD:.2%}  => target={dynamic_target:.2%}")


def get_scenario() -> dict:
    """
    Return active scenario parameters for MARKET_SCENARIO.

    'neutral'               → calibration-driven; no overlay; reports price return.
    'historical_backtest'   → real driver returns for the selected window (Pipeline D).
                              No GARCH/jump/vol overlays; calibrated financing + TE layer.
    'historical_bootstrap'  → block bootstrap from selected window (Pipeline E).
                              Random 63-day contiguous blocks; real returns only.
                              No GARCH/jump/vol overlays. Tests sequence-of-returns risk.
    'pessimistic' → −2% drift, 2× crisis prob, elevated vol/TE/jumps, wide spreads,
                    positive stock-bond corr (stagflation regime).
    'optimistic'  → +2% drift, 0.5× crisis prob, compressed vol/TE/jumps, tight spreads,
                    strong flight-to-quality hedge.
    'custom'      → neutral defaults merged with CUSTOM_SCENARIO_PARAMS overrides.
                    Set MARKET_SCENARIO = 'custom' and populate CUSTOM_SCENARIO_PARAMS.
    """
    _cal = _SCENARIO_CALIBRATED_PRESETS if isinstance(_SCENARIO_CALIBRATED_PRESETS, dict) else {}
    _neutral_base = dict(_SCENARIO_PRESETS['neutral'])
    if isinstance(_cal.get('neutral', None), dict):
        _neutral_base.update(_cal['neutral'])

    _scenario_key = _scenario_engine_key_for_key(MARKET_SCENARIO)

    if _scenario_key == 'custom':
        # Start from calibrated neutral defaults and apply user overrides.
        sc = dict(_neutral_base)
        sc.update(CUSTOM_SCENARIO_PARAMS)
        return sc

    sc = dict(_SCENARIO_PRESETS.get(_scenario_key, _SCENARIO_PRESETS['neutral']))
    if isinstance(_cal.get(_scenario_key, None), dict):
        sc.update(_cal[_scenario_key])
    # historical_backtest carries drift_tilt=0.0 and div_yield=0.0 directly — no
    # runtime anchor injection needed.
    return sc


def _normalize_correlation_override_scope(scope: Any) -> str:
    """
    Normalize correlation override scope aliases to one of:
      'portfolio_only' | 'generator_only' | 'both'
    """
    key = str(scope).strip().lower() if scope is not None else 'portfolio_only'
    aliases = {
        'portfolio_only': 'portfolio_only',
        'portfolio': 'portfolio_only',
        'optimizer_only': 'portfolio_only',
        'allocation_only': 'portfolio_only',
        'generator_only': 'generator_only',
        'generator': 'generator_only',
        'return_generator': 'generator_only',
        'joint_generator': 'generator_only',
        'returns_only': 'generator_only',
        'both': 'both',
        'all': 'both',
    }
    return aliases.get(key, 'portfolio_only')


def _apply_scenario_corr_overrides_to_portfolio_matrices(
    correlation_matrices: Dict[int, np.ndarray],
    calm_corr_override: Optional[float],
    crisis_corr_spike: Optional[float],
) -> Tuple[Dict[int, np.ndarray], Dict[str, Any]]:
    """
    Apply scenario SPY/TLT correlation overrides to strategy-optimization matrices.
    Matrix layout: [TQQQ=0, UPRO=1, SSO=2, TMF=3, SPY=4].
    """
    diag: Dict[str, Any] = {
        'applied': False,
        'base_calm_corr': None,
        'crisis_spike': None,
        'regime_targets': {}
    }
    if not isinstance(correlation_matrices, dict) or len(correlation_matrices) == 0:
        diag['reason'] = 'missing_correlation_matrices'
        return correlation_matrices, diag

    if calm_corr_override is not None and not np.isfinite(float(calm_corr_override)):
        calm_corr_override = None
    if crisis_corr_spike is not None and not np.isfinite(float(crisis_corr_spike)):
        crisis_corr_spike = None

    if calm_corr_override is None and crisis_corr_spike is None:
        diag['reason'] = 'no_overrides_requested'
        return correlation_matrices, diag

    try:
        base_calm = float(np.asarray(correlation_matrices[REGIME_LOW], dtype=float)[3, 4])
    except Exception:
        base_calm = -0.10

    calm_target = float(calm_corr_override) if calm_corr_override is not None else base_calm
    calm_target = float(np.clip(calm_target, -0.99, 0.99))
    spike = float(crisis_corr_spike) if crisis_corr_spike is not None else 0.12

    adj_corr: Dict[int, np.ndarray] = {}
    for reg, mat in correlation_matrices.items():
        mc = np.asarray(mat, dtype=float).copy()
        if mc.shape[0] < 5 or mc.shape[1] < 5:
            adj_corr[reg] = mc
            continue

        target = None
        if int(reg) == REGIME_LOW and calm_corr_override is not None:
            target = calm_target
        elif _is_stress_regime(int(reg)):
            reg_spike = spike * (0.6 if int(reg) == REGIME_BEAR else 1.0)
            target = float(np.clip(calm_target + reg_spike, -0.99, 0.99))

        if target is not None:
            mc[3, :] = [target, target, target, 1.0, target]
            mc[:, 3] = [target, target, target, 1.0, target]
            diag['regime_targets'][int(reg)] = float(target)

        mc_psd = nearest_psd_matrix(mc)
        if np.all(np.isfinite(mc_psd)):
            adj_corr[reg] = mc_psd
        else:
            adj_corr[reg] = np.asarray(mat, dtype=float)

    diag['applied'] = True
    diag['base_calm_corr'] = float(base_calm)
    diag['crisis_spike'] = float(spike)
    return adj_corr, diag


def _apply_scenario_corr_overrides_to_joint_return_model(
    joint_return_model: Dict[str, Any],
    calm_corr_override: Optional[float],
    crisis_corr_spike: Optional[float],
) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    """
    Apply scenario SPY/TLT correlation overrides directly to return-generator covariances.
    Assets are assumed to be ['SPY_Ret', 'QQQ_Ret', 'TLT_Ret'].
    """
    diag: Dict[str, Any] = {
        'applied': False,
        'base_calm_corr': None,
        'crisis_spike': None,
        'regime_targets': {}
    }
    if (not isinstance(joint_return_model, dict)
            or 'regimes' not in joint_return_model
            or not isinstance(joint_return_model['regimes'], dict)):
        diag['reason'] = 'missing_joint_return_model'
        return joint_return_model, diag

    if calm_corr_override is not None and not np.isfinite(float(calm_corr_override)):
        calm_corr_override = None
    if crisis_corr_spike is not None and not np.isfinite(float(crisis_corr_spike)):
        crisis_corr_spike = None

    if calm_corr_override is None and crisis_corr_spike is None:
        diag['reason'] = 'no_overrides_requested'
        return joint_return_model, diag

    out = copy.deepcopy(joint_return_model)
    try:
        cov0 = np.asarray(out['regimes'][REGIME_LOW]['cov'], dtype=float)
        sig0 = np.sqrt(np.clip(np.diag(cov0), 1e-12, None))
        base_calm = float(cov0[0, 2] / max(sig0[0] * sig0[2], 1e-12))
    except Exception:
        base_calm = -0.10

    calm_target = float(calm_corr_override) if calm_corr_override is not None else base_calm
    calm_target = float(np.clip(calm_target, -0.99, 0.99))
    spike = float(crisis_corr_spike) if crisis_corr_spike is not None else 0.12

    for reg, rp in out['regimes'].items():
        if not isinstance(rp, dict):
            continue
        cov = np.asarray(rp.get('cov', np.eye(3)), dtype=float)
        if cov.shape[0] < 3 or cov.shape[1] < 3:
            continue
        sig = np.sqrt(np.clip(np.diag(cov), 1e-12, None))
        corr = cov / np.outer(sig, sig)
        corr = nearest_psd_matrix(corr)

        target = None
        if int(reg) == REGIME_LOW and calm_corr_override is not None:
            target = calm_target
        elif _is_stress_regime(int(reg)):
            reg_spike = spike * (0.6 if int(reg) == REGIME_BEAR else 1.0)
            target = float(np.clip(calm_target + reg_spike, -0.99, 0.99))

        if target is None:
            continue

        # Keep stock-bond correlation coherent across SPY and QQQ.
        corr[0, 2] = target
        corr[2, 0] = target
        corr[1, 2] = target
        corr[2, 1] = target
        corr = nearest_psd_matrix(corr)
        cov_new = corr * np.outer(sig, sig)
        if np.all(np.isfinite(cov_new)):
            rp['cov'] = cov_new
            diag['regime_targets'][int(reg)] = float(target)

    diag['applied'] = True
    diag['base_calm_corr'] = float(base_calm)
    diag['crisis_spike'] = float(spike)
    return out, diag

def _select_market_scenario_interactive() -> None:
    """
    Backward-compatible wrapper around the 5-option institutional scenario menu.
    """
    global MARKET_SCENARIO
    resolution = resolve_selected_scenario(config_scenario=None)
    MARKET_SCENARIO = resolution.engine_key
    configure_cache_paths(
        start_date=ANALYSIS_START_DATE,
        end_date=ANALYSIS_END_DATE,
        scenario_name=MARKET_SCENARIO
    )
    print(f"  Scenario set to: {resolution.display_name}")


# ============================================================================
# RANDOMIZED START DATE CONFIGURATION
# ============================================================================
#
# To avoid overfitting to specific starting conditions, we randomize:
# 1. Which regime the simulation starts in
# 2. Where in a generated history the simulation begins
# 3. Optionally anchor to actual historical market conditions
#
# This tests strategy robustness across different market entry points.

# Master switch for start date randomization
USE_RANDOM_START = True

# Method for randomizing start conditions:
# - 'regime_only': Random starting regime (low vol or high vol)
# - 'offset': Generate extra history, start at random point
# - 'historical_anchor': Sample from actual historical starting conditions
RANDOM_START_METHOD = 'offset'

# For 'regime_only' method:
# Probability of starting in each regime (should sum to 1.0)
# Default reflects historical: calm most of the time, shock spikes rare, bear medium.
START_REGIME_PROBABILITIES = {
    REGIME_LOW: 0.74,
    REGIME_HIGH_VOL: 0.12,
    REGIME_BEAR: 0.14
}

# For 'offset' method:
# How much extra history to generate (in years)
# We generate this much extra, then pick a random start point
RANDOM_START_BUFFER_YEARS = 5

# For 'historical_anchor' method:
# Minimum years of historical data needed before an anchor point
# (We won't start at Day 1 of history - need some history to establish conditions)
MIN_HISTORY_FOR_ANCHOR = 2  # Years

# Whether to also randomize VIX starting level based on regime
RANDOMIZE_INITIAL_VIX = True

# VIX ranges by regime for random initialization
INITIAL_VIX_RANGE = {
    REGIME_LOW: (12, 20),
    REGIME_HIGH_VOL: (30, 55),
    REGIME_BEAR: (20, 35)
}

# Track which start method was used (for analysis)
# This will be stored in results for debugging
TRACK_START_CONDITIONS = True

# Real-only validation mode:
# - 'unconditional': use the main MC set directly
# - 'era_matched': run a separate validation MC set with historical-anchor starts
#   sampled from post-inception era to improve comparability vs real-only windows.
REAL_ONLY_VALIDATION_MODE = 'era_matched'
REAL_ONLY_VALIDATION_ANCHOR_START = '2006-01-01'
# Real-only pass gate focuses on assets with enough real rolling windows to form
# a stable distribution estimate; short post-inception series are reported but do
# not drive the hard pass/fail gate.
REAL_ONLY_CORE_MIN_WINDOWS = 200
REAL_ONLY_CORE_QUALITY_GATE = 65.0
# Repeatability check: run multiple real-only validation MC sets with different
# seeds and report quality mean/std to avoid one-off lucky passes.
REAL_ONLY_REPEATABILITY_RUNS = 5
REAL_ONLY_REPEATABILITY_SEED_BASE = 7000

# Institutional LETF reconstruction gate (hard fail thresholds).
# PHASE B FIX: replaced 'cum_return_error_max' with 'terminal_wealth_rel_err_max'.
# Old metric abs(cum_r - cum_a) was broken: a 7-yr LETF with 500% cumulative return
# would show 130% "cum_err" for a 1%/yr CAGR diff, making the 5% threshold absurd.
# New metric: |(1+cum_r)/(1+cum_a) - 1| — relative terminal wealth error.
# A CAGR diff of 0.5%/yr over 7 years implies ~3.5% terminal wealth rel error.
# Threshold of 0.10 allows ~1.4%/yr CAGR diff over 7 years.
LETF_RECONSTRUCTION_THRESHOLDS = {
    'corr_min': 0.995,
    'cagr_diff_max': 0.005,              # 0.5%/yr absolute
    'tracking_error_ann_max': 0.02,      # 2% annualized
    'vol_ratio_min': 0.97,
    'vol_ratio_max': 1.03,
    'max_drawdown_diff_max': 0.05,       # 5% absolute MDD difference
    'terminal_wealth_rel_err_max': 0.10, # 10% relative terminal wealth error
    'nav_rmse_rel_max': 0.05,            # 5% relative path RMSE (new secondary metric)
    'beta_min': 0.99,
    'beta_max': 1.01,
    'alpha_ann_abs_max': 0.005,          # "near zero" alpha => <= 0.5%/yr
    # Legacy key kept for any external callers; not used in checks.
    'cum_return_error_max': 0.05,        # DEPRECATED — see terminal_wealth_rel_err_max
}
RECONSTRUCTION_SELF_TEST_START = '2015-01-01'
RECONSTRUCTION_SELF_TEST_END = '2024-12-31'

# If True, _enforce_reconstruction_validation_gate raises RuntimeError on ANY threshold
# failure — synthetic backfill is forbidden until all assets pass.
# If False (default), the gate prints a prominent warning and continues simulation.
# Rationale for default False: OOS reconstruction accuracy for SPY-based 3× LETFs is
# structurally limited by regime non-stationarity.  The 2009-2014 training window
# captures UPRO/SSO outperforming 3×SPY by ~5%/yr (genuine historical bull-market alpha
# absorbed into driver_alpha + spread_fit).  OOS (2015-2024) UPRO outperforms by only
# ~3.4%/yr → ~1.8%/yr residual overpredict.  This cannot be fixed by changing the clip
# because spread_fit (AR1 model) absorbs the same mean regardless of driver_alpha.
# Use True only when reconstruction accuracy is critical (e.g., regulatory reporting).
LETF_RECONSTRUCTION_HARD_GATE = False

