# ============================================================================
# UTILITY FUNCTIONS
# ============================================================================

def save_cache(data, filepath):
    try:
        with open(filepath, 'wb') as f:
            pickle.dump(data, f)
    except Exception as e:
        print(f"⚠ Cache save failed: {e}")

def load_cache(filepath):
    if not filepath.exists():
        return None
    try:
        with open(filepath, 'rb') as f:
            obj = pickle.load(f)
        if (isinstance(obj, pd.DataFrame)
                and filepath.suffix == '.pkl'
                and str(filepath.name).startswith('historical_data')):
            healed_obj = obj
            healed = False
            healed_obj, qqq_healed = _rebuild_ndx_realonly_from_qqq_adjusted_close(
                healed_obj,
                verbose=False,
                force=False,
            )
            if qqq_healed:
                healed = True
                print("CACHE HEAL: rebuilt NDX_Ret_RealOnly using QQQ Adjusted Close total return")
            healed_obj, ohlc_healed = _attach_driver_ohlc_alias_columns(healed_obj)
            if ohlc_healed:
                healed = True
                print("CACHE HEAL: attached driver OHLC alias columns")
            if healed:
                save_cache(healed_obj, filepath)
            obj = healed_obj
        return obj
    except Exception as e:
        print(f"⚠ Cache load failed: {e}")
        return None


def _normalize_timeseries_column_name(name: Any) -> str:
    """ASCII-safe normalized column key for fuzzy timeseries matching."""
    return ''.join(ch.lower() for ch in str(name) if ch.isalnum())


def _coerce_timeseries_frame(obj: Any) -> Optional[pd.DataFrame]:
    """Coerce a local object (Series/DataFrame/cache payload) into a dated DataFrame."""
    try:
        if isinstance(obj, dict):
            for key in ('data', 'df', 'frame', 'series'):
                if key in obj:
                    obj = obj[key]
                    break
        if isinstance(obj, pd.Series):
            df = obj.to_frame(name='value')
        elif isinstance(obj, pd.DataFrame):
            df = obj.copy()
        else:
            return None

        if not isinstance(df.index, pd.DatetimeIndex):
            date_col = None
            for cand in ('Date', 'date', 'DATE', 'Datetime', 'datetime', 'timestamp', 'Timestamp'):
                if cand in df.columns:
                    date_col = cand
                    break
            if date_col is not None:
                dt = pd.to_datetime(df[date_col], errors='coerce')
                df = df.drop(columns=[date_col]).copy()
                df.index = dt
            elif len(df.columns) > 0:
                first_col = df.columns[0]
                dt = pd.to_datetime(df[first_col], errors='coerce')
                if int(dt.notna().sum()) >= max(10, int(len(df) * 0.8)):
                    df = df.drop(columns=[first_col]).copy()
                    df.index = dt
        if not isinstance(df.index, pd.DatetimeIndex):
            return None
        df = df.loc[~df.index.isna()].copy()
        if len(df) == 0:
            return None
        df.index = pd.to_datetime(df.index)
        df = df.sort_index()
        return df
    except Exception:
        return None


def _extract_ndxt_total_return_series(frame: pd.DataFrame,
                                      target_index: Optional[pd.DatetimeIndex] = None
                                      ) -> Tuple[Optional[pd.Series], Optional[pd.Series]]:
    """
    Extract a real Nasdaq-100 total-return series from a local frame.
    Returns (daily_return, price_level). If only price exists, returns are derived.
    """
    if not isinstance(frame, pd.DataFrame) or len(frame) == 0:
        return None, None

    norm_map = {_normalize_timeseries_column_name(c): c for c in frame.columns}

    exact_ret = [
        'ndxtretrealonly', 'ndxtrretrealonly', 'ndxtrret', 'ndxtret',
        'ndxtotalreturnretrealonly', 'ndxtotalreturnret', 'nasdaq100totalreturnret',
    ]
    exact_px = [
        'ndxtpricerealonly', 'ndxtrpricerealonly', 'ndxtrprice', 'ndxtprice',
        'ndxtotalreturnpricerealonly', 'ndxtotalreturnprice', 'nasdaq100totalreturnprice',
        'nasdaq100totalreturnclose', 'ndxtclose', 'ndxtrclose',
    ]

    ret_col = next((norm_map[k] for k in exact_ret if k in norm_map), None)
    px_col = next((norm_map[k] for k in exact_px if k in norm_map), None)

    if ret_col is None or px_col is None:
        for norm_name, orig_name in norm_map.items():
            is_ndxt = ('ndxt' in norm_name) or (
                'ndx' in norm_name and 'total' in norm_name and 'return' in norm_name
            )
            if not is_ndxt:
                continue
            has_ret_token = ('ret' in norm_name) or ('return' in norm_name)
            has_px_token = ('price' in norm_name) or ('close' in norm_name) or ('level' in norm_name)
            if ret_col is None and has_ret_token and not has_px_token:
                ret_col = orig_name
            if px_col is None and has_px_token and not ('ret' in norm_name and 'price' not in norm_name):
                px_col = orig_name

    ret_s: Optional[pd.Series] = None
    px_s: Optional[pd.Series] = None

    if ret_col is not None:
        cand = pd.to_numeric(frame[ret_col], errors='coerce')
        if int(cand.notna().sum()) >= 252:
            ret_s = cand
    if px_col is not None:
        cand_px = pd.to_numeric(frame[px_col], errors='coerce')
        if int(cand_px.notna().sum()) >= 252:
            px_s = cand_px
            if ret_s is None:
                cand_ret = cand_px.pct_change()
                if int(cand_ret.notna().sum()) >= 252:
                    ret_s = cand_ret

    if ret_s is None:
        return None, None

    ret_s = ret_s.copy()
    ret_s.index = pd.to_datetime(ret_s.index)
    ret_s = ret_s.sort_index()
    if px_s is not None:
        px_s = px_s.copy()
        px_s.index = pd.to_datetime(px_s.index)
        px_s = px_s.sort_index()

    if isinstance(target_index, pd.DatetimeIndex):
        ret_s = ret_s.reindex(target_index)
        if px_s is not None:
            px_s = px_s.reindex(target_index)

    if int(ret_s.notna().sum()) < 252:
        return None, None
    return ret_s, px_s


def _load_local_ndxt_total_return_series(target_index: Optional[pd.DatetimeIndex] = None,
                                         verbose: bool = False
                                         ) -> Tuple[Optional[pd.Series], Optional[pd.Series], Optional[str]]:
    """
    Best-effort local loader for a real Nasdaq-100 total-return history.
    Prefers explicitly persisted local files, then the canonical dataset if readable.
    """
    candidates: List[Tuple[str, Path]] = [
        ('pickle', CACHE_DIR / 'ndxt_total_return_local.pkl'),
        ('pickle', CACHE_DIR / 'ndx_total_return_local.pkl'),
        ('csv', CACHE_DIR / 'ndxt_total_return_local.csv'),
        ('csv', CACHE_DIR / 'ndx_total_return_local.csv'),
        ('parquet', Path('data/canonical/canonical_data.parquet')),
    ]

    for kind, path in candidates:
        if not path.exists():
            continue
        try:
            if kind == 'pickle':
                raw = pd.read_pickle(path)
            elif kind == 'csv':
                raw = pd.read_csv(path)
            else:
                raw = pd.read_parquet(path)
        except Exception:
            continue

        frame = _coerce_timeseries_frame(raw)
        if frame is None:
            continue
        ret_s, px_s = _extract_ndxt_total_return_series(frame, target_index=target_index)
        if ret_s is None:
            continue
        if verbose:
            print(f"  [NDX] Loaded real Nasdaq-100 total return from {path}")
        return ret_s, px_s, str(path)

    return None, None, None


def _attach_real_ndxt_total_return_columns(df: pd.DataFrame, verbose: bool = False) -> pd.DataFrame:
    """
    Persist a real Nasdaq-100 total-return history into the working panel when available.
    This is control-plane only: it populates data columns but does not alter emulator math.
    """
    if not isinstance(df, pd.DataFrame) or len(df) == 0:
        return df

    target_index = pd.DatetimeIndex(df.index)
    ret_local, px_local, detail = _load_local_ndxt_total_return_series(target_index=target_index, verbose=verbose)

    if ret_local is None:
        return df

    out = df.copy()

    existing_ret = None
    for cand in ('NDX_TR_Ret_RealOnly', 'NDXT_Ret_RealOnly', 'NDX_Ret_RealOnly'):
        if cand in out.columns:
            s = pd.to_numeric(out[cand], errors='coerce')
            if int(s.notna().sum()) > 0:
                existing_ret = s if existing_ret is None else existing_ret.combine_first(s)
    merged_ret = ret_local.copy()
    if existing_ret is not None:
        merged_ret = merged_ret.combine_first(existing_ret)

    out['NDX_TR_Ret_RealOnly'] = merged_ret
    out['NDXT_Ret_RealOnly'] = merged_ret
    out['NDX_Ret_RealOnly'] = merged_ret
    out['NDX_Ret_RealOnly_Source'] = 'NDXT_real'
    if detail is not None:
        out['NDX_Ret_RealOnly_Source_Detail'] = str(detail)

    if px_local is not None:
        existing_px = None
        for cand in ('NDX_TR_Price_RealOnly', 'NDXT_Price_RealOnly'):
            if cand in out.columns:
                s = pd.to_numeric(out[cand], errors='coerce')
                if int(s.notna().sum()) > 0:
                    existing_px = s if existing_px is None else existing_px.combine_first(s)
        merged_px = px_local.copy()
        if existing_px is not None:
            merged_px = merged_px.combine_first(existing_px)
        out['NDX_TR_Price_RealOnly'] = merged_px
        out['NDXT_Price_RealOnly'] = merged_px

    if verbose:
        n_real = int(pd.to_numeric(out['NDX_Ret_RealOnly'], errors='coerce').notna().sum())
        print(f"  [NDX] Persisted real Nasdaq-100 total-return history into cache panel "
              f"({n_real:,} rows, source=NDXT_real)")
    return out


def _attach_driver_ohlc_alias_columns(df: pd.DataFrame) -> Tuple[pd.DataFrame, bool]:
    """
    Best-effort aliasing of driver OHLC columns already present in the panel.
    This does not synthesize OHLC; it only exposes consistent names when source
    columns already exist (fresh Yahoo fetches or future enriched caches).
    """
    if not isinstance(df, pd.DataFrame) or len(df) == 0:
        return df, False

    out = df.copy()
    changed = False

    alias_specs: List[Tuple[str, Tuple[str, ...]]] = [
        ('SPY_Open_RealOnly', ('SPY_Open',)),
        ('SPY_High_RealOnly', ('SPY_High',)),
        ('SPY_Low_RealOnly', ('SPY_Low',)),
        ('QQQ_Open_RealOnly', ('QQQ_Open',)),
        ('QQQ_High_RealOnly', ('QQQ_High',)),
        ('QQQ_Low_RealOnly', ('QQQ_Low',)),
        ('NASDAQ_Open_RealOnly', ('NASDAQ_Open', 'IXIC_Open')),
        ('NASDAQ_High_RealOnly', ('NASDAQ_High', 'IXIC_High')),
        ('NASDAQ_Low_RealOnly', ('NASDAQ_Low', 'IXIC_Low')),
        ('IXIC_Open_RealOnly', ('IXIC_Open', 'NASDAQ_Open')),
        ('IXIC_High_RealOnly', ('IXIC_High', 'NASDAQ_High')),
        ('IXIC_Low_RealOnly', ('IXIC_Low', 'NASDAQ_Low')),
        ('NDX_Open_RealOnly', ('NDX_Open',)),
        ('NDX_High_RealOnly', ('NDX_High',)),
        ('NDX_Low_RealOnly', ('NDX_Low',)),
        ('NDXT_Open_RealOnly', ('NDXT_Open', 'NDX_TR_Open_RealOnly')),
        ('NDXT_High_RealOnly', ('NDXT_High', 'NDX_TR_High_RealOnly')),
        ('NDXT_Low_RealOnly', ('NDXT_Low', 'NDX_TR_Low_RealOnly')),
        ('NDX_TR_Open_RealOnly', ('NDXT_Open_RealOnly', 'NDXT_Open')),
        ('NDX_TR_High_RealOnly', ('NDXT_High_RealOnly', 'NDXT_High')),
        ('NDX_TR_Low_RealOnly', ('NDXT_Low_RealOnly', 'NDXT_Low')),
    ]

    for target, candidates in alias_specs:
        if target in out.columns:
            continue
        for cand in candidates:
            if cand in out.columns:
                out[target] = pd.to_numeric(out[cand], errors='coerce')
                changed = True
                break

    return out, changed


def _rebuild_ndx_realonly_from_qqq_adjusted_close(df: pd.DataFrame,
                                                  verbose: bool = False,
                                                  force: bool = False
                                                  ) -> Tuple[pd.DataFrame, bool]:
    """
    Build NDX_Ret_RealOnly from QQQ adjusted-close total return when no true NDXT
    history is available in the panel. This is a data-healing operation only.
    """
    if not isinstance(df, pd.DataFrame) or len(df) == 0:
        return df, False

    out = df.copy()

    qqq_px = None
    qqq_px_col = None
    for cand_col in (
        'QQQ_Adj_Close_RealOnly',
        'QQQ_AdjClose_RealOnly',
        'QQQ_Adj_Close',
        'QQQ_AdjClose',
        # In this engine, QQQ_Price_RealOnly / QQQ_Price come from
        # yfinance(auto_adjust=True), so they are already adjusted-close series.
        'QQQ_Price_RealOnly',
        'QQQ_Price',
    ):
        if cand_col not in out.columns:
            continue
        cand_px = pd.to_numeric(out[cand_col], errors='coerce')
        if int(cand_px.notna().sum()) >= 252:
            qqq_px = cand_px
            qqq_px_col = cand_col
            break

    if qqq_px is None:
        return df, False

    # Backfill explicit alias columns so downstream cache users can see the
    # adjusted-close lineage directly.
    alias_added = False
    if 'QQQ_Adj_Close_RealOnly' not in out.columns:
        out['QQQ_Adj_Close_RealOnly'] = qqq_px
        alias_added = True
    if 'QQQ_Adj_Close' not in out.columns:
        out['QQQ_Adj_Close'] = qqq_px
        alias_added = True

    qqq_adj_ret = qqq_px.pct_change()
    if int(qqq_adj_ret.notna().sum()) < 252:
        return out if alias_added else df, alias_added

    existing_src = ''
    if 'NDX_Ret_RealOnly_Source' in out.columns:
        src_non_na = out['NDX_Ret_RealOnly_Source'].dropna()
        if len(src_non_na) > 0:
            existing_src = str(src_non_na.iloc[-1]).strip()

    existing_ret = pd.to_numeric(out['NDX_Ret_RealOnly'], errors='coerce') if 'NDX_Ret_RealOnly' in out.columns else pd.Series(np.nan, index=out.index, dtype=float)
    existing_ret = existing_ret.reindex(out.index)

    if not force:
        # Preserve true NDXT if it already exists with usable coverage.
        if existing_src == 'NDXT_real' and int(existing_ret.notna().sum()) >= 252:
            return out if alias_added else df, alias_added

        has_ndx_col = 'NDX_Ret_RealOnly' in out.columns
        acceptable_src = existing_src in ('NDXT_real', 'QQQ_adj_close_total_return')
        missing_where_qqq = bool((qqq_adj_ret.notna() & existing_ret.isna()).any()) if has_ndx_col else True
        if has_ndx_col and acceptable_src and not missing_where_qqq:
            return out if alias_added else df, alias_added

    current = existing_ret if 'NDX_Ret_RealOnly' in out.columns else None
    changed = True
    if current is not None:
        same_mask = qqq_adj_ret.notna() & current.notna()
        same_len = int(same_mask.sum())
        if same_len > 0:
            max_diff = float((current[same_mask] - qqq_adj_ret[same_mask]).abs().max())
            changed = bool(
                max_diff > 1e-12
                or int(current.notna().sum()) != int(qqq_adj_ret.notna().sum())
                or existing_src != 'QQQ_adj_close_total_return'
                or alias_added
            )
        else:
            changed = True

    if not changed:
        return out if alias_added else df, alias_added

    out['NDX_Ret_RealOnly'] = qqq_adj_ret
    out['NDX_Ret_RealOnly_Source'] = 'QQQ_adj_close_total_return'
    if qqq_px_col is not None:
        out['NDX_Ret_RealOnly_Source_Detail'] = str(qqq_px_col)

    if verbose:
        print("CACHE HEAL: rebuilt NDX_Ret_RealOnly using QQQ Adjusted Close total return")
    return out, True


def _save_local_ff_factors_daily(ff_df: pd.DataFrame, source: str) -> None:
    """Persist raw FF daily factors (Mkt-RF, RF) for offline fallback."""
    try:
        if ff_df is None or len(ff_df) == 0:
            return
        need = ['Mkt-RF', 'RF']
        if any(c not in ff_df.columns for c in need):
            return
        out = ff_df[need].copy()
        out.index = pd.to_datetime(out.index)
        payload = {
            'schema': 'ff_factors_daily_v1',
            'source': str(source),
            'saved_at': str(pd.Timestamp.utcnow()),
            'data': out,
        }
        save_cache(payload, FF_FACTORS_LOCAL_CACHE)
    except Exception as _e:
        print(f"  [ff-fallback] WARNING: failed to persist FF factors local cache ({_e})")


def _load_local_ff_factors_daily() -> Optional[pd.DataFrame]:
    """Load persisted FF daily factors fallback."""
    try:
        obj = load_cache(FF_FACTORS_LOCAL_CACHE)
        if obj is None:
            return None
        if isinstance(obj, dict) and 'data' in obj:
            df = obj.get('data')
        else:
            df = obj
        if not isinstance(df, pd.DataFrame) or len(df) == 0:
            return None
        if any(c not in df.columns for c in ['Mkt-RF', 'RF']):
            return None
        out = df[['Mkt-RF', 'RF']].copy()
        out.index = pd.to_datetime(out.index)
        out = out.sort_index()
        return out
    except Exception as _e:
        print(f"  [ff-fallback] WARNING: failed to load FF factors local cache ({_e})")
        return None


