def _load_local_ff49_hitec_daily() -> Tuple[Optional[pd.Series], Optional[str]]:
    """Load persisted FF49 HiTec fallback. Returns (series, unit)."""
    try:
        obj = load_cache(FF49_HITEC_LOCAL_CACHE)
        if obj is None:
            return None, None
        if isinstance(obj, dict) and 'series' in obj:
            s = obj.get('series')
            unit = str(obj.get('unit', 'pct')).strip().lower()
        elif isinstance(obj, pd.Series):
            s = obj
            unit = 'decimal'
        else:
            return None, None
        if not isinstance(s, pd.Series) or len(s) == 0:
            return None, None
        out = pd.to_numeric(s, errors='coerce').dropna().copy()
        if len(out) == 0:
            return None, None
        out.index = pd.to_datetime(out.index)
        out = out.sort_index()
        if unit not in ('pct', 'decimal'):
            unit = 'pct'
        return out, unit
    except Exception as _e:
        print(f"  [ff-fallback] WARNING: failed to load FF49 HiTec local cache ({_e})")
        return None, None


def _seed_local_ff_caches_from_historical_cache(verbose: bool = True) -> Dict[str, bool]:
    """
    Best-effort seeding of FF local caches from existing historical_data_*.pkl files.
    This enables offline 1926 coverage when network fetch is unavailable.
    """
    seeded = {'factors': False, 'hitec': False}
    _existing_ff = _load_local_ff_factors_daily()
    _existing_hitec, _existing_hitec_unit = _load_local_ff49_hitec_daily()
    need_factors = _existing_ff is None or len(_existing_ff) == 0
    need_hitec = (
        _existing_hitec is None
        or len(_existing_hitec) == 0
        or pd.Timestamp(_existing_hitec.index.max()) < pd.Timestamp('1970-01-01')
    )
    if not need_factors and not need_hitec:
        return seeded

    candidates = sorted(CACHE_DIR.glob("historical_data_*.pkl"))
    # Prefer longest windows (often include 1926+).
    candidates = sorted(candidates, key=lambda p: p.stat().st_size, reverse=True)

    for path in candidates:
        try:
            obj = load_cache(path)
            if not isinstance(obj, pd.DataFrame) or len(obj) == 0:
                continue
            df = obj.copy()
            if 'SPY_Ret' not in df.columns:
                continue
            ff_mask = (
                df['Data_Source'].astype(str).eq('Fama-French')
                if 'Data_Source' in df.columns else pd.Series(False, index=df.index)
            )
            if not ff_mask.any():
                continue
            ff_rows = df.loc[ff_mask].copy()
            ff_rows.index = pd.to_datetime(ff_rows.index)
            ff_rows = ff_rows.sort_index()

            if need_factors:
                rf_dec = (
                    pd.to_numeric(ff_rows['RF'], errors='coerce')
                    if 'RF' in ff_rows.columns
                    else (
                        pd.to_numeric(ff_rows['IRX'], errors='coerce') / 100.0 / 252.0
                        if 'IRX' in ff_rows.columns else None
                    )
                )
                spy = pd.to_numeric(ff_rows['SPY_Ret'], errors='coerce')
                if rf_dec is not None:
                    mktrf_pct = (spy - rf_dec) * 100.0
                    rf_pct = rf_dec * 100.0
                    ff_like = pd.DataFrame({'Mkt-RF': mktrf_pct, 'RF': rf_pct}, index=ff_rows.index)
                    ff_like = ff_like.replace([np.inf, -np.inf], np.nan).dropna()
                    if len(ff_like) >= 252 * 10:
                        _save_local_ff_factors_daily(ff_like, source=f'seed:{path.name}')
                        seeded['factors'] = True
                        need_factors = False

            if need_hitec and 'QQQ_Ret' in df.columns:
                qqq_all = pd.to_numeric(df['QQQ_Ret'], errors='coerce').replace([np.inf, -np.inf], np.nan)
                if 'NASDAQ_Price' in df.columns:
                    ndq_px = pd.to_numeric(df['NASDAQ_Price'], errors='coerce')
                    ndq_first = ndq_px.first_valid_index()
                else:
                    ndq_first = None
                if ndq_first is not None:
                    qqq_proxy = qqq_all.loc[qqq_all.index < pd.Timestamp(ndq_first)].dropna()
                else:
                    qqq_proxy = qqq_all.dropna()
                if len(qqq_proxy) >= 252 * 10:
                    # Best-effort seed covering pre-NASDAQ years. If true FF49 HiTec
                    # is later fetched online, it overwrites this proxy seed.
                    _save_local_ff49_hitec_daily(
                        qqq_proxy,
                        unit='decimal',
                        source=f'seed_proxy_pre_ndq:{path.name}',
                    )
                    seeded['hitec'] = True
                    need_hitec = False

            if not need_factors and not need_hitec:
                break
        except Exception:
            continue

    if verbose and (seeded['factors'] or seeded['hitec']):
        print("  [ff-fallback] Seeded local FF caches from existing historical_data cache "
              f"(factors={seeded['factors']}, hitec={seeded['hitec']}).")
    return seeded

def get_max_underwater_days(equity_curve):
    """Calculates the longest period (in trading days) the strategy was in a drawdown."""
    hwm = equity_curve.cummax()
    underwater = equity_curve < hwm
    
    # Calculate run lengths of True values (underwater days)
    # This magic converts [F, T, T, T, F, T] into counts of consecutive Trues
    check_series = underwater.astype(int)
    # Group consecutive 1s and 0s
    groups = check_series.ne(check_series.shift()).cumsum()
    # Sum the 1s in each group
    run_lengths = check_series.groupby(groups).sum()
    
    if run_lengths.empty:
        return 0
    return run_lengths.max()

def nearest_psd_matrix(corr_matrix):
    """Project correlation matrix to nearest positive semi-definite matrix."""
    eigenvalues, eigenvectors = np.linalg.eigh(corr_matrix)
    eigenvalues[eigenvalues < 1e-8] = 1e-8
    
    corr_psd = eigenvectors @ np.diag(eigenvalues) @ eigenvectors.T
    
    # Normalize to correlation matrix (diagonal = 1)
    d = np.sqrt(np.diag(corr_psd))
    corr_psd = corr_psd / np.outer(d, d)
    
    return corr_psd

def _compute_stress_logit(vix: np.ndarray, rv: np.ndarray, ts: np.ndarray,
                          logit_params: Optional[Dict[str, float]] = None,
                          logit_shift: float = 0.0) -> np.ndarray:
    """Core stress logit; higher means higher high-volatility probability."""
    p = logit_params if isinstance(logit_params, dict) else STRESS_LOGIT_PARAMS
    b0 = float(p.get('intercept', DEFAULT_STRESS_LOGIT_PARAMS['intercept']))
    b1 = float(p.get('beta_vix', DEFAULT_STRESS_LOGIT_PARAMS['beta_vix']))
    b2 = float(p.get('beta_rv', DEFAULT_STRESS_LOGIT_PARAMS['beta_rv']))
    b3 = float(p.get('beta_ts', DEFAULT_STRESS_LOGIT_PARAMS['beta_ts']))
    return (
        b0
        + b1 * (np.nan_to_num(vix, nan=20.0) - 20.0)
        + b2 * (np.nan_to_num(rv, nan=0.18) - 0.18)
        + b3 * np.clip(-ts, -5, 5)
        + float(logit_shift)
    )


def calibrate_stress_logit_parameters(vix_series, realized_vol=None, term_spread=None,
                                      vix_stress_threshold: float = HIGH_VOL_STRESS_LABEL_VIX_THRESHOLD) -> Dict[str, float]:
    """
    Re-fit stress-logit coefficients on calibration data using VIX-based stress labels.

    Labels use VIX >= threshold (default 25) as a practical high-vol proxy.
    """
    vix = np.asarray(vix_series, dtype=float)
    n = len(vix)
    if n < 250:
        return dict(DEFAULT_STRESS_LOGIT_PARAMS)

    if realized_vol is None:
        rv = pd.Series(vix).rolling(20, min_periods=5).std().bfill().fillna(0).values / 100.0
    else:
        rv = np.asarray(realized_vol, dtype=float)
        rv = pd.Series(rv).ffill().bfill().fillna(np.nanmedian(rv)).values

    if term_spread is None:
        ts = np.zeros(n, dtype=float)
    else:
        ts = np.asarray(term_spread, dtype=float)
        ts = pd.Series(ts).ffill().bfill().fillna(0.0).values

    valid = np.isfinite(vix) & np.isfinite(rv) & np.isfinite(ts)
    if valid.sum() < 250:
        return dict(DEFAULT_STRESS_LOGIT_PARAMS)

    x1 = (np.nan_to_num(vix[valid], nan=20.0) - 20.0)
    x2 = (np.nan_to_num(rv[valid], nan=0.18) - 0.18)
    x3 = np.clip(-ts[valid], -5, 5)
    y = (vix[valid] >= float(vix_stress_threshold)).astype(float)

    # If labels collapse to one class, keep defaults and only shift intercept.
    if y.mean() <= 0.005 or y.mean() >= 0.995:
        out = dict(DEFAULT_STRESS_LOGIT_PARAMS)
        out['intercept'] = float(np.clip(np.log((y.mean() + 1e-6) / (1 - y.mean() + 1e-6)), -8.0, 2.0))
        return out

    # Standardize features to avoid single-feature domination, then fit with
    # explicit shrinkage back to default engineering priors.
    x1_mu, x1_sd = float(np.nanmean(x1)), float(np.nanstd(x1))
    x2_mu, x2_sd = float(np.nanmean(x2)), float(np.nanstd(x2))
    x3_mu, x3_sd = float(np.nanmean(x3)), float(np.nanstd(x3))
    x1_sd = x1_sd if x1_sd > 1e-8 else 1.0
    x2_sd = x2_sd if x2_sd > 1e-8 else 1.0
    x3_sd = x3_sd if x3_sd > 1e-8 else 1.0

    z1 = (x1 - x1_mu) / x1_sd
    z2 = (x2 - x2_mu) / x2_sd
    z3 = (x3 - x3_mu) / x3_sd
    X = np.column_stack([np.ones_like(z1), z1, z2, z3]).astype(float)

    # Prior in standardized space.
    b0_d = DEFAULT_STRESS_LOGIT_PARAMS['intercept']
    b1_d = DEFAULT_STRESS_LOGIT_PARAMS['beta_vix']
    b2_d = DEFAULT_STRESS_LOGIT_PARAMS['beta_rv']
    b3_d = DEFAULT_STRESS_LOGIT_PARAMS['beta_ts']
    beta_prior = np.array([
        b0_d + b1_d * x1_mu + b2_d * x2_mu + b3_d * x3_mu,
        b1_d * x1_sd,
        b2_d * x2_sd,
        b3_d * x3_sd
    ], dtype=float)
    beta = beta_prior.copy()

    # Ridge around priors (not around zero) to prevent boundary saturation.
    lam = 0.25
    reg = np.diag([0.02, lam, lam, lam])
    for _ in range(30):
        z = np.clip(X @ beta, -30, 30)
        p = 1.0 / (1.0 + np.exp(-z))
        w = np.clip(p * (1.0 - p), 1e-6, None)
        grad = (X.T @ (p - y)) + (reg @ (beta - beta_prior))
        hess = (X.T * w) @ X + reg
        try:
            step = np.linalg.solve(hess, grad)
        except np.linalg.LinAlgError:
            break
        beta_next = beta - step
        if np.linalg.norm(step) < 1e-6:
            beta = beta_next
            break
        beta = beta_next

    # Convert coefficients back to native feature space.
    beta_vix = float(beta[1] / x1_sd)
    beta_rv = float(beta[2] / x2_sd)
    beta_ts = float(beta[3] / x3_sd)
    intercept = float(beta[0] - beta[1] * x1_mu / x1_sd - beta[2] * x2_mu / x2_sd - beta[3] * x3_mu / x3_sd)

    # Shrink toward defaults to avoid unstable extremes.
    shrink = 0.55
    beta_vix = b1_d + shrink * (beta_vix - b1_d)
    beta_rv = b2_d + shrink * (beta_rv - b2_d)
    beta_ts = b3_d + shrink * (beta_ts - b3_d)

    # Conservative coefficient bounds that still allow sensitivity.
    beta_vix = float(np.clip(beta_vix, 0.10, 0.35))
    beta_rv = float(np.clip(beta_rv, 0.50, 8.00))
    beta_ts = float(np.clip(beta_ts, 0.00, 0.30))

    # Intercept calibration: match label frequency and keep p50 crossing realistic.
    rv_ref = float(np.nanmedian(rv[valid]))
    ts_ref = float(np.nanmedian(ts[valid]))
    vix_valid = vix[valid]
    target_cross_emp = np.nanpercentile(vix_valid[y == 1], 30) if np.any(y == 1) else (vix_stress_threshold + 1.5)
    target_cross = float(np.clip(target_cross_emp, vix_stress_threshold - 1.0, vix_stress_threshold + 5.0))
    intercept_cross = float(
        -beta_vix * (target_cross - 20.0)
        -beta_rv * (rv_ref - 0.18)
        -beta_ts * np.clip(-ts_ref, -5, 5)
    )
    # Frequency-matching intercept by Newton steps with fixed slopes.
    intercept_freq = intercept
    for _ in range(12):
        zf = np.clip(intercept_freq + beta_vix * x1 + beta_rv * x2 + beta_ts * x3, -30, 30)
        pf = 1.0 / (1.0 + np.exp(-zf))
        g = float(np.mean(pf) - np.mean(y))
        h = float(np.mean(pf * (1.0 - pf)))
        if abs(g) < 1e-5 or h < 1e-7:
            break
        intercept_freq -= g / h

    intercept = float(0.50 * intercept_freq + 0.50 * intercept_cross)
    # Keep intercept close to an institutionally stable range to avoid
    # boundary-collapse between near-always-calm and near-always-stress labels.
    intercept = float(np.clip(intercept, -5.5, -2.4))

    fitted = {
        'intercept': intercept,
        'beta_vix': beta_vix,
        'beta_rv': beta_rv,
        'beta_ts': beta_ts
    }
    return fitted


def estimate_effective_vix_p50(params: Dict[str, float], rv_level: float, ts_level: float) -> float:
    """
    Approximate VIX level where p(high-vol)=0.5 for given RV and term-spread conditions.
    """
    b0 = float(params.get('intercept', DEFAULT_STRESS_LOGIT_PARAMS['intercept']))
    b1 = float(params.get('beta_vix', DEFAULT_STRESS_LOGIT_PARAMS['beta_vix']))
    b2 = float(params.get('beta_rv', DEFAULT_STRESS_LOGIT_PARAMS['beta_rv']))
    b3 = float(params.get('beta_ts', DEFAULT_STRESS_LOGIT_PARAMS['beta_ts']))
    if abs(b1) < 1e-8:
        return float('nan')
    rhs = -b0 - b2 * (float(rv_level) - 0.18) - b3 * np.clip(-float(ts_level), -5, 5)
    return float(20.0 + rhs / b1)


def calibrate_high_vol_logit_shift(vix_series, realized_vol=None, term_spread=None,
                                   vix_stress_threshold: float = HIGH_VOL_STRESS_LABEL_VIX_THRESHOLD) -> float:
    """
    Calibrate logistic intercept shift so average predicted stress probability
    matches empirical stress frequency (VIX >= threshold) on calibration data.
    """
    params = calibrate_stress_logit_parameters(
        vix_series=vix_series,
        realized_vol=realized_vol,
        term_spread=term_spread,
        vix_stress_threshold=vix_stress_threshold
    )
    return float(params.get('intercept', DEFAULT_STRESS_LOGIT_PARAMS['intercept']) -
                 DEFAULT_STRESS_LOGIT_PARAMS['intercept'])


def compute_high_vol_probability(vix_series, realized_vol=None, term_spread=None, smoothing=0.94,
                                 logit_shift: Optional[float] = None,
                                 logit_params: Optional[Dict[str, float]] = None):
    """
    Probabilistic high-volatility regime score in [0, 1].

    Uses a smooth logistic model on VIX, realized volatility, and term structure,
    then applies EWMA smoothing to reduce brittle day-to-day flips.

    LIMITATION (B8-6): The logistic coefficients (-4.0, 0.22, 6.5, 0.10) are set by
    engineering judgment, not ML-fitted from historical labeled crisis episodes.  Any
    effective VIX threshold in the 20-30 range produces similar regime assignments in
    practice; boundary cases (VIX 22-28) may be misclassified in either direction.
    The effective p=0.5 crossing is VIX ≈ 38 at median realized-vol, so this classifier
    is more conservative than a simple VIX=25 hard threshold.
    """
    vix = np.asarray(vix_series, dtype=float)
    n = len(vix)

    if realized_vol is None:
        rv = pd.Series(vix).rolling(20, min_periods=5).std().bfill().fillna(0).values / 100.0
    else:
        rv = np.asarray(realized_vol, dtype=float)
        rv = pd.Series(rv).ffill().bfill().fillna(np.nanmedian(rv)).values

    if term_spread is None:
        ts = np.zeros(n)
    else:
        ts = np.asarray(term_spread, dtype=float)
        ts = pd.Series(ts).ffill().bfill().fillna(0.0).values

    # Logistic score: higher VIX, higher realized vol, and flatter/inverted curve
    # imply higher stress probability.
    if logit_shift is None:
        logit_shift = 0.0
    logit = _compute_stress_logit(vix, rv, ts, logit_params=logit_params, logit_shift=logit_shift)
    raw_p = 1.0 / (1.0 + np.exp(-np.clip(logit, -20, 20)))

    smoothed_p = np.zeros(n)
    if n > 0:
        smoothed_p[0] = raw_p[0]
    for i in range(1, n):
        smoothed_p[i] = smoothing * smoothed_p[i - 1] + (1 - smoothing) * raw_p[i]

    return np.clip(smoothed_p, 0.001, 0.999)


def infer_regime_from_vix(vix_series, realized_vol=None, term_spread=None, hysteresis=0.08,
                          logit_shift: Optional[float] = None,
                          logit_params: Optional[Dict[str, float]] = None,
                          spy_returns: Optional[np.ndarray] = None,
                          recession_proxy: Optional[np.ndarray] = None):
    """
    Infer regime using probabilistic stress score with hysteresis.

    This avoids brittle single-threshold switching at VIX=25 by combining VIX,
    realized vol, and optional term-structure information.

    If `spy_returns` is provided and N_REGIMES >= 3, overlays a third bear-market
    state based on sustained equity drawdowns.
    """
    p_high = compute_high_vol_probability(
        vix_series=vix_series,
        realized_vol=realized_vol,
        term_spread=term_spread,
        logit_shift=logit_shift,
        logit_params=logit_params
    )

    enter_high = 0.50 + hysteresis / 2
    exit_high = 0.50 - hysteresis / 2

    regimes = np.zeros(len(p_high), dtype=int)
    if len(p_high) == 0:
        return regimes

    current = REGIME_HIGH_VOL if p_high[0] >= 0.50 else REGIME_LOW
    regimes[0] = current
    for i in range(1, len(p_high)):
        if current == REGIME_LOW and p_high[i] >= enter_high:
            current = REGIME_HIGH_VOL
        elif current == REGIME_HIGH_VOL and p_high[i] <= exit_high:
            current = REGIME_LOW
        regimes[i] = current

    if N_REGIMES >= 3 and spy_returns is not None and len(spy_returns) == len(regimes):
        bear_mask = _identify_bear_market_mask(
            spy_returns=np.asarray(spy_returns, dtype=float),
            vix_series=np.asarray(vix_series, dtype=float),
            recession_proxy=recession_proxy,
            enter_drawdown=0.22,
            exit_drawdown=0.10,
            min_spell=max(63, MIN_REGIME_DURATION.get(REGIME_BEAR, 45)),
            max_join_gap=10
        )
        regimes = np.asarray(regimes, dtype=int)
        regimes[bear_mask] = REGIME_BEAR

    return regimes


def _is_stress_regime(regime_value: int) -> bool:
    """Return True if regime id is classified as stress (shock or bear)."""
    return int(regime_value) in set(STRESS_REGIME_IDS)


def _stress_mask(regimes: np.ndarray) -> np.ndarray:
    """Boolean mask for stress regimes over an integer regime path."""
    arr = np.asarray(regimes, dtype=int)
    return np.isin(arr, np.asarray(STRESS_REGIME_IDS, dtype=int))


def _stress_share(regimes: np.ndarray) -> float:
    """Fraction of observations in stress regimes."""
    arr = np.asarray(regimes, dtype=int)
    if len(arr) == 0:
        return 0.0
    return float(np.mean(_stress_mask(arr)))


def _regime_frequency_from_params(regime_params: Dict[int, Dict[str, Any]],
                                  regime_ids: Tuple[int, ...],
                                  use_topology: bool = True) -> float:
    """Aggregate regime frequency from calibrated params for one or more regimes."""
    total = 0.0
    seen = False
    for rid in regime_ids:
        p = regime_params.get(int(rid), {})
        key = 'frequency_topology' if use_topology else 'frequency'
        val = p.get(key, p.get('frequency', np.nan))
        if np.isfinite(float(val)):
            total += float(val)
            seen = True
    return float(total if seen else float('nan'))


def _drawdown_from_returns(returns: np.ndarray) -> np.ndarray:
    """Path drawdown series from daily returns."""
    arr = np.asarray(returns, dtype=float)
    if len(arr) == 0:
        return np.zeros(0, dtype=float)
    wealth = np.cumprod(1.0 + np.nan_to_num(arr, nan=0.0))
    peak = np.maximum.accumulate(np.maximum(wealth, 1e-12))
    return wealth / peak - 1.0


def _extract_boolean_episodes(mask: np.ndarray) -> List[Tuple[int, int]]:
    """
    Convert boolean mask to inclusive [start, end] episode tuples.
    """
    arr = np.asarray(mask, dtype=bool)
    if len(arr) == 0:
        return []
    episodes: List[Tuple[int, int]] = []
    i = 0
    n = len(arr)
    while i < n:
        if not arr[i]:
            i += 1
            continue
        s = i
        while i + 1 < n and arr[i + 1]:
            i += 1
        episodes.append((s, i))
        i += 1
    return episodes


def _episodes_to_mask(n: int, episodes: List[Tuple[int, int]]) -> np.ndarray:
    """Build boolean mask from inclusive [start, end] episodes."""
    out = np.zeros(int(n), dtype=bool)
    for s, e in episodes:
        s_i = int(max(0, s))
        e_i = int(min(n - 1, e))
        if e_i >= s_i:
            out[s_i:e_i + 1] = True
    return out


def _identify_bear_market_mask(spy_returns: np.ndarray,
                               vix_series: Optional[np.ndarray] = None,
                               recession_proxy: Optional[np.ndarray] = None,
                               enter_drawdown: float = 0.22,
                               exit_drawdown: float = 0.10,
                               min_spell: int = 63,
                               max_join_gap: int = 10) -> np.ndarray:
    """
    Identify prolonged equity-bear episodes from drawdown + trend/recession context.

    Intent: separate long economic bear markets (months/years) from short VIX spikes.
    """
    r = np.asarray(spy_returns, dtype=float)
    n = len(r)
    if n == 0:
        return np.zeros(0, dtype=bool)

    vix = np.full(n, 20.0, dtype=float) if vix_series is None else np.asarray(vix_series, dtype=float)
    if len(vix) != n:
        vix = pd.Series(vix).reindex(range(n)).ffill().bfill().fillna(20.0).to_numpy(dtype=float)

    rec = np.zeros(n, dtype=bool)
    if recession_proxy is not None:
        rp = np.asarray(recession_proxy, dtype=float)
        if len(rp) != n:
            rp = pd.Series(rp).reindex(range(n)).ffill().bfill().fillna(0.0).to_numpy(dtype=float)
        rec = rp > 0.5

    dd = _drawdown_from_returns(r)
    cum_3m = pd.Series(np.nan_to_num(r, nan=0.0)).rolling(63, min_periods=20).sum().to_numpy(dtype=float)
    cum_6m = pd.Series(np.nan_to_num(r, nan=0.0)).rolling(126, min_periods=40).sum().to_numpy(dtype=float)

    enter_sig = (
        (dd <= -float(enter_drawdown)) |
        ((dd <= -max(0.16, float(enter_drawdown) - 0.03)) & (cum_6m <= -0.10)) |
        rec
    )
    hold_sig = (
        (dd <= -float(exit_drawdown)) |
        ((dd <= -max(0.08, float(exit_drawdown) - 0.02)) & (cum_3m <= -0.01)) |
        rec
    )

    in_bear = bool(enter_sig[0])
    mask = np.zeros(n, dtype=bool)
    mask[0] = in_bear
    trough_dd = float(dd[0]) if in_bear else 0.0
    for i in range(1, n):
        if not in_bear and enter_sig[i]:
            in_bear = True
            trough_dd = float(dd[i])
        elif in_bear:
            trough_dd = min(trough_dd, float(dd[i]))
            recovered_from_trough = float(dd[i] - trough_dd)
            base_exit = (
                (not hold_sig[i]) and
                dd[i] > -float(exit_drawdown) and
                (cum_3m[i] > 0.01 or vix[i] < 21.0)
            )
            # Exit prolonged post-crash recoveries before full peak recapture.
            trend_exit = (
                (not rec[i]) and
                recovered_from_trough >= 0.18 and
                cum_6m[i] > 0.06 and
                cum_3m[i] > -0.005
            )
            if base_exit or trend_exit:
                in_bear = False
                trough_dd = 0.0
        mask[i] = in_bear

    # Merge nearby spells separated by brief relief rallies.
    episodes = _extract_boolean_episodes(mask)
    if len(episodes) > 1 and max_join_gap > 0:
        merged: List[Tuple[int, int]] = []
        cur_s, cur_e = episodes[0]
        for s, e in episodes[1:]:
            if s - cur_e - 1 <= int(max_join_gap):
                cur_e = e
            else:
                merged.append((cur_s, cur_e))
                cur_s, cur_e = s, e
        merged.append((cur_s, cur_e))
        episodes = merged

    # Drop very short pseudo-bears.
    episodes = [(s, e) for s, e in episodes if (e - s + 1) >= int(min_spell)]
    return _episodes_to_mask(n, episodes)


def _calibrate_bear_mask_to_share(spy_returns: np.ndarray,
                                  vix_series: Optional[np.ndarray] = None,
                                  recession_proxy: Optional[np.ndarray] = None,
                                  target_share: float = BEAR_LABEL_TARGET_SHARE,
                                  max_share: float = BEAR_LABEL_MAX_SHARE,
                                  target_median_days: float = BEAR_LABEL_TARGET_MEDIAN_DAYS,
                                  max_median_days: float = BEAR_LABEL_MAX_MEDIAN_DAYS,
                                  target_p90_days: float = BEAR_LABEL_TARGET_P90_DAYS,
                                  max_p90_days: float = BEAR_LABEL_MAX_P90_DAYS,
                                  max_spell_days: float = BEAR_LABEL_MAX_SPELL_DAYS) -> Tuple[np.ndarray, Dict[str, Any]]:
    """
    Select bear-label hyperparameters with explicit frequency + duration control.

    Primary target: keep bear occupancy realistic while preventing overly persistent
    multi-year labels that distort volatility/drawdown/CAGR distributions.
    """
    def _mask_stats(mask_arr: np.ndarray) -> Dict[str, float]:
        m = np.asarray(mask_arr, dtype=bool)
        eps = _extract_boolean_episodes(m)
        lens = np.asarray([e - s + 1 for s, e in eps], dtype=float) if eps else np.array([])
        return {
            'share': float(np.mean(m)) if len(m) > 0 else 0.0,
            'episodes': int(len(eps)),
            'median_days': float(np.median(lens)) if len(lens) > 0 else 0.0,
            'p90_days': float(np.percentile(lens, 90)) if len(lens) > 0 else 0.0,
            'max_days': float(np.max(lens)) if len(lens) > 0 else 0.0
        }

    def _apply_hard_caps(mask_arr: np.ndarray) -> Tuple[np.ndarray, Dict[str, Any]]:
        """
        Last-resort occupancy/duration control for walk-forward stability.
        Keeps deepest bear episodes first, then trims to share and max-spell caps.
        """
        m = np.asarray(mask_arr, dtype=bool).copy()
        n = int(len(m))
        if n == 0:
            return m, {'applied': False}

        cap_len = int(max(1, np.floor(float(max_share) * n)))
        dd = _drawdown_from_returns(np.asarray(spy_returns, dtype=float))
        episodes = _extract_boolean_episodes(m)
        if len(episodes) == 0:
            return m, {'applied': False}

        rows = []
        for s, e in episodes:
            seg = dd[s:e + 1]
            trough_rel = int(np.nanargmin(seg)) if len(seg) > 0 else 0
            rows.append({
                's': int(s),
                'e': int(e),
                'len': int(e - s + 1),
                'trough': int(s + trough_rel),
                'depth': float(abs(np.nanmin(seg))) if len(seg) > 0 else 0.0
            })

        rows.sort(key=lambda r: (r['depth'], r['len']), reverse=True)
        kept: List[Tuple[int, int]] = []
        used = 0
        applied = False
        min_keep = int(max(20, MIN_REGIME_DURATION.get(REGIME_BEAR, 45)))
        max_spell = int(max(40, round(float(max_spell_days))))

        for row in rows:
            if used >= cap_len:
                break
            remain = cap_len - used
            keep_len = int(min(row['len'], max_spell))
            if keep_len > remain:
                keep_len = int(max(min_keep, remain))
                keep_len = int(min(keep_len, row['len'], max_spell))
            if keep_len <= 0:
                continue
            if keep_len < row['len']:
                applied = True
            trough = int(row['trough'])
            half = keep_len // 2
            ks = int(max(row['s'], trough - half))
            ke = int(ks + keep_len - 1)
            if ke > row['e']:
                ke = int(row['e'])
                ks = int(max(row['s'], ke - keep_len + 1))
            kept.append((ks, ke))
            used += int(ke - ks + 1)

        if len(kept) == 0:
            return m, {'applied': False}

        m_new = _episodes_to_mask(n, kept)
        if np.sum(m_new) < np.sum(m):
            applied = True

        st = _mask_stats(m_new)
        return m_new, {
            'applied': bool(applied),
            'share': float(st['share']),
            'episodes': int(st['episodes']),
            'median_days': float(st['median_days']),
            'p90_days': float(st['p90_days']),
            'max_days': float(st['max_days']),
            'cap_len_days': int(cap_len),
            'kept_days': int(np.sum(m_new))
        }

    candidates = list(BEAR_LABEL_CANDIDATES)
    best_mask = None
    best_diag = None
    best_score = float('inf')
    best_feasible_score = float('inf')
    best_feasible = None
    best_feasible_diag = None

    for enter_dd, exit_dd, min_spell, join_gap in candidates:
        mask = _identify_bear_market_mask(
            spy_returns=spy_returns,
            vix_series=vix_series,
            recession_proxy=recession_proxy,
            enter_drawdown=float(enter_dd),
            exit_drawdown=float(exit_dd),
            min_spell=int(min_spell),
            max_join_gap=int(join_gap)
        )
        share = float(np.mean(mask)) if len(mask) > 0 else 0.0
        episodes = _extract_boolean_episodes(mask)
        lens = np.array([e - s + 1 for s, e in episodes], dtype=float) if episodes else np.array([])
        med_days = float(np.median(lens)) if len(lens) > 0 else 0.0
        p90_days = float(np.percentile(lens, 90)) if len(lens) > 0 else 0.0
        max_days = float(np.max(lens)) if len(lens) > 0 else 0.0

        # Composite score:
        # - share error anchors occupancy
        # - median/p90 penalties discourage unrealistic persistence
        # - hard-overbound penalties strongly penalize gate violations
        # - tiny episode-count penalty avoids degenerate 1-2 giant spells
        share_error = abs(share - float(target_share))
        median_error = abs(med_days - float(target_median_days)) / max(float(target_median_days), 1.0)
        p90_error = abs(p90_days - float(target_p90_days)) / max(float(target_p90_days), 1.0)
        median_over = max(0.0, med_days - float(max_median_days)) / max(float(max_median_days), 1.0)
        p90_over = max(0.0, p90_days - float(max_p90_days)) / max(float(max_p90_days), 1.0)
        max_over = max(0.0, max_days - float(max_spell_days)) / max(float(max_spell_days), 1.0)
        episodes_penalty = max(0.0, 3.0 - float(len(episodes))) / 3.0

        score = (
            1.00 * share_error +
            0.35 * median_error +
            0.25 * p90_error +
            1.10 * median_over +
            0.80 * p90_over +
            0.35 * max_over +
            0.10 * episodes_penalty
        )
        diag = {
            'enter_drawdown': float(enter_dd),
            'exit_drawdown': float(exit_dd),
            'min_spell': int(min_spell),
            'max_join_gap': int(join_gap),
            'share': float(share),
            'episodes': int(len(episodes)),
            'median_days': float(med_days),
            'p90_days': float(p90_days),
            'max_days': float(max_days),
            'objective_terms': {
                'share_error': float(share_error),
                'median_error': float(median_error),
                'p90_error': float(p90_error),
                'median_over': float(median_over),
                'p90_over': float(p90_over),
                'max_over': float(max_over),
                'episodes_penalty': float(episodes_penalty)
            }
        }
        if score < best_score:
            best_score = score
            best_mask = mask
            best_diag = diag
        if (share <= float(max_share)
                and med_days <= float(max_median_days)
                and p90_days <= float(max_p90_days)
                and max_days <= float(max_spell_days)):
            feasible_score = (
                abs(share - float(target_share))
                + 0.30 * abs(med_days - float(target_median_days)) / max(float(target_median_days), 1.0)
                + 0.20 * abs(p90_days - float(target_p90_days)) / max(float(target_p90_days), 1.0)
            )
            if feasible_score < best_feasible_score:
                best_feasible_score = feasible_score
                best_feasible = mask
                best_feasible_diag = diag

    if best_feasible is not None:
        out_mask = np.asarray(best_feasible, dtype=bool)
        out_diag = dict(best_feasible_diag) if isinstance(best_feasible_diag, dict) else {}
    else:
        out_mask = np.asarray(
            best_mask if best_mask is not None else np.zeros(len(np.asarray(spy_returns)), dtype=bool),
            dtype=bool
        )
        out_diag = dict(best_diag) if isinstance(best_diag, dict) else {}

    st0 = _mask_stats(out_mask)
    needs_cap = bool(
        st0['share'] > float(max_share) or
        st0['median_days'] > float(max_median_days) or
        st0['p90_days'] > float(max_p90_days) or
        st0['max_days'] > float(max_spell_days)
    )
    if needs_cap:
        capped_mask, cap_diag = _apply_hard_caps(out_mask)
        if bool(cap_diag.get('applied', False)):
            out_mask = np.asarray(capped_mask, dtype=bool)
            out_diag['hard_cap_applied'] = True
            out_diag['hard_cap_details'] = cap_diag
            st1 = _mask_stats(out_mask)
            out_diag['share'] = float(st1['share'])
            out_diag['episodes'] = int(st1['episodes'])
            out_diag['median_days'] = float(st1['median_days'])
            out_diag['p90_days'] = float(st1['p90_days'])
            out_diag['max_days'] = float(st1['max_days'])

    return out_mask, out_diag


def fill_missing_with_dynamic_factor(df: pd.DataFrame, target_col: str, factor_col: str,
                                     default_beta: float, seed: int = 1234) -> pd.Series:
    """Fill missing returns using overlap-calibrated dynamic beta + residual sampling."""
    if target_col not in df.columns:
        df[target_col] = np.nan

    target = df[target_col].copy()
    factor = df[factor_col].copy()

    valid = target.notna() & factor.notna()
    if valid.sum() < 40:
        return target.fillna(default_beta * factor)

    cov = target.rolling(252, min_periods=40).cov(factor)
    var = factor.rolling(252, min_periods=40).var()
    beta = (cov / var.replace(0, np.nan)).replace([np.inf, -np.inf], np.nan)
    beta = beta.clip(-3.0, 3.0).ffill().bfill().fillna(default_beta)

    alpha = (target - beta * factor).rolling(252, min_periods=40).mean()
    alpha = alpha.ffill().bfill().fillna(0.0)

    fitted = alpha + beta * factor
    residuals = (target - fitted)[valid].dropna().values
    missing = target.isna() & factor.notna()

    if len(residuals) > 20 and missing.any():
        rng = np.random.default_rng(seed)
        sampled_resid = rng.choice(residuals, size=missing.sum(), replace=True)
        target.loc[missing] = fitted.loc[missing].values + sampled_resid
    else:
        target.loc[missing] = fitted.loc[missing]

    return target

# ============================================================================
# DYNAMIC BORROWING COST CALCULATION
# ============================================================================

def calculate_daily_borrow_cost(leverage: float, risk_free_rate: float,
                                 spread: float) -> float:
    """
    Calculate the daily financing cost for a leveraged ETF.
    
    HOW LEVERAGED ETFs WORK:
    - Financing drag is modeled on the financed portion only ((L-1)× capital),
      then a calibrated spread is added as a separate annual deduction.
    - A 1x fund (like SPY) still incurs no financing cost here.

    The financing cost is:
        annual_cost = (leverage - 1) × risk_free_rate + spread
        daily_cost = annual_cost / 252
    
    Args:
        leverage: The fund's leverage ratio (e.g., 3.0 for TQQQ)
        risk_free_rate: Annual risk-free rate as decimal (e.g., 0.05 for 5%)
        spread: Annual spread above risk-free rate (e.g., 0.0075 for 0.75%)
    
    Returns:
        Daily borrowing cost as a decimal (e.g., 0.0002 for 2 bps/day)
    
    Example:
        # TQQQ with 5% rates and 0.75% spread:
        # Financing drag = 2 × 5.00% + 0.75% = 10.75% annual drag
        # Daily: 10.75% / 252 = 0.0427% per day
        
        daily_cost = calculate_daily_borrow_cost(3.0, 0.05, 0.0075)
        # Returns: 0.000456 (about 4.6 bps per day)
    """
    
    # If no leverage (1x fund), no financing cost in this helper.
    if leverage <= 1.0:
        return 0.0

    annual_cost = (leverage - 1.0) * risk_free_rate + spread

    # Convert to daily (252 trading days)
    daily_cost = annual_cost / 252
    
    return daily_cost


def get_borrow_cost_series(df: pd.DataFrame, leverage: float, 
                           spread: float) -> pd.Series:
    """
    Create a time series of daily borrowing costs based on historical rates.
    
    This uses the IRX (3-month T-bill rate) as a proxy for SOFR/short-term rates.
    
    Args:
        df: DataFrame with 'IRX' column (interest rate in percentage, e.g., 5.0 for 5%)
        leverage: Fund's leverage ratio
        spread: Annual spread above risk-free rate
    
    Returns:
        Series of daily borrowing costs (as decimals)
    """
    
    # IRX is in percentage points (e.g., 5.0 means 5%)
    # Convert to decimal (0.05)
    risk_free_rate = df['IRX'] / 100.0
    
    # Calculate daily borrow cost for each day
    borrowed_leverage = leverage - 1.0
    
    if borrowed_leverage <= 0:
        return pd.Series(0.0, index=df.index)
    
    # Annual cost = borrowed_leverage × (risk_free + spread)
    annual_cost = borrowed_leverage * (risk_free_rate + spread)
    
    # Daily cost
    daily_cost = annual_cost / 252
    
    return daily_cost

