def calculate_historical_rolling_cagrs(df: pd.DataFrame, asset: str, 
                                        years: int, 
                                        step_days: int = 21) -> Dict:
    """
    Calculate all rolling N-year CAGRs from historical data.
    
    This gives us the ACTUAL distribution of historical returns, which we can
    compare against our simulated distribution.
    
    Args:
        df: Historical DataFrame with price columns
        asset: Asset name (e.g., 'SPY', 'TQQQ', 'SSO')
        years: Rolling window in years (e.g., 10 for 10-year CAGR)
        step_days: Days between each calculation (21 = monthly, 1 = daily)
    
    Returns:
        Dict with:
        - 'cagrs': List of all rolling CAGRs
        - 'start_dates': Corresponding start dates
        - 'end_dates': Corresponding end dates
        - 'percentiles': Dict of percentile values
        - 'stats': Basic statistics
    
    Example:
        For 10-year horizon with 20 years of data:
        - Start at day 0, end at day 2520 -> first 10-year CAGR
        - Start at day 21, end at day 2541 -> second 10-year CAGR
        - ... continue until we run out of data
    """
    price_col = f'{asset}_Price'
    synthetic_col = f'{asset}_IsSynthetic'
    
    if price_col not in df.columns:
        print(f"  Warning: {asset}: Price column not found")
        return None
    
    # Use only REAL data if synthetic column exists
    if synthetic_col in df.columns:
        df_real = df[~df[synthetic_col]].copy()
        data_type = "REAL"
    else:
        df_real = df.copy()
        data_type = "ALL"
    
    window_days = int(years * 252)
    
    if len(df_real) < window_days:
        print(f"  Warning: {asset}: Insufficient {data_type} data "
              f"({len(df_real)/252:.2f}Y available, {years}Y needed)")
        return None
    
    # Resolve return column for rolling window volatility diagnostics.
    # Use underlying-market volatility for matching simulation path features.
    # Leveraged ETFs should be matched on driver volatility (SPY/QQQ), not
    # leveraged product volatility, to avoid deterministic leverage inflation.
    ret_col_candidates = []
    if asset in ['TQQQ', 'QLD']:
        ret_col_candidates.extend(['QQQ_Ret', 'QQQ_Real_Ret'])
    else:
        ret_col_candidates.extend(['SPY_Ret', 'SPY_Real_Ret'])
    ret_col_candidates.extend([f'{asset}_Real_Ret', f'{asset}_Ret'])
    ret_col = next((c for c in ret_col_candidates if c in df_real.columns), None)
    ret_values = df_real[ret_col].to_numpy(dtype=float) if ret_col is not None else None

    # Calculate rolling CAGRs
    cagrs = []
    start_dates = []
    end_dates = []
    window_ann_vols = []
    
    prices = df_real[price_col].values
    dates = df_real.index
    
    for start_idx in range(0, len(df_real) - window_days + 1, step_days):
        end_idx = start_idx + window_days - 1
        
        start_price = prices[start_idx]
        end_price = prices[end_idx]
        
        if start_price > 0 and end_price > 0:
            # Calculate CAGR
            total_return = end_price / start_price
            cagr = total_return ** (1/years) - 1
            
            cagrs.append(cagr)
            start_dates.append(dates[start_idx])
            end_dates.append(dates[end_idx])
            if ret_values is not None:
                window_rets = ret_values[start_idx:end_idx + 1]
                if len(window_rets) > 1:
                    window_ann_vols.append(float(np.nanstd(window_rets, ddof=1) * np.sqrt(252)))
                else:
                    window_ann_vols.append(float('nan'))
            else:
                window_ann_vols.append(float('nan'))
    
    if len(cagrs) == 0:
        print(f"  Warning: {asset}: No valid rolling periods found")
        return None
    
    cagrs = np.array(cagrs)
    window_ann_vols = np.asarray(window_ann_vols, dtype=float)
    
    # Calculate percentiles
    percentiles = {
        'p5': np.percentile(cagrs, 5),
        'p10': np.percentile(cagrs, 10),
        'p25': np.percentile(cagrs, 25),
        'p50': np.percentile(cagrs, 50),
        'p75': np.percentile(cagrs, 75),
        'p90': np.percentile(cagrs, 90),
        'p95': np.percentile(cagrs, 95)
    }
    
    # Basic stats
    stats = {
        'mean': np.mean(cagrs),
        'median': np.median(cagrs),
        'std': np.std(cagrs),
        'min': np.min(cagrs),
        'max': np.max(cagrs),
        'count': len(cagrs),
        'data_type': data_type
    }
    if np.any(np.isfinite(window_ann_vols)):
        stats['window_ann_vol_median'] = float(np.nanmedian(window_ann_vols))
        stats['window_ann_vol_p25'] = float(np.nanpercentile(window_ann_vols, 25))
        stats['window_ann_vol_p75'] = float(np.nanpercentile(window_ann_vols, 75))
    
    return {
        'cagrs': cagrs,
        'start_dates': start_dates,
        'end_dates': end_dates,
        'window_ann_vols': window_ann_vols,
        'percentiles': percentiles,
        'stats': stats,
        'years': years,
        'asset': asset
    }


def find_percentile_rank(value: float, distribution: np.ndarray) -> float:
    """
    Find what percentile a value would be in a distribution.
    
    Args:
        value: The value to rank
        distribution: Array of values defining the distribution
    
    Returns:
        Percentile rank (0-100)
    
    Example:
        If value is greater than 75% of distribution, returns ~75
    """
    if len(distribution) == 0:
        return 50.0
    
    # Count how many values are less than or equal to the given value
    rank = np.sum(distribution <= value) / len(distribution) * 100
    
    return rank


def calculate_distribution_overlap(dist1: np.ndarray, dist2: np.ndarray, 
                                   n_bins: int = 50) -> float:
    """
    Calculate the overlap between two distributions.
    
    Uses histogram intersection - a simple and intuitive measure.
    100% = identical distributions, 0% = no overlap.
    
    Args:
        dist1: First distribution (e.g., historical CAGRs)
        dist2: Second distribution (e.g., simulated CAGRs)
        n_bins: Number of bins for histogram
    
    Returns:
        Overlap percentage (0-100)
    """
    # Determine common range
    min_val = min(np.min(dist1), np.min(dist2))
    max_val = max(np.max(dist1), np.max(dist2))
    
    # Create histograms with same bins
    bins = np.linspace(min_val, max_val, n_bins + 1)
    
    hist1, _ = np.histogram(dist1, bins=bins, density=True)
    hist2, _ = np.histogram(dist2, bins=bins, density=True)
    
    # Normalize to sum to 1
    hist1 = hist1 / hist1.sum() if hist1.sum() > 0 else hist1
    hist2 = hist2 / hist2.sum() if hist2.sum() > 0 else hist2
    
    # Calculate intersection (minimum at each bin)
    overlap = np.sum(np.minimum(hist1, hist2)) * 100
    
    return overlap


def calculate_percentile_correlation(hist_percentiles: Dict, 
                                     sim_percentiles: Dict) -> Tuple[float, float]:
    """
    Calculate correlation between historical and simulated percentile curves.
    
    This measures whether the SHAPE of the distributions match, not just
    the absolute values.
    
    Args:
        hist_percentiles: Dict with p5, p10, p25, p50, p75, p90, p95 from historical
        sim_percentiles: Dict with same keys from simulation
    
    Returns:
        Tuple of (pearson_correlation, spearman_correlation)
    """
    from scipy.stats import pearsonr, spearmanr
    
    # Extract percentile values in order
    pct_keys = ['p5', 'p10', 'p25', 'p50', 'p75', 'p90', 'p95']
    
    hist_values = [hist_percentiles.get(k, 0) for k in pct_keys]
    sim_values = [sim_percentiles.get(k, 0) for k in pct_keys]
    
    # Calculate correlations
    if len(set(hist_values)) > 1 and len(set(sim_values)) > 1:
        pearson_r, _ = pearsonr(hist_values, sim_values)
        spearman_r, _ = spearmanr(hist_values, sim_values)
    else:
        pearson_r = 0.0
        spearman_r = 0.0
    
    return pearson_r, spearman_r


def calculate_distribution_distance_metrics(ref_dist: np.ndarray,
                                            sim_dist: np.ndarray,
                                            ref_percentiles: Dict,
                                            sim_percentiles: Dict) -> Dict[str, float]:
    """Distance metrics beyond rank correlation: KS, Wasserstein, and tail error."""
    from scipy.stats import ks_2samp, wasserstein_distance

    ks_stat, ks_p = ks_2samp(ref_dist, sim_dist)
    w_dist = float(wasserstein_distance(ref_dist, sim_dist))
    tail_error = 0.5 * (
        abs(float(sim_percentiles.get('p5', 0.0)) - float(ref_percentiles.get('p5', 0.0))) +
        abs(float(sim_percentiles.get('p95', 0.0)) - float(ref_percentiles.get('p95', 0.0)))
    )
    return {
        'ks_stat': float(ks_stat),
        'ks_pvalue': float(ks_p),
        'wasserstein': w_dist,
        'tail_error_p5_p95': float(tail_error)
    }


def rebalance_reference_windows(cagrs: np.ndarray,
                                includes_synthetic: Optional[np.ndarray],
                                target_synth_pct: float = 65.0,
                                min_real_windows: int = 24,
                                seed: int = 12345) -> Dict[str, Any]:
    """
    Rebalance reference windows so combined validation is not mechanically dominated
    by synthetic history when long pre-inception spans are included.

    Returns both raw and effective synthetic shares.
    """
    arr = np.asarray(cagrs, dtype=float)
    arr = arr[np.isfinite(arr)]
    if arr.size == 0 or includes_synthetic is None:
        return {
            'cagrs': arr,
            'includes_synthetic': None,
            'raw_synth_pct': float('nan'),
            'effective_synth_pct': float('nan'),
            'rebalanced': False
        }

    flags = np.asarray(includes_synthetic, dtype=bool)
    if flags.size != len(cagrs):
        return {
            'cagrs': arr,
            'includes_synthetic': None,
            'raw_synth_pct': float('nan'),
            'effective_synth_pct': float('nan'),
            'rebalanced': False
        }

    # Keep finite-aligned subset only.
    finite_mask = np.isfinite(np.asarray(cagrs, dtype=float))
    arr = np.asarray(cagrs, dtype=float)[finite_mask]
    flags = flags[finite_mask]

    raw_pct = float(np.mean(flags) * 100.0) if len(flags) else float('nan')
    if len(flags) == 0:
        return {
            'cagrs': arr,
            'includes_synthetic': flags,
            'raw_synth_pct': raw_pct,
            'effective_synth_pct': raw_pct,
            'rebalanced': False
        }

    synth_idx = np.where(flags)[0]
    real_idx = np.where(~flags)[0]
    n_real = int(len(real_idx))
    n_synth = int(len(synth_idx))

    # If already balanced enough or not enough real windows, keep raw.
    if raw_pct <= float(target_synth_pct) or n_real < int(min_real_windows) or n_synth == 0:
        return {
            'cagrs': arr,
            'includes_synthetic': flags,
            'raw_synth_pct': raw_pct,
            'effective_synth_pct': raw_pct,
            'rebalanced': False
        }

    # Keep all real windows; downsample synthetic windows to hit target share.
    target = float(np.clip(target_synth_pct, 5.0, 95.0))
    n_synth_keep = int(round(n_real * target / max(100.0 - target, 1e-9)))
    n_synth_keep = int(np.clip(n_synth_keep, 1, n_synth))

    rng = np.random.default_rng(int(seed + len(arr) + n_real * 17 + n_synth * 31))
    keep_synth = np.sort(rng.choice(synth_idx, size=n_synth_keep, replace=False))
    keep_idx = np.sort(np.concatenate([real_idx, keep_synth]))

    eff_arr = arr[keep_idx]
    eff_flags = flags[keep_idx]
    eff_pct = float(np.mean(eff_flags) * 100.0) if len(eff_flags) else float('nan')

    return {
        'cagrs': eff_arr,
        'includes_synthetic': eff_flags,
        'raw_synth_pct': raw_pct,
        'effective_synth_pct': eff_pct,
        'rebalanced': True
    }


def bootstrap_percentile_confidence_bands(samples: np.ndarray,
                                          percentiles: Tuple[int, ...] = (5, 10, 25, 50, 75, 90, 95),
                                          ci: float = 0.90,
                                          n_boot: int = 600,
                                          seed: int = 12345) -> Dict[str, Dict[str, float]]:
    """Bootstrap confidence bands for sample percentiles."""
    arr = np.asarray(samples, dtype=float)
    arr = arr[np.isfinite(arr)]
    if len(arr) == 0:
        return {}

    if len(arr) < 6:
        return {
            f"p{p}": {'lo': float(np.nanmin(arr)), 'hi': float(np.nanmax(arr)), 'est': float(np.percentile(arr, p))}
            for p in percentiles
        }

    alpha = max(0.001, min(0.499, (1.0 - float(ci)) / 2.0))
    rng = np.random.default_rng(seed + len(arr))
    idx = rng.integers(0, len(arr), size=(int(n_boot), len(arr)))
    boot = arr[idx]

    out = {}
    for p in percentiles:
        bvals = np.percentile(boot, p, axis=1)
        out[f"p{p}"] = {
            'lo': float(np.percentile(bvals, alpha * 100.0)),
            'hi': float(np.percentile(bvals, (1.0 - alpha) * 100.0)),
            'est': float(np.percentile(arr, p))
        }
    return out


def _estimate_real_period_crisis_share(df: pd.DataFrame, asset: str) -> float:
    """
    Estimate stress-share for the asset's real (non-synthetic) period using the
    calibrated regime classifier.
    """
    synthetic_col = f'{asset}_IsSynthetic'
    if synthetic_col in df.columns:
        df_real = df[~df[synthetic_col].fillna(False)].copy()
    else:
        df_real = df.copy()

    if len(df_real) < 252:
        return float('nan')

    rv = df_real['SPY_Ret'].rolling(20, min_periods=5).std().bfill().fillna(0).values * np.sqrt(252)
    ts = (df_real['TNX'] - df_real['IRX']).values if 'TNX' in df_real.columns and 'IRX' in df_real.columns else None
    regs = infer_regime_from_vix(
        vix_series=df_real['VIX'].values,
        realized_vol=rv,
        term_spread=ts,
        logit_shift=0.0,
        logit_params=STRESS_LOGIT_PARAMS,
        spy_returns=df_real['SPY_Ret'].values,
        recession_proxy=df_real['USREC'].values if 'USREC' in df_real.columns else None
    )
    if len(regs) == 0:
        return float('nan')
    return _stress_share(np.asarray(regs, dtype=int))


def select_simulated_cagrs_by_crisis_mix(sim_results: List[Dict[str, Any]],
                                         time_horizon: int,
                                         target_crisis_share: float,
                                         target_annual_vol: Optional[float] = None,
                                         vol_feature_key: str = 'spy_ann_vol',
                                         target_anchor_buckets: Optional[List[int]] = None,
                                         anchor_bucket_width: int = 5,
                                         min_keep: int = 20,
                                         component_weights: Optional[Dict[str, float]] = None,
                                         base_tolerance: float = 0.05,
                                         max_tolerance: float = 0.30) -> Tuple[np.ndarray, Dict[str, Any]]:
    """
    Select simulated paths by nearest composite match on:
    - stress share
    - annualized volatility
    - start-era bucket (anchor year bucket)
    Volatility component reads from per-path metadata key `vol_feature_key`.

    Uses nearest-neighbor selection (no tolerance-expansion fallback).
    """
    _ = base_tolerance
    _ = max_tolerance

    rows = []
    for r in sim_results:
        if r.get('status', 'success') == 'error':
            continue
        fw = r.get('Final_Wealth', None)
        rp = r.get('Regime_Path', None)
        if fw is None or fw <= 0 or rp is None:
            continue

        rp_arr = np.asarray(rp, dtype=int)
        crisis_share = _stress_share(rp_arr) if len(rp_arr) else float('nan')
        cagr = float((float(fw) / INITIAL_CAPITAL) ** (1 / time_horizon) - 1)

        meta = r.get('Metadata', {}) if isinstance(r, dict) else {}
        path_features = meta.get('path_features', {}) if isinstance(meta, dict) else {}
        sim_ann_vol = float(path_features.get(vol_feature_key, np.nan)) if isinstance(path_features, dict) else float('nan')

        anchor_year = float('nan')
        if isinstance(path_features, dict) and path_features.get('anchor_year', None) is not None:
            try:
                anchor_year = float(path_features.get('anchor_year'))
            except Exception:
                anchor_year = float('nan')
        elif isinstance(meta, dict) and meta.get('anchor_date', None) is not None:
            try:
                anchor_year = float(pd.Timestamp(meta.get('anchor_date')).year)
            except Exception:
                anchor_year = float('nan')

        rows.append({
            'cagr': cagr,
            'crisis_share': float(crisis_share),
            'ann_vol': float(sim_ann_vol),
            'anchor_year': float(anchor_year)
        })

    if not rows:
        return np.array([], dtype=float), {
            'used_filter': False,
            'kept': 0,
            'total': 0,
            'reason': 'no_valid_sim_paths'
        }

    cagrs = np.asarray([x['cagr'] for x in rows], dtype=float)
    crisis = np.asarray([x['crisis_share'] for x in rows], dtype=float)
    ann_vol = np.asarray([x['ann_vol'] for x in rows], dtype=float)
    anchor_year = np.asarray([x['anchor_year'] for x in rows], dtype=float)
    total = int(len(cagrs))

    use_stress = np.isfinite(float(target_crisis_share))
    use_vol = np.isfinite(float(target_annual_vol)) if target_annual_vol is not None else False
    use_era = bool(target_anchor_buckets and len(target_anchor_buckets) > 0)
    if not (use_stress or use_vol or use_era):
        return cagrs, {
            'used_filter': False,
            'kept': total,
            'total': total,
            'reason': 'no_finite_targets'
        }

    weights = {'stress': 0.55, 'vol': 0.30, 'era': 0.15}
    if isinstance(component_weights, dict):
        for k in ['stress', 'vol', 'era']:
            if k in component_weights and np.isfinite(float(component_weights[k])):
                weights[k] = float(max(0.0, component_weights[k]))

    if not use_stress:
        weights['stress'] = 0.0
    if not use_vol:
        weights['vol'] = 0.0
    if not use_era:
        weights['era'] = 0.0
    w_sum = max(weights['stress'] + weights['vol'] + weights['era'], 1e-12)
    weights = {k: v / w_sum for k, v in weights.items()}

    stress_dist = np.zeros(total, dtype=float)
    if use_stress:
        stress_dist = np.abs(crisis - float(target_crisis_share)) / 0.10
        stress_dist = np.where(np.isfinite(stress_dist), stress_dist, 3.0)

    vol_dist = np.zeros(total, dtype=float)
    if use_vol:
        vol_scale = max(float(target_annual_vol), 0.08)
        vol_dist = np.abs(ann_vol - float(target_annual_vol)) / vol_scale
        vol_dist = np.where(np.isfinite(vol_dist), vol_dist, 3.0)

    era_dist = np.zeros(total, dtype=float)
    if use_era:
        bucket_width = max(1, int(anchor_bucket_width))
        target_buckets = sorted(set(int(b) for b in target_anchor_buckets))
        for i in range(total):
            y = anchor_year[i]
            if not np.isfinite(y):
                era_dist[i] = 3.0
                continue
            by = int(y) // bucket_width * bucket_width
            era_dist[i] = min(abs(by - tb) for tb in target_buckets) / float(bucket_width)

    composite = (
        weights['stress'] * stress_dist +
        weights['vol'] * vol_dist +
        weights['era'] * era_dist
    )
    composite = np.where(np.isfinite(composite), composite, 9.0)

    # Avoid over-pruning when total MC paths are small (e.g., 50 runs).
    # Extremely small selected subsets produce unstable percentile estimates and
    # can create artificial underfit signals for leveraged assets.
    adaptive_floor = int(np.ceil(0.60 * total)) if total <= 120 else int(min_keep)
    keep_n = int(max(1, min(total, max(int(min_keep), adaptive_floor))))
    nearest_idx = np.argsort(composite)[:keep_n]
    nearest_idx = np.sort(nearest_idx)

    selected = cagrs[nearest_idx]
    selected_crisis = crisis[nearest_idx]
    selected_vol = ann_vol[nearest_idx]
    selected_year = anchor_year[nearest_idx]
    selected_comp = composite[nearest_idx]

    diag = {
        'used_filter': bool(keep_n < total),
        'selection_mode': 'composite_nearest',
        'kept': int(len(nearest_idx)),
        'total': total,
        'keep_fraction': float(len(nearest_idx) / max(total, 1)),
        'target_crisis_share': float(target_crisis_share) if use_stress else None,
        'target_annual_vol': float(target_annual_vol) if use_vol else None,
        'target_anchor_buckets': sorted(set(int(b) for b in target_anchor_buckets)) if use_era else None,
        'selected_crisis_share_mean': float(np.nanmean(selected_crisis)) if len(selected_crisis) > 0 else None,
        'selected_ann_vol_mean': float(np.nanmean(selected_vol)) if np.any(np.isfinite(selected_vol)) else None,
        'selected_anchor_year_median': float(np.nanmedian(selected_year)) if np.any(np.isfinite(selected_year)) else None,
        'selected_composite_score_median': float(np.nanmedian(selected_comp)) if len(selected_comp) > 0 else None,
        'selected_stress_abs_error_pp_median': (
            float(np.nanmedian(np.abs(selected_crisis - float(target_crisis_share))) * 100.0)
            if use_stress and len(selected_crisis) > 0 else None
        ),
        'selected_vol_abs_error_pp_median': (
            float(np.nanmedian(np.abs(selected_vol - float(target_annual_vol))) * 100.0)
            if use_vol and np.any(np.isfinite(selected_vol)) else None
        )
    }
    return selected, diag


def compare_simulated_vs_historical(df: pd.DataFrame, mc_results: Dict,
                                    time_horizon: int,
                                    use_crisis_mix_filter: bool = True) -> Dict:
    """
    Comprehensive comparison of simulated vs historical returns.
    
    This is the main function that:
    1. Calculates rolling historical CAGRs
    2. Extracts simulated CAGRs from Monte Carlo results
    3. Compares the distributions
    4. Ranks historical performance in simulation (and vice versa)
    5. Calculates correlation metrics
    
    Args:
        df: Historical DataFrame
        mc_results: Monte Carlo results dict
        time_horizon: Simulation horizon in years
    
    Returns:
        Dict with comparison results for each asset
    """
    print(f"\n{'='*100}")
    print(f"HISTORICAL vs SIMULATED COMPARISON ({time_horizon}-YEAR HORIZON)")
    print(f"{'='*100}")
    print("\nThis compares your Monte Carlo simulations against actual historical rolling returns.")
    print("A good simulation should produce similar distributions to what actually happened.\n")
    
    comparison_results = {}
    
    # Map strategies to assets
    strategy_to_asset = {
        'S1': 'TQQQ',
        'S2': 'SPY',
        'S3': 'SSO',
        'S20': 'QLD',
        'S21': 'UPRO'
    }

    for sid, asset in strategy_to_asset.items():
        print(f"\n{'-'*80}")
        print(f"{asset} BUY & HOLD (Strategy {sid})")
        print(f"{'-'*80}")
        
        # ====================================================================
        # STEP 1: Get Historical Rolling CAGRs
        # ====================================================================
        historical = calculate_historical_rolling_cagrs(
            df, asset, time_horizon, step_days=21  # Monthly rolling windows
        )
        
        if historical is None:
            print(f"  Skipping {asset} - insufficient historical data")
            continue
        
        hist_cagrs = historical['cagrs']
        hist_percentiles = historical['percentiles']
        hist_stats = historical['stats']
        hist_window_vols = np.asarray(historical.get('window_ann_vols', np.array([])), dtype=float)
        target_ann_vol = float(np.nanmedian(hist_window_vols)) if np.any(np.isfinite(hist_window_vols)) else float('nan')
        hist_start_years = np.asarray([pd.Timestamp(d).year for d in historical.get('start_dates', [])], dtype=float)
        target_anchor_buckets = sorted(set((hist_start_years.astype(int) // 5 * 5).tolist())) if len(hist_start_years) > 0 else []
        
        print(f"\n  HISTORICAL DATA ({hist_stats['data_type']} only):")
        print(f"     Rolling {time_horizon}-year periods: {hist_stats['count']}")
        print(f"     CAGR Range: {hist_stats['min']*100:+.2f}% to {hist_stats['max']*100:+.2f}%")
        print(f"     CAGR Median: {hist_stats['median']*100:+.2f}%")
        print(f"     CAGR Std Dev: {hist_stats['std']*100:.2f}%")
        
        # ====================================================================
        # STEP 2: Get Simulated CAGRs
        # ====================================================================
        if sid not in mc_results or not mc_results[sid]:
            print(f"  No simulation results for {sid}")
            continue
        
        sim_results = mc_results[sid]
        if use_crisis_mix_filter:
            target_crisis_share = _estimate_real_period_crisis_share(df, asset)
            vol_feature_key = 'qqq_ann_vol' if asset in ['TQQQ', 'QLD'] else 'spy_ann_vol'
            sim_cagrs, crisis_filter_diag = select_simulated_cagrs_by_crisis_mix(
                sim_results=sim_results,
                time_horizon=time_horizon,
                target_crisis_share=target_crisis_share,
                target_annual_vol=target_ann_vol,
                vol_feature_key=vol_feature_key,
                target_anchor_buckets=target_anchor_buckets,
                anchor_bucket_width=5,
                min_keep=max(20, int(np.ceil(0.60 * len(sim_results)))),
                component_weights={'stress': 0.40, 'vol': 0.35, 'era': 0.25}
            )
        else:
            sim_cagrs = np.array([
                (float(r['Final_Wealth']) / INITIAL_CAPITAL) ** (1 / time_horizon) - 1
                for r in sim_results
                if r.get('status', 'success') != 'error'
                and r.get('Final_Wealth', None) is not None
                and r.get('Final_Wealth', 0) > 0
            ], dtype=float)
            crisis_filter_diag = {
                'used_filter': False,
                'tolerance': None,
                'kept': int(len(sim_cagrs)),
                'total': int(len(sim_cagrs)),
                'reason': 'disabled'
            }
        if len(sim_cagrs) == 0:
            print(f"  No valid simulation results for {sid}")
            continue
        if crisis_filter_diag.get('selection_mode') == 'composite_nearest':
            def _as_float(_v):
                try:
                    return float(_v)
                except Exception:
                    return float('nan')
            _t_stress = _as_float(crisis_filter_diag.get('target_crisis_share', np.nan))
            _s_stress = _as_float(crisis_filter_diag.get('selected_crisis_share_mean', np.nan))
            _t_vol = _as_float(crisis_filter_diag.get('target_annual_vol', np.nan))
            _s_vol = _as_float(crisis_filter_diag.get('selected_ann_vol_mean', np.nan))
            _s_year = _as_float(crisis_filter_diag.get('selected_anchor_year_median', np.nan))
            print(f"     Composite-matched sims: {crisis_filter_diag['kept']}/{crisis_filter_diag['total']} "
                  f"(stress target={_t_stress*100:.1f}% sel={_s_stress*100:.1f}%, "
                  f"vol target={_t_vol*100:.1f}% sel={_s_vol*100:.1f}%, "
                  f"anchor median year={_s_year:.0f})")
            if crisis_filter_diag.get('selected_stress_abs_error_pp_median') is not None:
                _stress_err = _as_float(crisis_filter_diag.get('selected_stress_abs_error_pp_median', np.nan))
                _vol_err = _as_float(crisis_filter_diag.get('selected_vol_abs_error_pp_median', np.nan))
                print(f"     Composite errors: stress |err| med="
                      f"{_stress_err:.1f}pp, "
                      f"vol |err| med={_vol_err:.1f}pp")
        elif crisis_filter_diag.get('used_filter', False):
            print(f"     Regime-mix matched sims: {crisis_filter_diag['kept']}/{crisis_filter_diag['total']}")
        else:
            if crisis_filter_diag.get('reason') == 'disabled':
                print(f"     Regime-mix filter disabled; using all {crisis_filter_diag.get('total', len(sim_cagrs))} sims")
            else:
                print(f"     Regime-mix matching unavailable; using all {crisis_filter_diag.get('total', len(sim_cagrs))} sims")
        
        sim_percentiles = {
            'p5': np.percentile(sim_cagrs, 5),
            'p10': np.percentile(sim_cagrs, 10),
            'p25': np.percentile(sim_cagrs, 25),
            'p50': np.percentile(sim_cagrs, 50),
            'p75': np.percentile(sim_cagrs, 75),
            'p90': np.percentile(sim_cagrs, 90),
            'p95': np.percentile(sim_cagrs, 95)
        }
        sim_percentile_ci = bootstrap_percentile_confidence_bands(sim_cagrs, ci=0.90, n_boot=600, seed=101)
        
        sim_stats = {
            'mean': np.mean(sim_cagrs),
            'median': np.median(sim_cagrs),
            'std': np.std(sim_cagrs),
            'min': np.min(sim_cagrs),
            'max': np.max(sim_cagrs),
            'count': len(sim_cagrs)
        }
        
        print(f"\n  SIMULATED DATA:")
        print(f"     Monte Carlo simulations: {sim_stats['count']}")
        print(f"     CAGR Range: {sim_stats['min']*100:+.2f}% to {sim_stats['max']*100:+.2f}%")
        print(f"     CAGR Median: {sim_stats['median']*100:+.2f}%")
        print(f"     CAGR Std Dev: {sim_stats['std']*100:.2f}%")
        if sim_percentile_ci:
            _p5 = sim_percentile_ci.get('p5', {})
            _p50 = sim_percentile_ci.get('p50', {})
            _p95 = sim_percentile_ci.get('p95', {})
            print(f"     90% CI (bootstrap): "
                  f"P5 [{_p5.get('lo', np.nan)*100:+.2f}%, {_p5.get('hi', np.nan)*100:+.2f}%], "
                  f"P50 [{_p50.get('lo', np.nan)*100:+.2f}%, {_p50.get('hi', np.nan)*100:+.2f}%], "
                  f"P95 [{_p95.get('lo', np.nan)*100:+.2f}%, {_p95.get('hi', np.nan)*100:+.2f}%]")
        
        # ====================================================================
        # STEP 3: Calculate Percentile Rankings
        # ====================================================================
        
        # Where does historical median rank in simulation?
        hist_median_in_sim = find_percentile_rank(hist_stats['median'], sim_cagrs)
        
        # Where does simulated median rank in history?
        sim_median_in_hist = find_percentile_rank(sim_stats['median'], hist_cagrs)
        
        print(f"\n  PERCENTILE RANKINGS:")
        print(f"     Historical median ({hist_stats['median']*100:+.2f}%) would be P{hist_median_in_sim:.0f} in simulation")
        print(f"     Simulated median ({sim_stats['median']*100:+.2f}%) would be P{sim_median_in_hist:.0f} in history")
        
        # ====================================================================
        # STEP 4: Calculate Distribution Metrics
        # ====================================================================
        
        # Overlap between distributions
        overlap = calculate_distribution_overlap(hist_cagrs, sim_cagrs)
        
        # Correlation between percentile curves
        pearson_r, spearman_r = calculate_percentile_correlation(
            hist_percentiles, sim_percentiles
        )
        dist_metrics = calculate_distribution_distance_metrics(
            ref_dist=hist_cagrs,
            sim_dist=sim_cagrs,
            ref_percentiles=hist_percentiles,
            sim_percentiles=sim_percentiles
        )
        
        # Median difference
        median_diff = sim_stats['median'] - hist_stats['median']
        median_diff_pct = median_diff / abs(hist_stats['median']) * 100 if hist_stats['median'] != 0 else 0
        
        print(f"\n  DISTRIBUTION COMPARISON:")
        print(f"     Distribution Overlap: {overlap:.2f}%")
        print(f"     Percentile Correlation (Pearson): {pearson_r:.3f}")
        print(f"     Percentile Correlation (Spearman): {spearman_r:.3f}")
        print(f"     KS Statistic: {dist_metrics['ks_stat']:.3f} (p={dist_metrics['ks_pvalue']:.3f})")
        print(f"     Wasserstein Distance: {dist_metrics['wasserstein']:.4f}")
        print(f"     Tail Error (avg |P5|,|P95| diff): {dist_metrics['tail_error_p5_p95']*100:.2f}%")
        print(f"     Median Difference: {median_diff*100:+.2f}% ({median_diff_pct:+.2f}% relative)")
        
        # ====================================================================
        # STEP 5: Print Percentile Comparison Table
        # ====================================================================
        
        print(f"\n  PERCENTILE COMPARISON TABLE:")
        print(f"     {'Percentile':<12} {'Historical':>12} {'Simulated':>12} {'Difference':>12}")
        print(f"     {'-'*48}")
        
        for pct_name in ['p5', 'p10', 'p25', 'p50', 'p75', 'p90', 'p95']:
            hist_val = hist_percentiles[pct_name] * 100
            sim_val = sim_percentiles[pct_name] * 100
            diff = sim_val - hist_val
            print(f"     {pct_name.upper():<12} {hist_val:>+11.2f}% {sim_val:>+11.2f}% {diff:>+11.2f}%")
        
        # ====================================================================
        # STEP 6: Quality Assessment
        # ====================================================================
        
        # Determine quality of simulation match
        quality_score = 0
        quality_notes = []
        
        # Check 1: Is historical median within P25-P75 of simulation?
        if 25 <= hist_median_in_sim <= 75:
            quality_score += 25
            quality_notes.append("OK: Historical median within simulation IQR")
        else:
            quality_notes.append("WARN: Historical median outside simulation IQR")
        
        # Check 2: Distribution overlap > 50%?
        if overlap > 50:
            quality_score += 25
            quality_notes.append(f"OK: Good distribution overlap ({overlap:.0f}%)")
        elif overlap > 25:
            quality_score += 10
            quality_notes.append(f"WARN: Moderate distribution overlap ({overlap:.0f}%)")
        else:
            quality_notes.append(f"BAD: Poor distribution overlap ({overlap:.0f}%)")
        
        # Check 3: KS distance (distributional fit)
        if dist_metrics['ks_stat'] < 0.20:
            quality_score += 25
            quality_notes.append(f"OK: KS statistic low ({dist_metrics['ks_stat']:.3f})")
        elif dist_metrics['ks_stat'] < 0.30:
            quality_score += 15
            quality_notes.append(f"WARN: KS statistic moderate ({dist_metrics['ks_stat']:.3f})")
        else:
            quality_notes.append(f"BAD: KS statistic high ({dist_metrics['ks_stat']:.3f})")

        # Check 4: Tail fit (P5/P95) + transport distance.
        if dist_metrics['tail_error_p5_p95'] < 0.05 and dist_metrics['wasserstein'] < 0.04:
            quality_score += 25
            quality_notes.append(
                f"OK: Tail/transport fit good (tail_err={dist_metrics['tail_error_p5_p95']*100:.2f}%, "
                f"wass={dist_metrics['wasserstein']:.4f})"
            )
        elif dist_metrics['tail_error_p5_p95'] < 0.08 and dist_metrics['wasserstein'] < 0.07:
            quality_score += 15
            quality_notes.append(
                f"WARN: Tail/transport fit moderate (tail_err={dist_metrics['tail_error_p5_p95']*100:.2f}%, "
                f"wass={dist_metrics['wasserstein']:.4f})"
            )
        else:
            quality_notes.append(
                f"BAD: Tail/transport mismatch (tail_err={dist_metrics['tail_error_p5_p95']*100:.2f}%, "
                f"wass={dist_metrics['wasserstein']:.4f})"
            )

        # Explicit attribution of quality-point losses.
        median_component = 25.0 if (25 <= hist_median_in_sim <= 75) else 0.0
        overlap_component = 25.0 if overlap > 50 else (10.0 if overlap > 25 else 0.0)
        ks_component = 25.0 if dist_metrics['ks_stat'] < 0.20 else (15.0 if dist_metrics['ks_stat'] < 0.30 else 0.0)
        tail_component = 25.0 if (dist_metrics['tail_error_p5_p95'] < 0.05 and dist_metrics['wasserstein'] < 0.04) else (
            15.0 if (dist_metrics['tail_error_p5_p95'] < 0.08 and dist_metrics['wasserstein'] < 0.07) else 0.0
        )
        error_attribution = {
            'median_penalty': float(25.0 - median_component),
            'overlap_penalty': float(25.0 - overlap_component),
            'ks_penalty': float(25.0 - ks_component),
            'tail_penalty': float(25.0 - tail_component),
            'total_penalty': float((25.0 - median_component) + (25.0 - overlap_component) + (25.0 - ks_component) + (25.0 - tail_component))
        }
        
        print(f"\n  SIMULATION QUALITY ASSESSMENT:")
        for note in quality_notes:
            print(f"     {note}")
        print(f"\n     Overall Score: {quality_score}/100", end="")
        
        if quality_score >= 80:
            print(" - EXCELLENT match to history")
        elif quality_score >= 60:
            print(" - GOOD match to history")
        elif quality_score >= 40:
            print(" - FAIR match to history (review assumptions)")
        else:
            print(" - POOR match to history (simulation may be unreliable)")
        
        # Store results
        comparison_results[asset] = {
            'historical': {
                'cagrs': hist_cagrs,
                'percentiles': hist_percentiles,
                'stats': hist_stats
            },
            'simulated': {
                'cagrs': sim_cagrs,
                'percentiles': sim_percentiles,
                'stats': sim_stats
            },
            'comparison': {
                'hist_median_percentile_in_sim': hist_median_in_sim,
                'sim_median_percentile_in_hist': sim_median_in_hist,
                'distribution_overlap': overlap,
                'pearson_correlation': pearson_r,
                'spearman_correlation': spearman_r,
                'crisis_mix_filter_used': bool(crisis_filter_diag.get('used_filter', False)),
                'ks_stat': dist_metrics['ks_stat'],
                'ks_pvalue': dist_metrics['ks_pvalue'],
                'wasserstein': dist_metrics['wasserstein'],
                'tail_error_p5_p95': dist_metrics['tail_error_p5_p95'],
                'median_difference': median_diff,
                'quality_score': quality_score,
                'error_attribution': error_attribution,
                'sim_percentile_ci': sim_percentile_ci
            }
        }
    
    # ========================================================================
    # OVERALL SUMMARY
    # ========================================================================
    
    print(f"\n{'='*100}")
    print("OVERALL SIMULATION VALIDATION SUMMARY")
    print(f"{'='*100}")
    
    if comparison_results:
        asset_rows = [r for r in comparison_results.values() if isinstance(r, dict) and 'comparison' in r]
        avg_quality = np.mean([r['comparison']['quality_score'] for r in asset_rows])
        avg_overlap = np.mean([r['comparison']['distribution_overlap'] for r in asset_rows])
        avg_corr = np.mean([r['comparison']['spearman_correlation'] for r in asset_rows])
        avg_ks = np.mean([r['comparison']['ks_stat'] for r in asset_rows])
        avg_tail = np.mean([r['comparison']['tail_error_p5_p95'] for r in asset_rows])
        core_rows = [
            r for r in asset_rows
            if int(((r.get('historical') or {}).get('stats') or {}).get('count', 0)) >= int(REAL_ONLY_CORE_MIN_WINDOWS)
        ]
        core_avg_quality = float(np.mean([r['comparison']['quality_score'] for r in core_rows])) if core_rows else float('nan')

        print(f"\n  Average Quality Score: {avg_quality:.0f}/100")
        print(f"  Average Distribution Overlap: {avg_overlap:.2f}%")
        print(f"  Average Percentile Correlation: {avg_corr:.3f}")
        print(f"  Average KS Statistic: {avg_ks:.3f}")
        print(f"  Average Tail Error (P5/P95): {avg_tail*100:.2f}%")

        attribution_rows = []
        for asset_name, row in comparison_results.items():
            if not (isinstance(row, dict) and 'comparison' in row):
                continue
            attr = (row.get('comparison') or {}).get('error_attribution', {})
            if not isinstance(attr, dict):
                continue
            attribution_rows.append({
                'asset': asset_name,
                'total_penalty': float(attr.get('total_penalty', np.nan)),
                'median_penalty': float(attr.get('median_penalty', np.nan)),
                'overlap_penalty': float(attr.get('overlap_penalty', np.nan)),
                'ks_penalty': float(attr.get('ks_penalty', np.nan)),
                'tail_penalty': float(attr.get('tail_penalty', np.nan))
            })
        attribution_rows = [r for r in attribution_rows if np.isfinite(r['total_penalty'])]
        attribution_rows.sort(key=lambda x: x['total_penalty'], reverse=True)
        if attribution_rows:
            print("\n  Real-Only Fit Attribution (quality-point penalties):")
            for r in attribution_rows:
                print(f"    {r['asset']}: total={r['total_penalty']:.1f} "
                      f"(median={r['median_penalty']:.1f}, overlap={r['overlap_penalty']:.1f}, "
                      f"ks={r['ks_penalty']:.1f}, tail={r['tail_penalty']:.1f})")
        if core_rows:
            print(f"  Core Real-Only Quality (>= {REAL_ONLY_CORE_MIN_WINDOWS} windows): "
                  f"{core_avg_quality:.0f}/100 across {len(core_rows)} asset(s)")

        if avg_quality >= 70:
            print(f"\n  SIMULATION VALIDATED: Monte Carlo matches historical patterns well")
        elif avg_quality >= 50:
            print(f"\n  SIMULATION PARTIALLY VALIDATED: Some discrepancies with history")
        else:
            print(f"\n  SIMULATION CONCERNS: Significant differences from historical patterns")

        core_assets_evaluated = int(len(core_rows))
        high_confidence_core_required = 2
        if core_assets_evaluated >= high_confidence_core_required:
            pass_gate = bool(core_avg_quality >= float(REAL_ONLY_CORE_QUALITY_GATE))
            low_confidence_pass = False
            provisional_pass = bool(pass_gate)
        elif core_assets_evaluated == 1:
            provisional_pass = bool(core_avg_quality >= float(REAL_ONLY_CORE_QUALITY_GATE))
            low_confidence_pass = bool(provisional_pass)
            pass_gate = False
        else:
            provisional_pass = bool(avg_quality >= 70 and len(asset_rows) >= 3)
            low_confidence_pass = bool(provisional_pass)
            pass_gate = False

        if low_confidence_pass:
            print(f"  Low-confidence provisional pass: only {core_assets_evaluated} core asset(s) met "
                  f"{REAL_ONLY_CORE_MIN_WINDOWS} windows; high-confidence requires >= {high_confidence_core_required}. "
                  "Hard pass gate remains FAIL until core coverage is sufficient.")

        per_asset_quality = {
            str(asset_name): float((row.get('comparison') or {}).get('quality_score', np.nan))
            for asset_name, row in comparison_results.items()
            if isinstance(row, dict) and 'comparison' in row
        }
        per_asset_quality = {k: v for k, v in per_asset_quality.items() if np.isfinite(v)}

        comparison_results['__summary__'] = {
            'avg_quality': float(avg_quality),
            'avg_overlap': float(avg_overlap),
            'avg_corr': float(avg_corr),
            'avg_ks': float(avg_ks),
            'avg_tail_error': float(avg_tail),
            'error_attribution_ranked': attribution_rows,
            'core_avg_quality': core_avg_quality if np.isfinite(core_avg_quality) else None,
            'core_assets_evaluated': int(core_assets_evaluated),
            'core_assets_required_for_high_confidence': int(high_confidence_core_required),
            'core_min_windows': int(REAL_ONLY_CORE_MIN_WINDOWS),
            'assets_evaluated': int(len(asset_rows)),
            'per_asset_quality_scores': per_asset_quality,
            'provisional_pass': bool(provisional_pass),
            'low_confidence_pass': bool(low_confidence_pass),
            'pass_gate': bool(pass_gate)
        }

    print(f"\n{'='*100}\n")
    
    return comparison_results


def calculate_rolling_cagrs_all_data(df: pd.DataFrame, asset: str, 
                                      years: int, 
                                      step_days: int = 21) -> Dict:
    """
    Calculate all rolling N-year CAGRs using ALL data (historical + synthetic).
    
    Unlike calculate_historical_rolling_cagrs() which only uses REAL post-inception
    data, this function uses EVERYTHING including synthetic reconstructed data
    back to 1926.
    
    This tests: "If this LETF had existed since 1926 with current expense ratios,
    borrowing costs, and tracking error, what would the return distribution look like?"
    
    Args:
        df: DataFrame with price columns (including synthetic data)
        asset: Asset name (e.g., 'SPY', 'TQQQ', 'SSO')
        years: Rolling window in years (e.g., 10 for 10-year CAGR)
        step_days: Days between each calculation (21 = monthly, 1 = daily)
    
    Returns:
        Dict with:
        - 'cagrs': Array of all rolling CAGRs
        - 'start_dates': Corresponding start dates
        - 'end_dates': Corresponding end dates
        - 'percentiles': Dict of percentile values
        - 'stats': Basic statistics
        - 'synthetic_count': Number of periods that include synthetic data
        - 'real_count': Number of periods that are purely real data
    """
    price_col = f'{asset}_Price'
    synthetic_col = f'{asset}_IsSynthetic'
    
    if price_col not in df.columns:
        print(f"  Warning: {asset}: Price column not found")
        return None
    
    # Use ALL data (don't filter out synthetic)
    df_all = df.copy()
    
    window_days = int(years * 252)
    
    if len(df_all) < window_days:
        print(f"  Warning: {asset}: Insufficient data "
              f"({len(df_all)/252:.2f}Y available, {years}Y needed)")
        return None
    
    # Calculate rolling CAGRs
    cagrs = []
    start_dates = []
    end_dates = []
    includes_synthetic = []  # Track which periods include synthetic data
    
    prices = df_all[price_col].values
    dates = df_all.index
    
    # Check if synthetic column exists for tracking
    has_synthetic_col = synthetic_col in df_all.columns
    if has_synthetic_col:
        is_synthetic = df_all[synthetic_col].values
    
    for start_idx in range(0, len(df_all) - window_days + 1, step_days):
        end_idx = start_idx + window_days - 1
        
        start_price = prices[start_idx]
        end_price = prices[end_idx]
        
        if start_price > 0 and end_price > 0 and not np.isnan(start_price) and not np.isnan(end_price):
            # Calculate CAGR
            total_return = end_price / start_price
            cagr = total_return ** (1/years) - 1
            
            cagrs.append(cagr)
            start_dates.append(dates[start_idx])
            end_dates.append(dates[end_idx])
            
            # Track if this period includes any synthetic data
            if has_synthetic_col:
                period_has_synthetic = np.any(is_synthetic[start_idx:end_idx+1])
                includes_synthetic.append(period_has_synthetic)
            else:
                includes_synthetic.append(False)
    
    if len(cagrs) == 0:
        print(f"  Warning: {asset}: No valid rolling periods found")
        return None
    
    cagrs = np.array(cagrs)
    includes_synthetic = np.array(includes_synthetic)
    
    # Calculate percentiles
    percentiles = {
        'p5': np.percentile(cagrs, 5),
        'p10': np.percentile(cagrs, 10),
        'p25': np.percentile(cagrs, 25),
        'p50': np.percentile(cagrs, 50),
        'p75': np.percentile(cagrs, 75),
        'p90': np.percentile(cagrs, 90),
        'p95': np.percentile(cagrs, 95)
    }
    
    # Count synthetic vs real periods
    synthetic_count = np.sum(includes_synthetic)
    real_count = len(cagrs) - synthetic_count
    
    # Basic stats
    stats = {
        'mean': np.mean(cagrs),
        'median': np.median(cagrs),
        'std': np.std(cagrs),
        'min': np.min(cagrs),
        'max': np.max(cagrs),
        'count': len(cagrs),
        'data_type': 'ALL (Real + Synthetic)',
        'synthetic_count': synthetic_count,
        'real_count': real_count,
        'synthetic_pct': (synthetic_count / len(cagrs) * 100) if len(cagrs) > 0 else 0
    }
    
    # Find date range
    if len(start_dates) > 0:
        stats['earliest_start'] = min(start_dates)
        stats['latest_end'] = max(end_dates)
    
    return {
        'cagrs': cagrs,
        'start_dates': start_dates,
        'end_dates': end_dates,
        'percentiles': percentiles,
        'stats': stats,
        'years': years,
        'asset': asset,
        'includes_synthetic': includes_synthetic
    }


def calculate_rolling_cagrs_synthetic_only(df: pd.DataFrame, asset: str,
                                           years: int,
                                           step_days: int = 21) -> Optional[Dict]:
    """
    Rolling CAGR distribution using only windows where every day is synthetic.
    """
    price_col = f'{asset}_Price'
    synthetic_col = f'{asset}_IsSynthetic'
    if price_col not in df.columns or synthetic_col not in df.columns:
        return None

    df_all = df.copy()
    is_synthetic = df_all[synthetic_col].fillna(False).astype(bool).values
    prices = df_all[price_col].values
    dates = df_all.index
    window_days = int(years * 252)
    if len(df_all) < window_days:
        return None

    cagrs = []
    start_dates = []
    end_dates = []
    window_ann_vols = []
    for start_idx in range(0, len(df_all) - window_days + 1, step_days):
        end_idx = start_idx + window_days - 1
        if not np.all(is_synthetic[start_idx:end_idx + 1]):
            continue

        sp = prices[start_idx]
        ep = prices[end_idx]
        if sp > 0 and ep > 0 and np.isfinite(sp) and np.isfinite(ep):
            total_return = ep / sp
            cagr = total_return ** (1 / years) - 1
            cagrs.append(cagr)
            start_dates.append(dates[start_idx])
            end_dates.append(dates[end_idx])
            window_ann_vols.append(float('nan'))

    if len(cagrs) == 0:
        return None

    cagrs = np.asarray(cagrs, dtype=float)
    window_ann_vols = np.asarray(window_ann_vols, dtype=float)
    percentiles = {
        'p5': np.percentile(cagrs, 5),
        'p10': np.percentile(cagrs, 10),
        'p25': np.percentile(cagrs, 25),
        'p50': np.percentile(cagrs, 50),
        'p75': np.percentile(cagrs, 75),
        'p90': np.percentile(cagrs, 90),
        'p95': np.percentile(cagrs, 95)
    }
    stats = {
        'mean': np.mean(cagrs),
        'median': np.median(cagrs),
        'std': np.std(cagrs),
        'min': np.min(cagrs),
        'max': np.max(cagrs),
        'count': len(cagrs),
        'data_type': 'SYNTHETIC_ONLY'
    }
    if len(start_dates) > 0:
        stats['earliest_start'] = min(start_dates)
        stats['latest_end'] = max(end_dates)

    return {
        'cagrs': cagrs,
        'start_dates': start_dates,
        'end_dates': end_dates,
        'window_ann_vols': window_ann_vols,
        'percentiles': percentiles,
        'stats': stats,
        'years': years,
        'asset': asset
    }


def compare_simulated_vs_synthetic_only(df: pd.DataFrame, mc_results: Dict,
                                        time_horizon: int,
                                        real_only_passed: Optional[bool] = None) -> Dict:
    """
    Compare simulations against pure synthetic-only rolling windows.
    """
    print(f"\n{'='*100}")
    print(f"SYNTHETIC-ONLY vs SIMULATED COMPARISON ({time_horizon}-YEAR HORIZON)")
    print(f"{'='*100}")
    print("\nThis isolates windows fully inside pre-inception synthetic history.\n")

    comparison_results = {}
    strategy_to_asset = {
        'S1': 'TQQQ',
        'S2': 'SPY',
        'S3': 'SSO',
        'S20': 'QLD',
        'S21': 'UPRO'
    }

    for sid, asset in strategy_to_asset.items():
        print(f"\n{'-'*80}")
        print(f"{asset} BUY & HOLD (Strategy {sid}) - SYNTHETIC ONLY")
        print(f"{'-'*80}")

        synthetic_only = calculate_rolling_cagrs_synthetic_only(df, asset, time_horizon, step_days=21)
        if synthetic_only is None:
            print("  Skipping: insufficient pure synthetic-only windows")
            continue

        syn_cagrs = synthetic_only['cagrs']
        syn_percentiles = synthetic_only['percentiles']
        syn_stats = synthetic_only['stats']

        if sid not in mc_results or not mc_results[sid]:
            print(f"  No simulation results for {sid}")
            continue
        sim_results = mc_results[sid]
        sim_wealth = np.array([r['Final_Wealth'] for r in sim_results if r.get('status', 'success') != 'error'])
        if len(sim_wealth) == 0:
            print(f"  No valid simulation results for {sid}")
            continue
        sim_cagrs = (sim_wealth / INITIAL_CAPITAL) ** (1 / time_horizon) - 1
        sim_percentiles = {
            'p5': np.percentile(sim_cagrs, 5),
            'p10': np.percentile(sim_cagrs, 10),
            'p25': np.percentile(sim_cagrs, 25),
            'p50': np.percentile(sim_cagrs, 50),
            'p75': np.percentile(sim_cagrs, 75),
            'p90': np.percentile(sim_cagrs, 90),
            'p95': np.percentile(sim_cagrs, 95)
        }
        sim_stats = {
            'mean': np.mean(sim_cagrs),
            'median': np.median(sim_cagrs),
            'std': np.std(sim_cagrs),
            'min': np.min(sim_cagrs),
            'max': np.max(sim_cagrs),
            'count': len(sim_cagrs)
        }
        sim_percentile_ci = bootstrap_percentile_confidence_bands(sim_cagrs, ci=0.90, n_boot=600, seed=303)

        print(f"\n  SYNTHETIC-ONLY DATA:")
        print(f"     Rolling {time_horizon}-year periods: {syn_stats['count']}")
        if 'earliest_start' in syn_stats:
            _es = syn_stats['earliest_start']
            _le = syn_stats['latest_end']
            _es = _es.strftime('%Y-%m-%d') if hasattr(_es, 'strftime') else _es
            _le = _le.strftime('%Y-%m-%d') if hasattr(_le, 'strftime') else _le
            print(f"     Date range: {_es} to {_le}")
        print(f"     CAGR Range: {syn_stats['min']*100:+.2f}% to {syn_stats['max']*100:+.2f}%")
        print(f"     CAGR Median: {syn_stats['median']*100:+.2f}%")
        print(f"     CAGR Std Dev: {syn_stats['std']*100:.2f}%")
        print(f"\n  SIMULATED DATA:")
        print(f"     Monte Carlo simulations: {sim_stats['count']}")
        print(f"     CAGR Range: {sim_stats['min']*100:+.2f}% to {sim_stats['max']*100:+.2f}%")
        print(f"     CAGR Median: {sim_stats['median']*100:+.2f}%")
        print(f"     CAGR Std Dev: {sim_stats['std']*100:.2f}%")
        if sim_percentile_ci:
            _p5 = sim_percentile_ci.get('p5', {})
            _p50 = sim_percentile_ci.get('p50', {})
            _p95 = sim_percentile_ci.get('p95', {})
            print(f"     90% CI (bootstrap): "
                  f"P5 [{_p5.get('lo', np.nan)*100:+.2f}%, {_p5.get('hi', np.nan)*100:+.2f}%], "
                  f"P50 [{_p50.get('lo', np.nan)*100:+.2f}%, {_p50.get('hi', np.nan)*100:+.2f}%], "
                  f"P95 [{_p95.get('lo', np.nan)*100:+.2f}%, {_p95.get('hi', np.nan)*100:+.2f}%]")

        overlap = calculate_distribution_overlap(syn_cagrs, sim_cagrs)
        pearson_r, spearman_r = calculate_percentile_correlation(syn_percentiles, sim_percentiles)
        dist_metrics = calculate_distribution_distance_metrics(
            ref_dist=syn_cagrs,
            sim_dist=sim_cagrs,
            ref_percentiles=syn_percentiles,
            sim_percentiles=sim_percentiles
        )
        median_diff = sim_stats['median'] - syn_stats['median']
        syn_median_in_sim = find_percentile_rank(syn_stats['median'], sim_cagrs)

        print(f"\n  DISTRIBUTION COMPARISON:")
        print(f"     Distribution Overlap: {overlap:.2f}%")
        print(f"     Percentile Correlation (Spearman): {spearman_r:.3f}")
        print(f"     KS Statistic: {dist_metrics['ks_stat']:.3f} (p={dist_metrics['ks_pvalue']:.3f})")
        print(f"     Wasserstein Distance: {dist_metrics['wasserstein']:.4f}")
        print(f"     Tail Error (avg |P5|,|P95| diff): {dist_metrics['tail_error_p5_p95']*100:.2f}%")
        print(f"     Median Difference: {median_diff*100:+.2f}%")

        quality_score = 0
        quality_notes = []
        if 25 <= syn_median_in_sim <= 75:
            quality_score += 25
            quality_notes.append("OK: Synthetic median within simulation IQR")
        else:
            quality_notes.append("WARN: Synthetic median outside simulation IQR")
        if overlap > 50:
            quality_score += 25
            quality_notes.append(f"OK: Good distribution overlap ({overlap:.0f}%)")
        elif overlap > 25:
            quality_score += 10
            quality_notes.append(f"WARN: Moderate distribution overlap ({overlap:.0f}%)")
        else:
            quality_notes.append(f"BAD: Poor distribution overlap ({overlap:.0f}%)")
        if dist_metrics['ks_stat'] < 0.20:
            quality_score += 25
            quality_notes.append(f"OK: KS statistic low ({dist_metrics['ks_stat']:.3f})")
        elif dist_metrics['ks_stat'] < 0.30:
            quality_score += 15
            quality_notes.append(f"WARN: KS statistic moderate ({dist_metrics['ks_stat']:.3f})")
        else:
            quality_notes.append(f"BAD: KS statistic high ({dist_metrics['ks_stat']:.3f})")
        if dist_metrics['tail_error_p5_p95'] < 0.05 and dist_metrics['wasserstein'] < 0.04:
            quality_score += 25
            quality_notes.append(
                f"OK: Tail/transport fit good (tail_err={dist_metrics['tail_error_p5_p95']*100:.2f}%, "
                f"wass={dist_metrics['wasserstein']:.4f})"
            )
        elif dist_metrics['tail_error_p5_p95'] < 0.08 and dist_metrics['wasserstein'] < 0.07:
            quality_score += 15
            quality_notes.append(
                f"WARN: Tail/transport fit moderate (tail_err={dist_metrics['tail_error_p5_p95']*100:.2f}%, "
                f"wass={dist_metrics['wasserstein']:.4f})"
            )
        else:
            quality_notes.append(
                f"BAD: Tail/transport mismatch (tail_err={dist_metrics['tail_error_p5_p95']*100:.2f}%, "
                f"wass={dist_metrics['wasserstein']:.4f})"
            )

        print(f"\n  SIMULATION QUALITY ASSESSMENT (vs Synthetic-only):")
        for note in quality_notes:
            print(f"     {note}")
        print(f"\n     Overall Score: {quality_score}/100")

        comparison_results[asset] = {
            'synthetic_only': {
                'cagrs': syn_cagrs,
                'percentiles': syn_percentiles,
                'stats': syn_stats
            },
            'simulated': {
                'cagrs': sim_cagrs,
                'percentiles': sim_percentiles,
                'stats': sim_stats
            },
            'comparison': {
                'synthetic_median_percentile_in_sim': syn_median_in_sim,
                'distribution_overlap': overlap,
                'pearson_correlation': pearson_r,
                'spearman_correlation': spearman_r,
                'ks_stat': dist_metrics['ks_stat'],
                'ks_pvalue': dist_metrics['ks_pvalue'],
                'wasserstein': dist_metrics['wasserstein'],
                'tail_error_p5_p95': dist_metrics['tail_error_p5_p95'],
                'median_difference': median_diff,
                'quality_score': quality_score,
                'sim_percentile_ci': sim_percentile_ci
            }
        }

    print(f"\n{'='*100}")
    print("OVERALL VALIDATION SUMMARY (Synthetic-only)")
    print(f"{'='*100}")
    if comparison_results:
        asset_rows = [r for r in comparison_results.values() if isinstance(r, dict) and 'comparison' in r]
        avg_quality = np.mean([r['comparison']['quality_score'] for r in asset_rows])
        avg_overlap = np.mean([r['comparison']['distribution_overlap'] for r in asset_rows])
        avg_ks = np.mean([r['comparison']['ks_stat'] for r in asset_rows])
        avg_tail = np.mean([r['comparison']['tail_error_p5_p95'] for r in asset_rows])
        print(f"\n  Average Quality Score: {avg_quality:.0f}/100")
        print(f"  Average Distribution Overlap: {avg_overlap:.2f}%")
        print(f"  Average KS Statistic: {avg_ks:.3f}")
        print(f"  Average Tail Error (P5/P95): {avg_tail*100:.2f}%")
        if real_only_passed is False:
            print(f"\n  VALIDATION BLOCKED: Real-only historical validation failed")
        elif avg_quality >= 70:
            print(f"\n  SIMULATION VALIDATED: Monte Carlo matches synthetic-only patterns")
        elif avg_quality >= 50:
            print(f"\n  SIMULATION PARTIALLY VALIDATED: Some discrepancies with synthetic-only patterns")
        else:
            print(f"\n  SIMULATION CONCERNS: Significant differences from synthetic-only patterns")

        comparison_results['__summary__'] = {
            'avg_quality': float(avg_quality),
            'avg_overlap': float(avg_overlap),
            'avg_ks': float(avg_ks),
            'avg_tail_error': float(avg_tail),
            'assets_evaluated': int(len(asset_rows)),
            'pass_gate': bool(avg_quality >= 70 and real_only_passed is not False and len(asset_rows) >= 3)
        }
    print(f"\n{'='*100}\n")
    return comparison_results


def compare_simulated_vs_synthetic_historical(df: pd.DataFrame, mc_results: Dict,
                                              time_horizon: int,
                                              real_only_passed: Optional[bool] = None) -> Dict:
    """
    Compare simulated returns vs ALL historical data (including synthetic).
    
    This is the SECOND comparison that uses:
    - Real post-inception data (e.g., TQQQ since 2010)
    - PLUS synthetic reconstructed data (e.g., "what if TQQQ existed since 1926")
    
    The synthetic data uses current expense ratios, borrowing costs, and tracking
    error applied to historical underlying returns.
    
    This gives us ~100 years of "what if" data to compare against simulations,
    including extreme events like the Great Depression.
    
    Args:
        df: Historical DataFrame (with both real and synthetic data)
        mc_results: Monte Carlo results dict
        time_horizon: Simulation horizon in years
    
    Returns:
        Dict with comparison results for each asset
    """
    print(f"\n{'='*100}")
    print(f"SYNTHETIC + HISTORICAL vs SIMULATED COMPARISON ({time_horizon}-YEAR HORIZON)")
    print(f"{'='*100}")
    print("\nThis compares Monte Carlo simulations against ALL data (real + synthetic reconstruction).")
    print("Synthetic data assumes CURRENT expense ratios, borrowing costs, and tracking error.")
    print("This includes extreme events like the Great Depression (1929-1932).\n")
    
    comparison_results = {}
    
    # Map strategies to assets
    strategy_to_asset = {
        'S1': 'TQQQ',
        'S2': 'SPY',
        'S3': 'SSO',
        'S20': 'QLD',
        'S21': 'UPRO'
    }

    # Get asset configurations for display
    asset_configs = {
        'TQQQ': ASSETS.get('TQQQ', {}),
        'SSO': ASSETS.get('SSO', {}),
        'SPY': ASSETS.get('SPY', {}),
        'QLD': ASSETS.get('QLD', {}),
        'UPRO': ASSETS.get('UPRO', {})
    }
    
    for sid, asset in strategy_to_asset.items():
        print(f"\n{'-'*80}")
        print(f"{asset} BUY & HOLD (Strategy {sid}) - ALL DATA")
        print(f"{'-'*80}")
        
        # Show the parameters used for synthetic data
        config = asset_configs.get(asset, {})
        if config:
            print(f"\n  SYNTHETIC DATA PARAMETERS (applied to all pre-inception data):")
            print(f"     Leverage: {config.get('leverage', 'N/A')}x")
            print(f"     Expense Ratio: {config.get('expense_ratio', 0)*100:.2f}%")
            print(f"     Borrow Spread: {config.get('borrow_spread', 0)*100:.2f}%")
            print(f"     Tracking Error Base: {config.get('tracking_error_base', 0)*10000:.2f} bps")
            print(f"     Inception Date: {config.get('inception', 'N/A')}")
        
        # ====================================================================
        # STEP 1: Get Rolling CAGRs from ALL Data (Real + Synthetic)
        # ====================================================================
        all_data = calculate_rolling_cagrs_all_data(
            df, asset, time_horizon, step_days=21  # Monthly rolling windows
        )
        
        if all_data is None:
            print(f"  Skipping {asset} - insufficient data")
            continue
        
        all_cagrs_raw = np.asarray(all_data['cagrs'], dtype=float)
        all_percentiles = all_data['percentiles']
        all_stats = all_data['stats']
        _syn_policy = _asset_synthetic_risk_policy(asset)
        _reb = rebalance_reference_windows(
            cagrs=all_cagrs_raw,
            includes_synthetic=all_data.get('includes_synthetic', None),
            target_synth_pct=float(_syn_policy.get('target_synth_pct', 65.0)),
            min_real_windows=int(_syn_policy.get('min_real_windows', 24)),
            seed=1000 + time_horizon
        )
        all_cagrs = np.asarray(_reb['cagrs'], dtype=float)
        if len(all_cagrs) == 0:
            print("  Skipping: rebalanced reference windows empty")
            continue
        all_percentiles_eval = {
            'p5': np.percentile(all_cagrs, 5),
            'p10': np.percentile(all_cagrs, 10),
            'p25': np.percentile(all_cagrs, 25),
            'p50': np.percentile(all_cagrs, 50),
            'p75': np.percentile(all_cagrs, 75),
            'p90': np.percentile(all_cagrs, 90),
            'p95': np.percentile(all_cagrs, 95)
        }
        
        print(f"\n  ALL DATA (Real + Synthetic):")
        print(f"     Rolling {time_horizon}-year periods: {all_stats['count']}")
        print(f"     - Periods with synthetic data: {all_stats['synthetic_count']} ({all_stats['synthetic_pct']:.2f}%)")
        print(f"     - Periods with real data only: {all_stats['real_count']}")
        print(f"     - Synthetic-risk policy ({_syn_policy.get('risk_tier', 'n/a')}): "
              f"target synth ≤ {_syn_policy.get('target_synth_pct', float('nan')):.0f}%, "
              f"hard validation limit {_syn_policy.get('max_synth_pct_for_validation', float('nan')):.0f}%")
        if _reb.get('rebalanced', False):
            print(f"     - Effective synthetic share for scoring: {_reb['effective_synth_pct']:.2f}% "
                  f"(rebalanced from {_reb['raw_synth_pct']:.2f}%)")
        else:
            if np.isfinite(_reb.get('effective_synth_pct', np.nan)):
                print(f"     - Effective synthetic share for scoring: {_reb['effective_synth_pct']:.2f}%")
        if 'earliest_start' in all_stats:
            print(f"     Date range: {all_stats['earliest_start'].strftime('%Y-%m-%d') if hasattr(all_stats['earliest_start'], 'strftime') else all_stats['earliest_start']} to {all_stats['latest_end'].strftime('%Y-%m-%d') if hasattr(all_stats['latest_end'], 'strftime') else all_stats['latest_end']}")
        print(f"     CAGR Range: {all_stats['min']*100:+.2f}% to {all_stats['max']*100:+.2f}%")
        print(f"     CAGR Median: {all_stats['median']*100:+.2f}%")
        print(f"     CAGR Std Dev: {all_stats['std']*100:.2f}%")
        
        # ====================================================================
        # STEP 2: Get Simulated CAGRs
        # ====================================================================
        if sid not in mc_results or not mc_results[sid]:
            print(f"  No simulation results for {sid}")
            continue
        
        sim_results = mc_results[sid]
        sim_wealth = np.array([r['Final_Wealth'] for r in sim_results 
                               if r.get('status', 'success') != 'error'])
        
        if len(sim_wealth) == 0:
            print(f"  No valid simulation results for {sid}")
            continue
        
        # Convert wealth to CAGRs
        sim_cagrs = (sim_wealth / INITIAL_CAPITAL) ** (1/time_horizon) - 1
        
        sim_percentiles = {
            'p5': np.percentile(sim_cagrs, 5),
            'p10': np.percentile(sim_cagrs, 10),
            'p25': np.percentile(sim_cagrs, 25),
            'p50': np.percentile(sim_cagrs, 50),
            'p75': np.percentile(sim_cagrs, 75),
            'p90': np.percentile(sim_cagrs, 90),
            'p95': np.percentile(sim_cagrs, 95)
        }
        sim_percentile_ci = bootstrap_percentile_confidence_bands(sim_cagrs, ci=0.90, n_boot=600, seed=202)
        
        sim_stats = {
            'mean': np.mean(sim_cagrs),
            'median': np.median(sim_cagrs),
            'std': np.std(sim_cagrs),
            'min': np.min(sim_cagrs),
            'max': np.max(sim_cagrs),
            'count': len(sim_cagrs)
        }
        
        print(f"\n  SIMULATED DATA:")
        print(f"     Monte Carlo simulations: {sim_stats['count']}")
        print(f"     CAGR Range: {sim_stats['min']*100:+.2f}% to {sim_stats['max']*100:+.2f}%")
        print(f"     CAGR Median: {sim_stats['median']*100:+.2f}%")
        print(f"     CAGR Std Dev: {sim_stats['std']*100:.2f}%")
        if sim_percentile_ci:
            _p5 = sim_percentile_ci.get('p5', {})
            _p50 = sim_percentile_ci.get('p50', {})
            _p95 = sim_percentile_ci.get('p95', {})
            print(f"     90% CI (bootstrap): "
                  f"P5 [{_p5.get('lo', np.nan)*100:+.2f}%, {_p5.get('hi', np.nan)*100:+.2f}%], "
                  f"P50 [{_p50.get('lo', np.nan)*100:+.2f}%, {_p50.get('hi', np.nan)*100:+.2f}%], "
                  f"P95 [{_p95.get('lo', np.nan)*100:+.2f}%, {_p95.get('hi', np.nan)*100:+.2f}%]")
        
        # ====================================================================
        # STEP 3: Calculate Percentile Rankings
        # ====================================================================
        
        # Where does historical+synthetic median rank in simulation?
        all_median_in_sim = find_percentile_rank(float(np.median(all_cagrs)), sim_cagrs)
        
        # Where does simulated median rank in historical+synthetic?
        sim_median_in_all = find_percentile_rank(sim_stats['median'], all_cagrs)
        
        print(f"\n  PERCENTILE RANKINGS:")
        print(f"     Historical+Synthetic median ({np.median(all_cagrs)*100:+.2f}%) would be P{all_median_in_sim:.0f} in simulation")
        print(f"     Simulated median ({sim_stats['median']*100:+.2f}%) would be P{sim_median_in_all:.0f} in historical+synthetic")
        
        # ====================================================================
        # STEP 4: Calculate Distribution Metrics
        # ====================================================================
        
        # Overlap between distributions
        overlap = calculate_distribution_overlap(all_cagrs, sim_cagrs)
        
        # Correlation between percentile curves
        pearson_r, spearman_r = calculate_percentile_correlation(
            all_percentiles_eval, sim_percentiles
        )
        dist_metrics = calculate_distribution_distance_metrics(
            ref_dist=all_cagrs,
            sim_dist=sim_cagrs,
            ref_percentiles=all_percentiles_eval,
            sim_percentiles=sim_percentiles
        )
        
        # Median difference
        ref_median = float(np.median(all_cagrs))
        median_diff = sim_stats['median'] - ref_median
        median_diff_pct = median_diff / abs(ref_median) * 100 if ref_median != 0 else 0
        
        print(f"\n  DISTRIBUTION COMPARISON:")
        print(f"     Distribution Overlap: {overlap:.2f}%")
        print(f"     Percentile Correlation (Pearson): {pearson_r:.3f}")
        print(f"     Percentile Correlation (Spearman): {spearman_r:.3f}")
        print(f"     KS Statistic: {dist_metrics['ks_stat']:.3f} (p={dist_metrics['ks_pvalue']:.3f})")
        print(f"     Wasserstein Distance: {dist_metrics['wasserstein']:.4f}")
        print(f"     Tail Error (avg |P5|,|P95| diff): {dist_metrics['tail_error_p5_p95']*100:.2f}%")
        print(f"     Median Difference: {median_diff*100:+.2f}% ({median_diff_pct:+.2f}% relative)")
        
        # ====================================================================
        # STEP 5: Print Percentile Comparison Table
        # ====================================================================
        
        print(f"\n  PERCENTILE COMPARISON TABLE:")
        print(f"     {'Percentile':<12} {'Hist+Synth':>12} {'Simulated':>12} {'Difference':>12}")
        print(f"     {'-'*48}")
        
        for pct_name in ['p5', 'p10', 'p25', 'p50', 'p75', 'p90', 'p95']:
            all_val = all_percentiles_eval[pct_name] * 100
            sim_val = sim_percentiles[pct_name] * 100
            diff = sim_val - all_val
            print(f"     {pct_name.upper():<12} {all_val:>+11.2f}% {sim_val:>+11.2f}% {diff:>+11.2f}%")
        
        # ====================================================================
        # STEP 6: Quality Assessment
        # ====================================================================
        
        quality_score = 0
        quality_notes = []
        synthetic_pct_raw = float(all_stats.get('synthetic_pct', 0.0))
        synthetic_pct_effective = float(_reb.get('effective_synth_pct', synthetic_pct_raw))
        _synthetic_guardrail = float(_syn_policy.get('max_synth_pct_for_validation', 70.0))
        
        # Check 1: Is historical+synthetic median within P25-P75 of simulation?
        if 25 <= all_median_in_sim <= 75:
            quality_score += 25
            quality_notes.append("OK: Hist+Synth median within simulation IQR")
        else:
            quality_notes.append("WARN: Hist+Synth median outside simulation IQR")
        
        # Check 2: Distribution overlap > 50%?
        if overlap > 50:
            quality_score += 25
            quality_notes.append(f"OK: Good distribution overlap ({overlap:.0f}%)")
        elif overlap > 25:
            quality_score += 10
            quality_notes.append(f"WARN: Moderate distribution overlap ({overlap:.0f}%)")
        else:
            quality_notes.append(f"BAD: Poor distribution overlap ({overlap:.0f}%)")
        
        # Check 3: KS distance (distributional fit)
        if dist_metrics['ks_stat'] < 0.20:
            quality_score += 25
            quality_notes.append(f"OK: KS statistic low ({dist_metrics['ks_stat']:.3f})")
        elif dist_metrics['ks_stat'] < 0.30:
            quality_score += 15
            quality_notes.append(f"WARN: KS statistic moderate ({dist_metrics['ks_stat']:.3f})")
        else:
            quality_notes.append(f"BAD: KS statistic high ({dist_metrics['ks_stat']:.3f})")

        # Check 4: Tail fit (P5/P95) + transport distance.
        if dist_metrics['tail_error_p5_p95'] < 0.05 and dist_metrics['wasserstein'] < 0.04:
            quality_score += 25
            quality_notes.append(
                f"OK: Tail/transport fit good (tail_err={dist_metrics['tail_error_p5_p95']*100:.2f}%, "
                f"wass={dist_metrics['wasserstein']:.4f})"
            )
        elif dist_metrics['tail_error_p5_p95'] < 0.08 and dist_metrics['wasserstein'] < 0.07:
            quality_score += 15
            quality_notes.append(
                f"WARN: Tail/transport fit moderate (tail_err={dist_metrics['tail_error_p5_p95']*100:.2f}%, "
                f"wass={dist_metrics['wasserstein']:.4f})"
            )
        else:
            quality_notes.append(
                f"BAD: Tail/transport mismatch (tail_err={dist_metrics['tail_error_p5_p95']*100:.2f}%, "
                f"wass={dist_metrics['wasserstein']:.4f})"
            )

        # Guardrail: if most windows are synthetic, this is not a strong real-world validation.
        if synthetic_pct_effective >= _synthetic_guardrail:
            quality_score = min(quality_score, 70)
            quality_notes.append(
                f"WARN: effective synthetic share {synthetic_pct_effective:.1f}% (raw {synthetic_pct_raw:.1f}%) "
                f"exceeds guardrail {_synthetic_guardrail:.0f}% for {_syn_policy.get('risk_tier', 'asset tier')}; "
                "treat this as stress-testing, not real-history validation"
            )
        
        print(f"\n  SIMULATION QUALITY ASSESSMENT (vs Synthetic+Historical):")
        for note in quality_notes:
            print(f"     {note}")
        print(f"\n     Overall Score: {quality_score}/100", end="")
        
        if quality_score >= 80:
            print(" - EXCELLENT match to synthetic history")
        elif quality_score >= 60:
            print(" - GOOD match to synthetic history")
        elif quality_score >= 40:
            print(" - FAIR match to synthetic history (review assumptions)")
        else:
            print(" - POOR match to synthetic history (simulation may need calibration)")
        
        # ====================================================================
        # STEP 7: Extreme Event Analysis
        # ====================================================================
        
        # Find worst and best periods in the synthetic+historical data
        worst_idx = np.argmin(all_cagrs)
        best_idx = np.argmax(all_cagrs)
        
        print(f"\n  EXTREME EVENTS IN SYNTHETIC+HISTORICAL DATA:")
        print(f"     Worst {time_horizon}Y period: {all_cagrs[worst_idx]*100:+.2f}% CAGR", end="")
        if len(all_data['start_dates']) > worst_idx:
            start_dt = all_data['start_dates'][worst_idx]
            if hasattr(start_dt, 'strftime'):
                print(f" (starting {start_dt.strftime('%Y-%m-%d')})", end="")
        print()
        
        print(f"     Best {time_horizon}Y period:  {all_cagrs[best_idx]*100:+.2f}% CAGR", end="")
        if len(all_data['start_dates']) > best_idx:
            start_dt = all_data['start_dates'][best_idx]
            if hasattr(start_dt, 'strftime'):
                print(f" (starting {start_dt.strftime('%Y-%m-%d')})", end="")
        print()
        
        # What percentile would these extremes be in simulation?
        worst_in_sim = find_percentile_rank(all_cagrs[worst_idx], sim_cagrs)
        best_in_sim = find_percentile_rank(all_cagrs[best_idx], sim_cagrs)
        
        print(f"     Worst period would be P{worst_in_sim:.0f} in simulation")
        print(f"     Best period would be P{best_in_sim:.0f} in simulation")
        
        # Store results
        comparison_results[asset] = {
            'historical_synthetic': {
                'cagrs': all_cagrs,
                'percentiles': all_percentiles,
                'stats': all_stats
            },
            'simulated': {
                'cagrs': sim_cagrs,
                'percentiles': sim_percentiles,
                'stats': sim_stats
            },
            'comparison': {
                'all_median_percentile_in_sim': all_median_in_sim,
                'sim_median_percentile_in_all': sim_median_in_all,
                'distribution_overlap': overlap,
                'pearson_correlation': pearson_r,
                'spearman_correlation': spearman_r,
                'ks_stat': dist_metrics['ks_stat'],
                'ks_pvalue': dist_metrics['ks_pvalue'],
                'wasserstein': dist_metrics['wasserstein'],
                'tail_error_p5_p95': dist_metrics['tail_error_p5_p95'],
                'median_difference': median_diff,
                'quality_score': quality_score,
                'synthetic_pct': synthetic_pct_effective,
                'synthetic_pct_raw': synthetic_pct_raw,
                'synthetic_guardrail_pct': _synthetic_guardrail,
                'synthetic_target_pct': float(_syn_policy.get('target_synth_pct', 65.0)),
                'synthetic_risk_tier': str(_syn_policy.get('risk_tier', 'unknown')),
                'synthetic_rebalanced': bool(_reb.get('rebalanced', False)),
                'sim_percentile_ci': sim_percentile_ci
            },
            'extremes': {
                'worst_cagr': all_cagrs[worst_idx],
                'best_cagr': all_cagrs[best_idx],
                'worst_percentile_in_sim': worst_in_sim,
                'best_percentile_in_sim': best_in_sim
            }
        }
    
    # ========================================================================
    # OVERALL SUMMARY
    # ========================================================================
    
    print(f"\n{'='*100}")
    print("OVERALL VALIDATION SUMMARY (Synthetic + Historical)")
    print(f"{'='*100}")
    
    if comparison_results:
        asset_rows = [r for r in comparison_results.values() if isinstance(r, dict) and 'comparison' in r]
        avg_quality = np.mean([r['comparison']['quality_score'] for r in asset_rows])
        avg_overlap = np.mean([r['comparison']['distribution_overlap'] for r in asset_rows])
        avg_corr = np.mean([r['comparison']['spearman_correlation'] for r in asset_rows])
        avg_synth = np.mean([r['comparison'].get('synthetic_pct', 0.0) for r in asset_rows])
        avg_synth_raw = np.mean([r['comparison'].get('synthetic_pct_raw', r['comparison'].get('synthetic_pct', 0.0)) for r in asset_rows])
        synth_guardrail_max = np.mean([r['comparison'].get('synthetic_guardrail_pct', 70.0) for r in asset_rows])
        avg_ks = np.mean([r['comparison']['ks_stat'] for r in asset_rows])
        avg_tail = np.mean([r['comparison']['tail_error_p5_p95'] for r in asset_rows])
        _three_x_rows = [r for _asset, r in comparison_results.items()
                         if isinstance(r, dict) and 'comparison' in r and
                         float(ASSETS.get(_asset, {}).get('leverage', 1.0)) >= 3.0]
        avg_synth_3x = float(np.mean([r['comparison'].get('synthetic_pct', np.nan) for r in _three_x_rows])) if _three_x_rows else float('nan')

        print(f"\n  Average Quality Score: {avg_quality:.0f}/100")
        print(f"  Average Distribution Overlap: {avg_overlap:.2f}%")
        print(f"  Average Percentile Correlation: {avg_corr:.3f}")
        print(f"  Average Synthetic Window Share (effective): {avg_synth:.1f}%")
        print(f"  Average Synthetic Window Share (raw): {avg_synth_raw:.1f}%")
        if np.isfinite(avg_synth_3x):
            print(f"  Average Synthetic Share (3x funds): {avg_synth_3x:.1f}%")
        print(f"  Average Synthetic Guardrail (asset-tiered): {synth_guardrail_max:.1f}%")
        print(f"  Average KS Statistic: {avg_ks:.3f}")
        print(f"  Average Tail Error (P5/P95): {avg_tail*100:.2f}%")

        if real_only_passed is False:
            print(f"\n  VALIDATION BLOCKED: Real-only historical validation failed")
        elif avg_synth >= 70:
            print(f"\n  SYNTHETIC-DOMINATED CHECK: Useful for scenario stress-testing, "
                  f"not sufficient for real-world validation")
        elif np.isfinite(avg_synth_3x) and avg_synth_3x >= 60:
            print(f"\n  3x MODEL-RISK WARNING: 3x funds still synthetic-heavy "
                  f"({avg_synth_3x:.1f}% effective synthetic share)")
        elif avg_quality >= 70:
            print(f"\n  SIMULATION VALIDATED: Monte Carlo matches synthetic+historical patterns well")
        elif avg_quality >= 50:
            print(f"\n  SIMULATION PARTIALLY VALIDATED: Some discrepancies with synthetic history")
        else:
            print(f"\n  SIMULATION CONCERNS: Significant differences from synthetic historical patterns")
        
        # Note about synthetic data limitations
        print(f"\n  NOTE: Synthetic data uses current fund parameters (expense ratio, borrowing")
        print(f"        costs, tracking error). Historical actual costs would have varied.")

        comparison_results['__summary__'] = {
            'avg_quality': float(avg_quality),
            'avg_overlap': float(avg_overlap),
            'avg_corr': float(avg_corr),
            'avg_synth_pct': float(avg_synth),
            'avg_synth_pct_raw': float(avg_synth_raw),
            'avg_synth_pct_3x': float(avg_synth_3x) if np.isfinite(avg_synth_3x) else None,
            'avg_synth_guardrail_pct': float(synth_guardrail_max),
            'avg_ks': float(avg_ks),
            'avg_tail_error': float(avg_tail),
            'assets_evaluated': int(len(asset_rows)),
            'pass_gate': bool(avg_quality >= 70 and avg_synth < 70 and real_only_passed is not False and len(asset_rows) >= 3)
        }
    
    print(f"\n{'='*100}\n")
    
    return comparison_results


def run_real_only_repeatability_checks(df: pd.DataFrame,
                                       time_horizon: int,
                                       regime_model: Dict,
                                       correlation_matrices: Dict,
                                       strategy_ids: List[str],
                                       n_runs: int = REAL_ONLY_REPEATABILITY_RUNS) -> Dict[str, Any]:
    """
    Repeat real-only validation with different seeds and report score stability.
    """
    n_runs = int(max(1, n_runs))
    if n_runs <= 1:
        return {
            'enabled': False,
            'runs': 0,
            'mean_real_avg_quality': None,
            'std_real_avg_quality': None,
            'pass_rate': None
        }

    print(f"\n{'='*100}")
    print(f"REAL-ONLY REPEATABILITY CHECK ({n_runs} runs, {NUM_SIMULATIONS} sims each)")
    print(f"{'='*100}")

    rows = []
    for i in range(n_runs):
        seed_offset = int(REAL_ONLY_REPEATABILITY_SEED_BASE + 1009 * i)
        mc_rep = run_real_only_validation_mc(
            strategy_ids=strategy_ids,
            time_horizon=time_horizon,
            regime_model=regime_model,
            correlation_matrices=correlation_matrices,
            historical_df=df,
            seed_offset=seed_offset
        )
        with contextlib.redirect_stdout(io.StringIO()):
            comp_rep = compare_simulated_vs_historical(
                df,
                mc_rep,
                time_horizon,
                use_crisis_mix_filter=True
            )
        s = comp_rep.get('__summary__', {}) if isinstance(comp_rep, dict) else {}
        row = {
            'run': int(i + 1),
            'seed_offset': int(seed_offset),
            'real_avg_quality': float(s.get('avg_quality', np.nan)),
            'real_core_avg_quality': float(s.get('core_avg_quality', np.nan))
            if s.get('core_avg_quality', None) is not None else float('nan'),
            'core_assets_evaluated': int(s.get('core_assets_evaluated', 0)),
            'pass_gate': bool(s.get('pass_gate', False)),
            'low_confidence_pass': bool(s.get('low_confidence_pass', False)),
        }
        rows.append(row)
        _avg = row['real_avg_quality']
        _core = row['real_core_avg_quality']
        _core_s = f"{_core:.1f}" if np.isfinite(_core) else "n/a"
        print(f"  Run {i+1:>2}/{n_runs} | seed_offset={seed_offset:>6} | "
              f"real_avg_quality={_avg:>5.1f} | core_avg={_core_s:>5} | "
              f"pass={'Y' if row['pass_gate'] else 'N'} | "
              f"low_conf={'Y' if row['low_confidence_pass'] else 'N'}")

    q = np.array([r['real_avg_quality'] for r in rows], dtype=float)
    q = q[np.isfinite(q)]
    pass_rate = float(np.mean([1.0 if r['pass_gate'] else 0.0 for r in rows])) if rows else float('nan')
    out = {
        'enabled': True,
        'runs': int(len(rows)),
        'rows': rows,
        'mean_real_avg_quality': float(np.mean(q)) if len(q) > 0 else None,
        'std_real_avg_quality': float(np.std(q, ddof=1)) if len(q) > 1 else 0.0 if len(q) == 1 else None,
        'min_real_avg_quality': float(np.min(q)) if len(q) > 0 else None,
        'max_real_avg_quality': float(np.max(q)) if len(q) > 0 else None,
        'pass_rate': pass_rate if np.isfinite(pass_rate) else None,
        'low_confidence_pass_count': int(sum(1 for r in rows if r['low_confidence_pass'])),
    }

    _m = out.get('mean_real_avg_quality', None)
    _s = out.get('std_real_avg_quality', None)
    _mn = out.get('min_real_avg_quality', None)
    _mx = out.get('max_real_avg_quality', None)
    _pr = out.get('pass_rate', None)
    _m_s = f"{_m:.2f}" if _m is not None and np.isfinite(_m) else "n/a"
    _s_s = f"{_s:.2f}" if _s is not None and np.isfinite(_s) else "n/a"
    _mn_s = f"{_mn:.1f}" if _mn is not None and np.isfinite(_mn) else "n/a"
    _mx_s = f"{_mx:.1f}" if _mx is not None and np.isfinite(_mx) else "n/a"
    _pr_s = f"{_pr*100:.0f}%" if _pr is not None and np.isfinite(_pr) else "n/a"
    print(f"  Summary: mean={_m_s}, std={_s_s}, min={_mn_s}, max={_mx_s}, pass_rate={_pr_s}")
    print(f"{'='*100}\n")
    return out


def run_realism_regression_checks(regime_model: Dict,
                                  comparison_real: Dict,
                                  comparison_synthetic_only: Dict,
                                  comparison_combined: Dict) -> Dict:
    """
    Regression gates for realism claims:
    - Real-only validation must pass
    - Synthetic share must not dominate realism claim
    - Crisis regime frequency/duration must stay in plausible bounds
    """
    real_summary = comparison_real.get('__summary__', {}) if isinstance(comparison_real, dict) else {}
    real_repeatability = comparison_real.get('__repeatability__', {}) if isinstance(comparison_real, dict) else {}
    syn_summary = comparison_synthetic_only.get('__summary__', {}) if isinstance(comparison_synthetic_only, dict) else {}
    comb_summary = comparison_combined.get('__summary__', {}) if isinstance(comparison_combined, dict) else {}

    rp = regime_model.get('regime_params', {}) if isinstance(regime_model, dict) else {}
    shock = rp.get(REGIME_HIGH_VOL, {})
    bear = rp.get(REGIME_BEAR, {})
    stress_freq = _regime_frequency_from_params(rp, tuple(STRESS_REGIME_IDS), use_topology=True)
    shock_med = float(shock.get('duration_median_days', np.nan))
    bear_med = float(bear.get('duration_median_days', np.nan))
    bear_p90 = float(bear.get('duration_p90_days', np.nan))
    avg_synth = float(comb_summary.get('avg_synth_pct', np.nan))
    avg_synth_3x = float(comb_summary.get('avg_synth_pct_3x', np.nan)) if comb_summary.get('avg_synth_pct_3x', None) is not None else float('nan')

    checks = {
        'real_only_validation_passed': bool(real_summary.get('pass_gate', False)),
        'real_only_low_confidence_pass': bool(real_summary.get('low_confidence_pass', False)),
        'synthetic_only_report_available': bool(syn_summary.get('assets_evaluated', 0) > 0),
        'synthetic_share_gate_passed': bool(np.isfinite(avg_synth) and avg_synth < 70.0),
        'synthetic_share_3x_gate_passed': bool((not np.isfinite(avg_synth_3x)) or (avg_synth_3x < 60.0)),
        'crisis_frequency_gate_passed': bool(np.isfinite(stress_freq) and 0.03 <= stress_freq <= 0.40),
        'crisis_duration_gate_passed': bool(
            np.isfinite(shock_med) and np.isfinite(bear_med) and np.isfinite(bear_p90) and
            3.0 <= shock_med <= 90.0 and
            30.0 <= bear_med <= 520.0 and
            60.0 <= bear_p90 <= 1260.0
        ),
        'diagnostics': {
            'real_avg_quality': real_summary.get('avg_quality', None),
            'real_core_avg_quality': real_summary.get('core_avg_quality', None),
            'real_core_assets_evaluated': real_summary.get('core_assets_evaluated', None),
            'real_core_assets_required_for_high_confidence': real_summary.get('core_assets_required_for_high_confidence', None),
            'real_per_asset_quality_scores': real_summary.get('per_asset_quality_scores', None),
            'synthetic_only_avg_quality': syn_summary.get('avg_quality', None),
            'combined_avg_quality': comb_summary.get('avg_quality', None),
            'combined_avg_synthetic_pct': avg_synth if np.isfinite(avg_synth) else None,
            'combined_avg_synthetic_pct_raw': comb_summary.get('avg_synth_pct_raw', None),
            'combined_avg_synthetic_pct_3x': avg_synth_3x if np.isfinite(avg_synth_3x) else None,
            'repeatability_runs': real_repeatability.get('runs', None),
            'repeatability_mean_real_avg_quality': real_repeatability.get('mean_real_avg_quality', None),
            'repeatability_std_real_avg_quality': real_repeatability.get('std_real_avg_quality', None),
            'repeatability_pass_rate': real_repeatability.get('pass_rate', None),
            'stress_frequency_pct': (stress_freq * 100.0) if np.isfinite(stress_freq) else None,
            'shock_frequency_pct': (float(shock.get('frequency_topology', shock.get('frequency', np.nan))) * 100.0)
            if np.isfinite(float(shock.get('frequency_topology', shock.get('frequency', np.nan)))) else None,
            'bear_frequency_pct': (float(bear.get('frequency_topology', bear.get('frequency', np.nan))) * 100.0)
            if np.isfinite(float(bear.get('frequency_topology', bear.get('frequency', np.nan)))) else None,
            'shock_duration_median_days': shock_med if np.isfinite(shock_med) else None,
            'bear_duration_median_days': bear_med if np.isfinite(bear_med) else None,
            'bear_duration_p90_days': bear_p90 if np.isfinite(bear_p90) else None
        }
    }
    required = [
        'real_only_validation_passed',
        'synthetic_share_gate_passed',
        'synthetic_share_3x_gate_passed',
        'crisis_frequency_gate_passed',
        'crisis_duration_gate_passed'
    ]
    checks['all_passed'] = all(bool(checks.get(k, False)) for k in required)

    print(f"\n{'='*100}")
    print("REALISM REGRESSION CHECKS")
    print(f"{'='*100}")
    for k, v in checks.items():
        if isinstance(v, bool):
            print(f"  {'✓' if v else '✗'} {k}")
    if checks.get('real_only_low_confidence_pass', False):
        print("  ⚠ real_only_validation_passed is low-confidence (fewer than 2 core assets available)")
    if isinstance(real_repeatability, dict) and real_repeatability.get('enabled', False):
        _m = real_repeatability.get('mean_real_avg_quality', None)
        _s = real_repeatability.get('std_real_avg_quality', None)
        _p = real_repeatability.get('pass_rate', None)
        if _m is not None and _s is not None and _p is not None:
            print(f"  Repeatability: mean real_avg_quality={_m:.2f}, std={_s:.2f}, pass_rate={_p*100:.0f}%")
    print(f"  Diagnostics: {checks['diagnostics']}")
    if checks['all_passed']:
        print("  REALISM CLAIM ENABLED")
    else:
        print("  REALISM CLAIM BLOCKED: one or more regression gates failed")
    print(f"{'='*100}\n")
    return checks


