def _finite_median(values: List[float], default: float = float('nan')) -> float:
    """Median over finite values with graceful default."""
    if values is None:
        return default
    arr = np.asarray(values, dtype=float)
    arr = arr[np.isfinite(arr)]
    if arr.size == 0:
        return default
    return float(np.median(arr))


def _extract_strategy_decomposition_from_metadata(sim_result: Dict[str, Any],
                                                  strategy_id: str,
                                                  years: int) -> Optional[Dict[str, float]]:
    """
    Map path-level asset decomposition to strategy-level decomposition using
    realized pre-tax growth scaling.
    """
    if years <= 0:
        return None
    meta = sim_result.get('Metadata', {}) if isinstance(sim_result, dict) else {}
    pf = meta.get('path_features', {}) if isinstance(meta, dict) else {}
    asset_decomp = pf.get('asset_decomposition', {}) if isinstance(pf, dict) else {}
    strat_cfg = STRATEGIES.get(strategy_id, {})
    primary_asset = strat_cfg.get('asset', None)
    if primary_asset is None or not isinstance(asset_decomp, dict):
        return None
    base = asset_decomp.get(primary_asset, None)
    if not isinstance(base, dict):
        return None

    wealth = float(sim_result.get('Final_Wealth', np.nan))
    if not np.isfinite(wealth) or wealth <= 0:
        return None

    pre_tax_log_ann = float(np.log(max(wealth, 1e-12) / float(INITIAL_CAPITAL)) / float(years))
    base_total_log_ann = float(base.get('total_log_ann', np.nan))
    if np.isfinite(base_total_log_ann) and abs(base_total_log_ann) > 1e-10:
        # Effective strategy exposure scaling (captures partial cash / de-risking behavior).
        scale = float(np.clip(pre_tax_log_ann / base_total_log_ann, 0.0, 2.5))
    else:
        scale = 1.0

    out = {
        'primary_asset': str(primary_asset),
        'scale': scale,
        'pre_tax_log_ann': pre_tax_log_ann,
        'underlying_log_ann': float(scale * float(base.get('underlying_log_ann', np.nan))),
        'vol_drag_log_ann': float(scale * float(base.get('vol_drag_log_ann', np.nan))),
        'financing_log_ann': float(scale * float(base.get('financing_log_ann', np.nan))),
        'fees_log_ann': float(scale * float(base.get('fees_log_ann', np.nan))),
        'tracking_log_ann': float(scale * float(base.get('tracking_log_ann', np.nan))),
    }
    return out


