# ============================================================================
# ITEM 6 — SCENARIO GENERATOR VALIDATION
# ============================================================================

def validate_scenario_generator(
        paths_spy_returns: List[np.ndarray],
        df_historical: pd.DataFrame,
        regime_model: Optional[Dict] = None,
) -> Dict[str, Any]:
    """
    Validate that simulated SPY return paths have realistic statistical properties
    compared to the historical calibration sample.

    Checks:
      1. Crisis frequency  — fraction of days with |ret| > 2σ(calm) vs empirical ss_crisis
      2. Vol clustering    — lag-1 autocorr of squared returns (ARCH effect presence)
      3. Annual vol dist   — KS-test p-value of simulated rolling-vol vs historical
      4. MDD distribution  — P25/P50/P75/P90 of per-path MDD vs historical bootstrap
      5. Tail ratio        — sim 1% VaR vs historical 1% VaR (ratio in [0.7, 1.3])
      6. Crisis recovery   — avg recovery time (days) from >20% drawdown
    """
    from scipy import stats as _sp_stats

    if not paths_spy_returns:
        return {'overall_pass': False, 'reason': 'no simulated paths provided'}

    n_paths = len(paths_spy_returns)

    # Historical reference
    hist_col = 'SPY_Ret' if 'SPY_Ret' in df_historical.columns else None
    _hist_arr: Optional[np.ndarray] = None
    if hist_col is not None:
        _hist_arr = np.asarray(
            pd.to_numeric(df_historical[hist_col], errors='coerce').dropna().values,
            dtype=np.float64,
        )

    # Empirical crisis ss from regime_model (if available)
    _ss_crisis_emp = 0.099  # default from calibrated model
    if isinstance(regime_model, dict):
        _tm = regime_model.get('transition_matrix', None)
        if isinstance(_tm, np.ndarray) and _tm.shape == (2, 2):
            _p01 = _tm[0, 1]
            _p10 = _tm[1, 0]
            if _p01 + _p10 > 0:
                _ss_crisis_emp = float(_p01 / (_p01 + _p10))

    checks: Dict[str, Any] = {}
    metrics: Dict[str, Any] = {}
    n_pass = 0
    n_fail = 0

    print(f"\n  Scenario Generator Validation  (n_paths={n_paths:,})")
    print(f"  {'─'*60}")

    # ── Check 1: Crisis frequency ──────────────────────────────────────────
    if _hist_arr is not None:
        _hist_vol = float(np.std(_hist_arr, ddof=1)) * np.sqrt(252)
        _calm_sigma_d = _hist_vol / np.sqrt(252) * 1.0  # approx 1-σ daily in calm
        _crisis_thresh = 2.0 * _calm_sigma_d
        _sim_crisis_fracs = [
            float(np.mean(np.abs(p) > _crisis_thresh))
            for p in paths_spy_returns if len(p) > 0
        ]
        _sim_crisis_mean = float(np.mean(_sim_crisis_fracs)) if _sim_crisis_fracs else np.nan
        _tol1 = 0.05  # ±5pp tolerance
        _pass1 = np.isfinite(_sim_crisis_mean) and abs(_sim_crisis_mean - _ss_crisis_emp) < _tol1
        checks['crisis_frequency'] = {'pass': _pass1, 'sim': _sim_crisis_mean, 'empirical': _ss_crisis_emp}
        metrics['crisis_frequency_sim'] = _sim_crisis_mean
        _mark1 = '✓' if _pass1 else '✗'
        print(f"  {_mark1} C1 Crisis frequency: sim={_sim_crisis_mean*100:.1f}%  "
              f"empirical≈{_ss_crisis_emp*100:.1f}%  tol=±{_tol1*100:.0f}pp")
        n_pass += int(_pass1); n_fail += int(not _pass1)
    else:
        checks['crisis_frequency'] = {'pass': True, 'skipped': True}
        print(f"  — C1 Crisis frequency: skipped (no SPY_Ret in historical df)")
        n_pass += 1

    # ── Check 2: Vol clustering (lag-1 autocorr of squared returns) ───────
    _hist_acf: Optional[float] = None
    if _hist_arr is not None and len(_hist_arr) > 10:
        _sq_hist = _hist_arr ** 2
        _hist_acf = float(np.corrcoef(_sq_hist[:-1], _sq_hist[1:])[0, 1])
    _sim_acfs = []
    for _p in paths_spy_returns:
        _p_arr = np.asarray(_p, dtype=np.float64)
        _p_arr = _p_arr[np.isfinite(_p_arr)]
        if len(_p_arr) > 10:
            _sq = _p_arr ** 2
            _sim_acfs.append(float(np.corrcoef(_sq[:-1], _sq[1:])[0, 1]))
    _sim_acf_mean = float(np.nanmean(_sim_acfs)) if _sim_acfs else np.nan
    _tol2 = 0.07
    if _hist_acf is not None and np.isfinite(_sim_acf_mean):
        _pass2 = abs(_sim_acf_mean - _hist_acf) < _tol2
    else:
        _pass2 = True  # can't evaluate
    checks['vol_clustering'] = {'pass': _pass2, 'sim_acf': _sim_acf_mean, 'hist_acf': _hist_acf}
    metrics['vol_clustering_acf_sim'] = _sim_acf_mean
    _mark2 = '✓' if _pass2 else '✗'
    print(f"  {_mark2} C2 Vol clustering (lag-1 ACF of r²): "
          f"sim={_sim_acf_mean:.3f}  hist={_hist_acf:.3f if _hist_acf is not None else 'n/a'}  "
          f"tol=±{_tol2:.2f}")
    n_pass += int(_pass2); n_fail += int(not _pass2)

    # ── Check 3: Annual vol distribution (KS-test) ─────────────────────────
    _hist_rvols: List[float] = []
    if _hist_arr is not None and len(_hist_arr) >= 252:
        _hs = pd.Series(_hist_arr)
        for _i in range(0, len(_hist_arr) - 252, 63):
            _w = _hist_arr[_i:_i + 252]
            _hist_rvols.append(float(np.std(_w, ddof=1) * np.sqrt(252)))
    _sim_rvols = [
        float(np.std(np.asarray(p, dtype=np.float64), ddof=1) * np.sqrt(252))
        for p in paths_spy_returns if len(p) >= 10
    ]
    if len(_hist_rvols) >= 5 and len(_sim_rvols) >= 5:
        _ks_stat, _ks_p = _sp_stats.ks_2samp(_hist_rvols, _sim_rvols)
        _pass3 = bool(_ks_p >= 0.01)
        checks['annual_vol_dist'] = {'pass': _pass3, 'ks_stat': _ks_stat, 'ks_p': _ks_p}
        metrics['annual_vol_ks_p'] = _ks_p
        _mark3 = '✓' if _pass3 else '✗'
        print(f"  {_mark3} C3 Annual vol distribution (KS p={_ks_p:.3f}, stat={_ks_stat:.3f})  "
              f"threshold p≥0.01")
    else:
        checks['annual_vol_dist'] = {'pass': True, 'skipped': True}
        print(f"  — C3 Annual vol distribution: skipped (insufficient data)")
    n_pass += int(checks['annual_vol_dist'].get('pass', True))
    n_fail += int(not checks['annual_vol_dist'].get('pass', True))

    # ── Check 4: MDD distribution ──────────────────────────────────────────
    _sim_mdds = [
        float(abs(_max_drawdown_from_returns(np.asarray(p, dtype=np.float64))))
        for p in paths_spy_returns if len(p) >= 10
    ]
    if _hist_arr is not None and len(_sim_mdds) >= 5:
        _hist_mdd = float(abs(_max_drawdown_from_returns(_hist_arr)))
        _sim_mdd_p50 = float(np.median(_sim_mdds))
        _sim_mdd_p90 = float(np.percentile(_sim_mdds, 90))
        # For 10-year paths, MDD should generally exceed the historical 1-year MDD
        _pass4 = _sim_mdd_p50 >= _hist_mdd * 0.3  # very loose: median sim MDD ≥ 30% of hist
        checks['mdd_distribution'] = {
            'pass': _pass4,
            'sim_p50': _sim_mdd_p50, 'sim_p90': _sim_mdd_p90,
            'hist_mdd': _hist_mdd,
        }
        metrics.update({'mdd_sim_p50': _sim_mdd_p50, 'mdd_sim_p90': _sim_mdd_p90})
        _mark4 = '✓' if _pass4 else '✗'
        print(f"  {_mark4} C4 MDD dist: sim P50={_sim_mdd_p50*100:.1f}%  "
              f"P90={_sim_mdd_p90*100:.1f}%  hist={_hist_mdd*100:.1f}%")
    else:
        checks['mdd_distribution'] = {'pass': True, 'skipped': True}
        print(f"  — C4 MDD distribution: skipped")
    n_pass += int(checks['mdd_distribution'].get('pass', True))
    n_fail += int(not checks['mdd_distribution'].get('pass', True))

    # ── Check 5: Tail ratio (1% VaR) ──────────────────────────────────────
    if _hist_arr is not None and len(_hist_arr) >= 30:
        _hist_var1 = float(np.percentile(_hist_arr, 1))
        _sim_var1s = [
            float(np.percentile(np.asarray(p, dtype=np.float64), 1))
            for p in paths_spy_returns if len(p) >= 20
        ]
        if _sim_var1s:
            _sim_var1_mean = float(np.nanmean(_sim_var1s))
            _ratio5 = _sim_var1_mean / _hist_var1 if abs(_hist_var1) > 1e-8 else np.nan
            _pass5 = np.isfinite(_ratio5) and 0.7 <= _ratio5 <= 1.3
            checks['tail_ratio'] = {'pass': _pass5, 'ratio': _ratio5,
                                    'sim_var1': _sim_var1_mean, 'hist_var1': _hist_var1}
            metrics['tail_var1_ratio'] = _ratio5
            _mark5 = '✓' if _pass5 else '✗'
            print(f"  {_mark5} C5 Tail (1% VaR) ratio: {_ratio5:.2f}  "
                  f"(sim={_sim_var1_mean*100:.2f}%  hist={_hist_var1*100:.2f}%)  "
                  f"target [0.7, 1.3]")
        else:
            checks['tail_ratio'] = {'pass': True, 'skipped': True}
            print(f"  — C5 Tail ratio: skipped")
    else:
        checks['tail_ratio'] = {'pass': True, 'skipped': True}
        print(f"  — C5 Tail ratio: skipped (no historical reference)")
    n_pass += int(checks['tail_ratio'].get('pass', True))
    n_fail += int(not checks['tail_ratio'].get('pass', True))

    # ── Check 6: Crisis recovery time ──────────────────────────────────────
    def _recovery_times(ret_arr: np.ndarray, mdd_thresh: float = 0.20) -> List[int]:
        """Days to recover from peak-to-trough exceeding mdd_thresh."""
        wealth = np.cumprod(1.0 + ret_arr)
        peak = np.maximum.accumulate(wealth)
        dd = (wealth - peak) / np.maximum(peak, 1e-9)
        times = []
        in_crisis = False
        trough_peak = 1.0
        entry_day = 0
        for i, (w, d) in enumerate(zip(wealth, dd)):
            if not in_crisis and d <= -mdd_thresh:
                in_crisis = True
                entry_day = i
                trough_peak = float(peak[i])
            elif in_crisis and w >= trough_peak:
                times.append(i - entry_day)
                in_crisis = False
        return times

    _sim_recs = []
    for _p in paths_spy_returns:
        _p_arr = np.asarray(_p, dtype=np.float64)
        _p_arr = _p_arr[np.isfinite(_p_arr)]
        _rt = _recovery_times(_p_arr)
        if _rt:
            _sim_recs.extend(_rt)
    if _hist_arr is not None and _sim_recs:
        _hist_recs = _recovery_times(_hist_arr)
        _sim_rec_med = float(np.median(_sim_recs)) if _sim_recs else np.nan
        _hist_rec_med = float(np.median(_hist_recs)) if _hist_recs else np.nan
        _pass6 = True  # informational only — wide tolerance on recovery time
        checks['crisis_recovery'] = {
            'pass': _pass6, 'sim_median_days': _sim_rec_med,
            'hist_median_days': _hist_rec_med,
        }
        metrics.update({'crisis_recovery_sim_median': _sim_rec_med,
                        'crisis_recovery_hist_median': _hist_rec_med})
        print(f"  ✓ C6 Crisis recovery (informational): sim median={_sim_rec_med:.0f}d  "
              f"hist median={_hist_rec_med:.0f}d")
    else:
        checks['crisis_recovery'] = {'pass': True, 'skipped': True}
        print(f"  — C6 Crisis recovery: skipped")
    n_pass += int(checks['crisis_recovery'].get('pass', True))
    n_fail += int(not checks['crisis_recovery'].get('pass', True))

    overall = (n_fail == 0)
    _verdict = 'PASS' if overall else f'FAIL ({n_fail} checks failed)'
    print(f"  {'─'*60}")
    print(f"  Scenario validation: {n_pass}/{n_pass+n_fail} checks  {_verdict}")

    return {
        'overall_pass': overall,
        'n_pass': n_pass,
        'n_fail': n_fail,
        'checks': checks,
        'metrics': metrics,
    }


# ============================================================================
# ITEM 7 — SENSITIVITY TABLES
# ============================================================================

def run_sensitivity_tables(
        df: pd.DataFrame,
        regime_model: Dict,
        fund: str = 'UPRO',
        horizon_years: int = 10,
        n_paths: int = 100,
        base_scenario: str = 'neutral',
) -> Dict[str, Any]:
    """
    Run three sensitivity tables for a given LETF fund:
      Table A: Borrowing spread sensitivity  (borrow_spread_bps sweep)
      Table B: Risk-free rate sensitivity    (rf_shift_bps sweep)
      Table C: Volatility multiplier         (vol_mult sweep)

    For each cell: run n_paths simulations, extract P5/P50/P95 terminal wealth.
    Returns full dict with P5/P50/P95 for each cell. Prints ASCII tables.
    """
    import copy as _copy

    fund_u = str(fund).upper()
    n_years = int(horizon_years)

    # ── Table A: Spread sensitivity ────────────────────────────────────────
    _spreads_bps   = [0, 25, 50, 75, 100, 200]
    # ── Table B: Rate sensitivity ──────────────────────────────────────────
    _rf_shifts_bps = [-200, -100, 0, +100, +200, +400]
    # ── Table C: Vol multiplier ────────────────────────────────────────────
    _vol_mults     = [0.5, 0.75, 1.0, 1.25, 1.5, 2.0]

    def _run_cell(borrow_spread_bps: float = 0.0,
                  rf_shift_bps:       float = 0.0,
                  vol_mult:           float = 1.0) -> Tuple[float, float, float]:
        """Return (P5, P50, P95) of n_paths terminal wealth ratios."""
        _tws: List[float] = []
        _rng_cell = np.random.default_rng(int(abs(borrow_spread_bps * 100 + rf_shift_bps + vol_mult * 37)))
        for _pi in range(n_paths):
            try:
                _path_len = int(n_years * 252)
                _vol = float(regime_model.get('regimes', [{}])[0].get('daily_vol', 0.012)) if isinstance(regime_model, dict) else 0.012
                _mu  = float(regime_model.get('regimes', [{}])[0].get('daily_mean', 0.00057)) if isinstance(regime_model, dict) else 0.00057
                _rf_d = (0.045 + rf_shift_bps / 10000.0) / 252.0
                _bor_d = (borrow_spread_bps / 10000.0) / 252.0
                _underlying = _rng_cell.normal(_mu, _vol * vol_mult, _path_len)
                _lev = float(ASSETS[fund_u]['leverage'])
                _exp_d = float(ASSETS[fund_u]['expense_ratio']) / 252.0
                _letf = _lev * _underlying - (_lev - 1.0) * (_rf_d + _bor_d) - _exp_d
                _tw = float(np.prod(1.0 + np.clip(_letf, -0.99, 10.0)))
                _tws.append(_tw)
            except Exception:
                pass
        if not _tws:
            return (np.nan, np.nan, np.nan)
        _a = np.array(_tws, dtype=np.float64)
        return (float(np.percentile(_a, 5)), float(np.median(_a)), float(np.percentile(_a, 95)))

    def _print_table(title: str, param_vals: List[float], param_label: str,
                     cells: List[Tuple[float, float, float]]) -> None:
        print(f"\n  {title}")
        print(f"  {'─'*72}")
        print(f"  {param_label:<20} {'P5 TW':>8} {'P50 TW':>8} {'P95 TW':>8}  "
              f"{'P5 CAGR':>9} {'P50 CAGR':>10}")
        print(f"  {'─'*72}")
        for pv, (p5, p50, p95) in zip(param_vals, cells):
            if np.isnan(p5):
                print(f"  {str(pv):<20} {'n/a':>8}")
                continue
            _c5  = float((p5  ** (1.0/n_years) - 1.0) * 100) if p5  > 0 else np.nan
            _c50 = float((p50 ** (1.0/n_years) - 1.0) * 100) if p50 > 0 else np.nan
            print(f"  {str(pv):<20} {p5:>8.2f}x {p50:>8.2f}x {p95:>8.2f}x  "
                  f"{_c5:>+9.1f}% {_c50:>+10.1f}%")
        print(f"  {'─'*72}")

    results: Dict[str, Any] = {'fund': fund_u, 'horizon_years': n_years, 'n_paths': n_paths}

    print(f"\n  Sensitivity Tables — {fund_u}  "
          f"(horizon={n_years}yr, n_paths={n_paths}, base={base_scenario})")

    # Table A
    cells_a = [_run_cell(borrow_spread_bps=float(s)) for s in _spreads_bps]
    _print_table(
        f"Table A: Borrowing-Spread Sensitivity  [{fund_u}, {n_years}yr]",
        [float(s) for s in _spreads_bps], 'Spread (bps/yr)', cells_a,
    )
    results['table_a'] = {
        str(s): {'P5': c[0], 'P50': c[1], 'P95': c[2]}
        for s, c in zip(_spreads_bps, cells_a)
    }

    # Table B
    cells_b = [_run_cell(rf_shift_bps=float(s)) for s in _rf_shifts_bps]
    _print_table(
        f"Table B: Risk-Free Rate Sensitivity  [{fund_u}, {n_years}yr]",
        [float(s) for s in _rf_shifts_bps], 'RF shift (bps/yr)', cells_b,
    )
    results['table_b'] = {
        str(s): {'P5': c[0], 'P50': c[1], 'P95': c[2]}
        for s, c in zip(_rf_shifts_bps, cells_b)
    }

    # Table C
    cells_c = [_run_cell(vol_mult=float(v)) for v in _vol_mults]
    _print_table(
        f"Table C: Volatility Regime Sensitivity  [{fund_u}, {n_years}yr]",
        [float(v) for v in _vol_mults], 'Vol multiplier', cells_c,
    )
    results['table_c'] = {
        str(v): {'P5': c[0], 'P50': c[1], 'P95': c[2]}
        for v, c in zip(_vol_mults, cells_c)
    }

    return results


# ============================================================================
# ITEM 9 — PM-READY REPORT
# ============================================================================

def generate_pm_report(
        simulation_results: Optional[List[Dict]] = None,
        df: Optional[pd.DataFrame] = None,
        walkforward_results: Optional[Dict] = None,
        validation_report: Optional[Dict] = None,
        tracking_model: Optional[Dict] = None,
        scenario_name: str = 'neutral',
        output_format: str = 'text',
) -> str:
    """
    Generate a PM-ready briefing report summarising LETF Monte Carlo results.

    Sections:
      1. Headline metrics (median/P5/P95 terminal wealth and CAGR)
      2. Drawdown statistics (median MDD, P90 MDD)
      3. Risk metrics (VaR at 5% over multiple horizons)
      4. Tracking fidelity (walk-forward results, emulation type)
      5. Scenario assumptions
      6. Known limitations

    Returns the report as a string (and prints it).
    """
    import datetime as _dt

    _lines: List[str] = []

    def _add(line: str = '') -> None:
        _lines.append(line)

    _now = _dt.datetime.now().strftime('%Y-%m-%d')
    _bar = '═' * 70

    _add(_bar)
    _add('  LETF MONTE CARLO ANALYSIS — PM BRIEFING')
    _add(f'  Generated: {_now}  |  Engine: v1.6 / cache {CACHE_MODEL_VERSION}')
    _add(f'  Scenario: {scenario_name}  |  Calibration: post-2009 LETF inception')
    _add(_bar)

    # ── Section 1: Headline Metrics ────────────────────────────────────────
    _add('')
    _add('1. HEADLINE METRICS')
    _add(f"   {'Strategy':<22} {'Median TW':>10} {'P5 TW':>8} {'P95 TW':>8} {'Med CAGR':>10}")
    _add(f"   {'─'*60}")
    if simulation_results:
        _fund_stats: Dict[str, Dict[str, float]] = {}
        for _r in simulation_results:
            _fnd = str(_r.get('fund', _r.get('Strategy', 'Unknown')))
            _tw  = float(_r.get('Terminal_Wealth', np.nan))
            _cagr = float(_r.get('CAGR', np.nan))
            if _fnd not in _fund_stats:
                _fund_stats[_fnd] = {'tws': [], 'cagrs': []}
            if np.isfinite(_tw):
                _fund_stats[_fnd]['tws'].append(_tw)
            if np.isfinite(_cagr):
                _fund_stats[_fnd]['cagrs'].append(_cagr)
        for _fnd, _fd in sorted(_fund_stats.items()):
            _tws_arr  = np.array(_fd['tws'], dtype=np.float64)
            _cg_arr   = np.array(_fd['cagrs'], dtype=np.float64)
            _p50_tw   = float(np.median(_tws_arr))  if len(_tws_arr) > 0 else np.nan
            _p5_tw    = float(np.percentile(_tws_arr, 5))  if len(_tws_arr) > 0 else np.nan
            _p95_tw   = float(np.percentile(_tws_arr, 95)) if len(_tws_arr) > 0 else np.nan
            _med_cagr = float(np.median(_cg_arr)) if len(_cg_arr) > 0 else np.nan
            _add(f"   {_fnd:<22} {_p50_tw:>10.2f}x {_p5_tw:>8.2f}x {_p95_tw:>8.2f}x "
                 f"{_med_cagr*100:>+10.1f}%/yr")
    else:
        _add('   (no simulation results provided)')

    # ── Section 2: Drawdown Statistics ────────────────────────────────────
    _add('')
    _add('2. DRAWDOWN STATISTICS')
    _add(f"   {'Strategy':<22} {'Med MDD':>8} {'P90 MDD':>8} {'Med Recov':>12}")
    _add(f"   {'─'*55}")
    if simulation_results:
        _dd_stats: Dict[str, List[float]] = {}
        for _r in simulation_results:
            _fnd = str(_r.get('fund', _r.get('Strategy', 'Unknown')))
            _mdd = float(_r.get('Max_DD', np.nan))
            if _fnd not in _dd_stats:
                _dd_stats[_fnd] = []
            if np.isfinite(_mdd):
                _dd_stats[_fnd].append(_mdd)
        for _fnd, _mdds in sorted(_dd_stats.items()):
            if not _mdds:
                continue
            _ma = np.array(_mdds, dtype=np.float64)
            _p50_mdd = float(np.median(_ma))
            _p90_mdd = float(np.percentile(_ma, 90))
            _add(f"   {_fnd:<22} {_p50_mdd*100:>+8.1f}% {_p90_mdd*100:>+8.1f}%  {'n/a':>12}")
    else:
        _add('   (no simulation results provided)')

    # ── Section 3: Risk Metrics ────────────────────────────────────────────
    _add('')
    _add('3. RISK METRICS (VaR 5% — worst 5% of paths)')
    if simulation_results:
        _fnd_results: Dict[str, List[float]] = {}
        for _r in simulation_results:
            _fnd = str(_r.get('fund', _r.get('Strategy', 'Unknown')))
            _tw  = float(_r.get('Terminal_Wealth', np.nan))
            if _fnd not in _fnd_results:
                _fnd_results[_fnd] = []
            if np.isfinite(_tw):
                _fnd_results[_fnd].append(_tw)
        for _fnd, _tws_l in sorted(_fnd_results.items()):
            if not _tws_l:
                continue
            _ta = np.array(_tws_l, dtype=np.float64)
            _var5 = float(np.percentile(_ta, 5))
            _add(f"   {_fnd}: P5 terminal wealth = {_var5:.2f}x "
                 f"(worst-case 5% of paths over simulation horizon)")
    else:
        _add('   (no simulation results provided)')

    # ── Section 4: Tracking Fidelity ──────────────────────────────────────
    _add('')
    _add('4. TRACKING FIDELITY  (walk-forward, institutional_gate mode)')
    if walkforward_results:
        _wfr = walkforward_results
        _fnd_wf = _wfr.get('fund', 'N/A')
        _bias   = _wfr.get('pooled_mean_err_ann', np.nan)
        _tw_e   = _wfr.get('pooled_tw_rel_err', np.nan)
        _te_e   = _wfr.get('pooled_te_ann', np.nan)
        _verdict = 'PASS' if _wfr.get('overall_pass') else 'FAIL'
        _add(f"   {_fnd_wf}: bias={_bias*100:+.2f}%/yr  "
             f"TW_err={_tw_e*100:.1f}%  TE={_te_e*100:.2f}%  [{_verdict}]")
        _emul_type = (tracking_model or {}).get(_fnd_wf, {}).get('emulation_type', 'unknown')
        _add(f"   Emulation type: {_emul_type}")
    elif tracking_model:
        _add(f"   {'Asset':<8} {'Emul Type':<25} {'Spread':>12}")
        for _asset, _am in tracking_model.items():
            if not isinstance(_am, dict):
                continue
            _et  = str(_am.get('emulation_type', 'unknown'))
            _sp  = float(_am.get('calibrated_spread', np.nan))
            _sp_s = f"{_sp*100:+.3f}%/yr" if np.isfinite(_sp) else 'n/a'
            _add(f"   {_asset:<8} {_et:<25} {_sp_s:>12}")
    else:
        _add('   (no walk-forward or tracking model data provided)')

    # ── Section 5: Scenario Assumptions ───────────────────────────────────
    _add('')
    _add('5. SCENARIO ASSUMPTIONS')
    try:
        _sc = get_scenario()
        _add(f"   Scenario name    : {scenario_name}")
        _add(f"   Drift tilt       : {float(_sc.get('drift_tilt', 0.0))*100:+.1f}%/yr")
        _add(f"   Crisis prob scale: {float(_sc.get('crisis_prob_scale', 1.0)):.2f}×")
        _add(f"   Crisis dwell     : {float(_sc.get('crisis_dwell_scale', 1.0)):.2f}×")
        _add(f"   Inflation        : {float(_sc.get('inflation', 0.0))*100:.1f}%/yr")
    except Exception:
        _add(f"   Scenario name    : {scenario_name}")
        _add('   (could not load scenario parameters)')

    # ── Section 5b: Gate vs Diagnostic Distinction ────────────────────────
    _add('')
    _add('5b. VALIDATION MODE DISCLOSURE')
    _add('   Two modes exist for reconstruction validation:')
    _add('')
    _add('   INSTITUTIONAL_GATE (binding PASS/FAIL):')
    _add('     • Rolling alpha FROZEN at TRAIN-calibrated per-regime values for ALL OOS dates.')
    _add('     • No actual fund returns from the validation window influence the model.')
    _add('     • OOS CAGR bias in gate mode: typically ~0.5-1.0%/yr for UPRO (conservative).')
    _add('     • Gate PASS criteria: |CAGR_diff| < 0.5%/yr, TE < 2%, TW_rel_err < 10%.')
    _add('     • TRAIN period: fund inception → val_start. VALID: val_start → val_end.')
    _add('')
    _add('   DIAGNOSTIC_REPLAY (informational only, no PASS/FAIL):')
    _add('     • Rolling alpha uses causal lagged OOS fund returns (252-day rolling window).')
    _add('     • Achieves lower CAGR bias (~0.1-0.2%/yr) but uses OOS data; not auditable.')
    _add('     • Results labelled [DIAGNOSTIC ONLY]. Do NOT cite for regulatory purposes.')
    _add('')
    _add('   Structural gate FAILURES (pre-existing, not fixed by emulation):')
    _add('     • UPRO TE ~2.15%/yr > 2.0% gate: 3× leverage amplifies daily noise (structural).')
    _add('     • TQQQ TE ~2.96%/yr > 2.0% gate: 3× leverage + NASDAQ volatility (structural).')
    _add('     • SSO beta ~1.014 > 1.01 gate: rolling alpha slightly correlated with returns.')
    _add('     • These do NOT block simulation (LETF_RECONSTRUCTION_HARD_GATE=False).')
    _add('     • They are disclosed here and in per-asset FAIL REASONS output.')

    # ── Section 6: Known Limitations ──────────────────────────────────────
    _add('')
    _add('6. KNOWN LIMITATIONS')
    _add(f'   • TE for 3× LETFs (UPRO, TQQQ) structurally ~2-3%/yr (daily noise floor).')
    _add(f'     This exceeds the 2.0% gate. SIMULATION IS NOT HARD-BLOCKED (gate=soft).')
    _add(f'   • Crisis avg duration ~10.7d (VIX mean-reversion). Real bear markets: months.')
    _add(f'     Use crisis_dwell_scale ≥ 5 to compensate for multi-month drawdowns.')
    _add(f'   • Calibration window 2009-2024 (post-GFC): includes exceptional bull market.')
    _add(f'     Neutral median SPY CAGR ~16%/yr (block-bootstrap dominated by 2010-2026).')
    _add(f'     Use historical mode for long-run (1926+) projections.')
    _add(f'   • Rolling alpha is an emulation term. In gate mode: frozen to TRAIN values.')
    _add(f'     In diagnostic mode: adapts via causal 252-day rolling window (OOS data).')
    _add(f'     Walk-forward stability: typically ±0.1-0.2%/yr across 5 blocks.')
    _add(f'   • SPY-QQQ corr 0.96 (within 2015-2025 data); long-run band is [0.85, 0.92].')
    _add(f'   • Jump scale underestimates extreme events by ~5-15% (MAD conservatism).')
    _add(f'   • Metrics labelled GATE are binding. Metrics labelled DIAG are informational.')
    _add(f'     Never cite DIAGNOSTIC_REPLAY corr/TE/CAGR as pass criteria.')
    _add('')
    _add(_bar)

    report_text = '\n'.join(_lines)
    print(report_text)

    if output_format == 'dict':
        return report_text
    return report_text


# ============================================================================
# MAIN EXECUTION FUNCTION
# ============================================================================

def main(config_scenario: Optional[str] = None):
    """Main execution - runs complete LETF analysis with percentile reporting"""
    global ANALYSIS_START_DATE, MARKET_SCENARIO
    
    print("\n" + "="*80)
    print("LETF ANALYSIS WITH PERCENTILE REPORTING")
    print("="*80)

    # ========================================================================
    # STEP 0: Select Market Scenario
    # ========================================================================
    scenario_resolution = resolve_selected_scenario(config_scenario=config_scenario)
    MARKET_SCENARIO = scenario_resolution.engine_key
    assert scenario_resolution.canonical_key is not None
    print(f"SCENARIO SOURCE: {scenario_resolution.source}")
    print(f"SCENARIO SELECTED: {scenario_resolution.display_name}")
    configure_cache_paths(
        start_date=ANALYSIS_START_DATE,
        end_date=ANALYSIS_END_DATE,
        scenario_name=MARKET_SCENARIO
    )

    # ========================================================================
    # STEP 1: Select Analysis Date Range
    # ========================================================================
    selected_start, selected_end = get_start_date_interactive()
    
    print(f"\n  Using date range: {selected_start} to {selected_end}")
    configure_cache_paths(start_date=selected_start, end_date=selected_end, scenario_name=MARKET_SCENARIO)
    
    # ========================================================================
    # STEP 2: Fetch and Filter Historical Data
    # ========================================================================
    print("\nFetching historical data...")
    df = fetch_historical_data()
    
    # Verify data range
    print(f"\n  Data loaded: {df.index[0].date()} to {df.index[-1].date()}")
    print(f"  Total days: {len(df):,} ({len(df)/252:.2f} years)")
    set_historical_anchor_target_from_data(df)
    synthetic_risk_report = report_synthetic_model_risk(df)

    # Pre-load 1926 Fama-French data for historical scenarios.
    # Runs unconditionally so arrays are available even if the user switches scenario
    # mid-session.  Fast if FF data is already cached by pandas_datareader.
    print("\nLoading 1926+ Fama-French data for historical scenarios...")
    _load_historical_1926_data(df)

    # Load FRED CPI for real-return calculations in historical_backtest mode.
    # Runs unconditionally (fast; uses pandas_datareader FRED cache).
    print("Loading FRED CPI (CPIAUCSL) for real-return inflation adjustment...")
    load_cpi_series(start_date='1913-01-01')

    # Build calibration dataset (can be longer than selected analysis window).
    calibration_df, calibration_info = load_calibration_dataframe(
        selected_df=df,
        selected_start=selected_start,
        selected_end=selected_end,
        scenario_name=MARKET_SCENARIO
    )
    print(f"  Calibration dataset: {calibration_df.index[0].date()} -> {calibration_df.index[-1].date()} "
          f"({len(calibration_df):,} days, {len(calibration_df)/252:.2f} years)")
    
    # Calibrate regime model
    print("\nCalibrating regime model...")
    regime_model = calibrate_regime_model_volatility(calibration_df)

    # Institutional model components (roadmap Phase 1-3)
    print("Calibrating joint return model...")
    regime_model['joint_return_model'] = calibrate_joint_return_model(calibration_df, regime_model['regimes_historical'])

    print("Calibrating funding spread model...")
    regime_model['funding_model'] = calibrate_funding_spread_model(calibration_df)

    print("Calibrating structural macro model (CAPE/rates/term structure)...")
    regime_model['structural_econ_model'] = calibrate_structural_economic_model(calibration_df)

    print("Calibrating stress-state model...")
    regime_model['stress_state_model'] = calibrate_stress_state_model(calibration_df, regime_model['regimes_historical'])

    print("Calibrating tracking residual model...")
    regime_model['tracking_residual_model'] = calibrate_tracking_residual_model(
        calibration_df,
        funding_model=regime_model['funding_model']
    )
    if MARKET_SCENARIO in ('historical_backtest', 'historical_bootstrap'):
        print("Skipping leveraged-drag retune in historical mode "
              "(preserve direct historical fund-emulation parameters).")
        _funding_tuned = regime_model['funding_model']
        _tracking_tuned = regime_model['tracking_residual_model']
        _drag_diag = {
            'enabled': False,
            'reason': 'skipped_for_historical_mode',
            'scenario': str(MARKET_SCENARIO),
        }
    else:
        print("Re-tuning leveraged drag against real-only 10Y medians/tails...")
        _funding_tuned, _tracking_tuned, _drag_diag = tune_leveraged_drag_components_real_only(
            df=calibration_df,
            funding_model=regime_model['funding_model'],
            tracking_model=regime_model['tracking_residual_model'],
            years=10
        )
    regime_model['funding_model'] = _funding_tuned
    regime_model['tracking_residual_model'] = _tracking_tuned
    regime_model['drag_tuning'] = _drag_diag
    regime_model['calibration_window'] = dict(calibration_info)
    regime_model['synthetic_model_risk'] = dict(synthetic_risk_report)
    regime_model['calibration_report'] = report_calibration_details(
        calibration_info=calibration_info,
        regime_model=regime_model
    )
    regime_model['scenario_calibration'] = refresh_scenario_calibration(
        df=calibration_df,
        regime_model=regime_model
    )

    run_ctx: Dict[str, Any] = {
        'scenario_resolution': scenario_resolution,
        'selected_start': str(selected_start),
        'selected_end': str(selected_end),
        'simulation_window_start': str(selected_start),
        'simulation_window_end': str(selected_end),
        'validation_window_start': str(selected_start),
        'validation_window_end': str(selected_end),
        'strategy_ids': list(STRATEGIES.keys()),
    }
    run_ctx['relevant_assets'] = get_relevant_assets_for_selected_strategies(run_ctx['strategy_ids'])
    run_ctx['coverage_report'] = {}
    run_ctx['resolved_driver_map'] = {}
    run_ctx['resolved_driver_source_map'] = {}
    run_ctx['reconstruction_validation'] = {}

    if _is_extended_historical_backtest_key(scenario_resolution.canonical_key):
        run_ctx['coverage_report'] = detect_required_synthetic_coverage(
            source_df=df,
            relevant_assets=run_ctx['relevant_assets'],
            window=(selected_start, selected_end),
        )
        run_ctx['resolved_driver_map'] = resolve_run_driver_map(
            source_df=df,
            relevant_assets=run_ctx['relevant_assets'],
            scenario_meta=scenario_resolution,
        )
        run_ctx['resolved_driver_source_map'] = resolve_run_driver_source_map(
            source_df=df,
            driver_map=run_ctx['resolved_driver_map'],
        )
        if bool(run_ctx['coverage_report'].get('requires_synthetic', False)):
            print("Validating LETF reconstruction accuracy (institutional gate for Extended Historical Backtest)...")
            letf_reconstruction_validation = validate_reconstruction_on_run_dataframe(
                source_df=df,
                calibration_df=calibration_df,
                run_ctx=run_ctx,
            )
            letf_reconstruction_validation['integrity_audit'] = audit_reconstruction_validator_integrity(
                validation_report=letf_reconstruction_validation,
                run_ctx=run_ctx,
            )
            generate_reconstruction_diagnostic_report(letf_reconstruction_validation)
        else:
            letf_reconstruction_validation = {
                'status': 'not_required',
                'validation_window_start': str(selected_start),
                'validation_window_end': str(selected_end),
                'validation_residual_policy': 'N/A',
                'resolved_driver_mapping': dict(run_ctx['resolved_driver_map']),
                'assets': {},
                'assets_evaluated': 0,
                'assets_passed': 0,
                'overall_pass': True,
                'failures': [],
                'summary_message': 'Synthetic backfill not required for selected window.',
                'integrity_audit': {},
            }
        regime_model['letf_reconstruction_validation'] = dict(letf_reconstruction_validation)
        run_ctx['reconstruction_validation'] = letf_reconstruction_validation
    else:
        # Preserve the existing broad diagnostic report outside the historical
        # real-first routing path. This remains informational unless the global
        # warn-only/hard gate setting changes.
        print("Validating LETF reconstruction accuracy (institutional hard gate)...")
        letf_reconstruction_validation = validate_letf_reconstruction_accuracy(
            df=calibration_df,
            tracking_model=regime_model.get('tracking_residual_model', {}),
        )
        generate_reconstruction_diagnostic_report(letf_reconstruction_validation)
        regime_model['letf_reconstruction_validation'] = dict(letf_reconstruction_validation)
        _enforce_reconstruction_validation_gate(letf_reconstruction_validation)
        print(f"  {letf_reconstruction_validation.get('summary_message', '')}")
        run_ctx['reconstruction_validation'] = letf_reconstruction_validation

    df, calibration_df = orchestrate_run(
        source_df=df,
        calibration_df=calibration_df,
        regime_model=regime_model,
        run_ctx=run_ctx,
    )

    # Calibrate correlations
    print("Calibrating correlations...")
    correlation_matrices = calibrate_correlations_time_varying(calibration_df, regime_model)

    # Two-stage constrained tuning:
    # Stage A (SPY crash core) -> Stage B (LETF tail overlay, constrained by Stage A drawdown realism).
    if ENABLE_TWO_STAGE_TAIL_TUNING:
        print("Stage A: constrained SPY crash-state tuning (drawdown + volatility gates)...")
        stage_a_diag = tune_spy_crash_state_constrained(
            df=calibration_df,
            regime_model=regime_model,
            severity_grid=list(STAGE_A_CRASH_SEVERITY_GRID),
            dd_n_sims=int(STAGE_A_CRASH_DD_SIMS),
            vol_n_sims=int(STAGE_A_CRASH_VOL_SIMS),
            refine=bool(STAGE_A_CRASH_REFINE)
        )
        regime_model['spy_crash_tuning'] = dict(stage_a_diag)
        if isinstance(stage_a_diag.get('stress_state_model', None), dict):
            regime_model['stress_state_model'] = dict(stage_a_diag['stress_state_model'])
            save_cache(regime_model['stress_state_model'], STRESS_STATE_CACHE)

        print("Stage B: constrained LETF tail-overlay tuning (leveraged vol percentiles)...")
        stage_b_diag = tune_letf_tail_overlay_constrained(
            df=calibration_df,
            regime_model=regime_model,
            correlation_matrices=correlation_matrices,
            scales=list(STAGE_B_TAIL_SCALE_GRID),
            n_sims=int(STAGE_B_TAIL_MC_SIMS),
            horizon_years=int(STAGE_B_TAIL_HORIZON_YEARS),
            require_drawdown_pass=bool(STAGE_B_TAIL_REQUIRE_DD_PASS),
            dd_n_sims=int(STAGE_B_TAIL_DD_SIMS)
        )
        regime_model['letf_tail_tuning'] = dict(stage_b_diag)

    if ENABLE_STAGE_C_EXEC_TE_TUNING:
        print("Stage C: constrained TE/execution coefficient tuning (tracking + slippage + post-cost vol)...")
        stage_c_diag = tune_execution_te_coefficients_constrained(
            df=calibration_df,
            regime_model=regime_model,
            correlation_matrices=correlation_matrices,
            te_scales=list(STAGE_C_EXEC_TE_GRID),
            exec_scales=list(STAGE_C_EXEC_COST_GRID),
            n_sims=int(STAGE_C_EXEC_MC_SIMS),
            horizon_years=int(STAGE_C_EXEC_HORIZON_YEARS),
            strategy_ids=list(STAGE_C_EXEC_VOL_STRATEGIES),
            require_drawdown_pass=bool(STAGE_C_EXEC_REQUIRE_DD_PASS),
            dd_n_sims=int(STAGE_C_EXEC_DD_SIMS)
        )
        regime_model['execution_te_tuning'] = dict(stage_c_diag)
    
    # Run validation tests
    print("Running validation tests...")
    validation_results = run_validation_tests(
        df=df,
        regime_model=regime_model,
        walk_forward_df=calibration_df
    )

    # ── Historical Bootstrap: validation suite (G–I) ─────────────────────────
    # Runs when MARKET_SCENARIO == 'historical_bootstrap'.
    # Validates: purity (G), vol fidelity (H), MDD sanity (I).
    if MARKET_SCENARIO == 'historical_bootstrap':
        print("\nRunning Historical Bootstrap validation suite...")
        _bootstrap_seed_cfg = _SCENARIO_PRESETS['historical_bootstrap'].get('bootstrap_seed', None)
        _bootstrap_method_cfg = str(_SCENARIO_PRESETS['historical_bootstrap'].get('bootstrap_method', 'fixed')).strip().lower()
        _stationary_p_cfg = _SCENARIO_PRESETS['historical_bootstrap'].get('stationary_p', None)
        bootstrap_val = validate_historical_bootstrap(
            n_test_paths=20,
            horizon_years=10.0,   # 10-yr paths give meaningful MDD; independent of TIME_HORIZONS
            block_size=int(
                _SCENARIO_PRESETS['historical_bootstrap'].get('_hist1926_block_size', 63)
            ),
            bootstrap_seed=(int(_bootstrap_seed_cfg) if _bootstrap_seed_cfg is not None else None),
            bootstrap_method=_bootstrap_method_cfg,
            stationary_p=(float(_stationary_p_cfg) if _stationary_p_cfg is not None else None),
            start_date=selected_start,
            end_date=selected_end,
        )
        validation_results['historical_bootstrap'] = bootstrap_val

    # ── Historical Backtest: mandatory validation suite ───────────────────────
    # Runs when MARKET_SCENARIO == 'historical_backtest'.
    # Validates: driver immutability, SPY fidelity, borrow cost formula,
    #            LETF emulator OOS, taxable vs tax-free, determinism.
    if MARKET_SCENARIO == 'historical_backtest':
        print(f"\n{'█'*72}")
        print("  INSTITUTIONAL INTEGRITY MODE ENABLED")
        print("  Real data priority enforced — synthetic data cannot overwrite real data")
        print(f"  ENGINE CODE HASH: {ENGINE_CODE_HASH}")
        print(f"  DRIVER_ALPHA_INTEGRITY_THRESHOLD : {DRIVER_ALPHA_INTEGRITY_THRESHOLD:.1e}"
              f"  ({DRIVER_ALPHA_INTEGRITY_THRESHOLD*1e4:.3f} bps/d"
              f" / {DRIVER_ALPHA_INTEGRITY_THRESHOLD*252*100:.3f}%/yr)")
        print(f"  IMPLIED_SPREAD_NEGATIVE_THRESHOLD: {IMPLIED_SPREAD_NEGATIVE_THRESHOLD:.4f}/yr"
              f"  ({IMPLIED_SPREAD_NEGATIVE_THRESHOLD*1e4:.1f} bps/yr)")
        print(f"{'█'*72}\n")
        print("\nRunning Historical Backtest validation suite...")
        # Correlation matrices are needed for taxable validation; build lazily.
        _corr_for_val = correlation_matrices
        # Sentinel values for finally block — remain False/None if validation crashes.
        _recon_val_pass: bool = False
        _recon_val_dr_hash: Optional[str] = None
        _recon_val_dr_hash_n: Optional[int] = None
        _recon_val_dr_hash_ds: Optional[str] = None
        _recon_val_dr_hash_de: Optional[str] = None
        try:
            recon_val = run_historical_reconstruction_validation(
                df=df,
                regime_model=regime_model,
                correlation_matrices=_corr_for_val,
                window_start=selected_start,
                window_end=selected_end,
            )
            validation_results['historical_backtest'] = recon_val
            # Report CPI-adjusted inflation used in this window
            _wd = _slice_hist1926_to_window(selected_start, selected_end)
            if _wd is not None and _HIST_RECON_CPI is not None:
                try:
                    _cpi_s = float(_HIST_RECON_CPI.asof(pd.Timestamp(_wd['dates_start'])))
                    _cpi_e = float(_HIST_RECON_CPI.asof(pd.Timestamp(_wd['dates_end'])))
                    _infl  = (_cpi_e / _cpi_s) ** (252.0 / _wd['N']) - 1.0
                    print(f"\n  [historical_backtest] Inflation (FRED CPI, window): {_infl*100:.2f}%/yr")
                    # Update the active scenario inflation for display
                    _SCENARIO_PRESETS['historical_backtest']['inflation'] = float(_infl)
                except Exception:
                    pass
            _recon_val_pass    = bool(recon_val.get('overall_pass', False))
            _tr_basis          = recon_val.get('driver_total_return_basis') or {}
            _recon_val_dr_hash    = _tr_basis.get('driver_return_hash')
            _recon_val_dr_hash_n  = _tr_basis.get('driver_return_hash_n')
            _recon_val_dr_hash_ds = _tr_basis.get('driver_return_hash_date_start')
            _recon_val_dr_hash_de = _tr_basis.get('driver_return_hash_date_end')
        except Exception as _recon_crash:
            # Validation crashed — record failure so the metadata file is not left
            # with validation_pass=None.  Re-raise after the finally block writes.
            print(f"  ✗ Historical backtest validation CRASHED: {_recon_crash!r}")
            validation_results['historical_backtest'] = {
                'status': 'crashed', 'error': str(_recon_crash), 'overall_pass': False,
            }
            raise
        finally:
            # Always write the final validation_metadata.json — even on crash.
            # Overwrites the pre-validation record (validation_pass=None) from
            # generate_validation_snapshot.  The file never lies.
            try:
                export_validation_metadata(
                    canonical_hash=None,  # snapshot-scoped; not available in this path
                    driver_return_hash=_recon_val_dr_hash,
                    validation_pass=_recon_val_pass,
                    driver_return_hash_n=_recon_val_dr_hash_n,
                    driver_return_hash_date_start=_recon_val_dr_hash_ds,
                    driver_return_hash_date_end=_recon_val_dr_hash_de,
                    engine_code_hash=ENGINE_CODE_HASH,
                )
            except Exception as _meta_final_err:
                print(f"  ⚠ validation_metadata final update error: {_meta_final_err!r}")

    # Persist final validation payload after scenario-specific suites are appended.
    # run_validation_tests() writes the base payload; this second write ensures
    # keys like 'historical_backtest' / 'historical_bootstrap' are not lost.
    try:
        with open(VALIDATION_RESULTS, 'w') as f:
            json.dump(validation_results, f, indent=2)
    except Exception as _val_save_e:
        print(f"  ⚠ Failed to persist final validation payload: {_val_save_e}")

    # ========================================================================
    # STEP 3: Validate Time Horizons for Available Data
    # ========================================================================
    requested_horizons = [10]  # TEST: 10-year only
    TIME_HORIZONS = validate_time_horizons_for_start_date(ANALYSIS_START_DATE, requested_horizons)
    
    if not TIME_HORIZONS:
        print("\n⚠ ERROR: Not enough data for any requested time horizon!")
        print(f"  Requested horizons: {requested_horizons}")
        print(f"  Start date: {ANALYSIS_START_DATE}")
        return
    
    # ========================================================================
    # STEP 3b: SPY sanity check — verify unconditional stats before running LETFs
    # ========================================================================
    print(f"\n{'='*80}")
    print("SPY SIMULATION SANITY CHECK (500 paths × 1 year)")
    print(f"{'='*80}")
    _rng_chk = np.random.default_rng(999)
    _spy_cagrs, _spy_vols = [], []
    _jrm = regime_model.get('joint_return_model')
    _ssm = regime_model.get('stress_state_model')
    _vd  = regime_model.get('vix_dynamics')
    _rp  = regime_model.get('regime_params')
    for _i in range(500):
        _rng_i = np.random.default_rng(_i + 77777)
        _n = 252
        # Use the actual Weibull semi-Markov sampler (not the TM row-diagonal sampler)
        # so this check tests the same regime process as the engine (~3.4% crisis vs ~4.2% TM ss).
        _reg = simulate_regime_path_semi_markov(
            total_days=_n,
            start_regime=0,
            transition_matrix=regime_model['transition_matrix'],
            duration_samples=regime_model.get('duration_samples', None),
            rng=_rng_i,
        )
        if _jrm is not None:
            _j = simulate_joint_returns_t(n_days=_n, regime_path=_reg, joint_model=_jrm, rng=_rng_i)
            _spy = _j['SPY_Ret']
        else:
            _spy = np.zeros(_n)
        if _ssm is not None:
            _vix_chk = np.full(_n, 15.0)
            _ss = simulate_latent_stress_state(_n, _reg, _ssm, _vix_chk, _rng_i)
            _jmp = _ss.get('jump', np.zeros(_n))
            _spy = _spy + _jmp
            _spy, _ = apply_state_dependent_circuit_breakers(
                returns=_spy,
                regime_path=np.asarray(_reg, dtype=int),
                vix_series=np.asarray(_vix_chk, dtype=float),
                leverage=1.0,
                rng=np.random.default_rng(88000 + _i),
                stress_state=_ss,
                asset_class='equity'
            )
        _spy_cagrs.append((np.prod(1 + _spy) - 1) * 100)
        _spy_vols.append(_spy.std() * np.sqrt(252) * 100)
    _spy_cagrs = np.array(_spy_cagrs)
    _spy_vols  = np.array(_spy_vols)
    print(f"  SPY 1-year arithmetic return  — mean: {_spy_cagrs.mean():.2f}%  std: {_spy_cagrs.std():.2f}%")
    print(f"  SPY annualised vol            — mean: {_spy_vols.mean():.2f}%   std: {_spy_vols.std():.2f}%")
    _p10c, _p50c, _p90c = np.percentile(_spy_cagrs, [10, 50, 90])
    print(f"  SPY return percentiles        — P10: {_p10c:.1f}%  P50: {_p50c:.1f}%  P90: {_p90c:.1f}%")
    _ok = (5.0 <= _spy_cagrs.mean() <= 12.0) and (12.0 <= _spy_vols.mean() <= 22.0)
    print(f"  {'✓ PASS — SPY stats look reasonable' if _ok else '⚠ WARN — SPY mean or vol outside expected range [5-12% / 12-22%]'}")

    for horizon in TIME_HORIZONS:
        print(f"\n{'='*80}")
        print(f"MONTE CARLO SIMULATION: {horizon}-YEAR HORIZON  |  scenario: {scenario_resolution.display_name}")
        print(f"{'='*80}")
        
        mc_results = parallel_monte_carlo_fixed(
            strategy_ids=list(STRATEGIES.keys()),
            time_horizon=horizon,
            regime_model=regime_model,
            correlation_matrices=correlation_matrices,
            historical_df=df  # Pass historical data for block bootstrap
        )
        
        # Generate summary with new percentile format
        create_summary_statistics(mc_results, horizon)

        # ── Scenario-Aware Forward Realism Validation ─────────────────────────
        # historical_backtest uses its own dedicated institutional validator (SKIP).
        # All other scenarios run here with mode from SCENARIO_REALISM_MODE_MAP.
        # Validated on DRIVER-LEVEL returns (SPY + QQQ where available).
        _frl_mode = SCENARIO_REALISM_MODE_MAP.get(
            MARKET_SCENARIO, ScenarioRealismMode.WARN_ONLY
        )
        if _frl_mode != ScenarioRealismMode.SKIP:
            def _frl_get_real(col_pref: Tuple[str, ...]) -> np.ndarray:
                """Extract historical driver returns; prefer RealOnly columns."""
                for col in col_pref:
                    if col in df.columns:
                        arr = pd.to_numeric(df[col], errors='coerce').dropna().to_numpy(
                            dtype=np.float64)
                        if len(arr) > 50:
                            return arr
                return np.array([], dtype=np.float64)

            _frl_real_spy = _frl_get_real(('SPY_Ret_RealOnly', 'SPY_Ret'))
            _frl_real_qqq = _frl_get_real(('QQQ_Ret_RealOnly', 'QQQ_Ret'))

            # Gather up to 50 regime paths from S2 (SPY) and S3 (QQQ-linked)
            _frl_sampler   = regime_model.get('bootstrap_sampler', None)
            _frl_rng       = np.random.default_rng(42)
            _frl_n_cap     = 50

            def _frl_build_paths(
                    ref_paths: List[Dict],
                    ret_key: str,
            ) -> List[np.ndarray]:
                """Sample bootstrap returns for a list of mc_results path records."""
                out: List[np.ndarray] = []
                if _frl_sampler is None:
                    return out
                for _pr in ref_paths[:_frl_n_cap]:
                    try:
                        _rp = np.asarray(_pr.get('Regime_Path', []), dtype=np.int32)
                        if len(_rp) == 0:
                            continue
                        _rd = _frl_sampler.sample_returns(
                            n_days=len(_rp), regime_path=_rp, rng=_frl_rng)
                        _arr = np.asarray(_rd.get(ret_key, []), dtype=np.float64)
                        if len(_arr) > 0 and np.all(np.isfinite(_arr)):
                            out.append(_arr)
                    except Exception:
                        pass
                return out

            _frl_spy_paths = _frl_build_paths(mc_results.get('S2', []), 'SPY_Ret')
            _frl_qqq_paths = _frl_build_paths(mc_results.get('S3', []), 'QQQ_Ret')

            # Run validation for each available driver
            _frl_drivers = []
            if _frl_spy_paths and len(_frl_real_spy) > 0:
                _frl_drivers.append(('SPY', _frl_real_spy, _frl_spy_paths))
            if _frl_qqq_paths and len(_frl_real_qqq) > 0:
                _frl_drivers.append(('QQQ', _frl_real_qqq, _frl_qqq_paths))

            if _frl_drivers:
                for _frl_drv_name, _frl_real_r, _frl_synth in _frl_drivers:
                    try:
                        _frl_result = aggregate_forward_realism_across_paths(
                            real_r=_frl_real_r,
                            synth_paths=_frl_synth,
                            horizons=(1, 5, 21),
                            lags=20,
                            mode=_frl_mode,
                        )
                        print_forward_realism_report(
                            _frl_result,
                            scenario=f"{MARKET_SCENARIO} / {_frl_drv_name}",
                        )
                        if _frl_result.get('blocked', False):
                            raise RuntimeError(
                                f"FORWARD REALISM STRICT BLOCK ({_frl_drv_name}): "
                                f"{_frl_result['n_fail_paths']} of "
                                f"{_frl_result['n_paths']} paths FAILED realism "
                                f"thresholds in '{MARKET_SCENARIO}' scenario."
                            )
                    except ValueError as _frl_abs_err:
                        print(f"\n{'!'*80}")
                        print(f"  ABSURDITY GUARD ({_frl_drv_name}): {_frl_abs_err}")
                        print(f"{'!'*80}\n")
                        raise
            else:
                print(f"\n  Forward realism validation skipped "
                      f"(bootstrap sampler unavailable or no historical driver data "
                      f"for scenario={MARKET_SCENARIO}).")

        mc_results_real_validation = mc_results
        if str(REAL_ONLY_VALIDATION_MODE).strip().lower() == 'era_matched':
            print(f"\n{'='*80}")
            print(f"REAL-ONLY VALIDATION MC: {horizon}-YEAR HORIZON (ERA-MATCHED)")
            print(f"{'='*80}")
            mc_results_real_validation = run_real_only_validation_mc(
                strategy_ids=list(STRATEGIES.keys()),
                time_horizon=horizon,
                regime_model=regime_model,
                correlation_matrices=correlation_matrices,
                historical_df=df
            )

        if MARKET_SCENARIO == 'historical_backtest':
            # Historical backtest has its own dedicated scenario validator
            # (driver immutability, SPY fidelity, borrow formula, OOS emulator fit,
            # tax, determinism). Distributional MC-vs-history checks are designed
            # for stochastic scenarios and can emit misleading "blocked" messages
            # when replaying a short fixed historical window.
            print(f"\n{'='*100}")
            print("REALISM DISTRIBUTION CHECKS")
            print(f"{'='*100}")
            print("  Skipped for MARKET_SCENARIO='historical_backtest' (not applicable).")
            print("  Use HISTORICAL BACKTEST VALIDATION SUITE output above as the pass/fail source.")
            print(f"{'='*100}\n")
        else:
            # Compare simulated vs historical for buy & hold strategies (REAL DATA ONLY).
            # Keep crisis-mix conditioning enabled even in era-matched mode so selected
            # paths reflect observed stress occupancy in the real validation window.
            _use_crisis_mix_filter = True
            comparison_results_real = compare_simulated_vs_historical(
                df,
                mc_results_real_validation,
                horizon,
                use_crisis_mix_filter=_use_crisis_mix_filter
            )
            if int(REAL_ONLY_REPEATABILITY_RUNS) > 1:
                repeatability_diag = run_real_only_repeatability_checks(
                    df=df,
                    time_horizon=horizon,
                    regime_model=regime_model,
                    correlation_matrices=correlation_matrices,
                    strategy_ids=list(STRATEGIES.keys()),
                    n_runs=int(REAL_ONLY_REPEATABILITY_RUNS)
                )
                comparison_results_real['__repeatability__'] = repeatability_diag
            real_only_passed = bool(comparison_results_real.get('__summary__', {}).get('pass_gate', False))

            # NEW: Compare simulated vs SYNTHETIC-ONLY windows
            comparison_results_syn_only = compare_simulated_vs_synthetic_only(
                df, mc_results, horizon, real_only_passed=real_only_passed
            )

            # NEW: Compare simulated vs synthetic+historical for buy & hold strategies (ALL DATA)
            comparison_results_all = compare_simulated_vs_synthetic_historical(
                df, mc_results, horizon, real_only_passed=real_only_passed
            )

            # Regression gates for realism claims.
            realism_checks = run_realism_regression_checks(
                regime_model=regime_model,
                comparison_real=comparison_results_real,
                comparison_synthetic_only=comparison_results_syn_only,
                comparison_combined=comparison_results_all
            )
    
    print("\n" + "="*80)
    print("ANALYSIS COMPLETE")
    print("="*80)


def audit_historical_scenarios() -> Dict[str, Any]:
    """
    Audit historical_backtest and historical_bootstrap configuration/state.
    Prints:
      - detected weaknesses
      - potential realism improvements
      - remaining synthetic contamination
    """
    print(f"\n{'='*80}")
    print("HISTORICAL SCENARIO AUDIT")
    print(f"{'='*80}")

    out: Dict[str, Any] = {}
    overlay_keys = [
        'drift_tilt', 'div_yield', 'fat_tail_factor',
        'vol_scale_calm', 'vol_scale_crisis'
    ]
    expected = {
        'drift_tilt': 0.0,
        'div_yield': 0.0,
        'fat_tail_factor': 0.0,
        'vol_scale_calm': 1.0,
        'vol_scale_crisis': 1.0,
    }

    for scen in ('historical_backtest', 'historical_bootstrap'):
        cfg = dict(_SCENARIO_PRESETS.get(scen, {}))
        weaknesses: List[str] = []
        improvements: List[str] = []
        contamination: List[str] = []

        for k in overlay_keys:
            v = float(cfg.get(k, expected[k]))
            if abs(v - expected[k]) > 1e-12:
                contamination.append(f"{k}={v} (expected {expected[k]} for pure historical drivers)")

        mode = str(cfg.get('_hist1926_mode', ''))
        if scen == 'historical_backtest' and mode != 'backtest':
            weaknesses.append(f"_hist1926_mode is {mode!r}, expected 'backtest'")
        if scen == 'historical_bootstrap' and mode != 'bootstrap':
            weaknesses.append(f"_hist1926_mode is {mode!r}, expected 'bootstrap'")

        block_size = int(cfg.get('_hist1926_block_size', 63))
        if block_size <= 1:
            weaknesses.append(f"bootstrap block size={block_size}; structure preservation is weak")
        elif block_size < 20:
            improvements.append("increase block_size to better preserve volatility clustering")

        if scen == 'historical_bootstrap':
            if cfg.get('bootstrap_seed', None) is None:
                improvements.append("set historical_bootstrap.bootstrap_seed for exact reproducibility")
            contamination.append(
                "LETF layer remains stochastic (tracking-error AR model and tail-event overlay) "
                "because _is_reconstruction=False in historical_bootstrap."
            )
        else:
            contamination.append(
                "LETF layer uses calibrated financing spread and residual replay; "
                "underlying index drivers are chronological historical returns."
            )

        wd = _slice_hist1926_to_window(ANALYSIS_START_DATE, ANALYSIS_END_DATE, min_days=2)
        if wd is None:
            weaknesses.append(
                "selected analysis window could not be sliced from historical arrays"
            )
        else:
            improvements.append(
                f"current window is {wd['dates_start']} → {wd['dates_end']} ({wd['N']:,} days); "
                "keep this aligned with scenario intent."
            )

        print(f"\n[{scen}]")
        print("  detected weaknesses:")
        if weaknesses:
            for w in weaknesses:
                print(f"    - {w}")
        else:
            print("    - none detected")
        print("  potential realism improvements:")
        if improvements:
            for i in improvements:
                print(f"    - {i}")
        else:
            print("    - none identified")
        print("  remaining synthetic contamination:")
        if contamination:
            for c in contamination:
                print(f"    - {c}")
        else:
            print("    - none detected")

        out[scen] = {
            'weaknesses': weaknesses,
            'improvements': improvements,
            'synthetic_contamination': contamination,
        }

    print(f"\n{'='*80}")
    return out


